        Buff_Content_100 = {
          ContentES = "Cuando el PV de un enemigo de alta amenaza cae por debajo de #1, se vuelve invencible durante #2s y llama refuerzos. Cada enemigo derrotado otorga a todos los aliados 1 acumulación de Aumento de Daño Infligido de #3, acumulándose hasta #4 veces. La invencibilidad termina temprano una vez que se derroten un número determinado de enemigos.",
          TextMapId = "Buff_Content_100"
        },
        Buff_Content_101 = {
          ContentES = "Las unidades enemigas reciben el elemento seleccionado. Reciben un <H>400%</> más de daño de los elementos <H>ventajosos</>, y un <W>50%</> menos de daño de los elementos <W>desventajosos</>.",
          TextMapId = "Buff_Content_101"
        },
