        },
        Condition_Toast_PlayerLv_ModGuideBook_40 = {
          ContentES = "Wird freigeschaltet auf Prüfungsstufe 40",
          TextMapId = "Condition_Toast_PlayerLv_ModGuideBook_40"
        },
        Content_110101_1 = {
          ContentES = "Eine Stimme scheint von jenseits zu rufen ...",
          TextMapId = "Content_110101_1"
        },
        Content_110101_2 = {
          ContentES = "Lass dich nicht davon einfangen. Gehe weiter und entkomme dem Albtraum.",
          TextMapId = "Content_110101_2"
        },
        Content_110102_1 = {
          ContentES = "Du wachst aus dem Albtraum auf und siehst dich den messerscharfen Reißzähnen der Filthoiden gegenüber.",
          TextMapId = "Content_110102_1"
        },
        Content_110102_2 = {
          ContentES = "Deine Truppe wurde von wilden Filthoiden überfallen. Besiege sie und schließe dich wieder deiner Truppe an.",
          TextMapId = "Content_110102_2"
        },
        Content_110103_1 = {
          ContentES = "Nachdem du die plötzliche Bedrohung durch die Filthoiden neutralisiert hast, begib dich zur Notfallstation, um dich mit deiner Truppe wieder zu vereinen.",
          TextMapId = "Content_110103_1"
        },
        Content_110103_2 = {
          ContentES = "Der Kampf hat deiner Truppe schwer zugesetzt. Die Sanitäterin Daphne hat dich um Hilfe gebeten, um die Verwundeten zu versorgen.\n In der Zwischenzeit plant sie, medizinische Vorräte aus dem Lagerhaus zu holen. Aus Sicherheitsgründen beschließt du, an ihrer Stelle zu gehen.",
          TextMapId = "Content_110103_2"
        },
        Content_110103_3 = {
          ContentES = "Eine plötzliche Welle von Filthoiden nähert sich aus dem Korridor, aber die Verwundeten sind nicht in der Lage zu kämpfen. Als Truppführer und letzter Überlebender musst du die Stellung halten und deine Kameraden beschützen.",
          TextMapId = "Content_110103_3"
        },
        Content_110103_3_2 = {
          ContentES = "Avars rechtzeitiges Eintreffen hat das Blatt gewendet. Nutze diesen Moment, um den Anführer der Filthoiden zu besiegen und den Kampf zu beenden!",
          TextMapId = "Content_110103_3_2"
        },
        Content_110103_4 = {
          ContentES = "Zusammen mit Avar hast du die Filthoiden erfolgreich zurückgeschlagen. Zeit, zum Sanitätsposten zurückzukehren, um die nächsten Schritte zu besprechen.",
          TextMapId = "Content_110103_4"
        },
        Content_110104_1 = {
          ContentES = "Avar weist Daphne und die Verwundeten an, am Posten zu bleiben und auf Verstärkung zu warten. Währenddessen dringen du und Avar weiter in das Herz der Festung vor, um die Mission fortzusetzen.",
          TextMapId = "Content_110104_1"
        },
        Content_110104_2 = {
          ContentES = "Avar schätzt die Lage ein und glaubt, dass die Verlassenen die Operationspläne des Imperiums vorausgesehen haben, was euch in eine strategisch ungünstige Lage bringt.\n Um das Blatt zu wenden, beschließt er, den Phoxichor-Tank im Maschinenraum zu sabotieren, um die Verteidigungsanlagen der Festung außer Gefecht zu setzen und so die Lage für eure eingeschlossenen Kameraden zu erleichtern.",
          TextMapId = "Content_110104_2"
        },
        Content_110104_3 = {
          ContentES = "Avar schätzt die Lage ein und glaubt, dass die Verlassenen die Operationspläne des Imperiums vorausgesehen haben, was euch in eine strategisch ungünstige Lage bringt.\n Um das Blatt zu wenden, beschließt er, den Phoxichor-Tank im Maschinenraum zu sabotieren, um die Verteidigungsanlagen der Festung außer Gefecht zu setzen und so die Lage für eure eingeschlossenen Kameraden zu erleichtern.",
          TextMapId = "Content_110104_3"
        },
        Content_110105_1 = {
          ContentES = "Du begegnest zwei Mitgliedern der Einheit „Schneewölfe“. Doch einer von ihnen ist im Kern des Maschinenraums eingeschlossen.\n Arbeite mit Avar zusammen, um die Kraftquelle zu zerstören und deinen gefangenen Kameraden zu retten.",
          TextMapId = "Content_110105_1"
        },
        Content_110105_2 = {
          ContentES = "Du hast den Maschinenraum erfolgreich erreicht. Es ist Zeit, den Strom abzuschalten.",
          TextMapId = "Content_110105_2"
        },
        Content_110105_3 = {
          ContentES = "Du hast drei Kraftquellen abgeschaltet – doch plötzlich ertönt ein Alarm von den Phoxichor-Tanks im Maschinenraum ...",
          TextMapId = "Content_110105_3"
        },
        Content_110105_4 = {
          ContentES = "Über Funk schlägt Avar vor, die Phoxichor-Tanks zu überlasten, falls die normale Abschaltung fehlschlägt – um sie damit vollständig zu zerstören.",
          TextMapId = "Content_110105_4"
        },
        Content_110106_1 = {
          ContentES = [[
Auch wenn Vic gefallen ist, musst du die Mission fortsetzen.
 Arbeite mit Avar zusammen, um die Mechanismen im Maschinenraum zu deaktivieren, und achte auf lauernde Filthoiden.]],
          TextMapId = "Content_110106_1"
        },
        Content_110106_2 = {
          ContentES = "Du hast die Kraftquelle erfolgreich deaktiviert, aber dadurch wurde die Selbstzerstörungssequenz des Phoxichor-Tanks aktiviert. Entkomme aus dem Maschinenraum, bevor der Countdown abläuft.",
          TextMapId = "Content_110106_2"
        },
        Content_110106_3 = {
          ContentES = "Obwohl Fulvis, der Oberbefehlshaber, darauf besteht, die Mission fortzusetzen, erweist sich Avars Einschätzung als richtig. Statt eines riskanten Angriffs, der euch das Leben kosten könnte, konzentriert ihr euch zuerst darauf, die Greifen zu retten.",
          TextMapId = "Content_110106_3"
        },
        Content_110106_4 = {
          ContentES = "Du triffst auf Simon, der von Filthoiden eingekesselt ist. Besiege die Filthoiden.",
          TextMapId = "Content_110106_4"
        },
        Content_110106_5 = {
          ContentES = "Du hast Simon gefunden, aber er ist von Filthoiden umzingelt und sein Zustand sieht schlimm aus.",
          TextMapId = "Content_110106_5"
        },
        Content_110107_1 = {
          ContentES = "Es war zu spät, um Simon zu retten, aber seine letzten Worte verraten, dass noch weitere Kameraden in der Nähe der Bahngleise gefangen sind.\n Mach weiter, um diejenigen zu retten, die du noch retten kannst.",
          TextMapId = "Content_110107_1"
        },
        Content_110107_2 = {
          ContentES = "Unterwegs stößt du auf Filthoiden. Besiege sie schnell – lass dich nicht aufhalten.",
          TextMapId = "Content_110107_2"
        },
        Content_110107_3 = {
          ContentES = "Ein kurzes Gespräch mit Daphne verschafft dir einen Moment der Zuversicht. Geh weiter vorwärts.",
          TextMapId = "Content_110107_3"
        },
        Content_110108_1 = {
          ContentES = "Ein kurzes Gespräch mit Daphne verschafft dir einen Moment der Zuversicht. Geh weiter vorwärts.",
          TextMapId = "Content_110108_1"
        },
        Content_110108_2 = {
          ContentES = "Du hörst die Rufe deiner Kameraden, doch Filthoiden versperren dir den Weg. Besiege sie und schließe dich wieder deinem Trupp an.",
          TextMapId = "Content_110108_2"
        },
        Content_110108_3 = {
          ContentES = "Du hast die Filthoiden besiegt. Es ist Zeit, zu deinem Trupp zurückzukehren.",
          TextMapId = "Content_110108_3"
        },
        Content_110108_4 = {
          ContentES = "Dein Team traf auf zwei Charons. Die junge Frau erklärte, sie seien unschuldige Bewohner, die von den Verlassenen versklavt wurden. Da ihre Identität nicht überprüft werden konnte, beschlossen du und dein Team, vorsichtig in die Richtung weiterzugehen, die der Ältere angab – in der Hoffnung, Avar wiederzufinden.",
          TextMapId = "Content_110108_4"
        },
        Content_110108_6 = {
          ContentES = "Dein Team traf auf zwei Charons. Die junge Frau erklärte, sie seien unschuldige Bewohner, die von den Verlassenen versklavt wurden. Da ihre Identität nicht überprüft werden konnte, beschlossen du und dein Team, vorsichtig in die Richtung weiterzugehen, die der Ältere angab – in der Hoffnung, Avar wiederzufinden.",
          TextMapId = "Content_110108_6"
        },
        Content_110109_1 = {
          ContentES = "Avar plant, das Tor zum zentralen Kontrollraum mit einem Geschützturm aufzubrechen. Da der Maschinenraum außer Betrieb ist, müsst ihr das simulierte Schlachtfeld mit Notstrom wiederherstellen, um den Geschützturm neu zu positionieren.",
          TextMapId = "Content_110109_1"
        },
        Content_110109_2 = {
          ContentES = "Der Geschützturm bewegt sich entlang der Schiene. Beschütze ihn gemeinsam mit Avar vor herannahenden Filthoiden, bis er sein Ziel erreicht.",
          TextMapId = "Content_110109_2"
        },
        Content_110109_2_1 = {
          ContentES = "Um das Tor zum zentralen Kontrollraum aufzubrechen, musst du den Geschützturm neu positionieren. Aktiviere den Steuerungsmechanismus, um ihn entlang der Schiene zu bewegen.",
          TextMapId = "Content_110109_2_1"
        },
        Content_110109_3 = {
          ContentES = "Avar plant, das Tor zum zentralen Kontrollraum mit einem Geschützturm aufzubrechen. Da der Maschinenraum außer Betrieb ist, müsst ihr das simulierte Schlachtfeld mit Notstrom wiederherstellen, um den Geschützturm neu zu positionieren.",
          TextMapId = "Content_110109_3"
        },
        Content_110110_1 = {
          ContentES = "Nutze den Geschützturm, um den Durchgang zum zentralen Kontrollraum aufzubrechen.",
          TextMapId = "Content_110110_1"
        },
        Content_110110_2 = {
          ContentES = "Nach dem Beschuss ist die Seitentür zum zentralen Kontrollraum geöffnet. Untersuche den Bereich mit Avar.",
          TextMapId = "Content_110110_2"
        },
        Content_110110_3 = {
          ContentES = "Katya griff dich plötzlich an, doch Avar reagierte schnell und vereitelte ihren Plan.\n Besprich die aktuelle Situation mit Avar.",
          TextMapId = "Content_110110_3"
        },
        Content_110110_4 = {
          ContentES = "Du hast eine Pause gemacht. Während Avar sich erholt, befrage Katya, um herauszufinden, warum sie versucht hat, dich zu ermorden.\n Außerdem scheint Avar während des Kampfes ein Foto verloren zu haben – vielleicht kannst du ihm helfen, es zu finden.",
          TextMapId = "Content_110110_4"
        },
        Content_110110_5 = {
          ContentES = "Katya weigert sich, die Wahrheit zu sagen, und versucht eindeutig, dich zu provozieren. Ihre Unverschämtheit ruft dir diese vertraute Stimme in Erinnerung. Doch du behältst einen klaren Kopf.\n Sprich nun mit Avar, um deinen nächsten Schritt zu planen.",
          TextMapId = "Content_110110_5"
        },
        Content_110110_6 = {
          ContentES = "Avar plant zunächst, allein zum zentralen Kontrollraum zu gehen, doch seine Kameraden wollen ihn nicht allein der Gefahr aussetzen. Nach einiger Überredung willigt Avar ein, gemeinsam mit der Gruppe weiterzugehen.",
          TextMapId = "Content_110110_6"
        },
        Content_110110_7 = {
          ContentES = "Auf dem Weg zum zentralen Kontrollraum stößt ihr auf einen mächtigen Filthoid, der als Kriegsveteran bekannt ist. Du vertraust auf Avar, deinen Mentor und Kameraden, und bist zuversichtlich, dass ihr diesen mächtigen Gegner gemeinsam besiegen werdet.",
          TextMapId = "Content_110110_7"
        },
        Content_110110_8 = {
          ContentES = "Du hast den mächtigen Filthoid besiegt. Geh weiter vorwärts.",
          TextMapId = "Content_110110_8"
        },
        Content_110111_1 = {
          ContentES = "Als du den zentralen Kontrollraum erreichst, findest du ihn unerwartet leer vor – keine Spur vom Feind oder von Fallen.\n Untersuche die Umgebung und suche nach Hinweisen.",
          TextMapId = "Content_110111_1"
        },
        Content_110111_2 = {
          ContentES = "Plötzlich richtet Avar seine Waffe auf dich.",
          TextMapId = "Content_110111_2"
        }
      }
    end
  },
  {
    MinKey = "Content_110111_3",
    MaxKey = "Content_200104_9",
    Loader = function()
      return {
        Content_110111_3 = {
          ContentES = "Als du wieder zu dir kommst, stellst du fest, dass du noch lebst. Verschaffe dir einen Überblick über die Umgebung und schätze deine Lage ein.",
          TextMapId = "Content_110111_3"
        },
        Content_110111_4 = {
          ContentES = "Avar zeigt keine Lebenszeichen.\n Durch die Rundfunkübertragung erfährst du, dass die Legion einen Haftbefehl wegen Spionage gegen Daphne erlassen hat – eine Anschuldigung, die du als falsch erkennst. Du musst aus dem zentralen Kontrollraum fliehen und sie so schnell wie möglich finden.",
          TextMapId = "Content_110111_4"
        },
        Content_110111_5 = {
          ContentES = "Du findest Daphne, doch aus irgendeinem Grund richtet sie eine Waffe auf dich.",
          TextMapId = "Content_110111_5"
        },
        Content_110111_6 = {
          ContentES = "Du hast Daphne gefunden. Trotz ihrer Panik bemüht sie sich, ruhig zu bleiben und ihre Aufgaben als Sanitäterin zu erfüllen.\n Die Festung ist nicht mehr sicher. Entfliehe gemeinsam mit ihr durch die Kanalisation.",
          TextMapId = "Content_110111_6"
        },
        Content_110111_7 = {
          ContentES = "Hol den Schlüssel zurück",
          TextMapId = "Content_110111_7"
        },
        Content_110112_1 = {
          ContentES = "Die komplexe Anlage der Kanalisation erfordert eine sorgfältige Navigation. Gehe vorsichtig vor und finde einen Fluchtweg.",
          TextMapId = "Content_110112_1"
        },
        Content_110112_2 = {
          ContentES = "Der Feind versucht, die Kanalisation zu fluten, um deine Flucht zu verhindern. Aktiviere das Entwässerungssystem und setze deine Suche nach einem Ausgang fort.",
          TextMapId = "Content_110112_2"
        },
        Content_110113_1 = {
          ContentES = "Du und Daphne habt in der Hoffnung auf eine Überlebenschance Großkommandantin Sibylle in der Lonza-Festung gefunden. Kurz darauf werdet ihr als Verdächtige der Spionage in das imperiale Militärgefängnis zur Befragung gebracht.\n Um dich und Daphne zu schützen und Avars Opfer für die Gerechtigkeit zu ehren, musst du der Wächterin die Wahrheit beweisen.",
          TextMapId = "Content_110113_1"
        },
        Content_110113_2 = {
          ContentES = "Die Wächterin verabreicht dir ein Hypnotikum. Nach einem Moment der Benommenheit findest du dich in einem bizarren Raum wieder, der der Lonza-Festung ähnelt.\n Offenbar steht dir eine besondere Form des „Verhörs“ bevor.",
          TextMapId = "Content_110113_2"
        },
        Content_110113_3 = {
          ContentES = "Bestehe die feurige Prüfung der Wächterin, um deine Unschuld zu beweisen.",
          TextMapId = "Content_110113_3"
        },
        Content_110113_4 = {
          ContentES = "Du erklärst der Wächterin, was sich im zentralen Kontrollraum wirklich passiert ist – Avar hat seinen Verrat vorgetäuscht, um wichtige Beweise zu sichern, und sein Leben geopfert, um eine Aufzeichnung zu hinterlassen. Leider hat Fulvis' Adjutant Falsi die Aufzeichnung an sich genommen.\n Nachdem sie deine Aussage gehört hat, stimmt der Wächterin zu, den Fall weiter zu untersuchen.",
          TextMapId = "Content_110113_4"
        },
        Content_120001_1 = {
          ContentES = "Nachdem die Jagd auf Charon abgeschlossen ist, ist wieder Ruhe eingekehrt. Nun musst du nur noch zwanzig Tage auf die Nachricht über den „hochrangigen Gefangenen“ warten.\n Warum nutzt du die Ruhe nicht, um in der Asphodel vorbeizuschauen und dich nach neuen Missionen umzusehen?",
          TextMapId = "Content_120001_1"
        },
        Content_120001_2 = {
          ContentES = "Die Opernkarte von Camilla weckt Erinnerungen an die Jagd nach Charon – und an Kinder aus dem Schneeland, das Theaterstück, das mit diesem tragischen Fall verbunden ist.\n Jetzt, wo es wieder aufgeführt wird, lohnt es sich vielleicht, es dir selbst anzusehen.",
          TextMapId = "Content_120001_2"
        },
        Content_120001_3 = {
          ContentES = "Die Menge vor dem Theater ist voller Aufregung. Vielleicht solltest du einen Moment bleiben und hören, worüber alle reden.",
          TextMapId = "Content_120001_3"
        },
        Content_120001_4 = {
          ContentES = "Die Vorstellung beginnt gleich. Gehe am besten zum Haupteingang – es wäre schade, die Ouvertüre zu verpassen.",
          TextMapId = "Content_120001_4"
        },
        Content_120002_1 = {
          ContentES = "Ein frustrierter Schwarzhändler rempelt dich an, nachdem er eine Eintrittskarte nicht verkaufen konnte.\n Mach dir keine Gedanken darüber – geh einfach zum Theatereingang.",
          TextMapId = "Content_120002_1"
        },
        Content_120002_2 = {
          ContentES = "Dank der rechtzeitigen Intervention einer Fremden namens Zhiliu erhältst du nicht nur Zutritt, sondern wirst auch in eine Loge der ersten Klasse geführt, von der die meisten nur träumen können.\n Vielleicht ist jetzt ein guter Zeitpunkt, um deiner unerwarteten Wohltäterin zu danken.",
          TextMapId = "Content_120002_2"
        },
        Content_120002_3 = {
          ContentES = "Die Vorstellung beginnt gleich. Nimm deinen Platz ein – und lass die Vorfreude steigen.",
          TextMapId = "Content_120002_3"
        },
        Content_120002_4 = {
          ContentES = [[
Obwohl der Zauber der Oper noch in deinen Gedanken nachhallt, signalisieren die aufgehenden Lichter ihr Ende.
 Zeit, der Menge zu folgen und sich auf den Weg zu machen.]],
          TextMapId = "Content_120002_4"
        },
        Content_120002_5 = {
          ContentES = "Gerade als du gehen willst, versperrt dir ein Fremder den Weg. Zhilius verspäteter Geschäftspartner ist endlich aufgetaucht – \n und er sieht nicht gerade freundlich aus. Bleib wachsam.",
          TextMapId = "Content_120002_5"
        },
        Content_120002_6 = {
          ContentES = "Zhiliu geht mit dem Schwarzmarkthändler, der sie über den Tisch ziehen wollte, ohne mit der Wimper zu zucken um.\n Bring ihr nun den Phoxichor, damit sie seine Echtheit überprüfen kann.",
          TextMapId = "Content_120002_6"
        },
        Content_120002_7 = {
          ContentES = "Wie erwartet, stellt sich der Phoxichor als Fälschung heraus. Aber du kannst das Bild dieses seltsamen Rauchschwäfels, der auf deine Anwesenheit reagiert, nicht aus deinem Kopf bekommen ...\n Trotzdem ist es jetzt Zeit, zu gehen.",
          TextMapId = "Content_120002_7"
        },
        Content_120002_8 = {
          ContentES = "Du bist dabei, dich vor dem Theater von Zhiliu zu verabschieden – nur um zu erfahren, dass sie auch in die Asphodel geht.\n Da ihr beide dorthin geht, kannst du sie genauso gut dorthin begleiten.",
          TextMapId = "Content_120002_8"
        },
        Content_120002_9 = {
          ContentES = "Was für ein Tag. Erstatte Camilla Bericht – \n vielleicht hast du mehr zu erzählen als erwartet.",
          TextMapId = "Content_120002_9"
        },
        Content_120003_1 = {
          ContentES = [[
Ein neuer Tag beginnt.
 Gehe wie immer in die Asphodel und schau, was dort los ist.]],
          TextMapId = "Content_120003_1"
        },
        Content_120003_2 = {
          ContentES = "Eine seltsame Nachricht stört die Ruhe – ist es eine geheime Botschaft von Berry oder eine gut geplante Falle?\n Da du Snow nicht mit hineinziehen willst, entschuldigst du dich und schleichst dich leise davon.\n Gehe zurück zur Raststätte und warte auf die Abenddämmerung.",
          TextMapId = "Content_120003_2"
        },
        Content_120003_3 = {
          ContentES = [[
Ob die Nachricht wirklich von Berry stammt oder nicht, musst du herausfinden.
 Sobald es dunkel ist, geh zur roten Telefonzelle, wie in der Nachricht angegeben.]],
          TextMapId = "Content_120003_3"
        },
        Content_120003_4 = {
          ContentES = "Snow wartet bereits vor der Raststätte – offensichtlich hat sie deinen Plan durchschaut.\n Entschlossen, sich gemeinsam den bevorstehenden Herausforderungen zu stellen, machen du und Snow dich erneut auf den Weg.",
          TextMapId = "Content_120003_4"
        },
        Content_120003_5 = {
          ContentES = "Könnte diese weißhaarige Gestalt wirklich Berry sein?\n Das Mädchen, das du gesucht hast, könnte nur wenige Schritte entfernt sein – nähere dich vorsichtig.",
          TextMapId = "Content_120003_5"
        },
        Content_120003_6 = {
          ContentES = [[
Wie du vermutet hast, war die Gestalt in der Telefonzelle eine Falle der Legion. Gut, dass du vorbereitet bist.
 Sprich mit Snow und entscheidet, wie ihr weiter vorgehen wollt.]],
          TextMapId = "Content_120003_6"
        },
        Content_120003_7 = {
          ContentES = "Ihr habt das Schlimmste vermieden – aber die Legion ist jetzt in höchster Alarmbereitschaft. \n Bewegt euch schnell und verschwindet, bevor die Patrouillen euch entdecken.",
          TextMapId = "Content_120003_7"
        },
        Content_120003_8 = {
          ContentES = "Zhiliu taucht gerade rechtzeitig auf, um euch aus der Klemme zu helfen.\n Steig in ihr Auto ein – es gibt keine Zeit zu verlieren.",
          TextMapId = "Content_120003_8"
        },
        Content_120003_9 = {
          ContentES = "Das ist eure letzte Hürde in dieser Nacht.\n Komm an den Torwächtern vorbei, ohne Verdacht zu erregen – und schaff es aus Icelake heraus.",
          TextMapId = "Content_120003_9"
        },
        Content_120101_1 = {
          ContentES = "Nach einer langen Reise über ferne Meere bist du endlich in Huaxu angekommen.\n Die anmutige Landschaft, die sich vor dir ausbreitet, erinnert dich leise daran, dass du weit von zu Hause entfernt bist. Sprich mit Zhiliu, um mehr über diesen Ort zu erfahren.",
          TextMapId = "Content_120101_1"
        },
        Content_120101_10 = {
          ContentES = "Jetzt, da du die Neun Kapitel gelernt hast, beginnst du, dich in Huaxu zurechtzufinden.\n Folge Karp-Luno zur Händlergilde EverSpring und schließe dich wieder Zhiliu an.",
          TextMapId = "Content_120101_10"
        },
        Content_120101_11 = {
          ContentES = "Auf halbem Weg deiner Reise bebt plötzlich der Boden.\n Ein Vollstrecker, den du kurz am Hafen getroffen hast, wird plötzlich feindselig und hat eine unheimliche Farbe – anders als alle Bi'an, die du bisher gesehen hast.\n Mit der Hilfe einer vorbeikommenden Händlerin überlebst du die Bedrohung. Sprich mit ihr, um mehr zu erfahren.",
          TextMapId = "Content_120101_11"
        },
        Content_120101_12 = {
          ContentES = "Von Yusheng erfährst du, dass der Segen, der dich beschützt hat, an etwas namens „Weihrauch” gebunden ist und dass er im Argent-Loong-Tempel nahe EverSpring wieder aufgefüllt werden kann.\n Folge Karp-Luno zur Händlergilde EverSpring und schließe dich wieder Zhiliu an.",
          TextMapId = "Content_120101_12"
        },
        Content_120101_13 = {
          ContentES = "Auf halbem Weg deiner Reise bebt plötzlich der Boden.\n Ein Vollstrecker, den du kurz am Hafen getroffen hast, wird plötzlich feindselig und hat eine unheimliche Farbe – anders als alle Bi'an, die du bisher gesehen hast.\n Keine Zeit zum Nachdenken. Mach dich bereit für den Kampf.",
          TextMapId = "Content_120101_13"
        },
        Content_120101_2 = {
          ContentES = "Das Schiff hat gerade erst angelegt, als vom Pier ein Ruf nach Zhiliu ertönt.\n Gehe von Bord und schau nach, was los ist.",
          TextMapId = "Content_120101_2"
        },
        Content_120101_3 = {
          ContentES = "Alles in Huaxu fühlt sich neu und aufregend an.\n Der Hafen ist voller Stimmen von Händlern und Reisenden. Da du Zeit hast, schau dich um.",
          TextMapId = "Content_120101_3"
        },
        Content_120101_4 = {
          ContentES = "Alles in Huaxu fühlt sich neu und aufregend an.\n Der Hafen ist voller Stimmen von Händlern und Reisenden. Da du Zeit hast, schau dich um.",
          TextMapId = "Content_120101_4"
        },
        Content_120101_5 = {
          ContentES = "Im Handumdrehen ist Snow verschwunden. Such sie am besten.",
          TextMapId = "Content_120101_5"
        },
        Content_120101_6 = {
          ContentES = "Du kommst gerade rechtzeitig, um Snows Prahlerei gegenüber Karp-Luno zu unterbrechen. Jetzt, wo die Dämonenkönigin eine kleine Bewundererin hat, ist sie richtig stolz.\n Bring Snow am besten zu Zhiliu zurück, bevor ihr das zu Kopf steigt.",
          TextMapId = "Content_120101_6"
        },
        Content_120101_7 = {
          ContentES = "Gerade als in Huaxu alles ruhig zu sein scheint, kommt es zu einem Zwischenfall.\n Am Hafen kommt es zu einem Raubüberfall – der jedoch schnell von einem Bi'an, einem göttlichen Tier, das auf dem Wind reitet, beendet wird. Zhiliu erklärt, dass das Reich durch die Neun Kapitel von Dafeng geschützt wird, wodurch Verbrechen so gut wie unbekannt sind.\n Während sie spricht, kommt einer ihrer Adjutanten atemlos herbeigeeilt.\n Was hat den Verbrecher hierher gelockt? Finde es heraus.",
          TextMapId = "Content_120101_7"
        },
        Content_120101_8 = {
          ContentES = "Zhiliu muss gehen, um dringende Aufgaben zu erledigen.\n Bevor sie geht, erinnert sie dich daran, dass sich alle im Reich Huaxu an die Neun Kapitel von Dafeng halten müssen.\n Um dich als gesetzestreuer Gast zu verhalten, folge Karp-Luno zur Stele.",
          TextMapId = "Content_120101_8"
        },
        Content_120101_9 = {
          ContentES = "Während Karp-Luno die Neun Kapitel erklärt, streift eine leise Stimme deine Gedanken – die Stele scheint zu dir zu sprechen ...",
          TextMapId = "Content_120101_9"
        },
        Content_120102_1 = {
          ContentES = "Nachdem du dich von Karp-Luno getrennt hast, führt dich dein Weg bis kurz hinter die Stufen von EverSpring.\n Triff dich mit Zhiliu, um mehr über die bevorstehende Mission zu erfahren.",
          TextMapId = "Content_120102_1"
        },
        Content_120102_10 = {
          ContentES = "Wahrscheinlich vor lauter Erschöpfung schläft Yuming mitten im Gespräch ein.\n Such einen sicheren Ort und hilf ihm, sich auszuruhen.",
          TextMapId = "Content_120102_10"
        },
        Content_120102_11 = {
          ContentES = "Dieser Umweg endet hier. Folge dem Weg aus der Gezeitenlied-Höhle und setze deinen Weg fort.",
          TextMapId = "Content_120102_11"
        },
        Content_120102_14 = {
          ContentES = "Du kommst an und siehst, dass sich der Magistrat von Yingtian gerade noch gegen eine Gruppe Zobel-Bi'an behaupten kann.\n Schließ dich dem Kampf an und wende das Blatt.",
          TextMapId = "Content_120102_14"
        },
        Content_120102_1_1 = {
          ContentES = "/",
          TextMapId = "Content_120102_1_1"
        },
        Content_120102_1_2 = {
          ContentES = "/",
          TextMapId = "Content_120102_1_2"
        },
        Content_120102_1_3 = {
          ContentES = "Nach dem Abschied von Karp-Luno führt dich dein Weg bis kurz hinter die Stufen der Immerquell.\n Triff Zhiliu, um mehr über den bevorstehenden Auftrag zu erfahren.",
          TextMapId = "Content_120102_1_3"
        },
        Content_120102_2 = {
          ContentES = "Du kommst gerade rechtzeitig, um zu sehen, wie Zhiliu mit ruhiger Autorität einen Streit unter den Sternenwebern beilegt. Aus ihrem Gespräch wird die Dringlichkeit der Plage von Zhuyin deutlich.\n Triff dich mit Zhiliu, um mehr über die bevorstehende Mission zu erfahren.",
          TextMapId = "Content_120102_2"
        },
        Content_120102_3 = {
          ContentES = "Zhiliu hat dich damit beauftragt, drei Zhuyin-Schuppen aus der Gritblight-Ebene zu holen – ein Schritt, um die Plage von Zhuyin einzudämmen.\n Für einen echten Phoxjäger ist die Pflicht ihre eigene Belohnung – auch wenn eine großzügige Bezahlung nie schadet.",
          TextMapId = "Content_120102_3"
        },
        Content_120102_3_1 = {
          ContentES = "/",
          TextMapId = "Content_120102_3_1"
        },
        Content_120102_4 = {
          ContentES = "Auf Anweisung von Zhiliu führt euer Weg durch die Gezeitenlied-Höhle zum Schwarzmarkt, wo ein speziell hergestelltes Werkzeug auf euch wartet, das für das Sammeln der Zhuyin-Schuppen unerlässlich ist.",
          TextMapId = "Content_120102_4"
        },
        Content_120102_5 = {
          ContentES = "Auf Anweisung von Zhiliu führt euer Weg durch die Gezeitenlied-Höhle zum Schwarzmarkt, wo ein speziell hergestelltes Werkzeug auf euch wartet, das für das Sammeln der Zhuyin-Schuppen unerlässlich ist.\n Das leise Echo des Wassers an diesem schattigen Ort weckt einen Gedanken – warum beginnen so viele Aufträge in Höhlen? Aber müßige Überlegungen müssen warten.\n Auch diese Höhle ist von Zobel-Bi‘an überrannt. Kämpfe dich durch.",
          TextMapId = "Content_120102_5"
        },
        Content_120102_6 = {
          ContentES = "Der Magistrat von Yingtian kommt gerade rechtzeitig und wehrt einen Angriff der Zobel-Bi‘an ab. Nachdem das Missverständnis ausgeräumt ist, bietet er dir an, dich sicher aus der Höhle zu begleiten.",
          TextMapId = "Content_120102_6"
        },
        Content_120102_7 = {
          ContentES = "Nachdem er dich zum Ausgang der Höhle begleitet hat, geht der Magistrat alleine weiter.\n Dein Weg liegt vor dir, aber unheimliche Geräusche hinter dir machen dich nervös.\n Ihr habt euch vielleicht gerade erst kennengelernt – aber er hat dir geholfen. Gehe nachsehen, ob es ihm gut geht.",
          TextMapId = "Content_120102_7"
        },
        Content_120102_8 = {
          ContentES = "Du kommst an und siehst, dass sich der Magistrat von Yingtian gerade noch gegen eine Gruppe Zobel-Bi'an behaupten kann.\n Schließ dich dem Kampf an und wende das Blatt.",
          TextMapId = "Content_120102_8"
        },
        Content_120102_9 = {
          ContentES = "Nach einem harten Kampf sind die letzten Zobel-Bi'an, die in der Höhle lauern, endlich besiegt.\n Der Magistrat von Yingtian scheint schwer verletzt zu sein. Sieh nach, wie es ihm geht.",
          TextMapId = "Content_120102_9"
        },
        Content_120103_1 = {
          ContentES = "Auf Zhilius Anweisung müssen Erstbesucher, die den Schwarzmarkt aufsuchen, durch die Küstenhöhle gehen, einen bestimmten Anhänger tragen und das Passwort nennen.",
          TextMapId = "Content_120103_1"
        },
        Content_120103_10 = {
          ContentES = "Während du die Schuppen sammelst, hörst du eine leise Stimme. Eine Szene von EverSpring unter Angriff schießt plötzlich in deinen Kopf – eine unerschütterliche Vorahnung dessen, was kommen wird.\n Beeil dich zurück und schau nach, was los ist.",
          TextMapId = "Content_120103_10"
        },
        Content_120103_11_1 = {
          ContentES = "Deine Befürchtungen haben sich bewahrheitet. Zum Glück haben sich die Mitarbeiter von EverSpring zusammengeschlossen und zu den Waffen gegriffen, um ihre Heimat zu verteidigen.\n Die Lage ist vorerst stabil. Finde Zhiliu und biete deine Hilfe an.",
          TextMapId = "Content_120103_11_1"
        },
        Content_120103_11_2 = {
          ContentES = "Deine Befürchtungen haben sich bewahrheitet. Hilf den Mitarbeitern von EverSpring, den Angriff der Zobel-Bi'an abzuwehren.",
          TextMapId = "Content_120103_11_2"
        },
        Content_120103_11_3 = {
          ContentES = "Du siehst, wie Zhiliu einen protestierenden Mann mittleren Alters mit kühler Autorität abweist – ein Schritt, der dazu dient, die Reihen zu festigen.\n Sie schickt dich, um den Vorhof des Argent-Loong-Tempels zu verstärken. Halte noch ein wenig durch, dann wird der Räucherwächter das Blatt wenden können.",
          TextMapId = "Content_120103_11_3"
        },
        Content_120103_12 = {
          ContentES = "Nachdem das Ritual beendet ist, steigt Taihao – ein prächtiger Loong – herab, um das Böse zu vernichten.\n Die Krise ist vorbei. Gehe zurück und berichte Zhiliu.",
          TextMapId = "Content_120103_12"
        },
        Content_120103_13 = {
          ContentES = "Du gibst Zhiliu die Zhuyin-Schuppen.\n Aber als du die frühere warnende Stimme erwähnst, wirkt sie distanziert – zumindest scheint es so.\n Fürs Erste gibt's nichts mehr zu tun. Verlasse EverSpring.",
          TextMapId = "Content_120103_13"
        },
        Content_120103_14_1 = {
          ContentES = "Begib dich zur Halle der Vergänglichkeit",
          TextMapId = "Content_120103_14_1"
        },
        Content_120103_14_2 = {
          ContentES = "Sprich mit Herrn Qiu",
          TextMapId = "Content_120103_14_2"
        },
        Content_120103_2 = {
          ContentES = "Auf Zhilius Anweisung müssen Erstbesucher, die den Schwarzmarkt aufsuchen, durch die Küstenhöhle gehen, einen bestimmten Anhänger tragen und das Passwort nennen.\n Ein Schwarzmarkthändler wartet gleich da vorne. Sprich mit ihm.",
          TextMapId = "Content_120103_2"
        },
        Content_120103_3 = {
          ContentES = "Irgendwie hast du den Anhänger verloren. Ohne ihn fällt das Treffen ins Wasser.\n Gerade als du ratlos dastehst, bricht in der Nähe ein Tumult aus. Du kannst dir genauso gut ansehen, was los ist.",
          TextMapId = "Content_120103_3"
        },
        Content_120103_4 = {
          ContentES = "Du erfährst, dass der Schwarzmarkthändler eine Lücke in den Neun Kapiteln von Dafeng ausgenutzt hat, um einer jungen Frau das Geld ihrer Familie abzunehmen – und ihr dann einen Bi'an als „Strafe” auf sie gesetzt hat. Dank deines rechtzeitigen Eingreifens konnte das Schlimmste verhindert werden.\n Sieh jetzt nach dem verletzten Mädchen.",
          TextMapId = "Content_120103_4"
        },
        Content_120103_5 = {
          ContentES = "Als die Spannungen ihren Höhepunkt erreichen, mischt sich ein Fremder ein und ruft zur Ruhe auf. Er begrüßt dich als Ehrengast und sagt, sein Chef, Herr Qiu, wolle mit dir sprechen.",
          TextMapId = "Content_120103_5"
        },
        Content_120103_5_1 = {
          ContentES = "Dein Gespräch mit dem Schwarzmarktboss war alles andere als angenehm.\n Trotzdem hat er dir die Werkzeuge zum Sammeln von Zhuyin-Schuppen gegeben. Du willst nicht länger bleiben – verlasse diesen Ort sofort.",
          TextMapId = "Content_120103_5_1"
        },
        Content_120103_6 = {
          ContentES = "Besorgt um das verletzte Mädchen kehrst du zurück, um nach ihr zu sehen und um zu überprüfen, ob der Schwarzmarkthändler sein Versprechen gehalten hat.",
          TextMapId = "Content_120103_6"
        },
        Content_120103_7 = {
          ContentES = "Eine weißhaarige Frau erscheint, die die Wunden des Mädchens mit geheimnisvollen Künsten versorgt – und auch deine Müdigkeit lindert.\n Wer ist diese geheimnisvolle Heilerin? Sprich mit ihr.",
          TextMapId = "Content_120103_7"
        },
        Content_120103_8 = {
          ContentES = "Nachdem ihr euch auf einen Besuch in der Halle der Vergänglichkeit geeinigt habt, trennt ihr euch vorerst von Fushu.\n Konzentriere dich nun auf die bevorstehende Aufgabe: Gehe zum Eingang der Gritblight-Ebene, suche Meister Gongshang auf und lerne den Umgang mit seinen Werkzeugen.",
          TextMapId = "Content_120103_8"
        },
        Content_120103_8_1 = {
          ContentES = "Nach der Klärung eines kleinen Missverständnisses bezüglich der Lehrlingsaufnahme fasst Meister Gongshang wieder Fassung und beginnt, dir den Umgang mit dem Mechanischen Nexus zu zeigen.\n Sprich mit ihm, um das Tutorial fortzusetzen.",
          TextMapId = "Content_120103_8_1"
        },
        Content_120103_8_2 = {
          ContentES = "Nach der Klärung eines kleinen Missverständnisses bezüglich der Lehrlingsaufnahme fasst Meister Gongshang wieder Fassung und beginnt, dir den Umgang mit dem Mechanischen Nexus zu zeigen.\n Versuche, damit eine Taixu-Rune aufzunehmen.",
          TextMapId = "Content_120103_8_2"
        },
        Content_120103_8_3 = {
          ContentES = "Nach der Klärung eines kleinen Missverständnisses bezüglich der Lehrlingsaufnahme fasst Meister Gongshang wieder Fassung und beginnt, dir den Umgang mit dem Mechanischen Nexus zu zeigen.\n Versuche, damit Gritblight zu neutralisieren.",
          TextMapId = "Content_120103_8_3"
        },
        Content_120103_8_4 = {
          ContentES = "Nach der Klärung eines kleinen Missverständnisses bezüglich der Lehrlingsaufnahme fasst Meister Gongshang wieder Fassung und beginnt, dir den Umgang mit dem Mechanischen Nexus zu zeigen.\n Versuche, das von der Jishu-Sekte gestellte Rätsel zu lösen.",
          TextMapId = "Content_120103_8_4"
        },
        Content_120103_8_5 = {
          ContentES = "Nach der Klärung eines kleinen Missverständnisses bezüglich der Lehrlingsaufnahme fasst Meister Gongshang wieder Fassung und beginnt, dir den Umgang mit dem Mechanischen Nexus zu zeigen.\n Du hast das Tutorial vorbildlich abgeschlossen – und nun möchte Meister Gongshang dir etwas mitteilen.",
          TextMapId = "Content_120103_8_5"
        },
        Content_120103_9 = {
          ContentES = "Nachdem das Missverständnis geklärt ist – Meister Gongshang hielt dich fälschlicherweise für angehende Lehrlinge – hast du gelernt, den Mechanischen Nexus zu bedienen, um den Gritblight zu neutralisieren, und den Titel „ehrenhafte Lehrlinge der Jishu-Sekte“ erhalten.\n Begib dich in die Höhen der Gritblight-Ebene und sammle drei Zhuyin-Schuppen für Zhiliu.",
          TextMapId = "Content_120103_9"
        },
        Content_120104_1 = {
          ContentES = "Fushu hat dir über Zhiliu mitgeteilt, dass es dem jungen Mädchen, das du auf dem Schwarzmarkt gerettet hast, schlechter geht.\n Gehe zur Halle der Vergänglichkeit und schau nach ihr.",
          TextMapId = "Content_120104_1"
        },
        Content_120104_10 = {
          ContentES = "Der verspielte junge Wishen weigert sich zu gehen – nicht bevor du sein Rätsel gelöst hast.",
          TextMapId = "Content_120104_10"
        },
        Content_120104_11 = {
          ContentES = "Der junge Wishen hat seinen Spaß gehabt. Zeit, ihn zurückzubegleiten.",
          TextMapId = "Content_120104_11"
        },
        Content_120104_12 = {
          ContentES = "Mit Hilfe der drei jungen Wishen bist du an der wahren Yu-Quelle angekommen – einem Ort, an dem diese Welt und die nächste zusammenkommen.\n Frag den Ältesten Wishen, wo du das Wangyou-Kraut finden kannst.",
          TextMapId = "Content_120104_12"
        },
        Content_120104_13 = {
          ContentES = "Das Kraut wächst in der Nähe eines Wasserfalls auf der anderen Seite des Berges.\n Auch dort hat sich das Gritblight ausgebreitet – und einige Wishen sind verschwunden. Der Älteste bittet dich, der Sache nachzugehen.",
          TextMapId = "Content_120104_13"
        },
        Content_120104_14 = {
          ContentES = "Du hast das Kraut gefunden, das zur Heilung des Mädchens benötigt wird. Sammle es ein.",
          TextMapId = "Content_120104_14"
        },
        Content_120104_15 = {
          ContentES = "Während du das Kraut einsammelst, ruft Snow dich zu sich – was hat sie gefunden?",
          TextMapId = "Content_120104_15"
        },
        Content_120104_17 = {
          ContentES = "Mit Fushus Hilfe bist du aus dem Vergessensspalt entkommen – einem lichtlosen Reich, in dem nur alte Erinnerungen zurückbleiben.\n Snow hat besorgt auf dich gewartet. Tröste sie.",
          TextMapId = "Content_120104_17"
        },
        Content_120104_2 = {
          ContentES = "Du folgst dem Bergpfad und findest die Halle der Vergänglichkeit inmitten eines Aprikosenhains.\n Es ist still und verlassen – deine Rufe bleiben unbeantwortet. Ist Fushu wirklich hier? Du und Snow beschließen, hineinzugehen und nachzuschauen.",
          TextMapId = "Content_120104_2"
        },
        Content_120104_20 = {
          ContentES = "Von einem Hilferuf angezogen, bist du in den Vergessensspalt gefallen – ein lichtloses Reich, in dem alles in Vergessenheit gerät.\n Finde einen Weg hinaus, bevor du die vergisst, die dir lieb sind.",
          TextMapId = "Content_120104_20"
        },
        Content_120104_3 = {
          ContentES = "Du folgst dem Bergpfad und findest die Halle der Vergänglichkeit inmitten eines Aprikosenhains.\n Es ist still und verlassen – deine Rufe bleiben unbeantwortet. Ist Fushu wirklich hier? Sieh dich um.",
          TextMapId = "Content_120104_3"
        },
        Content_120104_4 = {
          ContentES = "Das Mädchen ist seit dem Angriff von Bi’an noch immer nicht wieder zu sich gekommen. Fushu ist die ganze Nacht an ihrer Seite geblieben und ist an ihrem Krankenbett eingeschlafen.\n Nachdem ihr über ein Heilmittel gesprochen habt, beschließt du, zur Yu-Quelle zu reisen – einem mystischen Reich –, um ein seltenes Kraut namens Wangyou zu suchen, das ihre Wunden heilen kann.",
          TextMapId = "Content_120104_4"
        },
        Content_120104_5 = {
          ContentES = "Auch die Yu-Quelle ist von der Gritblight heimgesucht worden. Reinige den Bereich mit der Methode, die dir Meister Gongshang beigebracht hat.",
          TextMapId = "Content_120104_5"
        },
        Content_120104_6 = {
          ContentES = "Du hast einen jungen Wishen gerettet, der im Gritblight gefangen war. Bring ihn sicher zurück zum Altar.",
          TextMapId = "Content_120104_6"
        },
        Content_120104_7 = {
          ContentES = "Die beiden anderen Wishen, die am Altar bleiben sollten, sind wegen dem Gritblight verschwunden. Suche sie.",
          TextMapId = "Content_120104_7"
        },
        Content_120104_8 = {
          ContentES = "In der Höhle findest du einen schüchternen jungen Wishen. Filthoiden versperren den Weg. Räum den Weg frei und bring ihn zurück zum Altar.",
          TextMapId = "Content_120104_8"
        },
        Content_120104_9 = {
          ContentES = "Zwei junge Wishen sind sicher zum Altar zurückgekehrt. Zeit, den letzten zu finden.",
          TextMapId = "Content_120104_9"
        },
        Content_120105_1 = {
          ContentES = "Außerhalb von EverSpring hält dich einer von Herrn Qius Männern mit einer Einladung auf – er will, dass du an einer sogenannten „Jagdexpedition“ teilnimmst.\n Der launische Schwarzmarktboss hat ganz klar seine eigenen Pläne, aber die versprochene Belohnung ist schwer abzulehnen.\n Begib dich zum Verborgenen Loong und hör dir an, was er zu sagen hat.",
          TextMapId = "Content_120105_1"
        },
        Content_120105_14 = {
          ContentES = "Die Unruhe der Beute löst die uralte Vielfach-Fangjagd-Formation aus – eine spektakuläre Konstruktion, die aus dem Boden hervorbricht. Du und deine Verbündeten kämpfen euch durch die Falle und gelangen schließlich in die offene Weite von Krähenlied-Hohl.\n Zu deiner Überraschung ist die „Beute“ tatsächlich Yuming, den du einmal kurz getroffen hast.\n Als du dich weigerst, mitzuspielen, beschwört er die Neun Kapitel von Dafeng und zwingt Yuming, dich anzugreifen.\n Verteidige dich. Behalte deine Position.",
          TextMapId = "Content_120105_14"
        },
        Content_120105_15 = {
          ContentES = "Mitten im Kampf hält sich Yuming zurück – aber der Widerstand gegen die Neun Kapitel verschlimmert seine Verletzungen.\n In diesem Moment taucht eine unerwartete Gestalt auf: Kezhou, der Wanderer, dem du in der Vielfach-Fangjagd-Formation begegnet bist, ruft nach seinem älteren Mitschüler – Yuming. Yuming weicht dem aus, dem er sich nicht stellen kann, nutzt eine Gelegenheit und zieht sich zurück.\n Der Kampf ist vorbei, aber Herr Qius Betrug wird nicht unangefochten bleiben. Konfrontiere sie.",
          TextMapId = "Content_120105_15"
        },
        Content_120105_16 = {
          ContentES = "Herr Qiu geht und hinterlässt eine kryptische Abschiedsbemerkung.\n Kezhou steht schweigend da, ungewöhnlich niedergeschlagen. Sprich mit ihm.",
          TextMapId = "Content_120105_16"
        },
        Content_120105_2 = {
          ContentES = "„Das Timing ist entscheidend“, sagt Herr Qiu und drängt dich, aufzubrechen. Auf dem Weg nach Krähenlied-Hohl wird er dir die Quest erklären.",
          TextMapId = "Content_120105_2"
        },
        Content_120105_20 = {
          ContentES = "Von seiner Beute aufgescheucht, bricht die gewaltige Vielfach-Fangjagd-Formation aus dem Boden hervor und schließt dich in dem uralten Mechanismus ein. Finde einen Weg zur Flucht.",
          TextMapId = "Content_120105_20"
        },
        Content_120105_3 = {
          ContentES = "Herr Qiu behauptet, du seist hier, um einen Bi'an als Trophäe für seine Sammlung zu fangen.\n Dieser wurde tief ins Krähenlied-Hohl getrieben – aber Überreste alter Kriegstechnologie könnten den Plan erschweren.\n Bleib wachsam, wenn du dich auf den Weg machst.",
          TextMapId = "Content_120105_3"
        },
        Content_120106_1 = {
          ContentES = "Es ist schon eine Weile her, seit du die Zhuyin-Schuppen geliefert hast. Du fragst dich, wie Zhiliu mit den Vorbereitungen vorankommt.\n Gehe zurück nach EverSpring und schau, ob du irgendwie helfen kannst.",
          TextMapId = "Content_120106_1"
        },
        Content_120106_2 = {
          ContentES = "Unheilvolle Erschütterungen kommen aus Richtung des Altars. Laut Wangchun hat Zhiliu mit dem Siegelritual angefangen.\n Du beschließt, ihr zu helfen – in Zeiten wie diesen zählt jede Hilfe.",
          TextMapId = "Content_120106_2"
        },
        Content_120106_3 = {
          ContentES = "Du kommst gerade rechtzeitig, um zu sehen, dass Zhuyin kaum noch zu bändigen ist.\n Ein Teil des Siegels bricht zusammen und Zhiliu kann ihren Posten nicht verlassen. Du bietest an, es zu überprüfen und zu stabilisieren.",
          TextMapId = "Content_120106_3"
        },
        Content_120106_6 = {
          ContentES = "Als du näher kommst, erhebt sich ein leiser, trauriger Schrei aus Zhuyins Innerstem.\n Das Siegel versagt – Zhuyin befreit sich. In der Sekunde vor der Katastrophe drückst du Zhilius Münze auf ihre Stirn und nutzt die letzten Reste der Siegelkraft, um sie zu Fall zu bringen. Für einen Herzschlag überschwemmen Fragmente ihrer Erinnerungen deinen Geist.\n Keine Zeit zum Nachdenken – der eigentliche Kampf beginnt jetzt.",
          TextMapId = "Content_120106_6"
        },
        Content_120106_7 = {
          ContentES = "Zhiliu wendet sich ohne Vorwarnung gegen dich und fesselt dich – die Versiegelung war nur ein Trick. Sie ist gekommen, um Zhuyins Kraft zu absorbieren, und deine unerwartete Anwesenheit hätte beinahe ihren Plan durchkreuzt.\n Fushu und Kezhou kommen einen Moment zu spät. Nachdem sie ihren Erfolg erzielt hat, zieht sich Zhiliu zurück und lässt dich inmitten der Trümmer zurück.\n Berate dich mit ihnen, wie es weitergehen soll.",
          TextMapId = "Content_120106_7"
        },
        Content_120106_8 = {
          ContentES = "Du bist zufällig nach Huaxu gekommen – ohne zu ahnen, dass du in eine riesige Verschwörung verwickelt werden würdest.\n Es gibt keine schnellen Antworten. Im Moment ist es am besten, den Altar hinter sich zu lassen und weiterzugehen.",
          TextMapId = "Content_120106_8"
        },
        Content_120111_0 = {
          ContentES = "Gehe zu Finas Haus, um die Geschichte zu beginnen.",
          TextMapId = "Content_120111_0"
        },
        Content_120111_1 = {
          ContentES = "Der große Magier hat den stärksten Schutzzauber gewirkt, den er kennt. Sei jetzt mutig – geh nach draußen und mach dich auf den Weg in die weite, weite Welt.",
          TextMapId = "Content_120111_1"
        },
        Content_120111_1_1 = {
          ContentES = "Ein neuer Tag bricht an. Blättere durch die unvollendete Geschichte von gestern und stell dir die nächste Seite vor.",
          TextMapId = "Content_120111_1_1"
        },
        Content_120111_2 = {
          ContentES = "Eine Gruppe von Kindern spielt in einer Ecke von Mist Aken. Gehe hin und sag Hallo.",
          TextMapId = "Content_120111_2"
        },
        Content_120111_3 = {
          ContentES = "Das Spiel hat begonnen – finde die versteckten Bratkartoffeln!",
          TextMapId = "Content_120111_3"
        },
        Content_120111_4 = {
          ContentES = "Das Spiel hat begonnen – finde die versteckten Bratkartoffeln!",
          TextMapId = "Content_120111_4"
        },
        Content_120111_5 = {
          ContentES = "Eine neue Runde beginnt – gib dein Bestes, um diesmal alle Bratkartoffeln zu finden.",
          TextMapId = "Content_120111_5"
        },
        Content_120111_6 = {
          ContentES = "Öffne dein Zauberbuch und schließe „Abschied von der Höhle von gestern” ab, um zu lernen, wie man den großen Magier herbeiruft.",
          TextMapId = "Content_120111_6"
        },
        Content_120111_7 = {
          ContentES = "Der große Magier scheint herausgefunden zu haben, wo sich eine Bratkartoffel versteckt – folge ihm und sieh selbst.",
          TextMapId = "Content_120111_7"
        },
        Content_120111_8 = {
          ContentES = "Der große Magier scheint herausgefunden zu haben, wo sich eine Bratkartoffel versteckt – folge ihm und sieh selbst.",
          TextMapId = "Content_120111_8"
        },
        Content_120111_9 = {
          ContentES = "Der Schutzzauber wirkt nur bei Tageslicht – komm vor Einbruch der Nacht nach Hause und ruhe dich aus.",
          TextMapId = "Content_120111_9"
        },
        Content_120112_0 = {
          ContentES = "Gehe zu Finas Haus, um die Geschichte fortzusetzen.",
          TextMapId = "Content_120112_0"
        },
        Content_120112_1 = {
          ContentES = "Ein neuer Tag bricht an. Gehe nach draußen und mach dich auf zu einem neuen Abenteuer.",
          TextMapId = "Content_120112_1"
        },
        Content_120112_2 = {
          ContentES = "Gestern hast du Mist Aken erkundet. Heute wartet ein ganz neues Reich darauf, entdeckt zu werden.",
          TextMapId = "Content_120112_2"
        },
        Content_120112_3 = {
          ContentES = "{性别:Kleiner Gehilfe|Kleine Gehilfe} der schweigsamen Detektivin – los geht's! Tonne 7 muss gründlich untersucht werden!",
          TextMapId = "Content_120112_3"
        },
        Content_120112_3_1 = {
          ContentES = "Diesmal gibt es keine Hinweise – aber {性别:ein echter kleiner Gehilfe|eine echte kleine Gehilfe} meldet sich immer zurück. Gehe zurück zur schweigenden Detektivin.",
          TextMapId = "Content_120112_3_1"
        },
        Content_120112_3_2 = {
          ContentES = "Beflügelt von den Worten der schweigenden Detektivin beschließt du, die größte Tonne 9 nach Hinweisen zu durchsuchen!",
          TextMapId = "Content_120112_3_2"
        },
        Content_120112_4 = {
          ContentES = "Öffne dein Zauberbuch und schließe „Durch das Labyrinth der Erinnerung” ab, um zu lernen, wie man {性别:Herr|Frau} Einhorn beschwört.",
          TextMapId = "Content_120112_4"
        },
        Content_120112_5 = {
          ContentES = "{性别:Herr|Frau} Einhorn scheint zu wissen, wo der Hinweis versteckt ist – gehe hinterher und überzeuge dich selbst.",
          TextMapId = "Content_120112_5"
        },
        Content_120112_5_1 = {
          ContentES = "Von {性别:Herrn|Frau} Einhorn geführt, kommst du an den Ort. Schau genau hin – der Hinweis könnte in der Nähe sein.",
          TextMapId = "Content_120112_5_1"
        },
        Content_120112_5_2 = {
          ContentES = "Du hast einen wichtigen Hinweis gefunden – gib ihn der schweigenden Detektivin zur Untersuchung.",
          TextMapId = "Content_120112_5_2"
        },
        Content_120112_6 = {
          ContentES = "Das heutige Abenteuer ist beendet. Gehe schnell nach Hause, bevor es dunkel wird, und ruh dich aus.",
          TextMapId = "Content_120112_6"
        },
        Content_120112_6_2 = {
          ContentES = "{性别:Herr|Frau} Einhorn hat etwas Seltsames entdeckt – gehe hinterher und finde heraus, was es ist.",
          TextMapId = "Content_120112_6_2"
        },
        Content_120112_7 = {
          ContentES = "Von {性别:Herrn|Frau} Einhorn geführt, bist du der echten Version von {性别:Herrn|Frau} Einhorn begegnet – was für ein wunderbarer Tag. Eile nach Hause und schreibe das heutige Abenteuer auf.",
          TextMapId = "Content_120112_7"
        },
        Content_120113_0 = {
          ContentES = "Gehe zu Finas Haus, um die Geschichte fortzusetzen.",
          TextMapId = "Content_120113_0"
        },
        Content_120113_1 = {
          ContentES = "Ein neuer Tag bricht an. Gehe nach draußen und mach dich auf zu einem neuen Abenteuer.",
          TextMapId = "Content_120113_1"
        },
        Content_120113_2 = {
          ContentES = "Gestern hast du auf dem Platz die schweigende Detektivin getroffen – wen wirst du heute wohl treffen? Gehe hin und finde es heraus.",
          TextMapId = "Content_120113_2"
        },
        Content_120113_3 = {
          ContentES = "Such zusammen mit {性别:Herrn|Frau} Einhorn auf dem Platz nach der jungen Adligen, die du gerade getroffen hast.",
          TextMapId = "Content_120113_3"
        },
        Content_120113_4 = {
          ContentES = "Du hast dich mit Cassandra verabredet. Um ihre Mission auszuführen, gehe schnell nach Hause und übe deine Magie!",
          TextMapId = "Content_120113_4"
        },
        Content_120113_5 = {
          ContentES = "Öffne dein Zauberbuch und schließe „Über das dornige Tal” ab, um zu lernen, wie man Frau Schmetterling beschwört.",
          TextMapId = "Content_120113_5"
        },
        Content_120113_6 = {
          ContentES = "Es ist spät – Zeit, sich auszuruhen.",
          TextMapId = "Content_120113_6"
        },
        Content_120114_0 = {
          ContentES = "Gehe zu Finas Haus, um die Geschichte fortzusetzen.",
          TextMapId = "Content_120114_0"
        },
        Content_120114_1 = {
          ContentES = "Der Tag der Begegnung mit Cassandra ist gekommen. Suche zuerst {性别:Herr|Frau} Einhorn und geht dann gemeinsam hin.",
          TextMapId = "Content_120114_1"
        },
        Content_120114_10_1 = {
          ContentES = "Die kleine Nachtigall hat ihren Mut gefunden – endlich breitet sie ihre Flügel aus.",
          TextMapId = "Content_120114_10_1"
        },
        Content_120114_10_2 = {
          ContentES = "Das Abenteuer endet triumphierend. Jetzt gehe mit deinen Freunden zurück.",
          TextMapId = "Content_120114_10_2"
        },
        Content_120114_10_3 = {
          ContentES = "Das Abenteuer endet triumphierend. Jetzt gehe mit deinen Freunden zurück.",
          TextMapId = "Content_120114_10_3"
        },
        Content_120114_10_4 = {
          ContentES = "Cassandra ist mit Soldaten von der Sicherheitsbehörde angekommen. Jetzt ist es sicher – gehe zu ihr und sprich mit ihr.",
          TextMapId = "Content_120114_10_4"
        },
        Content_120114_11 = {
          ContentES = "Du hast für heute Abend eine Teeparty geplant – gehe nach Hause und bereite alles vor.",
          TextMapId = "Content_120114_11"
        },
        Content_120114_12 = {
          ContentES = "Jemand klopft ... gehe nachsehen, wer da ist.",
          TextMapId = "Content_120114_12"
        },
        Content_120114_13 = {
          ContentES = "Öffne dein Zauberbuch und schließe „Zu den blühenden Feldern” ab, um zu lernen, wie man die kleine Nachtigall beschwört.",
          TextMapId = "Content_120114_13"
        },
        Content_120114_2 = {
          ContentES = "Der Tag der Begegnung mit Cassandra ist gekommen. Suche zuerst {性别:Herr|Frau} Einhorn und geht dann gemeinsam hin.",
          TextMapId = "Content_120114_2"
        },
        Content_120114_3 = {
          ContentES = "Gehe mit {性别:Herrn|Frau} Einhorn zum Treffpunkt, um Cassandra zu treffen.",
          TextMapId = "Content_120114_3"
        },
        Content_120114_3_1 = {
          ContentES = "Du hast Cassandra die „List” erklärt. Warte jetzt hier, während sie ihren Freund holt.",
          TextMapId = "Content_120114_3_1"
        },
        Content_120114_4 = {
          ContentES = "Du hättest nicht gedacht, dass er Cassandras Freund sein würde ... Gehe nach Hause und gehe ihnen aus dem Weg.",
          TextMapId = "Content_120114_4"
        },
        Content_120114_5 = {
          ContentES = "Die Kinder sagen, dass Mark vielleicht weiß, wo Savio ist – frag ihn.",
          TextMapId = "Content_120114_5"
        },
        Content_120114_5_1 = {
          ContentES = "Mark hat gesehen, wie Savio die Stadt verlassen hat – beeil dich und hol ihn ein.",
          TextMapId = "Content_120114_5_1"
        },
        Content_120114_6 = {
          ContentES = "Mark hat gesehen, wie Savio die Stadt verlassen hat – beeil dich und hol ihn ein.",
          TextMapId = "Content_120114_6"
        },
        Content_120114_7 = {
          ContentES = "Alle Anzeichen deuten auf Banditen in der Nähe von Klagendem See hin. Gehe mit {性别:Herrn|Frau} Einhorn dorthin.",
          TextMapId = "Content_120114_7"
        },
        Content_120114_8 = {
          ContentES = "Die Banditen haben Savio entführt – finde einen Weg, ihn sicher zu befreien.",
          TextMapId = "Content_120114_8"
        },
        Content_120114_9 = {
          ContentES = "Besiege die Banditen und befreie Savio.",
          TextMapId = "Content_120114_9"
        },
        Content_120114_9_1 = {
          ContentES = "Der Lärm hat Filthoiden angelockt – erledige auch sie.",
          TextMapId = "Content_120114_9_1"
        },
        Content_120201_1 = {
          ContentES = "Betritt die dunkle Kammer",
          TextMapId = "Content_120201_1"
        },
        Content_120201_10 = {
          ContentES = "Geh zur Halle des Handwerks, um den Räucherofen abzuholen",
          TextMapId = "Content_120201_10"
        },
        Content_120201_11 = {
          ContentES = "Hole den Räucherofen ab",
          TextMapId = "Content_120201_11"
        },
        Content_120201_12 = {
          ContentES = "Überprüfe das Schwarze Brett und sieh nach, was los ist.",
          TextMapId = "Content_120201_12"
        },
        Content_120201_2 = {
          ContentES = "Betritt Huaxu – Phase Ⅱ",
          TextMapId = "Content_120201_2"
        },
        Content_120201_3 = {
          ContentES = "Ruh dich aus",
          TextMapId = "Content_120201_3"
        },
        Content_120201_4 = {
          ContentES = "Kaufe Medizin",
          TextMapId = "Content_120201_4"
        },
        Content_120201_5 = {
          ContentES = "Bring Snow die Medizin zurück",
          TextMapId = "Content_120201_5"
        },
        Content_120201_6 = {
          ContentES = "Passiere auf dem Weg zur Halle der Quellen die Halle des Gerichts",
          TextMapId = "Content_120201_6"
        },
        Content_120201_7 = {
          ContentES = "Begib dich zur Halle der Quellen",
          TextMapId = "Content_120201_7"
        },
        Content_120201_8 = {
          ContentES = "Liefere die Waren ab",
          TextMapId = "Content_120201_8"
        },
        Content_120201_9 = {
          ContentES = "Begib dich zur Halle des Weihrauchs",
          TextMapId = "Content_120201_9"
        },
        Content_200101_1 = {
          ContentES = "Vor der Raststätte steht eine bekannte Gestalt, die an Snow erinnert.",
          TextMapId = "Content_200101_1"
        },
        Content_200101_2 = {
          ContentES = "Jemand hat dich von hinten begrüßt. Schau nach, wer es ist.",
          TextMapId = "Content_200101_2"
        },
        Content_200101_3 = {
          ContentES = "Die Person, die dich gerade aufgehalten hat, hat sich als Luno-Schmiedin vorgestellt.\n Laut Snow ist sie eine Älteste, obwohl alle Lunarianer, unabhängig von ihrem Alter, ein ähnliches Aussehen und eine ähnliche Statur haben.\n Als Gegenleistung für ihre Schmiedekünste hofft Luno-Schmiedin, dich auf deiner Reise begleiten zu dürfen.\n Bring sie zurück zur Raststätte.",
          TextMapId = "Content_200101_3"
        },
        Content_200101_4 = {
          ContentES = "Luno-Schmiedin ist stolz auf ihre Schmiedefähigkeiten.\n Zeit, ihr Talent auf die Probe zu stellen.",
          TextMapId = "Content_200101_4"
        },
        Content_200102_1 = {
          ContentES = "Gehe nach Hypnos’ Haus, um wie versprochen nach Psyche zu sehen.",
          TextMapId = "Content_200102_1"
        },
        Content_200102_2 = {
          ContentES = "Die Blumen, die Psyche liebevoll gepflegt hat, welken und scheinen keine Nährstoffe mehr zu bekommen.\n Um sie wiederzubeleben, braucht man spezielle Erde aus einer Höhle außerhalb von Icelake – eine einfache Aufgabe für {性别:einen Phoxjäger|eine Phoxjägerin}",
          TextMapId = "Content_200102_2"
        },
        Content_200102_3 = {
          ContentES = "Laut Psyche findet man diese spezielle Erde in einer Höhle in der Nähe von Klagendem See.\n Sammle die richtige Erde für sie.",
          TextMapId = "Content_200102_3"
        },
        Content_200102_4 = {
          ContentES = "Die Erde am Eingang der Höhle ist zu trocken, um Blumen anzubauen. Gehe tiefer hinein, um geeignete Erde zu finden.",
          TextMapId = "Content_200102_4"
        },
        Content_200102_5 = {
          ContentES = "Es war eine Herausforderung, aber du hast endlich weichen, geeignete Erde tief in der Höhle gefunden.\n Bring die Erde zurück zu Hypnos’ Haus. Psyche wird sich sicher riesig freuen.",
          TextMapId = "Content_200102_5"
        },
        Content_200103_1 = {
          ContentES = "Snow regt sich wieder über irgendwas in der Raststätte auf.\n Wahrscheinlich ist es nichts – aber du solltest ihr zuliebe nachsehen, was los ist.",
          TextMapId = "Content_200103_1"
        },
        Content_200103_2 = {
          ContentES = "Gerüchten zufolge streift ein riesiges Schwein in der Nähe von Icelake umher.\n Könnte das wahr sein? Wie groß könnte es sein? Am besten siehst du selbst nach ...",
          TextMapId = "Content_200103_2"
        },
        Content_200103_3 = {
          ContentES = "So viel zu den Tierfreunden – wie sich herausstellt, sind sie erbärmliche Wilderer. Gut, dass das Schwein aufgetaucht ist.\n Kämpfe Seite an Seite mit deinem neuen Verbündeten und erteile ihnen eine Lektion!",
          TextMapId = "Content_200103_3"
        },
        Content_200103_4 = {
          ContentES = "Nachdem du dich um die Wilderer gekümmert hast, hast du endlich Zeit, dir das Schwein genauer anzusehen.\n Moment mal ... hat es gerade gesprochen? Oder war das jemand anderes?",
          TextMapId = "Content_200103_4"
        },
        Content_200103_5 = {
          ContentES = "Das Geniemon-System ist jetzt freigeschaltet. Füttere ein Geniemon und freunde dich mit ihm an, damit es dich auf deiner weiteren Reise begleitet.",
          TextMapId = "Content_200103_5"
        },
        Content_200104_1 = {
          ContentES = "Die Nachricht von einem riesigen Schwein hat auch die Asphodel erreicht ... Könnte Truffle noch in der Nähe sein?\n Frag lieber Camilla, was los ist.",
          TextMapId = "Content_200104_1"
        },
        Content_200104_3 = {
          ContentES = "Es stellt sich heraus, dass Truffle noch immer in der Nähe von Icelake herumlungert. Könnten die Geniemon-Wilderer zurückgekehrt sein?\n Suche sie lieber. Sie könnte Hilfe brauchen.",
          TextMapId = "Content_200104_3"
        },
        Content_200104_4 = {
          ContentES = "Es waren also diese elenden Wilderer, die immer noch versuchen, den Geniemon Schaden zuzufügen.\n Dafür werden sie bezahlen müssen – aber zuerst musst du sie aufspüren ...",
          TextMapId = "Content_200104_4"
        },
        Content_200104_5 = {
          ContentES = "Zurück in die Kanalisation ... Warum verstecken sich alle Bösewichte so gern im Dreck?\n Beeile dich lieber und finde die Geniemon, bevor sie sich zu sehr an den Gestank gewöhnen.",
          TextMapId = "Content_200104_5"
        },
        Content_200104_6 = {
          ContentES = "Der Gestank verwirrt Filberts Nase ... aber ein schlau aussehender Geniemon taucht auf, als würde er den Weg weisen.\n Folge dem Geniemon.",
          TextMapId = "Content_200104_6"
        },
        Content_200104_7 = {
          ContentES = "Du hast die Geniemon-Wilderer tief in den Abwasserkanälen gefunden. Sie scheinen in Erinnerungen an die Vergangenheit zu schwelgen und von der Zukunft zu träumen.\n Es ist Zeit, ihnen etwas Verstand einzubläuen – egal, was ihre Hintergrundgeschichte ist.",
          TextMapId = "Content_200104_7"
        },
        Content_200104_8 = {
          ContentES = "Du hast viele neue Geniemon-Freunde gefunden – das ist schön, aber sich um so viele zu kümmern, könnte eine Herausforderung sein.\n Frag lieber Camilla. Wenn jemand helfen kann, dann Camilla. Wahrscheinlich. Hoffentlich.",
          TextMapId = "Content_200104_8"
        },
        Content_200104_9 = {
          ContentES = "Nimm die Geniemon mit und lass sie frei. Hilf ihnen mit Freundlichkeit im Herzen, ihren Weg nach draußen zu finden. Lass die dunklen Kanalisationen hinter dir und kehre zum Licht zurück.",
          TextMapId = "Content_200104_9"
        }
      }
    end
  },
  {
    MinKey = "Content_200201_1",
    MaxKey = "Content_200305_1",
    Loader = function()
      return {
        Content_200201_1 = {
          ContentES = "Sally ist eine warmherzige ältere Frau, die am Seitentor von Icelake lebt. In ihrer Nähe riecht es immer nach leckerer Pilzcremesuppe.\n Allerdings wirkt sie in letzter Zeit ziemlich abgelenkt. Vielleicht ist es ein guter Zeitpunkt für ein tröstendes Gespräch.",
          TextMapId = "Content_200201_1"
        },
        Content_200201_2 = {
          ContentES = "Frau Sally scheint sich Sorgen um eine Frau zu machen, die ihr am Herzen liegt. Wenn du diese Frau triffst, kannst du ihr vielleicht helfen.",
          TextMapId = "Content_200201_2"
        },
        Content_200201_3 = {
          ContentES = "Frau Hilin wartet schon seit Jahren auf einen Charon namens Hamel Dickinson. Sie sieht sehr verzweifelt aus. Hilf Frau Hilin, Hinweise zu Hamel Dickinson zu finden.",
          TextMapId = "Content_200201_3"
        },
        Content_200201_4 = {
          ContentES = "Begib dich in die Tiefen der Grube, um Hinweise auf den Verbleib von Hamel Dickinson zu finden.",
          TextMapId = "Content_200201_4"
        },
        Content_200201_5 = {
          ContentES = "In den Tiefen der Grube hast du ein altes Tagebuch entdeckt, auf dessen Titelseite der Name Hamel Dickinson steht.\n Es scheint Ereignisse zu dokumentieren, die mit Hammer in Verbindung stehen. Gehe zurück nach Icelake und gib das Tagebuch Frau Hilin.",
          TextMapId = "Content_200201_5"
        },
        Content_200201_6 = {
          ContentES = "Nachdem sie das Tagebuch gelesen hat, bittet Frau Hilin um etwas Zeit für sich allein.\n Sprich mit ihrer Zofe Sally, um deine Belohnung einzufordern – und den Rest der Geschichte zu hören.",
          TextMapId = "Content_200201_6"
        },
        Content_200201_7 = {
          ContentES = "Du hast das Tagebuch geheim gehalten – vielleicht ist das auch besser so.\n Suche Frau Hilins Zofe Sally, um deine Belohnung einzufordern und die Geschichte von Frau Hilin und Hamel Dickinson zu erfahren.",
          TextMapId = "Content_200201_7"
        },
        Content_200202_1 = {
          ContentES = "Ein Mann in der Nähe des Stadttors schreit laut, er scheint etwas zu verkaufen.",
          TextMapId = "Content_200202_1"
        },
        Content_200202_2 = {
          ContentES = "Martin, der behauptet, der König der Plünderer in Icelake zu sein, hat dir einige verlorene Gegenstände gegeben und möchte, dass du ihre Besitzer findest.",
          TextMapId = "Content_200202_2"
        },
        Content_200202_3 = {
          ContentES = "Papiersterne aus abgelaufenen Zugtickets ... Vielleicht ist die Ticketverkäuferin die Besitzerin.\n Allerdings wirkt sie ziemlich ... „höflich”.",
          TextMapId = "Content_200202_3"
        },
        Content_200203_1 = {
          ContentES = "Die Frau mit der heiseren Stimme und den schmutzigen, eleganten Kleidern\n hielt immer wieder Passanten an, als würde sie etwas suchen ...",
          TextMapId = "Content_200203_1"
        },
        Content_200203_12 = {
          ContentES = "Seit du diese traurige Frau zurückgelassen hast, fühlst du dich beobachtet. Sie scheint etwas zu sagen zu haben.",
          TextMapId = "Content_200203_12"
        },
        Content_200203_13 = {
          ContentES = "Frag herum – vielleicht weiß jemand etwas anderes.",
          TextMapId = "Content_200203_13"
        },
        Content_200203_14 = {
          ContentES = "Vielleicht gibt es noch andere, die mehr wissen – frag doch mal herum, wo der Arzt ist.",
          TextMapId = "Content_200203_14"
        },
        Content_200203_2 = {
          ContentES = "Elsas einzige Tochter Annie ist verschwunden.\n Halte in Icelake Ausschau nach jemandem, der Annie sein könnte.",
          TextMapId = "Content_200203_2"
        },
        Content_200203_3 = {
          ContentES = "Suche auch außerhalb der Stadtmauern – der Arzt ist vielleicht nicht weit weg.\n Mit etwas Glück kannst du sie noch einholen.",
          TextMapId = "Content_200203_3"
        },
        Content_200203_3_2 = {
          ContentES = "Die Filthoiden sind besiegt. Die Frau, die du gerettet hast, steht jetzt vor dir, als hätte sie dir etwas zu sagen.\n Sprich mit ihr.",
          TextMapId = "Content_200203_3_2"
        },
        Content_200203_3_3 = {
          ContentES = "Außerhalb der Stadtmauern hat eine Gruppe Filthoiden eine Frau in die Enge getrieben.\n Bekämpfe sie und bringe die Frau in Sicherheit.",
          TextMapId = "Content_200203_3_3"
        },
        Content_200203_4 = {
          ContentES = "Annie ist auf tragische Weise ums Leben gekommen, während das andere Mädchen, Alice, das Annies Kleidung bekommen hat, überlebt hat.\n Obwohl Alice die Tortur in den verschneiten Bergen überstanden hat, hat das schwere Fieber, an dem sie danach litt, ihre Erinnerungen ausgelöscht.\n Jetzt, da die Wahrheit ans Licht gekommen ist, musst du allen alles erklären.",
          TextMapId = "Content_200203_4"
        },
        Content_200203_5 = {
          ContentES = "Alice hat sich an alles erinnert.\n Jetzt sollten wir Frau Elsa von Annes Tod erzählen ...",
          TextMapId = "Content_200203_5"
        },
        Content_200203_6 = {
          ContentES = "Wir haben beschlossen, Annies Tod geheim zu halten.\n Bring jetzt „Annie” zu Frau Elsa, damit sie sich wiedersehen können.",
          TextMapId = "Content_200203_6"
        },
        Content_200204_1 = {
          ContentES = "Du hast eine Einladung von Wells bekommen. Er möchte, dass du ihn in der Asphodel triffst.",
          TextMapId = "Content_200204_1"
        },
        Content_200204_2 = {
          ContentES = "Wells hält dich für fähig und möchte einen Auftrag mit dir erledigen.",
          TextMapId = "Content_200204_2"
        },
        Content_200204_3 = {
          ContentES = [[
Du hast zugestimmt, mit Wells an dem Auftrag zu arbeiten.
 Mach dich bereit und gehe mit ihm.]],
          TextMapId = "Content_200204_3"
        },
        Content_200204_4 = {
          ContentES = [[
Wells scheint in Schwierigkeiten zu stecken ...
 Tu etwas, um ihn aus der Wut seines Schwiegervaters zu befreien.]],
          TextMapId = "Content_200204_4"
        },
        Content_200204_5 = {
          ContentES = "Resignation ist seit langem eine stille Unterströmung in Wells’ Leben. Jetzt bittet er dich nur noch, ein paar Drinks mit ihm zu nehmen.\n Du erkennst dieses Lächeln – zu müde, um echt zu sein –, aber was kannst du sonst tun? Öffne ein paar Fässer, erhebe dein Glas und trink mit ihm. Vielleicht lässt die Bitterkeit nach, wenn auch nur für eine Weile.",
          TextMapId = "Content_200204_5"
        },
        Content_200205_1 = {
          ContentES = "Vor der Taverne verkauft ein alter Mann namens Brunetto Hinweise auf einen versteckten Schatz auf einer südlichen Insel. Aber Schätze, die für bloßes Silber verkauft werden, sind selten echt. Sprich mit ihm – und versuche, ein wenig Wahrheit ans Licht zu bringen.",
          TextMapId = "Content_200205_1"
        },
        Content_200205_10 = {
          ContentES = "Du hast Brunettos Buch gefunden und einen Fisch gefangen, der auf der Purgatorio-Insel heimisch ist. Das sollte sein Heimweh für eine Weile lindern. Wenn du zurück in Icelake bist, denk daran, ihm beides zu bringen.",
          TextMapId = "Content_200205_10"
        },
        Content_200205_2 = {
          ContentES = "Im Laufe eures Gesprächs erfährst du, dass Brunetto – genau wie du – einst von der Purgatorio-Insel stammt. Als junger Mann verließ er die Insel, um die Welt zu erkunden, ohne zu ahnen, dass eine einzige Bootsfahrt zum Imperium ihn seine Heimat kosten würde. Seitdem hat er sich mit Geschichten und falschen Hoffnungen über Wasser gehalten.\n Als du ihm erzählst, was aus der Purgatorio-Insel geworden ist, regt sich etwas tief in ihm. Solltest du die Gelegenheit haben, kehre für ihn zur Purgatorio-Insel zurück, besuche sein altes Haus und bring ihm etwas aus der Heimat mit.",
          TextMapId = "Content_200205_2"
        },
        Content_200205_3 = {
          ContentES = "Du kehrst zur Purgatorio-Insel zurück. Es ist, als ob die Zeit stehen geblieben wäre – das Dorf ist noch genauso, wie die Filthoiden es verlassen haben, die Ruinen tragen noch immer ihre Spuren. Brunetto lebte einst in einer Hütte am östlichen Rand. Schau mal nach – vielleicht ist noch etwas von ihm übrig.",
          TextMapId = "Content_200205_3"
        },
        Content_200205_4 = {
          ContentES = "In Brunettos altem Zuhause findest du eine gut erhaltene Truhe – was auch immer darin liegt, muss ihm sehr viel bedeutet haben. Der Schlüssel ist jedoch nirgends zu sehen.\n Durchsuche die Umgebung – wenn du Glück hast, findest du ihn vielleicht noch.",
          TextMapId = "Content_200205_4"
        },
        Content_200205_5 = {
          ContentES = "Nach einer sorgfältigen Suche entdeckst du einen kleinen Schlüssel, der in einer Ecke einer bröckelnden Mauer steckt – seine Form passt perfekt zu Brunettos Truhe.\n Benutze ihn, um die Truhe zu öffnen und das darin Verborgene zu holen.",
          TextMapId = "Content_200205_5"
        },
        Content_200205_6 = {
          ContentES = "Du kehrst nach Icelake zurück und findest Brunetto wieder vor der Taverne, wo er Flyer für die Icelake-Fischereien verteilt. Es scheint, als hätte er endlich einen ehrlichen Weg gefunden, seinen Lebensunterhalt zu verdienen.\n Gib ihm, was du von der Purgatorio-Insel mitgebracht hast – vielleicht hat er etwas dazu zu sagen.",
          TextMapId = "Content_200205_6"
        },
        Content_200205_7 = {
          ContentES = "Du hast es geschafft, Brunettos Truhe zu öffnen – nur um darin ein einziges Buch zu finden. Als du danach greifst, scheint das Geräusch des Schlosses etwas angezogen zu haben. Filthoiden nähern sich. Mach dich bereit zum Kampf.",
          TextMapId = "Content_200205_7"
        },
        Content_200205_8 = {
          ContentES = "Der Ort, die Auseinandersetzung – alles kommt dir bekannt vor. Vor Jahren hast du dich hier mit Brunettos Enkel heftig gestritten, was in einer Schlägerei endete. Du erinnerst dich, dass ihr euch am Ende versöhnt habt, aber die Details sind verschwommen.\n Gehe auf das Dach, wo du früher gesessen hast. Vielleicht hilft dir das, deine Erinnerung aufzufrischen.",
          TextMapId = "Content_200205_8"
        },
        Content_200205_9 = {
          ContentES = "Während du auf dem Dach sitzt, taucht ein weiteres Fragment deines Lebens auf der Purgatorio-Insel – drei Brote, ein Junge mit Schluckauf, eine wiederhergestellte Freundschaft. Es stellt sich heraus, dass du und Brunetto euch schon länger kennen, als du gedacht hast. Um diese seltsame kleine Verbindung zu ehren, fang ihm einen Fisch, der auf der Purgatorio-Insel heimisch ist.",
          TextMapId = "Content_200205_9"
        },
        Content_20020605_3 = {
          ContentES = "In der Nähe von Bucks Haus entdeckst du einen leeren Milchkrug mit Alkoholresten, etwas Popcorn, das halb im Schnee vergraben ist, und eine Spur kleiner Fußabdrücke.\n Da Buck nie trinkt, sollten diese Hinweise helfen, die Liste der Verdächtigen einzugrenzen.",
          TextMapId = "Content_20020605_3"
        },
        Content_20020606_5 = {
          ContentES = "In der Nähe des Galea-Theaters fallen dir drei verdächtige Gestalten auf: ein Betrunkener, ein neugieriges Mädchen und ein Junge, der auf der Straße Snacks verkauft. Alle drei scheinen in irgendeiner Weise mit Alkohol oder Popcorn in Verbindung zu stehen. Leite aus den Hinweisen, die du gesammelt hast, ab, wer der wahrscheinlichste Täter ist.",
          TextMapId = "Content_20020606_5"
        },
        Content_200206_1 = {
          ContentES = "Gehe wie immer nach der Asphodel, um zu sehen, ob es neue Aufträge gibt. Übrigens, die Taverne scheint heute ungewöhnlich lebhaft zu sein.",
          TextMapId = "Content_200206_1"
        },
        Content_200206_2 = {
          ContentES = "Ein temperamentvoller Gast steht auf einem Tisch in der Asphodel und schwatzt unverständliche Worte – aber interessanterweise riecht er nicht nach Alkohol.\n Unterhalte dich mit Camilla und erfahre mehr über diesen Gast.",
          TextMapId = "Content_200206_2"
        },
        Content_200206_3 = {
          ContentES = "Als Dramatiker ist Herr Buck nie geizig mit seinen rhetorischen Schnörkeln und zeigt seine literarischen Fähigkeiten als professioneller Dramatiker.\n Im Moment scheint Herr Buck aber eher einen Übersetzer als Applaus zu brauchen. Versuche, seine kunstvollen Formulierungen zu verstehen.",
          TextMapId = "Content_200206_3"
        },
        Content_200206_4 = {
          ContentES = "Es stellt sich heraus, dass Herr Buck von einem nächtlichen Eindringling geplagt wird – und schon hast du eine neue Mission.\n Gehe in die Gegend um sein Haus und schau, was du finden kannst.",
          TextMapId = "Content_200206_4"
        },
        Content_200206_5 = {
          ContentES = "Wenn wirklich jemand in Herr Bucks Haus eingebrochen ist, muss er etwas zurückgelassen haben. Schau dich um – vielleicht findest du Hinweise, die es wert sind, aufgedeckt zu werden.",
          TextMapId = "Content_200206_5"
        },
        Content_200206_6 = {
          ContentES = "Nach dem Gespräch mit seinem Nachbarn erfährst du, dass die Kinder aus der Gegend Herr Bucks Haus meiden – und dass sie auch nicht in die Taverne dürfen. Damit bleibt nur noch ein Ort, an dem der Eindringling ihm begegnet sein könnte: das Galea-Theater.\n Gehe dorthin und halte Ausschau nach einem Kind, das dem Profil des Diebs der Inspiration entspricht.",
          TextMapId = "Content_200206_6"
        },
        Content_200206_7 = {
          ContentES = "Du hast den Betrunkenen und das Mädchen ausgeschlossen – übrig bleibt nur noch Arnaud, der Junge, der vor dem Theater Bier und Popcorn verkauft. Sprich mit ihm. Ein paar vorsichtige Fragen sollten reichen, um zu bestätigen, ob er derjenige ist, den du suchst.",
          TextMapId = "Content_200206_7"
        },
        Content_200206_8 = {
          ContentES = "Du hast erfahren, warum Arnaud sich um Mitternacht in Herr Bucks Haus geschlichen hat, aber nur Herr Buck hat das Recht zu entscheiden, was damit zu tun ist.\n Gehe mit Arnaud und deinen Erkenntnissen zurück nach der Asphodel.",
          TextMapId = "Content_200206_8"
        },
        Content_200206_9 = {
          ContentES = "Deine Schlussfolgerung lautet, dass ein Kind in Bucks Haus eingebrochen ist und es irgendwie geschafft hat, ihn betrunken zu machen – aber seine Identität bleibt unklar.\n Sprich mit Bucks Nachbarn, um mehr über die Leute zu erfahren, mit denen er Kontakt hatte.",
          TextMapId = "Content_200206_9"
        },
        Content_200207_1 = {
          ContentES = "Am Denkmal auf dem Silberfrieden-Platz findet gerade eine Gedenkfeier statt, zu der sich eine Schulgruppe versammelt hat. Eine Schülerin, die für ihre guten Noten geehrt wird, wird nach den Reden Blumen überreichen.\n Gehe hin und schau dir das an.",
          TextMapId = "Content_200207_1"
        },
        Content_200207_2 = {
          ContentES = "Emma, die Schülerin, die die Blumen überreicht, wirkt abgelenkt. Da sie allein ist und in Gedanken versunken scheint, ist jetzt vielleicht ein guter Zeitpunkt, um sie zu fragen, was sie beschäftigt.",
          TextMapId = "Content_200207_2"
        },
        Content_200207_3 = {
          ContentES = "Emma hat kürzlich eine ältere Charon-Frau aus den Slums kennengelernt. Wegen des heutigen Events musste Emma ihr Treffen absagen und hat dich gebeten, eine selbstgemachte Puppe in ihrem Namen zu überbringen.",
          TextMapId = "Content_200207_3"
        },
        Content_200207_4 = {
          ContentES = "In Mist Aken findest du die ältere Frau, die Emma erwähnt hat – Belinda, eine Hellseherin, die mit ihren Worten die Herzen ihrer Mitmenschen in Charon beruhigt.\n Gib ihr Emmas Geschenk.",
          TextMapId = "Content_200207_4"
        },
        Content_200207_5 = {
          ContentES = "Belinda hat bemerkt, dass du kürzlich einen geliebten Menschen verloren hast, und deutet eine mögliche Wiedervereinigung an.\n Sie möchte ein Geschenk für dich herstellen – dafür braucht sie aber einen Eisendraht, der deine Präsenz trägt. Durchsuche die Glevum-Grube, um ein passendes Stück zu finden.",
          TextMapId = "Content_200207_5"
        },
        Content_200207_6 = {
          ContentES = "Du hast den Eisendraht, der deine Präsenz trägt, von Luno-Plündererin zurückerobert. Gehe zurück nach Icelake und bringe ihn Belinda. Mal sehen, was für ein Geschenk sie für dich herstellen wird.",
          TextMapId = "Content_200207_6"
        },
        Content_200207_7 = {
          ContentES = "Gerade als du den Draht, um den Belinda gebeten hatte, in der Glevum-Grube gefunden hattest, tauchte eine Luno-Plündererin aus dem Nichts auf und schnappte ihn dir direkt vor der Nase weg. Du weißt immer noch nicht, warum eine Hellseherin ein Stück Draht braucht, das deine Präsenz trägt ... aber das heißt nicht, dass du eine kleine Diebin damit davonkommen lässt.\n Verfolge Luno-Plündererin und erteile ihr eine Lektion, die sie nicht vergessen wird.",
          TextMapId = "Content_200207_7"
        },
        Content_200208_1 = {
          ContentES = "Margie hat dir einen Schlüssel gegeben, dessen Design alte Erinnerungen weckt. Wenn du recht hast, hast du einmal ein passendes Schloss bei Henrik gesehen. Welche Geschichte verbirgt sich wohl hinter diesem Schloss?\n Gehe zu Hypnos’ Haus und finde es heraus.",
          TextMapId = "Content_200208_1"
        },
        Content_200208_2 = {
          ContentES = "Eine Frau, die du nicht kennst, räumt mit geübter Leichtigkeit Hypnos’ Haus auf. Wer auch immer sie ist, jeder, der noch hier ist, muss eine Verbindung zu Henrik haben – oder zu den Kindern, die er einst beherbergt hat.\n Sprich mit ihr und finde heraus, ob deine Vermutung stimmt.",
          TextMapId = "Content_200208_2"
        },
        Content_200208_3 = {
          ContentES = "Du hast erfahren, dass Lina einst als Haushälterin in Hypnos' Haus gearbeitet hat. Der Schlüssel von Margie könnte die Schublade öffnen, in der Henrik seine wichtigsten Unterlagen aufbewahrte.\n Finde ihn – und decke die Wahrheit hinter Hypnos' Haus auf.",
          TextMapId = "Content_200208_3"
        },
        Content_200208_4 = {
          ContentES = "Neben der Truhe, die Henrik zurückgelassen hat, entdeckst du eine verzierte Holzkiste – eine, die vorher eindeutig nicht da war. Sie fällt viel zu sehr auf, fast so, als wollte jemand sicherstellen, dass sie bemerkt wird – und das passt überhaupt nicht zu Henrik. Aber wenn er sie nicht hier zurückgelassen hat ... wer dann?\n Es gibt nur einen Weg, das herauszufinden. Öffne sie – und schaue nach, was drin ist.",
          TextMapId = "Content_200208_4"
        },
        Content_200209_1 = {
          ContentES = "Auf dem Silberfrieden-Platz siehst du Luna, eine örtliche Ärztin, die sichtlich besorgt am Straßenrand steht. Vielleicht solltest du mal nachfragen, ob sie Hilfe braucht.",
          TextMapId = "Content_200209_1"
        },
        Content_200209_2 = {
          ContentES = "Dr. Luna, die einen Stapel Rezepte umklammert, fällt dir ins Auge. Sie könnte etwas mit einem der Gegenstände zu tun haben, die du von Margie bekommen hast. Gehe zu ihr und sprich mit ihr.",
          TextMapId = "Content_200209_2"
        },
        Content_200209_3 = {
          ContentES = "Dir kommt ein Gedanke. Vielleicht könnte es etwas bewirken, wenn du dieser besorgten Ärztin, die sich so offensichtlich nach Aufmerksamkeit sehnt, deine Hilfe anbietest.",
          TextMapId = "Content_200209_3"
        },
        Content_200209_4 = {
          ContentES = "Dir kommt ein Gedanke. Vielleicht könnte es etwas bewirken, wenn du dieser besorgten Ärztin, die sich so offensichtlich nach Aufmerksamkeit sehnt, deine Hilfe anbietest.",
          TextMapId = "Content_200209_4"
        },
        Content_200209_5 = {
          ContentES = "Vielleicht findest du darin nützliche Informationen – oder sogar genau das Heilmittel, das sie braucht.",
          TextMapId = "Content_200209_5"
        },
        Content_200209_6 = {
          ContentES = "Jetzt, wo du das Heilmittel gefunden hast, ist es Zeit, zu Luna zurückzukehren und ihr deine Entdeckung mitzuteilen. Du bist dir allerdings nicht ganz sicher, was dabei herauskommen wird ...",
          TextMapId = "Content_200209_6"
        },
        Content_200209_7 = {
          ContentES = "Vertreibe die Schläger, die sie belästigen.",
          TextMapId = "Content_200209_7"
        },
        Content_200210_1 = {
          ContentES = "Du hast den Schwarzmarkt erreicht, wo dir ein zwielichtiger Händler auffällt. Stell dich ihm vor.",
          TextMapId = "Content_200210_1"
        },
        Content_200210_2 = {
          ContentES = "Folge den Anweisungen des Schwarzmarkthändlers Harlowe zum angegebenen Ort in der Nähe von Klagendem See, um die Mission zu erfüllen.",
          TextMapId = "Content_200210_2"
        },
        Content_200210_3 = {
          ContentES = "Das Zielgebiet ist von Filthoiden überrannt. Besiege sie.",
          TextMapId = "Content_200210_3"
        },
        Content_200210_4 = {
          ContentES = "Du hast die Filthoiden erfolgreich bekämpft. Jetzt ist es an der Zeit, deine verdiente Belohnung von Harlowe einzufordern.",
          TextMapId = "Content_200210_4"
        },
        Content_200210_7 = {
          ContentES = "Gerüchten zufolge gibt es in den Kanalisationen von Icelake einen geheimen Schwarzmarkt. Dort wurden schon unzählige zwielichtige Geschäfte gemacht.\n Als {性别:fähiger Phoxjäger|fähige Phoxjägerin} ist es deine Pflicht, in die Kanalisation hinabzusteigen und Nachforschungen anzustellen.",
          TextMapId = "Content_200210_7"
        },
        Content_200211_1 = {
          ContentES = "In Icelake fällt dir ein Sola-Mädchen auf, das zu glauben scheint, sie sei eine Charon. Das könnte einen Blick wert sein.",
          TextMapId = "Content_200211_1"
        },
        Content_200211_2 = {
          ContentES = "Faye, verärgert und von ihren Klassenkameraden gemobbt, ist mit bedeckten Ohren davongelaufen. Finde dieses verstörte Mädchen und tröste sie.",
          TextMapId = "Content_200211_2"
        },
        Content_200211_3 = {
          ContentES = "Nach einem kurzen Gespräch mit Faye erfährst du, dass ihre Klassenkameraden sie gemobbt haben.\n Es ist Zeit, diesen Tyrannen eine Lektion zu erteilen und Faye zu helfen, sich zu wehren.",
          TextMapId = "Content_200211_3"
        },
        Content_200211_4 = {
          ContentES = "Nach einem kurzen Gespräch mit Faye erfährst du, dass ihre Klassenkameraden sie gemobbt haben.\n Es ist Zeit, diesen Tyrannen eine Lektion zu erteilen und Faye zu helfen, sich zu wehren.",
          TextMapId = "Content_200211_4"
        },
        Content_200211_5 = {
          ContentES = "Mit deiner Hilfe hat Faye genug Mut gesammelt und sich gegen diese Tyrannen gewehrt. Wütend holten sie Verstärkung.\n Aber diese Schläger waren dir nicht gewachsen. Jetzt, wo sie sich zerstreut haben, schau nach Faye.",
          TextMapId = "Content_200211_5"
        },
        Content_200212_2 = {
          ContentES = "In der Nähe von Icelake fällt dir ein Bergmann auf, der sichtlich beunruhigt ist und neben sich einen Sack Erz liegen hat, der mit etwas befleckt ist, das wie Blut aussieht.\n Die ganze Situation kommt dir seltsam vor. Melde das Kevin, einem der Eskortensoldaten, die am Stadttor stationiert sind – das ist das Sicherste.",
          TextMapId = "Content_200212_2"
        },
        Content_200212_3 = {
          ContentES = "Wie sich herausstellt, hat Kevin schon einen Bericht darüber bekommen. Als hilfsbereiter Einwohner von Icelake erklärst du dich bereit, Kevin zu Larrys Standort zu führen, um die Sache weiter zu untersuchen.",
          TextMapId = "Content_200212_3"
        },
        Content_200212_4 = {
          ContentES = "Larry erschrickt, als er dich und Kevin sieht. Er gerät in Panik und greift verzweifelt an.\n Besiege ihn, um die Situation zu beruhigen.",
          TextMapId = "Content_200212_4"
        },
        Content_200212_5 = {
          ContentES = "Du hast es geschafft, Larry zu überwältigen, und er beruhigt sich endlich.\n Sprich jetzt mit ihm, um die ganze Geschichte aufzudecken.",
          TextMapId = "Content_200212_5"
        },
        Content_200212_6 = {
          ContentES = "Das Stück Phoxene ist mit Blut verschmiert – und Larrys zitternde Stimme und seine flüchtigen Blicke sind nicht gerade beruhigend. Er fordert ein, nur ein gewöhnlicher Bergmann zu sein, besteht aber darauf, dass er einen ganzen Sack Phoxene besitzt. Irgendetwas passt hier nicht zusammen. Es könnte sich lohnen, zu untersuchen, woher das Phoxene wirklich stammt.",
          TextMapId = "Content_200212_6"
        },
        Content_200212_7 = {
          ContentES = "Der Sack Phoxene hat eindeutig eine fragwürdige Herkunft. Er wird kaum sauberer aussehen, egal in wessen Tasche er landet – warum also sollte er nicht dir gehören? Gehe zurück zu Larry.",
          TextMapId = "Content_200212_7"
        },
        Content_200212_8 = {
          ContentES = "Larrys Verstand beginnt zu zerfallen. Sein zerbrechliches Ego und die Schuldgefühle, die ihn seit seiner Tat quälen, haben ihn zerrissen. Jetzt, wo sein Traumleben zusammenbricht, lässt er seine Verzweiflung an dir aus. Verteidige dich – und hilf ihm, sich der Wahrheit zu stellen, vor der er wegläuft.",
          TextMapId = "Content_200212_8"
        },
        Content_200213_1 = {
          ContentES = "Du bist jetzt schon eine Weile in Icelake. Trotz der unerbittlichen Kälte ist Margie ein Leuchtfeuer der Wärme in den Slums – man sieht sie immer dabei, wie sie Hilfsgüter an Bedürftige verteilt.\n Es ist schon eine Weile her, seit du ihr geholfen hast, den Dieb in der Kanalisation zu verfolgen. Es ist Zeit, dich mit ihr zu treffen.",
          TextMapId = "Content_200213_1"
        },
        Content_200213_2 = {
          ContentES = "Wie Margie sagte, können Dinge, die wertlos erscheinen, manchmal einen großen Wert haben. Sogar die Mülltonnen, die in der Stadt verstreut sind, könnten unbekannte Geschichten verbergen.\n Die 3 Gegenstände, die du von Margie bekommen hast – ein Rezept, eine Schachtel mit Papiersternen und ein Schlüssel – bergen jeweils ein Geheimnis. Folge den Hinweisen auf diesen 3 Gegenständen, um die Geschichten hinter ihnen aufzudecken!",
          TextMapId = "Content_200213_2"
        },
        Content_200213_3 = {
          ContentES = "Nachdem du die Geschichten der 3 Gegenstände, die du von Margie bekommen hast, untersucht hast, hat sich deine Sicht auf Icelake verändert.\n Gehe zurück zu Mist Aken und schau nach Margie.",
          TextMapId = "Content_200213_3"
        },
        Content_200213_4 = {
          ContentES = "Nachdem du die Geschichten hinter den drei Gegenständen untersucht hast, ist es Zeit, Margie zu treffen und ihr deine Erkenntnisse mitzuteilen.",
          TextMapId = "Content_200213_4"
        },
        Content_200215_1 = {
          ContentES = "Marcus, ein Koch mit einer Leidenschaft für kulinarische Experimente, ist immer auf der Suche nach neuen Zutaten. Du kennst einen guten Angelplatz in der Nähe von Klagendem See. Gehe dorthin und schau, ob du etwas Besonderes für ihn fangen kannst.",
          TextMapId = "Content_200215_1"
        },
        Content_200215_2 = {
          ContentES = "Wirf deine Angel aus und fang eine Phoxene-Forelle für Marcus. Dieses Mal ist er auf der Suche nach einem bestimmten Geschmack – hoffen wir, dass das Gericht seinen Geschmack trifft.",
          TextMapId = "Content_200215_2"
        },
        Content_200215_3 = {
          ContentES = "Du hast die Zutaten für die Marinade gesammelt, die Marcus braucht. Bring sie ihm.",
          TextMapId = "Content_200215_3"
        },
        Content_200215_4 = {
          ContentES = "Auch wenn seine Gerichte immer noch schwer verdaulich sind, hast du zugestimmt, Marcus’ kulinarischer Partner zu sein.\n Mal sehen, was seine nächste kulinarische Kreation sein wird.",
          TextMapId = "Content_200215_4"
        },
        Content_200215_41 = {
          ContentES = "Du bist immer noch skeptisch. Aber da du den Fisch selbst gefangen hast, kannst du Marcus’ Kochkünste auch mal probieren.",
          TextMapId = "Content_200215_41"
        },
        Content_200215_5 = {
          ContentES = "Tolle Arbeit – niemand kann so gut mit einer Angel umgehen wie du! Bring jetzt die frisch gefangene Phoxene-Forelle zu Marcus.",
          TextMapId = "Content_200215_5"
        },
        Content_200215_6 = {
          ContentES = "Tolle Arbeit – niemand kann so gut mit einer Angel umgehen wie du! Bring jetzt die frisch gefangene Phoxene-Forelle zu Marcus.",
          TextMapId = "Content_200215_6"
        },
        Content_200215_7 = {
          ContentES = "Es ist schon eine Weile her, seit du Marcus das letzte Mal gesehen hast. Du fragst dich, wie es dem hartnäckigen Koch mit seinen kulinarischen Kreationen geht.\n Du hast gehört, dass er in letzter Zeit oft am Stadttor rumhängt. Gehe mal nachsehen, wie es ihm geht.",
          TextMapId = "Content_200215_7"
        },
        Content_200215_8 = {
          ContentES = "Marcus sitzt auf einer Bank am Tor von Icelake. Sprich mit ihm.",
          TextMapId = "Content_200215_8"
        },
        Content_200216_1 = {
          ContentES = "Du hast von einer seltsamen Schatztruhe vor Icelake gehört. Schau sie dir an.",
          TextMapId = "Content_200216_1"
        },
        Content_200216_2 = {
          ContentES = "Du findest die Truhe am Straßenrand, aber sie scheint nichts Besonderes zu sein.\n Denk nicht zu viel darüber nach – öffne sie einfach.",
          TextMapId = "Content_200216_2"
        },
        Content_200216_3 = {
          ContentES = "Als du versuchst, die Truhe zu öffnen, tauchen plötzlich drei Männer auf, die sich die Kaiserlichen Drei nennen und einfordern, dass die Truhe ihnen gehört.\n Da es nichts bringt, mit ihnen zu diskutieren, musst du die Sache wohl auf die harte Tour klären.",
          TextMapId = "Content_200216_3"
        },
        Content_200216_4 = {
          ContentES = "Nachdem du die Kaiserlichen Drei besiegt hast, scheinen sie dir etwas mitteilen zu wollen.",
          TextMapId = "Content_200216_4"
        },
        Content_200217_1 = {
          ContentES = "Dean, ein Spirituosenverkäufer vor der Asphodel, scheint sich über Camilla zu beschweren. Finde heraus, was los ist.",
          TextMapId = "Content_200217_1"
        },
        Content_200218_1 = {
          ContentES = "Du befindest dich wieder hier. Die letzten zitternden Worte dieses süßen Mädchens scheinen noch immer in der Luft zu hallen.\n In diesem Moment murmelt eine mysteriöse Frau leise vor sich hin, als würde sie beten. Ihr Flüstern klingt wie ein Segen von Mutter Embla und spendet Trost für die traurige Seele, die über diesen frostigen Klippen schwebt ...",
          TextMapId = "Content_200218_1"
        },
        Content_200219_1 = {
          ContentES = "Außerhalb von Icelake fährt der Zug unermüdlich im Kreis. Mit seinem heulenden Pfeifen bringt er Gäste aus der Ferne herbei und schickt zugleich mutige Reisende wieder fort.\n Heute scheint etwas mit dem Ticketschalter nicht zu stimmen – es könnte sich lohnen, dem nachzugehen.",
          TextMapId = "Content_200219_1"
        },
        Content_200219_2 = {
          ContentES = "Dieser ausländische Händler scheint in Schwierigkeiten zu sein. Sprich mit ihm.",
          TextMapId = "Content_200219_2"
        },
        Content_200219_3 = {
          ContentES = "Als {性别:warmherziger Phoxjäger|warmherzige Phoxjägerin} ist es undenkbar, einen Reisenden in Not zu ignorieren. Es ist Zeit, die Angelegenheit mit dem unfreundlichen Ticketverkäufer zu klären.",
          TextMapId = "Content_200219_3"
        },
        Content_200219_4 = {
          ContentES = "Der alte Trödelsammler wirft dir immer wieder Blicke zu, als würde er versuchen, den Mut aufzubringen, etwas zu sagen. Vielleicht lohnt es sich, zu ihm zu gehen und ein Gespräch zu beginnen.",
          TextMapId = "Content_200219_4"
        },
        Content_200219_5 = {
          ContentES = "Hilf dem ausländischen Händler dabei, das Origami fertigzustellen – eine stille, herzliche Geste der guten Wünsche, von Hand gefertigt.",
          TextMapId = "Content_200219_5"
        },
        Content_200220_1 = {
          ContentES = "Als {性别:engagierter Phoxjäger|engagierte Phoxjägerin} legst du Wert darauf, keine interessanten Missionen zu verpassen. Gehe nach der Asphodel und hol dir ein paar neue Aufträge.",
          TextMapId = "Content_200220_1"
        },
        Content_200220_2 = {
          ContentES = "Du bemerkst einen unbekannten Kellner, der neben dem Auftragsbrett steht und vor sich hin murmelt. Stell dich ihm vor und finde heraus, was ihn beschäftigt.",
          TextMapId = "Content_200220_2"
        },
        Content_200220_3 = {
          ContentES = "Nachdem du mit Outsider ein Team gebildet hast, schlägt Snow einen Wettbewerb vor, um zu entscheiden, wer die Ehre hat, deinem neuen Team einen Namen zu geben.",
          TextMapId = "Content_200220_3"
        },
        Content_200220_4 = {
          ContentES = "Nachdem du mit Outsider ein Team gebildet hast, schlägt Snow einen Wettbewerb vor, um zu entscheiden, wer die Ehre hat, deinem neuen Team einen Namen zu geben.\n Laut Snow weiß die Luno-Abenteurerin in der Nähe der Raststätte, wie der Wettbewerb funktioniert. Sprich mit ihr.",
          TextMapId = "Content_200220_4"
        },
        Content_200220_5 = {
          ContentES = [[
Mit der Luno-Abenteurerin als Richterin beginnt die erste Runde!
 Begib dich zum angegebenen Ort, um die Herausforderung zu starten.]],
          TextMapId = "Content_200220_5"
        },
        Content_200220_6 = {
          ContentES = "Die Herausforderung beginnt! Folge den leuchtenden Kreisen, die von der Luno-Abenteurerin markiert wurden, um die Ziellinie zu erreichen!",
          TextMapId = "Content_200220_6"
        },
        Content_200220_7 = {
          ContentES = [[
Mit der Luno-Abenteurerin als Richterin beginnt die zweite Runde!
 Begib dich zum angegebenen Ort, um die Herausforderung zu starten.]],
          TextMapId = "Content_200220_7"
        },
        Content_200220_8 = {
          ContentES = "Die Herausforderung beginnt! Ziele und zerplatze die von der Luno-Schmiedin hergestellten Ballons!",
          TextMapId = "Content_200220_8"
        },
        Content_200220_9 = {
          ContentES = "Herzlichen Glückwunsch! Du hast Outsider übertroffen und den Wettbewerb gewonnen.\n Jetzt hast du die Chance, dir einen coolen Namen für dein neues Phoxjäger-Team auszudenken.",
          TextMapId = "Content_200220_9"
        },
        Content_200221_1 = {
          ContentES = "In der Nähe des Auftragsbretts in der Asphodel murmelt eine junge Gelehrte vor sich hin und wirkt ziemlich unruhig. Vielleicht lohnt es sich, zu sehen, ob sie Hilfe gebrauchen kann.",
          TextMapId = "Content_200221_1"
        },
        Content_200221_2 = {
          ContentES = "Nachdem du zugestimmt hast, Shirley bei der Suche nach einem interessanten Thema zu helfen, wagst du dich an Orte, die die meisten lieber meiden würden.",
          TextMapId = "Content_200221_2"
        },
        Content_200221_3 = {
          ContentES = "Du hast nicht viel von den Abwasserkanälen erwartet – doch irgendwie hast du doch etwas gefunden. Vielleicht stimmt es ja, dass Inspiration in vergessenen Ecken zu finden ist. Als Nächstes könnte es sich lohnen, einen Blick auf die Stadtmauern zu werfen.",
          TextMapId = "Content_200221_3"
        },
        Content_200221_4 = {
          ContentES = "Ein kleiner Umweg hat zu mehr geführt, als du erwartet hast. Shirley wartet mit einer Belohnung in der Hand am Stadttor von Icelake auf dich.",
          TextMapId = "Content_200221_4"
        },
        Content_200221_5 = {
          ContentES = "An Bedürftigen mangelt es nie – und Freundlichkeit findet stets ihren Weg zurück.\n Gehe zu der Asphodel und schau, wer vielleicht Hilfe braucht. Die junge Frau, die etwas abseits steht – Frau Shirley – wirkt besonders nervös.",
          TextMapId = "Content_200221_5"
        },
        Content_200222_1 = {
          ContentES = "Eine kostenlose Fahrt in den Abwasserkanälen? Das klingt alles ziemlich zweifelhaft ... aber Dutton scheint seltsam zuversichtlich zu sein. Da es kostenlos ist, kannst du ihm genauso gut den Gefallen tun und sehen, was er sich ausgedacht hat.",
          TextMapId = "Content_200222_1"
        },
        Content_200222_2 = {
          ContentES = "Es stellt sich heraus, dass er Lucas Wasserrutsche nachgebaut hat ... mitten in der Kanalisation. Die Rohre sehen ziemlich fragwürdig aus, also lehnst du die Ehre, als Erster mitzufahren, klugerweise ab. Lass Dutton zuerst fahren.",
          TextMapId = "Content_200222_2"
        },
        Content_200222_3 = {
          ContentES = "Dutton ist am Ausgang nirgends zu sehen. Den lauten Schlägen nach zu urteilen, die durch die Rohre hallen, könnte er in ernsthaften Schwierigkeiten stecken. Du solltest ihn besser schnell finden.",
          TextMapId = "Content_200222_3"
        },
        Content_200222_4 = {
          ContentES = "Endlich findest du Dutton. Nach so einer Fahrt ist es ein Wunder, dass er noch atmet. Hoffen wir, dass das seinen Traum, weitere Fahrgeschäfte in Mist Aken zu eröffnen, nicht zunichte gemacht hat.",
          TextMapId = "Content_200222_4"
        },
        Content_200223_1 = {
          ContentES = "Theo – ein selbsternannter junger Forscher – will unbedingt alles über die Charon herausfinden. Du hast Glück, denn du bist sein allererstes Fallbeispiel.",
          TextMapId = "Content_200223_1"
        },
        Content_200224_1 = {
          ContentES = "Du triffst Theo wieder in der Nähe des Kanaleingangs. Du kannst dir genauso gut anhören, welchem interessanten Thema er diesmal nachgeht.",
          TextMapId = "Content_200224_1"
        },
        Content_200224_2 = {
          ContentES = "Aus Gründen, die nur er selbst kennt, hat Theo plötzlich Interesse an Kanalratten gefunden. Auf seine Bitte hin erklärst du dich bereit, ihm bei der Suche nach einem Nest zu helfen.",
          TextMapId = "Content_200224_2"
        },
        Content_200224_3 = {
          ContentES = "Du entdeckst eine der Ratten, nach denen Theo gesucht hat, die um eine Kurve im Tunnel huscht. Folge ihr – das Nest kann nicht mehr weit sein.",
          TextMapId = "Content_200224_3"
        },
        Content_200224_4 = {
          ContentES = "Theo trifft endlich auf seine lang ersehnten Forschungsobjekte – doch sie erweisen sich als weit weniger edel, als er sich vorgestellt hatte. Knurrend und aggressiv stürzen sie sich auf dich. Du sagst Theo, er soll weglaufen, und machst dich bereit für einen Kampf.",
          TextMapId = "Content_200224_4"
        },
        Content_200224_5 = {
          ContentES = "Nachdem die Ratten erledigt sind, ist Theos Studie abgeschlossen – und er hat einen Eindruck davon bekommen, wie es wirklich ist, ein Phoxjäger zu sein. Zeit, zu sehen, zu welchen Schlussfolgerungen er gekommen ist.",
          TextMapId = "Content_200224_5"
        },
        Content_200225_1 = {
          ContentES = "Du triffst Theo wieder in der Nähe von Hypnos' Haus. Hör dir am besten an, welcher seltsamen Idee er diesmal nachgeht.",
          TextMapId = "Content_200225_1"
        },
        Content_200225_2 = {
          ContentES = "Theo will verstehen, wie das Leben der Charons wirklich ist. Anstatt es ihm nur zu erzählen, warum zeigst du es ihm nicht einfach? Mach zunächst ein paar Fotos von ihrem Alltag.",
          TextMapId = "Content_200225_2"
        },
        Content_200225_3 = {
          ContentES = "Als Theo die Charons bei ihrem Alltag beobachtet, erkennt er, dass sie sich nicht von den Solarianern unterscheiden – sie sind keine Monster, sondern ganz normale Menschen, auch wenn die Erwachsenen ihm immer etwas anderes erzählt haben. Inspiriert eilt er zu Hypnos' Haus, um die Bewohner persönlich zu treffen.\n Aber du kennst die Wahrheit: Das Haus ist jetzt leer. Vielleicht ist es an der Zeit, Theo den anderen Grund zu verraten, warum die Charons gemieden werden – Verderbnis.",
          TextMapId = "Content_200225_3"
        },
        Content_200227_1 = {
          ContentES = "Eine neue Form des immersiven Theaters hat ihren Weg von der Republik Luca nach Icelake gefunden. Das Galea-Theater sucht Freiwillige, die an diesem künstlerischen Projekt teilnehmen möchten. Wenn du Zeit hast, schau doch mal vorbei und sprich mit der Truppe.",
          TextMapId = "Content_200227_1"
        },
        Content_200228_1 = {
          ContentES = "Die Luno-Schmiedin scheint etwas zu sagen zu haben. Sie ruft dir zu, während du vorbeigehst – am besten schaust du kurz bei ihr vorbei, wenn du Zeit hast.",
          TextMapId = "Content_200228_1"
        },
        Content_200228_2 = {
          ContentES = "Vor jedem Abenteuer ist Vorbereitung das A und O – eine Regel, die jeder angehende Entdecker befolgen sollte. Gehe zurück zur Raststätte und mach dich bereit, bevor du aufbrichst.",
          TextMapId = "Content_200228_2"
        },
        Content_200228_3 = {
          ContentES = "Eine gute Waffe ist der zuverlässigste Gefährte eines Reisenden. Lass dir von der Luno-Schmiedin zeigen, wie es geht – versuche, eine Waffe zu schmieden, die gut in deiner Hand liegt.",
          TextMapId = "Content_200228_3"
        },
        Content_200229_1 = {
          ContentES = "Du hörst jemanden in der Nähe der Raststätte deinen Namen rufen. Wenn du Zeit hast, versuche doch, der Stimme zu folgen – vielleicht braucht die Person deine Hilfe.",
          TextMapId = "Content_200229_1"
        },
        Content_200229_2 = {
          ContentES = "Die Luno-Schmiedin hat ein neues Färberezept gefunden und möchte, dass du es ausprobierst. Angesichts Amiettes nicht gerade zuverlässigem Ruf ist es nur natürlich, dass du dir ein wenig unsicher bist, was das Ergebnis angeht.",
          TextMapId = "Content_200229_2"
        },
        Content_200229_3 = {
          ContentES = "Befolge das Rezept und führe den Färbeprozess durch – natürlich alles im Namen des edlen Strebens nach Schönheit.",
          TextMapId = "Content_200229_3"
        },
        Content_200230_1 = {
          ContentES = "Ein extravaganter Mann versperrt dir den Weg und behauptet, seine Lehrerin warte auf dich. Folge ihm und schau, was los ist.",
          TextMapId = "Content_200230_1"
        },
        Content_200230_2 = {
          ContentES = "Violetta hat dir eine ungefähre Adresse für den Absender des Briefes gegeben. Frage in der Gegend nach Hinweisen.",
          TextMapId = "Content_200230_2"
        },
        Content_200230_3 = {
          ContentES = "Ein Wachposten bastelt an seinem alten Plattenspieler herum. Hilf ihm – vielleicht gibt er dir im Gegenzug einen Hinweis.",
          TextMapId = "Content_200230_3"
        },
        Content_200230_4 = {
          ContentES = "Der Plattenspieler ist repariert. Jetzt muss der Soldat sein Versprechen einlösen.",
          TextMapId = "Content_200230_4"
        },
        Content_200230_5 = {
          ContentES = "Dieser eifrige Verehrer von Violetta hat falsche Vorstellungen – beruhige ihn, auch wenn du Gewalt anwenden musst.",
          TextMapId = "Content_200230_5"
        },
        Content_200230_6 = {
          ContentES = "Der hingebungsvolle Verehrer scheint nicht zu merken, dass er seinem Idol Ärger bereitet. Hilf ihm, zur Vernunft zu kommen.",
          TextMapId = "Content_200230_6"
        },
        Content_200230_7 = {
          ContentES = "Nachdem die Lage vorerst unter Kontrolle ist, gehe zurück zu Violetta und erkläre ihr die Situation.",
          TextMapId = "Content_200230_7"
        },
        Content_200231_1 = {
          ContentES = "Ein Junge namens Lars braucht deine Hilfe. Hör dir an, was er zu sagen hat.",
          TextMapId = "Content_200231_1"
        },
        Content_200231_2 = {
          ContentES = "Folge Lars zu Donats Haus in Mist Aken.",
          TextMapId = "Content_200231_2"
        },
        Content_200231_3 = {
          ContentES = "Donat ist nicht zu Hause. Lars erinnert sich, dass er von einer Rückkehr zur Glevum-Grube gesprochen hat – begib dich dorthin und suche nach ihm.",
          TextMapId = "Content_200231_3"
        },
        Content_200231_4 = {
          ContentES = "Donat besteht darauf, tiefer in die Grube vorzudringen. Du hast Lars dein Wort gegeben – beschütze Donat und begleite ihn weiter.",
          TextMapId = "Content_200231_4"
        },
        Content_200231_5 = {
          ContentES = "Donat vertraut dir sein „Verbrechen” an, das wohl mit einem Fall von vor sechzehn Jahren zu tun hat.",
          TextMapId = "Content_200231_5"
        },
        Content_200231_6 = {
          ContentES = "Filthoiden streifen immer noch in der Nähe herum. Schalte sie aus, bevor du weitergehst.",
          TextMapId = "Content_200231_6"
        },
        Content_200232_1 = {
          ContentES = "Unheimlicher Gesang schwebt von einer nahe gelegenen Straßenecke herüber. Nimm deinen Mut zusammen und suche nach der Quelle.",
          TextMapId = "Content_200232_1"
        },
        Content_200232_2 = {
          ContentES = "Du hast die Quelle gefunden – eine seltsame Holzkiste. Vielleicht kannst du sie fragen, warum sie nachts singt.",
          TextMapId = "Content_200232_2"
        },
        Content_200232_3 = {
          ContentES = "Eine Phoxjägerin namens Giselle interessiert sich für deine seltsame Begegnung. Sie wird sich für dich umhören – im Gegenzug sollst du ein paar Kräuter für sie sammeln.",
          TextMapId = "Content_200232_3"
        },
        Content_200232_4 = {
          ContentES = "Du hast die Kräuter gesammelt, die sie benötigt. Bring sie nach der Asphodel und frage Camilla nach Giselle.",
          TextMapId = "Content_200232_4"
        },
        Content_200232_5 = {
          ContentES = "Was du gesehen hast, ergibt wenig Sinn. Gehe zurück zu Giselle und frage sie direkt.",
          TextMapId = "Content_200232_5"
        },
        Content_200232_6 = {
          ContentES = "Filthoiden schnüffeln an den Kräutern herum. Schalte sie aus, bevor du weitergehst.",
          TextMapId = "Content_200232_6"
        },
        Content_200233_1 = {
          ContentES = "Deine Hinweise deuten auf eine Entführung und Brandstiftung vor sechzehn Jahren hin. Folge den Hinweisen – und decke die Wahrheit auf, die sich darunter verbirgt.",
          TextMapId = "Content_200233_1"
        },
        Content_200233_2 = {
          ContentES = "Wenn deine Vermutungen richtig sind, steckt Giselle hinter allem – einschließlich der „Entführung” von Violettas Schülerin. Gehe zum vereinbarten Treffpunkt und schau, was sie vorhat.",
          TextMapId = "Content_200233_2"
        },
        Content_200233_3 = {
          ContentES = "Violettas Worte haben Giselle bis aufs Blut erschüttert. Halte sie auf – bevor sie etwas tut, was sie nicht rückgängig machen kann.",
          TextMapId = "Content_200233_3"
        },
        Content_200233_4 = {
          ContentES = "Violetta erkennt deine Schlussfolgerung stillschweigend an – auch wenn einige Wahrheiten noch unklar sind. Begleite sie vorerst zu einem Ort, den sie im Sinn hat.",
          TextMapId = "Content_200233_4"
        },
        Content_200233_5 = {
          ContentES = "Du hast dich entschieden, die Wahrheit zu verbergen – die Verstorbenen hätten nicht gewollt, dass ihre Geschichte begraben wird. Lass die Show weitergehen. Putini spielt weiter im Theater von Icelake.",
          TextMapId = "Content_200233_5"
        },
        Content_200233_6 = {
          ContentES = "Die Wahrheit muss ans Licht kommen – die Verstorbenen verdienen keine falschen Anschuldigungen. Violetta respektiert deine Entscheidung ... und schließt den Vorhang mit einem letzten Schwanengesang.",
          TextMapId = "Content_200233_6"
        },
        Content_200234_1 = {
          ContentES = "Du siehst die streuende Katze wieder in der Nähe des Platzes herumlungern. Sie scheint dich zu erkennen – und miaut leise.",
          TextMapId = "Content_200234_1"
        },
        Content_200234_2 = {
          ContentES = "Die Katze sprintet in Richtung Raststätte und schaut zurück, als wolle sie dich auffordern, ihr zu folgen. Folge ihr am besten und schau, wohin sie dich führt.",
          TextMapId = "Content_200234_2"
        },
        Content_200235_1 = {
          ContentES = "Schließe Mission: Absicherung einmal ab",
          TextMapId = "Content_200235_1"
        },
        Content_200235_2 = {
          ContentES = "Schließe eine Mission im Handbuch des Nachtfahrers ab",
          TextMapId = "Content_200235_2"
        },
        Content_200236_1 = {
          ContentES = "Schließe eine Verdeckte Mission: Truffle und Filbert ab, um ihre Gedankenfragmente zu bekommen.",
          TextMapId = "Content_200236_1"
        },
        Content_200236_2 = {
          ContentES = "Benutze in der Bewaffnung die Gedankenfragmente von Truffle und Filbert, um Erinnerung abzuschließen und die Figur freizuschalten.",
          TextMapId = "Content_200236_2"
        },
        Content_200301_1 = {
          ContentES = "Ein schwadronierender alter Mann hält dich mit kryptischen Worten auf. Er hat einen Auftrag für dich.",
          TextMapId = "Content_200301_1"
        },
        Content_200301_2 = {
          ContentES = "Am Rande der Gritblight-Ebene geratet ihr in Schwierigkeiten.",
          TextMapId = "Content_200301_2"
        },
        Content_200301_3 = {
          ContentES = "Jemand, den du nie erwartet hättest, taucht auf. Und doch, wenn du zurückblickst ... macht es fast Sinn.",
          TextMapId = "Content_200301_3"
        },
        Content_200301_4 = {
          ContentES = "Nachdem du mit dem alten Mann gesprochen hast, beschließt du, ihn zur Gritblight-Ebene zu begleiten. Der Weg vor euch ist gefährlich. Bleib wachsam.",
          TextMapId = "Content_200301_4"
        },
        Content_200301_5 = {
          ContentES = "Kurz nach dem Betreten der Gritblight-Ebene wirst du angegriffen. Sobald die Feinde zurückgeschlagen sind, erscheint dein Ziel vor dir – gönn dir eine kurze Rast und setze dann deinen Weg fort.",
          TextMapId = "Content_200301_5"
        },
        Content_200301_6 = {
          ContentES = "Nach vielen Wendungen bringst du den alten Mann schließlich sicher zu seinem Ziel. Es scheint, als wolle er noch mehr sagen. Sprich mit ihm.",
          TextMapId = "Content_200301_6"
        },
        Content_200301_7 = {
          ContentES = "Aus unbekannten Gründen wird dein Weg plötzlich von einem Rudel Bi'an angegriffen. Wehre sie ab.",
          TextMapId = "Content_200301_7"
        },
        Content_200302_1 = {
          ContentES = "In der Nähe des Tors von EverSpring hallen laute Stimmen aus der Ferne wider. Es stellt sich heraus, dass der Handel der Sternenweber in Huaxu durch die Plage von Zhuyin bedroht ist. Wenn du Zeit hast, hilf Zhao Qian.",
          TextMapId = "Content_200302_1"
        },
        Content_200302_2 = {
          ContentES = "Nachdem du mit dem Sternweber gesprochen hast, erklärst du dich bereit, ihn eine Zeit lang zu begleiten. Hilf ihm nun, die erste Lieferung einzusammeln.",
          TextMapId = "Content_200302_2"
        },
        Content_200302_3 = {
          ContentES = "Auf dem Weg, die Waren abzuholen, versperren mehrere Zobel-Bi'an deinen Pfad. Vertreibe sie.",
          TextMapId = "Content_200302_3"
        },
        Content_200302_4 = {
          ContentES = "Nachdem du die kandierten Früchte für die Vidofnir-Gebirge gesammelt hast, bittet Zhao Qian dich, mit ihm die zweite Lieferung abzuholen. Nach einer kurzen Rast machst du dich erneut auf den Weg.",
          TextMapId = "Content_200302_4"
        },
        Content_200302_5 = {
          ContentES = "Mit den Waren bereit bleibt nur noch, sie zum Sternkai zu bringen.",
          TextMapId = "Content_200302_5"
        },
        Content_200302_6 = {
          ContentES = "Der Ladeplatz am Sternkai ist aus irgendeinem Grund von kleinen Tieren überfüllt. Räume sie weg, lade die Waren ab und warte zusammen mit Zhao Qian auf das Eintreffen des Frachtschiffs.",
          TextMapId = "Content_200302_6"
        },
        Content_200303_1 = {
          ContentES = "Ein seltsamer Mann hält dich auf dem Schwarzmarkt an. Er scheint die Quelle der Stimme in deinem Kopf zu kennen. Hör dir an, was er zu sagen hat.",
          TextMapId = "Content_200303_1"
        },
        Content_200303_2 = {
          ContentES = "Ren Wus Geschichte klingt verdächtig – aber eine Schatzsuche kann ja nicht schaden. Folge seiner Spur und schau, was dabei rauskommt.",
          TextMapId = "Content_200303_2"
        },
        Content_200303_3 = {
          ContentES = "Die erste Suche bringt eine kleine „Überraschung”. Was nun? Finde den Ort, der im Orakel genannt wird, und schau ihn dir an.",
          TextMapId = "Content_200303_3"
        },
        Content_200303_4 = {
          ContentES = "Dass du in Gefahr gerätst, kann kein Zufall sein. Es ist Zeit herauszufinden, was Ren Wu wirklich will.",
          TextMapId = "Content_200303_4"
        },
        Content_200303_5 = {
          ContentES = "Ren Wu taucht plötzlich wieder auf und schnappt sich deinen Preis – aber irgendetwas stimmt nicht. Vielleicht gibt es einen Weg, dir zurückzuholen, was dir gehört.",
          TextMapId = "Content_200303_5"
        },
        Content_200304_1 = {
          ContentES = "Snow hat von einem Stand in der Nähe von Nebelkai gehört, der hervorragende Osmanthus-Kuchen verkauft. Geh mit ihr hin und sieh ihn dir an.",
          TextMapId = "Content_200304_1"
        },
        Content_200304_10 = {
          ContentES = "Nachdem Li die Geschichte von Yuming und Kezhou erzählt hat, verabschiedet er sich. Überbringe die Nachricht, die Kezhou dir anvertraut hat, an Yuming.",
          TextMapId = "Content_200304_10"
        },
        Content_200304_2 = {
          ContentES = "Du entdeckst den Osmanthus-Kuchenstand, den Snow vorher erwähnt hat, vor dir. Gehe hin und stelle dich in die Schlange.",
          TextMapId = "Content_200304_2"
        },
        Content_200304_3 = {
          ContentES = "Zwei kleine Jungen lösen das Rätsel, erhalten ihre kostenlosen Osmanthus-Kuchen und gehen zufrieden davon. Als du ihnen zusiehst, bekommst du selbst Lust, das Rätselspiel des Standes auszuprobieren.",
          TextMapId = "Content_200304_3"
        },
        Content_200304_4 = {
          ContentES = "Gerade als du deinen Osmanthus-Kuchen erhältst, hörst du, dass der Standbesitzer möglicherweise in Gefahr ist. Schließe dich mit Li Huan zusammen und suche nach ihm.",
          TextMapId = "Content_200304_4"
        },
        Content_200304_5 = {
          ContentES = "Li Huan folgend, findest du den Standbesitzer zusammen mit den beiden Jungen von vorher, umzingelt von einem Rudel Zobel-Bi'an. Beeile dich, sie zu retten.",
          TextMapId = "Content_200304_5"
        },
        Content_200304_6 = {
          ContentES = "Während du die Zobel-Bi'an abwehrst, taucht ein unerwarteter Verbündeter, Yuming, auf. Mit seiner Hilfe vertreibt ihr die Bestien mühelos. Sprich mit Li, dem Osmanthus-Kuchen-Hersteller, um zu erfahren, was geschehen ist.",
          TextMapId = "Content_200304_6"
        },
        Content_200304_7 = {
          ContentES = "Nach dem Gespräch begleitest du Li auf einem kurzen Spaziergang und bringst ihn sicher nach Hause.",
          TextMapId = "Content_200304_7"
        },
        Content_200304_8 = {
          ContentES = "Die Zobel-Bi'an kehren zurück und unterbrechen euer Gespräch. Vertreibe sie.",
          TextMapId = "Content_200304_8"
        },
        Content_200304_9 = {
          ContentES = "Sobald die Bedrohung vorüber ist, verstummt der alte Mann und seufzt. Gehe zu ihm und höre, was er zu sagen hat.",
          TextMapId = "Content_200304_9"
        },
        Content_200305_1 = {
          ContentES = "Ein zitterndes kleines Mädchen betet zu Lord Argent. Sieh nach, was sie erschreckt hat.",
          TextMapId = "Content_200305_1"
        }
      }
    end
  },
  {
    MinKey = "Content_200305_2",
    MaxKey = "DUNGEON_DEFENCE_112",
    Loader = function()
      return {
        Content_200305_2 = {
          ContentES = "Durch dein Gespräch erfährst du, dass in ihrem Zuhause seltsame Ereignisse vor sich gehen. Es ist eindeutig unsicher, sie dort allein zu lassen – finde heraus, was dahintersteckt.",
          TextMapId = "Content_200305_2"
        },
        Content_200305_3 = {
          ContentES = "Deine Untersuchung hat mehrere bemerkenswerte Hinweise in Linglings Zuhause aufgedeckt. Prüfe sie sorgfältig und sieh, wie sie zusammenhängen.",
          TextMapId = "Content_200305_3"
        },
        Content_200305_4 = {
          ContentES = "Deine Erkenntnisse zeigen, dass diese Störungen durch einen Wishen verursacht wurden. Rund um Nebelkai kennt niemand die Wishen besser als Fushu – suche ihre Hilfe in der Halle der Vergänglichkeit.",
          TextMapId = "Content_200305_4"
        },
        Content_200305_5 = {
          ContentES = "Laut Fushu wird Lingling mit einem Bündel Skylilien in der Lage sein, den Wishen zu sehen, der ihr Zuhause heimsucht. Sammle also einige Skylilien.",
          TextMapId = "Content_200305_5"
        },
        Content_200305_6 = {
          ContentES = "Diese Skylilien sollten ausreichen. Bring sie zurück zu Fushu in der Halle der Vergänglichkeit.",
          TextMapId = "Content_200305_6"
        },
        Content_200305_7 = {
          ContentES = "Mit den nun durch Fushus Zauber versehenen Skylilien kehre zu Linglings Zuhause zurück. Es ist Zeit, dass sie sich dem „Tätern“ der Spukereignisse stellt.",
          TextMapId = "Content_200305_7"
        },
        Content_200305_8 = {
          ContentES = "Der Wishen, der Linglings Zuhause heimsucht, ist nicht ihre Großmutter – es ist ihr Ur-Ur-Großvater, der Lingling fälschlicherweise für seine Enkelin Pingping hält. Hilf Lingling, einige Webhüpfer zu sammeln, um seinen letzten Wunsch zu erfüllen.",
          TextMapId = "Content_200305_8"
        },
        Content_200305_9 = {
          ContentES = "Mit diesen Webhüpfern sollte Linglings Ur-Ur-Großvater endlich loslassen können. Kehre zu Linglings Zuhause zurück.",
          TextMapId = "Content_200305_9"
        },
        Content_200306_1 = {
          ContentES = "Ein seltsames Zittern läuft durch den von dir getragenen Mechanischen Nexus, als wollte es dich auf etwas hinweisen. Folge seiner Führung und begib dich zum angegebenen Ort.",
          TextMapId = "Content_200306_1"
        },
        Content_200306_2 = {
          ContentES = "Meister Gongshang ist gespannt, dir die Funktionsweise der von der Jishu-Sekte entworfenen Mechanismen zu zeigen. Nach einem kurzen Austausch stimmst du zu, die nahegelegenen Apparaturen mit ihm auszuprobieren.",
          TextMapId = "Content_200306_2"
        },
        Content_200306_3 = {
          ContentES = "Nachdem du nun alle Mechanismen ausprobiert hast, teile deine Eindrücke mit Meister Gongshang.",
          TextMapId = "Content_200306_3"
        },
        Content_200307_1 = {
          ContentES = "Dem Regisseur bei der Probe helfen",
          TextMapId = "Content_200307_1"
        },
        Content_200309_1 = {
          ContentES = "In letzter Zeit haben einige Einheimische von Huaxu berichtet, dass sie beim Durchqueren der Dämmerungsschlucht plötzlich einen Schauer über den Rücken liefen – wahrscheinlich das Werk eines Wishen. Bringe Snow mit, um das Gebiet zu untersuchen.",
          TextMapId = "Content_200309_1"
        },
        Content_200309_2 = {
          ContentES = "Obwohl der Wishen namens Weisheng schon lange verstorben ist, sehnt er sich immer noch danach, das Schicksal seiner schwerkranken Frau Xianshu zu erfahren. Er glaubt, dass die Heilerin in der Halle der Vergänglichkeit mehr wissen könnte. Sprich mit Fushu.",
          TextMapId = "Content_200309_2"
        },
        Content_200309_3 = {
          ContentES = "Fushu erklärt, dass Weisheng schon lange gestorben ist und die Heilerin, die einst seine Frau behandelte, ihre ältere Schwester Fufeng war. Fufeng hinterließ mehrere Fallakten in der Halle – vielleicht enthält eine von ihnen Hinweise auf Xianshu.",
          TextMapId = "Content_200309_3"
        },
        Content_200309_4 = {
          ContentES = "Gemeinsam mit Snow hast du mehrere Fallakten in der Halle untersucht, doch keine scheint Xianshu zu betreffen. Dennoch beginnen sich die Hinweise zusammenzufügen. Sprich erneut mit Fushu.",
          TextMapId = "Content_200309_4"
        },
        Content_200309_5 = {
          ContentES = "Die Wahrheit ist nun klar, und Fushu hat ihre Gedanken darüber geteilt, wie man der armen Seele, die fast ein Jahrhundert gewartet hat, am besten die Nachricht überbringt. Kehre zu Weisheng zurück und erzähle ihm, was mit Xianshu geschehen ist.",
          TextMapId = "Content_200309_5"
        },
        Content_200309_6 = {
          ContentES = "Du hast bereits drei Fallakten aus etwa derselben Zeit untersucht, doch keine der Patientendetails passt zu denen von Weishengs Frau – bis auf eine ... Könnte die wahre Identität der Patientin tatsächlich ...? Denke sorgfältig nach, bevor du eine Entscheidung triffst.",
          TextMapId = "Content_200309_6"
        },
        Content_400111_1 = {
          ContentES = "Einst erfüllt von fröhlichem Geplauder, liegt über der Asphodel nun eine schwere Stimmung voller Seufzer. Gehe nachsehen, was passiert.",
          TextMapId = "Content_400111_1"
        },
        Content_400111_2 = {
          ContentES = "Um das Lachen nach Icelake zurückzubringen, benötigst du die Anleitung einiger Luno-Ältesten!",
          TextMapId = "Content_400111_2"
        },
        Content_400111_3 = {
          ContentES = "Die Methode der Luno-Schmiedin funktioniert nicht, also ist es Zeit, dass Luno-Dienerin die Bühne betritt.",
          TextMapId = "Content_400111_3"
        },
        Content_400111_4 = {
          ContentES = "Versuchen wir als Nächstes die Methode der Luno-Abenteurerin. Es wird schon klappen! Wahrscheinlich.",
          TextMapId = "Content_400111_4"
        },
        Content_400111_5 = {
          ContentES = "Während du draußen in der Wildnis unterwegs bist, gerätst du unerwartet in Gefahr. Hilf den Kindern, in Sicherheit zu gelangen.",
          TextMapId = "Content_400111_5"
        },
        Content_400111_6 = {
          ContentES = "Du hast alles versucht, was dir einfällt. Gibt es wirklich keinen anderen Weg, die Menschen zum Lächeln zu bringen? Denk nach ... wirklich nach ... da muss doch etwas sein.",
          TextMapId = "Content_400111_6"
        },
        Content_400111_7 = {
          ContentES = "Harte Arbeit lässt eine wahrhaft entschlossene Seele nie im Stich ... nein – eine wahrhaft entschlossene Snow! Es mag Zufall gewesen sein, aber es hat die Stimmung aller gehoben. Nennen wir das ein glückliches Ende!",
          TextMapId = "Content_400111_7"
        },
        Content_Batt01_01_01 = {
          ContentES = "Von seiner Beute aufgescheucht, bricht die gewaltige Vielfach-Fangjagd-Formation aus dem Boden hervor und schließt dich in dem uralten Mechanismus ein. Finde einen Weg zur Flucht.",
          TextMapId = "Content_Batt01_01_01"
