        Content_Batt01_04_01 = {
          ContentES = "Von seiner Beute aufgescheucht, bricht die gewaltige Vielfach-Fangjagd-Formation aus dem Boden hervor und schließt dich in dem uralten Mechanismus ein. Finde einen Weg zur Flucht.",
          TextMapId = "Content_Batt01_04_01"
        },
        Content_Batt02_01_01 = {
          ContentES = "Vom Beutetier geweckt, erhebt sich die prächtige Vielfach-Fangjagd-Formation aus der Erde und fängt dich in seinem uralten Mechanismus ein.\n Von Herrn Qiu getrennt, bemerkst du einen Fremden vor dir. Sprich mit ihm und erfahre, was geschehen ist.",
          TextMapId = "Content_Batt02_01_01"
        },
        Content_Batt02_01_02 = {
          ContentES = "Vom Beutetier geweckt, erhebt sich die prächtige Vielfach-Fangjagd-Formation aus der Erde und fängt dich in seinem uralten Mechanismus ein.\n Von Herrn Qiu getrennt triffst du einen Mann namens Kezhou. Eure Schicksale sind nun miteinander verwoben – setzt euren Weg gemeinsam fort, um einen Ausweg zu finden.",
          TextMapId = "Content_Batt02_01_02"
        },
        Content_Batt02_01_03 = {
          ContentES = "Vom Beutetier geweckt, erhebt sich die prächtige Vielfach-Fangjagd-Formation aus der Erde und fängt dich in seinem uralten Mechanismus ein.\n Von Herrn Qiu getrennt triffst du einen Mann namens Kezhou. Eure Schicksale sind nun miteinander verwoben – setzt euren Weg gemeinsam fort, um einen Ausweg zu finden.",
          TextMapId = "Content_Batt02_01_03"
        },
        Content_Batt02_01_04 = {
          ContentES = "Vom Beutetier geweckt, erhebt sich die prächtige Vielfach-Fangjagd-Formation aus der Erde und fängt dich in seinem uralten Mechanismus ein.\n Von Herrn Qiu getrennt triffst du einen Mann namens Kezhou. Eure Schicksale sind nun miteinander verwoben – setzt euren Weg gemeinsam fort, um einen Ausweg zu finden.",
          TextMapId = "Content_Batt02_01_04"
        },
        Content_Batt02_01_05 = {
          ContentES = "Vom Beutetier geweckt, erhebt sich die prächtige Vielfach-Fangjagd-Formation aus der Erde und fängt dich in seinem uralten Mechanismus ein.\n Von Herrn Qiu getrennt triffst du einen Mann namens Kezhou. Eure Schicksale sind nun miteinander verwoben – setzt euren Weg gemeinsam fort, um einen Ausweg zu finden.",
          TextMapId = "Content_Batt02_01_05"
        },
        Content_Batt02_02_01 = {
          ContentES = "Vom Beutetier geweckt, erhebt sich die prächtige Vielfach-Fangjagd-Formation aus der Erde und fängt dich in seinem uralten Mechanismus ein.\n Von Herrn Qiu getrennt triffst du einen Mann namens Kezhou. Eure Schicksale sind nun miteinander verwoben – setzt euren Weg gemeinsam fort, um einen Ausweg zu finden.",
          TextMapId = "Content_Batt02_02_01"
        },
        Content_Batt02_02_02 = {
          ContentES = "Vom Beutetier geweckt, erhebt sich die prächtige Vielfach-Fangjagd-Formation aus der Erde und fängt dich in seinem uralten Mechanismus ein.\n Von Herrn Qiu getrennt triffst du einen Mann namens Kezhou. Eure Schicksale sind nun miteinander verwoben – setzt euren Weg gemeinsam fort, um einen Ausweg zu finden.",
          TextMapId = "Content_Batt02_02_02"
        },
        Content_Batt02_02_03 = {
          ContentES = "Vom Beutetier geweckt, erhebt sich die prächtige Vielfach-Fangjagd-Formation aus der Erde und fängt dich in seinem uralten Mechanismus ein.\n Von Herrn Qiu getrennt triffst du einen Mann namens Kezhou. Eure Schicksale sind nun miteinander verwoben – setzt euren Weg gemeinsam fort, um einen Ausweg zu finden.",
          TextMapId = "Content_Batt02_02_03"
        },
