        },
        Event_Des_101001 = {
          ContentES = "Während der Aktion 7 Tage einloggen, um Belohnungen zu erhalten",
          TextMapId = "Event_Des_101001"
        },
        Event_Des_101002 = {
          ContentES = "Während der Aktion 7 Tage einloggen, um Belohnungen zu erhalten",
          TextMapId = "Event_Des_101002"
        },
        Event_Des_101003 = {
          ContentES = "Während der Aktion 7 Tage einloggen, um Belohnungen zu erhalten",
          TextMapId = "Event_Des_101003"
        },
        Event_Des_101004 = {
          ContentES = "Das Zeitalter von Loong geht hier zu Ende. Und ich werde sein Erbe antreten.\n Melde dich während der Aktion an 5 Tagen an, um Belohnungen zu erhalten.",
          TextMapId = "Event_Des_101004"
        },
        Event_Des_101005 = {
          ContentES = "Während der Aktion 7 Tage einloggen, um Belohnungen zu erhalten",
          TextMapId = "Event_Des_101005"
        },
        Event_Des_102001 = {
          ContentES = "Huaxu – ein friedliches Land, von Duftschwaden umhüllt.\n Auf Einladung bist du hierhergekommen und erwartest das Bild, das Zhiliu für dich zeichnen will: eine Szenerie zugleich zeitlos und noch nie gesehen.",
          TextMapId = "Event_Des_102001"
        },
        Event_Des_103001 = {
          ContentES = "Lass mich dich auf die endlosen Pfade der Zeit führen.",
          TextMapId = "Event_Des_103001"
        },
        Event_Des_103002 = {
          ContentES = "Zuschauer oder Protagonist – die Wahl liegt bei dir. Betritt das Geschehen, wo Mut mächtigen Gegnern begegnet ... und der Sieg auf dich wartet.",
          TextMapId = "Event_Des_103002"
        },
        Event_Des_103003 = {
          ContentES = "Schließe den Hauptauftrag „Beute gegen Jäger“ ab, um die Belohnungen zu erhalten, einschließlich des Gegenstands „Gedankenfragment: Outsider“.",
          TextMapId = "Event_Des_103003"
        },
        Event_Des_103004 = {
          ContentES = "Schließe den Hauptauftrag „Die Überwacher“ ab, um die Belohnungen zu erhalten, einschließlich des Gegenstands „Gedankenfragment: Daphne“.",
          TextMapId = "Event_Des_103004"
        },
        Event_Des_103005 = {
          ContentES = "Die Huaxu-Händlerin Zhiliu, der du einst begegnet bist, hält sich derzeit auf der Asphodel auf. Als {性别:bewährter Phoxjäger|bewährte Phoxjägerin} wurdest du empfohlen, sie bei den Vorbereitungen zu unterstützen. Sammle Materialien für Zhiliu und sichere dir großzügige Belohnungen.",
          TextMapId = "Event_Des_103005"
        },
        Event_Des_103006 = {
          ContentES = "H... Hey ... Hey, stopp, stopp, stopp! Dieses Mal machen wir es doch mal zivilisiert, ja?! Zum Beispiel ... wetten wir! Wenn du meine kleine Herausforderung schaffst, gehört die Beute dir!\n – Luno-Plündererin, zusammengesunken auf dem Boden, um Gnade flehend",
          TextMapId = "Event_Des_103006"
        },
        Event_Des_103007 = {
          ContentES = "Dies ist ein Präzisionstraining, eine Feuerprobe für deine Schießfertigkeiten. Ziel anvisieren – feuern! Erreiche alle Übungsziele.",
          TextMapId = "Event_Des_103007"
        },
        Event_Des_103008 = {
          ContentES = "Folge Luno, um den Weg nicht zu verlieren und exklusive Belohnungen zu erhalten!",
          TextMapId = "Event_Des_103008"
        },
        Event_Des_103009001 = {
          ContentES = "Während de人Aktion werden in den Missionen des Handbuchs des Nachtfahrers die Drop-Raten für Dämonenkeile erhöht. Außerdem gibt es zeitlich begrenzte Dämonenkeil-Missionen.",
          TextMapId = "Event_Des_103009001"
        },
        Event_Des_103010 = {
          ContentES = "Wenn eine junge Nachtigall aus dem Nest fliegt, sieht sie den weiten Himmel und streift über weiche Wiesen – doch sie muss sich auch kaltem Regen und tobenden Winden stellen.\n Doch das Mädchen hat beschlossen: kein Zurück mehr. Mit ihrem magischen Pinsel wird sie einen Traum in allen Farben malen und in dieser harten, unerbittlichen Welt einen Himmel finden, der für immer warm und hell ist, so wie in ihren liebsten Märchen.",
          TextMapId = "Event_Des_103010"
        },
        Event_Des_103011 = {
          ContentES = "Nach einer Reihe unerwarteter Wendungen endete das Silberkerzen-Festival, und über Icelake legte sich erneut ein Schatten.\n In diesem kritischen Moment trat die selbsternannte „Dämonenkönigin des Lichts“ auf die Bühne!",
          TextMapId = "Event_Des_103011"
        },
        Event_Des_103012 = {
          ContentES = "Schließe Mystisches Labyrinth der Schwierigkeit I–VI ab, um Belohnungen zu erhalten, einschließlich „Gedankenfragment: Lisbell“.",
          TextMapId = "Event_Des_103012"
        },
        Event_Des_103013 = {
          ContentES = "Schließe die speziellen Nebenaufträge „Oh, Geniemon!“ und „Einführung: Verdeckte Mission“ ab, um Belohnungen zu erhalten, einschließlich „Gedankenfragment: Truffle und Filbert“.",
          TextMapId = "Event_Des_103013"
        },
        Event_Des_105102011 = {
          ContentES = "In einer Mittsommernacht, unter funkelnden Sternen, ein Wald, in dem Stiefmütterchen und Schmetterlingsflügel einen zarten Reigen tanzten – ein Anblick, den sie nie zuvor gesehen hatte.",
          TextMapId = "Event_Des_105102011"
        },
        Event_Des_105102012 = {
          ContentES = "Unter Schichten aus Schleiern wird Liebe im Flüstern gestanden und mit dem Tod die Ewigkeit berührt.",
          TextMapId = "Event_Des_105102012"
        },
        Event_Des_105102013 = {
          ContentES = "Warmen Sonnenschein sammeln, fein verarbeiten und verschwenderisch verteilen!",
          TextMapId = "Event_Des_105102013"
        },
        Event_Des_105102014 = {
          ContentES = "Gezeiten, die den Staub wegspülen, Wellen, die das Herz beruhigen.",
          TextMapId = "Event_Des_105102014"
        },
        Event_Des_106001 = {
          ContentES = "Erhöhe deine Prüfungsstufe und erhalte reiche Belohnungen.",
          TextMapId = "Event_Des_106001"
        },
        Event_Des_106101 = {
          ContentES = "Kuratiertes Versiegeltes Schreiben: Elpides im Überfluss",
          TextMapId = "Event_Des_106101"
        },
        Event_Des_107001 = {
          ContentES = "Melde dich im Spiel an und erhalte Makellose Sanduhr ×10",
          TextMapId = "Event_Des_107001"
        },
        Event_Des_107002 = {
          ContentES = "Melde dich sowohl auf dem PC als auch mobil an, um Belohnungen zu erhalten, darunter den Avatarrahmen „Stilles Räuchergefäß“ und Makellose Sanduhren.",
          TextMapId = "Event_Des_107002"
        },
        Event_Des_107003 = {
          ContentES = "Der Koop-Bereich wird nach Abschluss aller Hauptaufträge des ersten Kapitels Nachtfahrer „Schwarzes Eisen & Weiße Blume“ freigeschaltet. Begib dich zum Platz von Icelake, nimm am Koop teil und erhalte wertvolle Belohnungen.",
          TextMapId = "Event_Des_107003"
        },
        Event_Des_108001 = {
          ContentES = "Der traumhafter Vogelgeist bringt dir einen neuen Zweig – und neue Prüfungen.\n Schließe die zeitlich begrenzten Prüfungen des Vogelgeistes ab, um Belohnungen zu erhalten.",
          TextMapId = "Event_Des_108001"
        },
        Event_Des_WorldLan_101001 = {
          ContentES = "In this age of splendor, we reunite.",
          TextMapId = "Event_Des_WorldLan_101001"
        },
        Event_PretextTasks2_UnlockTips = {
          ContentES = "Durch Fortschritt in der Haupthandlung freischaltbar",
          TextMapId = "Event_PretextTasks2_UnlockTips"
        },
        Event_Raid_Des = {
          ContentES = "Wettbewerb ist tief in den Knochen der Menschheit verankert — der ursprüngliche Antrieb, der unser Volk wachsen, gedeihen und bestehen ließ.\n Doch dies ist nicht das Gesetz des Dschungels. Dies ist disziplinierte Rivalität — das Feuer, das ein Team antreibt, und der Schmelztiegel, in dem Legenden geschmiedet werden.",
          TextMapId = "Event_Raid_Des"
        },
        Event_Raid_Rule = {
          ContentES = "Aktionsregeln\n 1. Der Phoxjäger-Gipfel ist in zwei Phasen unterteilt: die Gruppenphase (Vorrunden) und die Apex-Rangliste-Phase (Finale). Die Aktion beginnt mit der Gruppenphase.\n 2. In der Gruppenphase erhält dein Team Punkte basierend auf der Kampfleistung. Dein höchster Punktestand bestimmt deine Gruppenzuordnung. Die Belohnungen werden nach Gruppenplatzierung am Ende der Phase verteilt, also stelle sicher, dass du sie auf der Aktionsseite abholst. Anschließend beginnt sofort die Apex-Rangliste-Phase.\n 3. In der Apex-Rangliste-Phase erhält dein Team Rangpunkte basierend auf der Leistung in jedem Level. Dein höchster Rangpunktestand bestimmt deine Platzierung innerhalb der Gruppe. Jeder Versuch in der Apex-Rangliste-Phase verbraucht einen Team-Pass und gewährt eine bestimmte Anzahl Phoxmünzen entsprechend der erreichten Rangpunkte.\n 4. Phoxmünzen können im Apex-Shop gegen Gegenstände eingetauscht werden. Bestimmte Gegenstände werden basierend auf deinem höchsten Rangpunktestand in der Apex-Rangliste-Phase freigeschaltet.\n 5. Teams, die die Gruppenphase überspringen, werden keiner Gruppe zugeteilt und erscheinen nicht in den Gruppenranglisten während der Apex-Rangliste-Phase. Sie können jedoch weiterhin Apex-Rangliste-Herausforderungen bestreiten, um Phoxmünzen zu verdienen und diese im Apex-Shop einzutauschen, einschließlich Gegenständen, die durch das Erreichen höherer Rangpunkt-Meilensteine freigeschaltet werden.\n \n Levelregeln:\n 1. In Gruppenphasen-Herausforderungen muss die erforderliche Anzahl Gegner innerhalb des Zeitlimits besiegt werden, um das Level zu bestehen.\n 2. In Apex-Rangliste-Herausforderungen verursacht das Besiegen normaler Gegner auch zusätzlichen Schaden an extrem gefährlichen Gegnern. Das Level gilt als bestanden, wenn der extrem gefährliche Gegner innerhalb des Zeitlimits besiegt wird.\n 3. In beiden Phasen erhältst du Bonuspunkte basierend auf der verbleibenden Zeit.\n 4. Wenn du die Stufe nicht erfolgreich abschließt, erhältst du beim Ablauf des Zeitlimits Punkte basierend auf deinem Fortschritt.",
          TextMapId = "Event_Raid_Rule"
        },
        Event_Raid_Rule_Dungeon = {
          ContentES = "Levelregeln:\n 1. In Gruppenphasen-Herausforderungen muss die erforderliche Anzahl Gegner innerhalb des Zeitlimits besiegt werden, um das Level zu bestehen.\n 2. In Apex-Rangliste-Herausforderungen verursacht das Besiegen normaler Gegner auch zusätzlichen Schaden an extrem gefährlichen Gegnern. Das Level gilt als bestanden, wenn der extrem gefährliche Gegner innerhalb des Zeitlimits besiegt wird.\n 3. In beiden Phasen erhältst du Bonuspunkte basierend auf der verbleibenden Zeit.\n 4. Wenn du das Level nicht erfolgreich abschließt, erhältst du beim Ablauf des Zeitlimits dennoch Punkte basierend auf einem bestimmten Anteil deiner geschätzten Punktzahl.\n \n Aktionsregeln\n 1. Der Phoxjäger-Gipfel ist in zwei Phasen unterteilt: die Gruppenphase (Vorrunden) und die Apex-Rangliste-Phase (Finale). Die Aktion beginnt mit der Gruppenphase.\n 2. In der Gruppenphase erhält dein Team Punkte basierend auf der Kampfleistung. Dein höchster Punktestand bestimmt deine Gruppenzuordnung. Die Belohnungen werden nach Gruppenplatzierung am Ende der Phase verteilt, also stelle sicher, dass du sie auf der Aktionsseite abholst. Anschließend beginnt sofort die Apex-Rangliste-Phase.\n 3. In der Apex-Rangliste-Phase erhält dein Team Rangpunkte basierend auf der Leistung in jedem Level. Dein höchster Rangpunktestand bestimmt deine Platzierung innerhalb der Gruppe. Jeder Versuch in der Apex-Rangliste-Phase verbraucht einen Team-Pass und gewährt eine bestimmte Anzahl Phoxmünzen entsprechend der erreichten Rangpunkte.\n 4. Phoxmünzen können im Apex-Shop gegen Gegenstände eingetauscht werden. Bestimmte Gegenstände werden basierend auf deinem höchsten Rangpunktestand in der Apex-Rangliste-Phase freigeschaltet.\n 5. Teams, die die Gruppenphase überspringen, werden keiner Gruppe zugeteilt und erscheinen nicht in den Gruppenranglisten während der Apex-Rangliste-Phase. Sie können jedoch weiterhin Apex-Rangliste-Herausforderungen bestreiten, um Phoxmünzen zu verdienen und diese im Apex-Shop einzutauschen, einschließlich Gegenständen, die durch das Erreichen höherer Rangpunkt-Meilensteine freigeschaltet werden.",
          TextMapId = "Event_Raid_Rule_Dungeon"
        },
        Event_Raid_Title = {
          ContentES = "Phoxjäger-Gipfel",
          TextMapId = "Event_Raid_Title"
        },
        Event_RewardTitle_103007 = {
          ContentES = "Übungsbelohnungen",
          TextMapId = "Event_RewardTitle_103007"
        },
        Event_Rule_103002 = {
          ContentES = "<Title>Über das Immersive Theater</>\n 1. Das Immersive Theater ist in drei Abschnitte unterteilt: [Klassisches Repertoire], [Vorgestelltes Repertoire] und [Unsterbliches Repertoire]. Schließe jeden Abschnitt ab, um den nächsten freizuschalten. [Klassisches Repertoire] sind einmalige Herausforderungen. [Vorgestelltes Repertoire] und [Unsterbliches Repertoire] wechseln mit Versionsaktualisierung. [Unsterbliches Repertoire] enthält auch permanente Level, die nach Erfüllung bestimmter Bedingungen erneut gespielt werden können.\n 2. Besiege alle Gegner innerhalb des Zeitlimits, um ein Level abzuschließen. Das Abschließen eines Levels belohnt mit [Sternen] und [Eintrittskarten]. Sterne schalten Meilenstein-Belohnungen frei. Eintrittskarten können im Theater-Geschenshop gegen Gegenstände eingetauscht werden.\n 3. [Klassisches Repertoire] und [Vorgestelltes Repertoire] beinhalten zwei Runden pro Level: [Odyssee des Helden] und [Heimweg des Helden]. Für jede Runde müssen unterschiedliche Teams eingesetzt werden. Die Endbelohnungen basieren auf den insgesamt gesammelten Sternen beider Runden. [Unsterbliches Repertoire] beinhaltet nur [Odyssee des Helden].\n 4. Jede Runde besteht aus 5 Räumen, die der Reihe nach abgeschlossen werden müssen. Schließe alle Räume in [Odyssee des Helden] und [Heimweg des Helden] ab, um den nächsten Akt freizuschalten. Das Nichtbesiegen des Gegners oder Zeitüberschreitung in einem Raum verhindert den Fortschritt.\n 5. Alle Phasen verfügen über [Phasenbewertung] — ein einzigartiger Mechanismus, der während des Kampfes Buffs oder Debuffs gewährt. Du kannst deine Strategie an die aktiven Effekte anpassen.",
          TextMapId = "Event_Rule_103002"
        },
        Event_Rule_103011 = {
          ContentES = "<H>Lunos Spezialtheater – Regeln</>\n 1. Nachdem du den Auftrag „Lunos Spezialtheater“ abgeschlossen hast, kannst du dich beim Direktor Putsch im <H>Galea-Theater</> für die Aktion anmelden.\n 2. Im <H>Lunoball</> folge Lunos Anweisungen auf der Bühne und zeige die passenden <H>Geniemon</> und <H>Posen</>, um Belohnungen zu erhalten. Um die Anforderungen zu erfüllen, reicht es, denselben Typ Geniemon zu zeigen. Setze die Fertigkeit von Brobox ein, um die Anforderungen von <H>Glänzende Brobox</> und <H>Leidenschaftliche Brobox</> zu erfüllen.\n 3. Erfüllst du in jedem <H>Lunoball</> eine oder mehrere Anforderungen, erhältst du am Ende des Balls <H>Premium-Belohnungen</>.\n Jedes Konto kann während des Aktionszeitraums höchstens <H>5</>-mal <H>Premium-Belohnungen</> erhalten; danach werden selbst bei erfüllten Anforderungen nur noch <H>normale Belohnungen</> vergeben.\n Der Abstand zwischen zwei <H>Lunoballs</> beträgt eine halbe Stunde.\n 4. Im <H>Festlichen Beisammensein</> werden Belohnungen per Mail verschickt, sobald ein bestimmter Fortschritt beim Abliefern von Materialien erreicht wurde.\n 5. Im <H>Festlichen Beisammensein</> fügt die Schaltfläche [Auto. hinzufügen] die ablieferbaren Materialien automatisch entsprechend ihrer Qualität hinzu.\n 6. Im <H>Festlichen Beisammensein</> wird die Funktion [Auto. hinzufügen] deaktiviert, sobald alle Liefermeilensteine erreicht sind. Du kannst die Materialien jedoch weiterhin manuell hinzufügen und abliefern, um Aufträge abzuschließen und Belohnungen zu erhalten.",
          TextMapId = "Event_Rule_103011"
        },
