        Guide_Message_AbyssUI_1 = {
          ContentES = "<H>Immersives Theater</> ist jetzt verfügbar. Fordere Gegner heraus, die sich als Gegner verkleiden, und verbessere deine Kampffähigkeiten.",
          TextMapId = "Guide_Message_AbyssUI_1"
        },
        Guide_Message_AbyssUI_2 = {
          ContentES = "Wähle hier die Schwierigkeitsgrad des Repertoires aus.",
          TextMapId = "Guide_Message_AbyssUI_2"
        },
        Guide_Message_AbyssUI_3 = {
          ContentES = "Jedes Repertoire umfasst mehrere Akte. Wähle hier einen Akt aus, um die Herausforderung zu starten",
          TextMapId = "Guide_Message_AbyssUI_3"
        },
        Guide_Message_AbyssUI_3_Pad = {
          ContentES = "Jedes Repertoire umfasst mehrere Akte. Drücke, um einen Akt auszuwählen",
          TextMapId = "Guide_Message_AbyssUI_3_Pad"
        },
        Guide_Message_AbyssUI_4 = {
          ContentES = "Hier kannst du dir die <H>Levelbewertung</> für diesen Akt ansehen. Jede Bewertung hat einen einzigartigen Einfluss auf die Herausforderung. Triff unbedingt die richtige Wahl, um deine Herausforderung zu vereinfachen",
          TextMapId = "Guide_Message_AbyssUI_4"
        },
        Guide_Message_AbyssUI_5 = {
          ContentES = "Am Ende jedes Akts erhältst du basierend auf deinen Fortschritten eine Sternbewertung. Schließe alle Herausforderungen eines Aktes ab, um den nächsten freizuschalten",
          TextMapId = "Guide_Message_AbyssUI_5"
        },
        Guide_Message_AbyssUI_6 = {
          ContentES = "Wähle hier, um deine Herausforderungsbelohnungen zu erhalten.",
          TextMapId = "Guide_Message_AbyssUI_6"
        },
        Guide_Message_AbyssUI_7 = {
          ContentES = "Wähle hier, um dein Team für diese Herausforderung aufzustellen.",
          TextMapId = "Guide_Message_AbyssUI_7"
        },
        Guide_Message_AbyssUI_8 = {
          ContentES = "Wähle <H>Los</>, um die Herausforderung zu starten",
          TextMapId = "Guide_Message_AbyssUI_8"
        },
