          TextMapId = "MESSAGE_JUMP_PHONE"
        },
        MESSAGE_LOADING_101_PC = {
          ContentES = "Ein belebter Hafen in Nebelkai-Bezirk, das ganze Jahr über von Schiffen frequentiert. Er dient als erster Anlaufpunkt für die Sternenweber, die über den Kontinent Atlasia aufbrechen.",
          TextMapId = "MESSAGE_LOADING_101_PC"
        },
        MESSAGE_LOADING_102_PC = {
          ContentES = "Große Steintafeln, auf denen die Gesetze der Neun Kapitel eingraviert sind. An prominenten Orten in ganz Huaxu aufgestellt, dienen sie allen als stetige Erinnerung.",
          TextMapId = "MESSAGE_LOADING_102_PC"
        },
        MESSAGE_LOADING_103_PC = {
          ContentES = "Eine weite Ebene in Nebelkai-Bezirk, dicht mit hohen Schilfhalmen bewachsen, in denen man oft Smaragdfink sehen kann, wie sie durch die schwankenden Halme flattern.",
          TextMapId = "MESSAGE_LOADING_103_PC"
        },
        MESSAGE_LOADING_104_PC = {
          ContentES = "Eine bedeutende Handelsgilde auf den Ebenen von Nebelkai und der Hauptverband der Sternenweber.\n Am Fuße eines gewaltigen Baumes gelegen, wird die Gilde von einem mondförmigen Gerät gekrönt, das durch Weihrauch betrieben wird.",
          TextMapId = "MESSAGE_LOADING_104_PC"
        },
        MESSAGE_LOADING_105_PC = {
          ContentES = "Eine Küstenhöhle am westlichen Rand der Ebenen von Nebelkai. Das Echo der Gezeiten hallt endlos durch ihre Tiefen und verleiht der Höhle ihren Namen.",
          TextMapId = "MESSAGE_LOADING_105_PC"
        },
        MESSAGE_LOADING_106_PC = {
          ContentES = "Der Schwarzmarkt von Nebelkai, entlang einer westlichen Küste zwischen Schiffswracks gelegen.\n Ihre Abgeschiedenheit und die geringe Frequentierung ziehen opportunistische Händler an und machen sie zu einem Zentrum für illegale Geschäfte.",
          TextMapId = "MESSAGE_LOADING_106_PC"
        },
        MESSAGE_LOADING_107_PC = {
          ContentES = "Das alte Schlachtfeld der Schlacht von Shuli, nordwestlich von Nebelkai auf einer einsamen Insel im Meer gelegen. Einst ein zentrales Forschungsgebiet der Jishu-Sekte, wurden die meisten Konstrukte im Krieg zerstört, einige sind jedoch noch voll funktionsfähig.",
          TextMapId = "MESSAGE_LOADING_107_PC"
        },
        MESSAGE_LOADING_108_PC = {
          ContentES = "Ein Hochlandgebiet nordwestlich von Nebelkai. Von den entfesselten Energien Zhuyins durchzogen, ist es nun von Gritblight bedeckt und karg. Die Vegetation der Oberfläche ist kristallisiert, und schroffe Felsen durchziehen das Land — eine Landschaft, die als Gritblight-Ebene bekannt geworden ist.",
          TextMapId = "MESSAGE_LOADING_108_PC"
        },
        MESSAGE_LOADING_109_PC = {
          ContentES = "Eine weite Ebene in Nebelkai-Bezirk, dicht mit hohen Schilfhalmen bewachsen, in denen man oft Smaragdfink sehen kann, wie sie durch die schwankenden Halme flattern.",
          TextMapId = "MESSAGE_LOADING_109_PC"
        },
        MESSAGE_LOADING_10_PC = {
          ContentES = "Eine abgelegene Insel mitten im offenen Meer an der Grenze zwischen Hyperborea und Elysium. Die Elysianer errichteten dort vor einem Jahrtausend einen Schrein, doch heute zeugen nur noch Ruinen von seiner einstigen Pracht.",
          TextMapId = "MESSAGE_LOADING_10_PC"
        },
        MESSAGE_LOADING_110_PC = {
          ContentES = "Eine Insel im Herzen des zentralen Sees von Nebelkai, ruhig und abgeschieden unter dichtem Grün. Es heißt, dass die Wishen hier ihre Heimat haben.",
          TextMapId = "MESSAGE_LOADING_110_PC"
        },
        MESSAGE_LOADING_111_PC = {
          ContentES = "Die Ahnenklinik des Hauses Fu, ein Zweig des Zhuyou-Clans, bekannt für seine Heilkunst. Gelegen in einem Aprikosenhain im nördlichen Nebelkai, ist sie noch immer ein Ort, an dem Menschen Behandlung suchen.",
          TextMapId = "MESSAGE_LOADING_111_PC"
        },
        MESSAGE_LOADING_112_PC = {
          ContentES = "Ein Altar, errichtet von früheren Generationen, um Zhuyin zu versiegeln. Er steht über dem aufbrausenden Meer und blickt aus der Ferne auf die Gritblight-Ebene.",
          TextMapId = "MESSAGE_LOADING_112_PC"
        },
        MESSAGE_LOADING_113_PC = {
          ContentES = "Eine anomale Dimension, entstanden, als die Yu-Quelle durch den Fluch von Zhuyin verunreinigt wurde. Innerhalb dieser Dimension vergessen die Seelen allmählich alle weltlichen Bindungen und gehen für immer verloren.",
          TextMapId = "MESSAGE_LOADING_113_PC"
        },
        MESSAGE_LOADING_114_PC = {
          ContentES = "Eine anomale Dimension, entstanden, als die Yu-Quelle durch den Fluch von Zhuyin verunreinigt wurde. Innerhalb dieser Dimension vergessen die Seelen allmählich alle weltlichen Bindungen und gehen für immer verloren.",
          TextMapId = "MESSAGE_LOADING_114_PC"
        },
        MESSAGE_LOADING_115_PC = {
          ContentES = "Eine anomale Dimension, entstanden, als die Yu-Quelle durch den Fluch von Zhuyin verunreinigt wurde. Innerhalb dieser Dimension vergessen die Seelen allmählich alle weltlichen Bindungen und gehen für immer verloren.",
          TextMapId = "MESSAGE_LOADING_115_PC"
        },
        MESSAGE_LOADING_116_PC = {
          ContentES = "Eine urzeitliche mechanische Falle, lange Zeit in der Krähenlied-Hohl ruhend, wurde während Herr Qius Jagdeinsatzes versehentlich ausgelöst.",
          TextMapId = "MESSAGE_LOADING_116_PC"
        },
        MESSAGE_LOADING_117_PC = {
          ContentES = "Eine urzeitliche mechanische Falle, lange Zeit in der Krähenlied-Hohl ruhend, wurde während Herr Qius Jagdeinsatzes versehentlich ausgelöst.",
          TextMapId = "MESSAGE_LOADING_117_PC"
        },
        MESSAGE_LOADING_118_PC = {
          ContentES = "Eine urzeitliche mechanische Falle, lange Zeit in der Krähenlied-Hohl ruhend, wurde während Herr Qius Jagdeinsatzes versehentlich ausgelöst.",
          TextMapId = "MESSAGE_LOADING_118_PC"
        },
        MESSAGE_LOADING_119_PC = {
          ContentES = "Eine überraschend stattliche Residenz, verborgen in einem gestrandeten Wrack auf dem Dunstmarkt.\n Hier wartet Herr Qiu – Meister des Schwarzmarkts – still auf dein Eintreffen.",
          TextMapId = "MESSAGE_LOADING_119_PC"
        },
        MESSAGE_LOADING_11_PC = {
          ContentES = "Eine Stadt an der nördlichen Grenze des Hyperboreischen Imperiums, die untrennbar mit der Entstehung des Imperiums verbunden ist und früher ein wichtiger Phoxene-Knotenpunkt war. Die unerbittliche Kälte und die Schneestürme dienen als ihre treuesten Wächter.",
          TextMapId = "MESSAGE_LOADING_11_PC"
        },
        MESSAGE_LOADING_12_PC = {
          ContentES = "Das mit „Magie“ geborene Volk trägt den Namen Charon – dieser Name besitzt von Nation zu Nation eine sehr unterschiedliche Bedeutung. Hier im Hyperboreischen Imperium tragen sie den unheilvollen Titel „Kinder des Dämons“.",
          TextMapId = "MESSAGE_LOADING_12_PC"
        },
        MESSAGE_LOADING_13_PC = {
          ContentES = "Im Volk der Charon verfügen diejenigen, die mit besonderen Talenten geboren werden, über vielfältige magische Kräfte, die im hyperboreischen Imperium als „dämonische Künste“ gebrandmarkt werden.",
          TextMapId = "MESSAGE_LOADING_13_PC"
        },
        MESSAGE_LOADING_14_PC = {
          ContentES = "Diese Monster, die überall zu finden sind und oft in Rudeln durch die Wildnis ziehen, sind eine Gefahr, die man nicht unterschätzen sollte.",
          TextMapId = "MESSAGE_LOADING_14_PC"
        },
        MESSAGE_LOADING_15_PC = {
          ContentES = "Ein freundliches Volk, das auch als Lunos bezeichnet wird, und neben den Menschen koexistiert. Sie ähneln menschlichen Kindern, unterscheiden sich jedoch durch ihr mondhelles weißes Haar, von den sich auch der Name ableitet. Sie sind dafür bekannt, dass sie den Menschen in guter Absicht helfen wollen, aber oftmals sorgen ihre Bemühungen mehr für Chaos als für Hilfe.",
          TextMapId = "MESSAGE_LOADING_15_PC"
        },
        MESSAGE_LOADING_16_PC = {
          ContentES = "Eine imperiale Nation, die sich im Norden von Atlasia angesiedelt hat. Dieses Volk liebt militärische Eroberungen und alchemistische Fähigkeiten und steht in ständigem Konflikt mit der Elysischen Kirche.\nUnter der glorreichen Krone gedeiht ein Vermächtnis aus Tapferkeit und Eisen. Alle Ehre dem Kaiser.",
          TextMapId = "MESSAGE_LOADING_16_PC"
        },
        MESSAGE_LOADING_17_PC = {
          ContentES = "Im Süden von Atlasia befindet sich ein Königreich, das sich dem Göttlichen verschrieben hat. Es befolgt die Gebote von neun Gottheiten und wahrt eine alte, geordnete Regierungsform. Dieses prächtige, unvergängliche Land, das wie ein Stück Phoxene auf hohen Ästen thront, verspricht unvergleichliches Glück und eine strahlende Zukunft.",
          TextMapId = "MESSAGE_LOADING_17_PC"
        },
        MESSAGE_LOADING_18_PC = {
          ContentES = "Im Osten von Atlasia liegt ein Land, das sich durch prachtvolle Pavillons und Paläste auszeichnet, die das Landschaftsbild prägen. Dies ist das angestammte Land der Sternenweber, die auf dem ganzen Kontinent für ihr kaufmännisches Geschick bekannt sind.\nVon den Sternen geleitet erschaffen sie Schönheit aus den Gaben der Erde. Ihre erhabenen Gesänge werden zu Poesie, zu einer Ode, die der friedlichen Einsamkeit huldigt.",
          TextMapId = "MESSAGE_LOADING_18_PC"
        },
        MESSAGE_LOADING_19_PC = {
          ContentES = "Ducke dich und gleite durch niedrige, enge Lücken.",
          TextMapId = "MESSAGE_LOADING_19_PC"
        },
        MESSAGE_LOADING_1_PC = {
          ContentES = "Drücke &Slide& und anschließend &Jump&, um einen Spiralsprung über Klippen auszuführen oder weite Entfernungen zu überwinden.",
          TextMapId = "MESSAGE_LOADING_1_PC"
        },
        MESSAGE_LOADING_1_Phone = {
          ContentES = "Halte die Springen-Taste gedrückt und wische nach oben, um einen Spiralsprung über Klippen auszuführen oder weite Entfernungen zu überwinden",
          TextMapId = "MESSAGE_LOADING_1_Phone"
        },
        MESSAGE_LOADING_201_PC = {
          ContentES = "Östlich von Atlasia liegt ein Land mit prächtigen Pavillons und Palästen, die die Skyline beherrschen. Es ist das Stammland der Sternenweber, auf dem ganzen Kontinent für ihr Handelstalent bekannt.\n Von den Sternen geleitet, formen sie aus den Gaben der Erde Schönheit; ihre erhabenen Gesänge werden zur Poesie, eine Ode an die stille Einsamkeit.",
          TextMapId = "MESSAGE_LOADING_201_PC"
        },
        MESSAGE_LOADING_202_PC = {
          ContentES = "Ein bedeutender Hafen im Süden von Huaxu, wo Flüsse auf das Meer treffen. Nahe der alten Hauptstadt Haojing gelegen, ist er für sein mildes Klima und seine reizvollen Landschaften bekannt. Dieses Handelszentrum dient als wichtigster Anlaufpunkt für Ausländer, die Huaxu besuchen.",
          TextMapId = "MESSAGE_LOADING_202_PC"
        },
        MESSAGE_LOADING_203_PC = {
          ContentES = "Huaxus Bezeichnung für Charon.\n Anders als im Hyperboreischen Imperium gelten Charon hier als glückverheißendes Volk, das die Nation beschützt.",
          TextMapId = "MESSAGE_LOADING_203_PC"
        },
        MESSAGE_LOADING_204_PC = {
          ContentES = "Eine Katastrophe, die Huaxu heimsuchte, ausgehend von der Gritblight-Ebene und vor allem Nebelkai betreffend.\n Ihre Ausbreitung hat Handelsrouten abgeschnitten und das tägliche Leben schwer beeinträchtigt.",
          TextMapId = "MESSAGE_LOADING_204_PC"
        },
        MESSAGE_LOADING_205_PC = {
          ContentES = "Das höchste Gesetz, das ganz Huaxu regiert.\n Alle innerhalb seiner Grenzen müssen seinen Geboten folgen, andernfalls drohen Strafen, vollstreckt durch Bi’an oder den Magistrat von Yingtian.",
          TextMapId = "MESSAGE_LOADING_205_PC"
        },
        MESSAGE_LOADING_206_PC = {
          ContentES = "Als Meister der Navigation und des Handels verfügen die Sternenweber über die einzigartige Kunst der himmlischen Wegfindung, mit der sie selbst die gefährlichsten Seebedingungen überwinden. Ihr Einfluss reicht bis in die entlegensten Winkel Atlasias.",
          TextMapId = "MESSAGE_LOADING_206_PC"
        },
        MESSAGE_LOADING_207_PC = {
          ContentES = "Eine in ganz Huaxu verehrte Gottheit, dem einfachen Volk als Lord Argent bekannt. Sie gilt als Verkörperung des Himmlischen Weges und des in den Neun Kapiteln von Dafeng niedergelegten göttlichen Willens.",
          TextMapId = "MESSAGE_LOADING_207_PC"
        },
        MESSAGE_LOADING_208_PC = {
          ContentES = "Hüter und Vollstrecker Huaxus, handelnd nach dem Willen der Neun Kapitel.\n Ein göttliches Wesen mit Wolfs­haupt, tierischem Leib, weißem Fell und goldenen Hörnern.\n Werden die Neun Kapitel gebrochen, erscheint Bi’an, um das Urteil zu vollziehen.",
          TextMapId = "MESSAGE_LOADING_208_PC"
        },
        MESSAGE_LOADING_209_PC = {
          ContentES = "In ihrer Gestalt Bi’an ähnlich, jedoch pechschwarz gefärbt.\n Diese chaotischen Abscheulichkeiten sind jüngst nahe Nebelkai aufgetaucht – Ausgeburten der Plage von Zhuyin, jenseits der Kontrolle der Neun Kapitel.\n Sie greifen Reisende in der Wildnis wahllos an und gefährden die öffentliche Sicherheit schwer.",
          TextMapId = "MESSAGE_LOADING_209_PC"
        },
        MESSAGE_LOADING_20_PC = {
          ContentES = "Nutze den Spiralsprung, um dich schnell fortzubewegen – damit kannst du sogar an Orte kommen, die ansonsten nicht erreichbar sind.",
          TextMapId = "MESSAGE_LOADING_20_PC"
        },
        MESSAGE_LOADING_210_PC = {
          ContentES = "Eine in ganz Huaxu weit verbreitete Substanz, aus ausgewählten Zutaten mit speziellen Verfahren veredelt und in Riten der Zwiesprache mit dem Göttlichen verwendet. Überall im Land brennen Räucherbecken, ihr Duft liegt allgegenwärtig in der Luft, und viele Menschen tragen Räucherbeutel bei sich. Räucherwerk gilt als eines der prägenden Merkmale Huaxus.",
          TextMapId = "MESSAGE_LOADING_210_PC"
        },
        MESSAGE_LOADING_211_PC = {
          ContentES = "Eine bösartige Gottheit aus Huaxus alten Legenden, Rivale von Taihao, heute jenseits von Nebelkai versiegelt. Ihre wahnsinnige Macht ist dennoch nach außen gedrungen und hat die Plage von Zhuyin hervorgebracht.",
          TextMapId = "MESSAGE_LOADING_211_PC"
        },
        MESSAGE_LOADING_212_PC = {
          ContentES = "Vollstrecker innerhalb des Systems der Neun Kapitel, im Rang über Bi’an stehend. Auch sie sind aus Loongscions verwandelt. Nach ähnlicher Argumentation wie bei Bi’an vermuten Gelehrte, dass die Magistrate von Yingtian dem entsprechen, was gemeinhin als „Daimon“ bezeichnet würde.",
          TextMapId = "MESSAGE_LOADING_212_PC"
        },
        MESSAGE_LOADING_215_PC = {
          ContentES = "Eine von der Familie Fu, einem Zweig des Zhuyou-Clans, überlieferte Heilkunst, deren Kraft aus den Neun Kapiteln von Dafeng stammt. Der Anwender nutzt seine eigene Lebensessenz als Medium, um stagnierendes Qi und andere schädliche Krankheitsstoffe aus dem Körper des Patienten zu vertreiben. Längere Anwendung belastet den Anwender erheblich.",
          TextMapId = "MESSAGE_LOADING_215_PC"
        },
        MESSAGE_LOADING_217_PC = {
          ContentES = "Der Zhuyou-Clan war einst von den Neun Kapiteln von Dafeng mit der Gabe der Heilung gesegnet und genoss in Huaxu hohes Ansehen; ihm oblag die Pflege der Kranken.\n Mit dem Aufstieg der Heilkundelehre im vergangenen Jahrhundert sind die Zhuyou-Heilkünste jedoch zurückgegangen, und wahre Nachfolger innerhalb des Clans sind äußerst selten geworden.",
          TextMapId = "MESSAGE_LOADING_217_PC"
        },
        MESSAGE_LOADING_218_PC = {
          ContentES = "Mechanische Nexus kann eine beträchtliche Zugkraft erzeugen, wodurch er Kiesseuche von Oberflächen absorbieren oder Jishu-Sphären zu festgelegten Punkten ziehen kann.",
          TextMapId = "MESSAGE_LOADING_218_PC"
        },
        MESSAGE_LOADING_219_PC = {
          ContentES = "Mechanische Nexus kann nahegelegene Objekte scannen und interessante Punkte hervorheben.",
          TextMapId = "MESSAGE_LOADING_219_PC"
        },
        MESSAGE_LOADING_21_PC = {
          ContentES = "Nachdem du die Kampfhaltung eines Elite-Gegners vollständig gebrochen hast, kannst du „Asks Vergeltung“ entfesseln, um beträchtlichen Schaden zu verursachen.\nAsk ist der ehrwürdige Vatergott unter den Charons.",
          TextMapId = "MESSAGE_LOADING_21_PC"
        },
        MESSAGE_LOADING_220_PC = {
          ContentES = "Ein von der Jishu-Sekte gefertigtes Gerät. Dieser Würfel mit eingebettetem Energiekern wurde vom Schwarzmarkt eigens für Zhiliu angefertigt, um Zhuyin-Schuppen zu ernten. Er vereint starke Adsorptionskraft mit vielfältigen Funktionen.",
          TextMapId = "MESSAGE_LOADING_220_PC"
        },
        MESSAGE_LOADING_221_PC = {
          ContentES = "Eine geologische Seuche, die während der Plage von Zhuyin im Gebiet von Nebelkai entstand. Sie erscheint als violettes, kristallines Pulver, das sich auf Oberflächen absetzt und die Lebenskraft lebender Wesen entzieht.",
          TextMapId = "MESSAGE_LOADING_221_PC"
        },
        MESSAGE_LOADING_224_PC = {
          ContentES = "Einst zu den Schutzsekten Huaxus gezählt, ist die Jishu-Sekte längst in Verfall geraten. Berühmt für ihre Meisterschaft in Mechanpuppen und anderen Automatenkonstrukten, liefert sie weiterhin zivile Geräte in ganz Huaxu, doch gelten bestimmte Techniken der Mechanpuppenfertigung inzwischen als tabu.",
          TextMapId = "MESSAGE_LOADING_224_PC"
        },
        MESSAGE_LOADING_225_PC = {
          ContentES = "Eine Schutzsekte Huaxus, gegründet von Yang, einem der Gründungsmeister der Neun Kapitel von Dafeng. Ihre Mitglieder nutzen Weihrauch, um mit dem Göttlichen zu verkehren.\n In der Antike war die Xuanheng-Sekte die erste, die die mystischen Eigenschaften des Weihrauchs entdeckte, und sie bewahrt dieses Wissen seither als geheime Kunst.",
          TextMapId = "MESSAGE_LOADING_225_PC"
        },
        MESSAGE_LOADING_227_PC = {
          ContentES = "In Huaxu können unter dem Einfluss der Neun Kapitel von Dafeng die bei Tod zurückbleibenden Obsessionen Gestalt annehmen und zu Wesen werden, die als Wishen bekannt sind.\n Sie bewahren kaum Erinnerungen an ihr früheres Leben, und ihre Fähigkeit zu sprechen oder die Welt zu begreifen schwindet oft allmählich.",
          TextMapId = "MESSAGE_LOADING_227_PC"
        },
        MESSAGE_LOADING_22_PC = {
          ContentES = "Sprich mit Leuten in verschiedenen Städten. Regelmäßige Interaktionen können den „Eindruck”, den andere von dir haben, nach und nach beeinflussen.",
          TextMapId = "MESSAGE_LOADING_22_PC"
        },
        MESSAGE_LOADING_23_PC = {
          ContentES = "Wenn der Schild Schaden erleidet, wird die VTD nicht berücksichtigt. Nach einer gewissen Zeit ohne erlittenen Schaden regeneriert sich der Schild automatisch.",
          TextMapId = "MESSAGE_LOADING_23_PC"
        },
        MESSAGE_LOADING_24_PC = {
          ContentES = "Sobald die Kampfhaltung eines Elite-Gegners unterbrochen wird, ist er kurzzeitig handlungsunfähig und versucht, erneut seine Kampfhaltung einzunehmen. Währenddessen erleidet er erhöhten Schaden. Nutze diese Phase optimal, um schneller den Sieg zu erringen.",
          TextMapId = "MESSAGE_LOADING_24_PC"
        },
        MESSAGE_LOADING_29_PC = {
          ContentES = "Hieb: Verursacht höheren Schaden am Schild des Ziels. \n Durchdringung: Verursacht höheren Schaden an den LP des Ziels. \n Erschütterung: Schwächt die Kampfhaltung des Ziels weiter.",
          TextMapId = "MESSAGE_LOADING_29_PC"
        },
        MESSAGE_LOADING_2_PC = {
          ContentES = "Drücke in der Luft &Attack&, um einen Sturzangriff auszuführen.",
          TextMapId = "MESSAGE_LOADING_2_PC"
        },
        MESSAGE_LOADING_2_Phone = {
          ContentES = "Tippe in der Luft auf die Angriffstaste, um einen Sturzangriff auszuführen.",
          TextMapId = "MESSAGE_LOADING_2_Phone"
        },
        MESSAGE_LOADING_31_PC = {
          ContentES = "Wenn du Dämonenkeile ausrüstest, kannst du deine Figuren und Waffen erheblich verstärken. Einige seltene Dämonenkeile können sogar die Fähigkeitseffekte des Trägers verzieren.",
          TextMapId = "MESSAGE_LOADING_31_PC"
        },
        MESSAGE_LOADING_32_PC = {
          ContentES = "Dämonenkeile sind eine Belastung für den Träger, und die maximale Belastung, die ein Träger aushalten kann, nennt man Toleranz. Wenn du deine Figuren und Waffen hochstufst, kannst du dieses Limit erhöhen und mehr Keile ausrüsten, um dir im Kampf einen größeren Vorteil zu verschaffen.",
          TextMapId = "MESSAGE_LOADING_32_PC"
        },
        MESSAGE_LOADING_33_PC = {
          ContentES = "Jeder Dämonenkeil verfügt über eine Affinität, die mit bestimmten Trägern in Resonanz steht – man bezeichnet dies als „Spur“. Wenn die Spur eines Keils mit der des Trägers (Figur/Waffe) übereinstimmt, wird weniger Toleranz verbraucht – wenn sie allerdings nicht zusammenpassen, ist eine größere Toleranz erforderlich.",
          TextMapId = "MESSAGE_LOADING_33_PC"
        },
        MESSAGE_LOADING_34_PC = {
          ContentES = "Die neueste Erfindung der Imperialen Alchemie-Akademie im Bereich der Dämonenkeil-Technologie, mit der man die Spur der Plätze verändern kann.",
          TextMapId = "MESSAGE_LOADING_34_PC"
        },
        MESSAGE_LOADING_35_PC = {
          ContentES = "Die speziellen Aufträge der Asphodel für {性别:Phoxjäger|Phoxjägerinnen}. Diese Missionen bieten gewöhnlich stattliche Belohnungen. Schließe sie ab, um die Kampfkraft deines Teams zu stärken.",
          TextMapId = "MESSAGE_LOADING_35_PC"
        },
        MESSAGE_LOADING_36_PC = {
          ContentES = "Lass dich nicht von den endlosen Wellen von Gegnern ausbremsen. Lokalisiere sofort dein Ziel, um die Mission schnell abzuschließen.",
          TextMapId = "MESSAGE_LOADING_36_PC"
        },
        MESSAGE_LOADING_37_PC = {
          ContentES = "Nutze Sprungpads, um den Evakuierungspunkt schneller zu erreichen, nachdem du dich um die teuflische Bombe „Großes Feuerwerk“ gekümmert hast.",
          TextMapId = "MESSAGE_LOADING_37_PC"
        },
        MESSAGE_LOADING_38_PC = {
