        Message_Guide_Achievement_1 = {
          ContentES = "Du hast einen Erfolg abgeschlossen. Hole dir deine Belohnung ab!",
          TextMapId = "Message_Guide_Achievement_1"
        },
        Message_Guide_Achievement_2_PC = {
          ContentES = "Halte <H>&ShowCursor&</> gedrückt, um den Mauszeiger einzublenden, und wähle dann <H>Erfolge</> um das Menü „Erfolge“ zu öffnen.",
          TextMapId = "Message_Guide_Achievement_2_PC"
        },
        Message_Guide_Achievement_2_Pad = {
          ContentES = "Drücke, um das Menü <H>Erfolge</> zu öffnen",
          TextMapId = "Message_Guide_Achievement_2_Pad"
        },
        Message_Guide_Achievement_2_Phone = {
          ContentES = "Wähle <H>Erfolge</>, um das Menü „Erfolge“ zu öffnen.",
          TextMapId = "Message_Guide_Achievement_2_Phone"
        },
        Message_Guide_Achievement_3 = {
          ContentES = "Nimm verschiedene Herausforderungen an und schließe weitere Erfolge in zukünftigen Abenteuern ab!",
          TextMapId = "Message_Guide_Achievement_3"
        },
        Message_Guide_Achievement_4 = {
          ContentES = "Wähle „Einsammeln“, um die Belohnungen einzusammeln.",
          TextMapId = "Message_Guide_Achievement_4"
        },
