        Message_Guide_ModLevelUp_1 = {
          ContentES = "Eine Erhöhung der <H>Stufe der Dämonenkeile</> kann Daimonen und Waffen weiter verstärken.",
          TextMapId = "Message_Guide_ModLevelUp_1"
        },
        Message_Guide_ModLevelUp_4 = {
          ContentES = "Wähle einen Dämonenkeil",
          TextMapId = "Message_Guide_ModLevelUp_4"
        },
        Message_Guide_ModLevelUp_4_Pad = {
          ContentES = "Drücke, um einen Dämonenkeil auszuwählen",
          TextMapId = "Message_Guide_ModLevelUp_4_Pad"
        },
        Message_Guide_ModLevelUp_5 = {
          ContentES = "Wähle „Dämonenkeil hochstufen“",
          TextMapId = "Message_Guide_ModLevelUp_5"
        },
        Message_Guide_ModLevelUp_5_Pad = {
          ContentES = "Drücke, um „Dämonenkeil hochstufen“ auszuwählen",
          TextMapId = "Message_Guide_ModLevelUp_5_Pad"
        },
        Message_Guide_ModLevelUp_6 = {
          ContentES = "Das Hochstufen von Dämonenkeilen <H>erhöht deine Kampfkraft beträchtlich</>.",
          TextMapId = "Message_Guide_ModLevelUp_6"
        },
        Message_Guide_ModLevelUp_7 = {
          ContentES = "Das Hochstufen eines Dämonenkeils <H>erhöht die für ihn erforderliche Toleranz</>. Achte darauf, dass die gesamte erforderliche Toleranz nach dem Hochstufen des Dämonenkeils <H>nicht</> die <H>Toleranz-Obergrenze</> überschreitet.",
          TextMapId = "Message_Guide_ModLevelUp_7"
        },
        Message_Guide_ModTendency_1 = {
          ContentES = "Die der Figur innewohnende Spur kann mithilfe von <H>Spurwechselmodulen</> angepasst werden.",
          TextMapId = "Message_Guide_ModTendency_1"
        },
        Message_Guide_ModTendency_10 = {
          ContentES = "Wenn du einen mächtigen Dämonenkeil besitzt, aber Probleme mit einer <H>inkompatiblen Spur</> hast, solltest du <H>die Spur des Platzes anpassen</>.",
          TextMapId = "Message_Guide_ModTendency_10"
        },
        Message_Guide_ModTendency_11 = {
          ContentES = "Wenn die Spur des Platzes einer Figur mit der Spur eines Dämonenkeils <H>übereinstimmt</>, <H>verringert</> sich die <H>Toleranz</>, die für das Ausrüsten dieses Dämonenkeils erforderlich ist.",
          TextMapId = "Message_Guide_ModTendency_11"
        },
        Message_Guide_ModTendency_4 = {
          ContentES = "Wähle den Dämonenkeil-Platz",
          TextMapId = "Message_Guide_ModTendency_4"
        },
        Message_Guide_ModTendency_4_Pad = {
          ContentES = "Drücke, um einen Dämonenkeil-Platz auszuwählen",
          TextMapId = "Message_Guide_ModTendency_4_Pad"
        },
        Message_Guide_ModTendency_5 = {
          ContentES = "Wähle „Platz-Spur anpassen“",
          TextMapId = "Message_Guide_ModTendency_5"
        },
        Message_Guide_ModTendency_5_Pad = {
          ContentES = "Drücke, um „Platz-Spur anpassen“ auszuwählen",
          TextMapId = "Message_Guide_ModTendency_5_Pad"
        },
        Message_Guide_ModTendency_6 = {
          ContentES = "Du kannst <H>Spurwechselmodule</> verwenden, um die innewohnende <H>Spur</> des Dämonenkeil-Platzes einer Figur hinzuzufügen, anzupassen oder zu eliminieren.",
          TextMapId = "Message_Guide_ModTendency_6"
        },
        Message_Guide_ModTendency_7 = {
          ContentES = "Ärgert dich die limitierte Toleranzobergrenze, die mehr Dämonenkeil-Konfigurationen verhindert? Achte auf die <H>Spur</>!",
          TextMapId = "Message_Guide_ModTendency_7"
        },
        Message_Guide_ModTendency_8 = {
          ContentES = "Alle Figuren oder Waffen haben bestimmte Eigenschaften, die zu verschiedenen <H>Spuren</> für ihre <H>Dämonenkeil-Plätze</> führen.",
          TextMapId = "Message_Guide_ModTendency_8"
        },
        Message_Guide_ModTendency_9 = {
          ContentES = "Um <H>Dämonenkeile</> effektiver einsetzen zu können, wurden einige speziell mit einer <H>Spur</> hergestellt, die für bestimmte Figuren maßgeschneidert wurde.",
          TextMapId = "Message_Guide_ModTendency_9"
        },
        Message_Guide_Mod_1 = {
          ContentES = "<H>Dämonenkeile</>, hergestellt von der Spathatoi aus Hyperborea, sind tragbare Komponenten, die die Kraft von Daimonen und Waffen erheblich verstärken, sobald sie ausgerüstet sind.",
          TextMapId = "Message_Guide_Mod_1"
        },
        Message_Guide_Mod_10 = {
          ContentES = "Wähle einen Dämonenkeil aus, um dir seine Effekte anzusehen",
          TextMapId = "Message_Guide_Mod_10"
        },
        Message_Guide_Mod_11 = {
          ContentES = "Verbrauche <H>Münzen</> und <H>Karminkügelchen</>, um Dämonenkeile <H>hochzustufen</> und ihre Kräfte deutlich zu verstärken. Allerdings erhöht das Hochstufen von Dämonenkeilen auch die Belastung für den Träger – dabei kann die Toleranzobergrenze für das Ausrüsten überschritten werden.",
          TextMapId = "Message_Guide_Mod_11"
        },
        Message_Guide_Mod_12 = {
          ContentES = "Hier kannst du schnell zwischen Figuren und Waffen wechseln, um ihre Dämonenkeile bei Bedarf anzupassen.",
          TextMapId = "Message_Guide_Mod_12"
        },
        Message_Guide_Mod_13 = {
          ContentES = "Ein Figuren-Dämonenkeil kann von mehreren Figuren genutzt werden. Ebenso kann der gleiche Waffen-Dämonenkeil bei mehreren Waffen eingesetzt werden.",
          TextMapId = "Message_Guide_Mod_13"
        },
        Message_Guide_Mod_14 = {
          ContentES = "Du solltest deine Figure und Waffen <H>hochstufen</>, um ihre Toleranzobergrenzen zu erhöhen.",
