        },
        Mon_Name_9810001 = {
          ContentES = "Seevoogel",
          TextMapId = "Mon_Name_9810001"
        },
        MonsterRushEvent_Wuyou_DungeonDes01 = {
          ContentES = "Ein mysteriöser, schwerttragender Wishen taucht plötzlich auf und versperrt dir den Weg. Vielleicht spürt er dein Talent und möchte dir einen oder zwei Tricks zeigen.\n „Pass gut auf. Ich zeige es nur einmal.“",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes01"
        },
        MonsterRushEvent_Wuyou_DungeonDes02 = {
          ContentES = "Sonnenstrahlen fallen durch das Blätterdach, ein Windhauch streift dein Haar. Als erinnere sich der kleine Wishen an einen fernen Nachmittag, gähnt er ausgiebig.\n ... Moment, gähnen Wishen überhaupt?",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes02"
        },
        MonsterRushEvent_Wuyou_DungeonDes03 = {
          ContentES = "Der eifrige Schwertkämpfer, der träge Hirte – ihr lautstarkes Streitgespräch hallt in deinen Ohren. Hoffentlich nehmen sie dich am Ende nicht ins Visier, du fröhlicher Reisender, gefangen in ihrem ausgelassenen Gezänk.",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes03"
        },
        MonsterRushEvent_Wuyou_DungeonDes04 = {
          ContentES = "Ein Talismanschein ... zwei ... drei ... Du siehst zu, wie der Wishen immer neue Zettel aus seinem Rücken zieht, wie ein Bühnenmagier, der unendlich viele Karten aus dem Ärmel fächert.\n „Nicht dieser ... auch nicht jener ... Wo ist mein Blitz-Talisman nur?“",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes04"
        },
        MonsterRushEvent_Wuyou_DungeonDes05 = {
          ContentES = "Gemächlich legt dir ein Wishen seinen Strohhut in die Hände und bittet dich, ihn sicher aufzubewahren.\n Im nächsten Moment glaubst du, eine Gestalt in Anzug, die eine Axt hält, aus dem Schatten steigen zu sehen, die brüllt „Wer will sonst noch?“",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes05"
        },
        MonsterRushEvent_Wuyou_DungeonDes06 = {
          ContentES = "Man sagt, Wishen entstehen aus unerfüllten Sehnsüchten. Du wirfst nicht nur einen Blick auf die still umher schwebenden Gefährten.\n Welche unerfüllte Wunschvorstellung hält sie wohl in dieser Welt gefangen?",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes06"
        },
        MonsterRushEvent_Wuyou_DungeonDes07 = {
          ContentES = "Wenn Verschwinden Loslassen bedeutet, kennt die Welt der Wishen keine traurigen Abschiede.\n In den Farben der Seele schimmernde, wunderliche Geister versammeln sich hier – und morgen wird, wie immer, ein Tag voller Lärm und Wunder sein.",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonDes07"
        },
        MonsterRushEvent_Wuyou_DungeonName01 = {
          ContentES = "Lektionen des namenlosen Schwertkämpfers",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName01"
        },
        MonsterRushEvent_Wuyou_DungeonName02 = {
          ContentES = "Das Gähnen des verwirrten Hirtenjungen",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName02"
        },
        MonsterRushEvent_Wuyou_DungeonName03 = {
          ContentES = "Eine ausgelassene Farce",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName03"
        },
        MonsterRushEvent_Wuyou_DungeonName04 = {
          ContentES = "Unerschöpfliche Zaubertricks",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName04"
        },
        MonsterRushEvent_Wuyou_DungeonName05 = {
          ContentES = "Der gemächliche Wahnsinnige",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName05"
        },
        MonsterRushEvent_Wuyou_DungeonName06 = {
          ContentES = "Prüfung der verschwommenen Träume",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName06"
        },
        MonsterRushEvent_Wuyou_DungeonName07 = {
          ContentES = "Ein unbeschwerter Morgen",
          TextMapId = "MonsterRushEvent_Wuyou_DungeonName07"
        },
        MonsterRushEvent_Wuyou_PetDesc_1 = {
          ContentES = "Un Wishen que maneja talismanes destructivos con asombrosa facilidad, pero lo que más te intriga es de dónde saca esta casi infinita reserva de talismanes.",
          TextMapId = "MonsterRushEvent_Wuyou_PetDesc_1"
        },
        MonsterRushEvent_Wuyou_PetDesc_2 = {
          ContentES = "Un Wishen de apariencia calmada y controlada, pero despertar su ira podría tener consecuencias que nadie se atreve a imaginar.",
          TextMapId = "MonsterRushEvent_Wuyou_PetDesc_2"
        },
        MonsterRushEvent_Wuyou_PetDesc_3 = {
          ContentES = "Un Wishen maestro en el arte de hacer girar las espadas: las hojas que giran a su alrededor formarían un fondo perfecto para una foto… siempre que acepte concederte este favor.",
          TextMapId = "MonsterRushEvent_Wuyou_PetDesc_3"
        },
        MonsterRushEvent_Wuyou_PetDesc_4 = {
          ContentES = "Un Wishen que se desplaza siempre con ligereza despreocupada. En días sombríos, basta acariciar suavemente la parte superior de su cabeza para sentir tu corazón más ligero.",
          TextMapId = "MonsterRushEvent_Wuyou_PetDesc_4"
        },
        MonsterRushEvent_Wuyou_PetName_1 = {
          ContentES = "Wishen de los talismanes",
          TextMapId = "MonsterRushEvent_Wuyou_PetName_1"
        },
        MonsterRushEvent_Wuyou_PetName_2 = {
          ContentES = "Wishen asceta",
