        PartyReward_Description_110101 = {
          ContentES = "Unter seiner bitteren, ungenießbaren Schale verbirgt sich die süß-sauren Körnchen der Erinnerung.",
          TextMapId = "PartyReward_Description_110101"
        },
        PartyReward_Description_110102 = {
          ContentES = "Eine abgebrochene Feder, die nach dem salzigen Geruch des Meeres duftet und einen leichten Hauch von Blut verströmt – ein Beweis für die Naivität und den Mut eines jungen Mädchens.",
          TextMapId = "PartyReward_Description_110102"
        },
        PartyReward_Description_110103 = {
          ContentES = "Selbst aus einem Käfig heraus blicken manche immer noch zum Horizont.",
          TextMapId = "PartyReward_Description_110103"
        },
        PartyReward_Description_110104 = {
          ContentES = "Die flüchtigen Momente des Glücks sind für immer vorbei. Aber zum Glück gibt es immer ein Morgen.",
          TextMapId = "PartyReward_Description_110104"
        },
        PartyReward_Description_110301 = {
          ContentES = "Größe und Form wurden sorgfältig entworfen, um die abgebrochenen Hörner gerade so zu verbergen, sodass der Charon-Junge als gewöhnlicher Sola durchgehen kann.",
          TextMapId = "PartyReward_Description_110301"
        },
        PartyReward_Description_110302 = {
          ContentES = "Ein Journalist schildert in blumiger Ausdrucksweise das legendäre Leben eines wohlhabenden Kaufmanns und rühmt dessen Weisheit, Eleganz und Großzügigkeit – als wollte er der Welt einen goldenen Strohhalm vor die Nase halten.",
          TextMapId = "PartyReward_Description_110302"
        },
        PartyReward_Description_110303 = {
          ContentES = "Auf dem kalten Metall ist die Zahl „47“ eingraviert – so verschlissen, dass sie kaum noch zu erkennen ist. Der Name, den diese Seele einmal trug, wurde schon vor langer Zeit ausradiert und wird nie wieder wahrgenommen werden.",
          TextMapId = "PartyReward_Description_110303"
        },
        PartyReward_Description_110304 = {
          ContentES = "Hell, herzlich und sanft locken sie die Kinder, die in der Nacht verweilen, und geleiten sie nach Hause. Doch für ein Tier, das sich in den Schatten verloren hat, bleiben solche Lichter für immer unerreichbar.",
          TextMapId = "PartyReward_Description_110304"
        },
        PartyReward_Description_150201 = {
          ContentES = "An den durchsichtigen Scherben haftet dunkelrote Flüssigkeit, die längst verfestigt ist – einst war es das Wunder, nach dem ein junges Mädchen verzweifelt gesucht hatte.",
          TextMapId = "PartyReward_Description_150201"
        },
        PartyReward_Description_150202 = {
          ContentES = "Eine Schriftrolle, auf der die unerfüllten Träume eines jungen Mannes und einer jungen Frau festgehalten wurden. Dieses zeitlose und unverfälschte Erbe haben sie den nachfolgenden Generationen anvertraut.",
          TextMapId = "PartyReward_Description_150202"
        },
        PartyReward_Description_150203 = {
          ContentES = "Aus frischem Wildbret und Gemüse zubereitet wärmte dieser Eintopf einst ein Herz, das in einer kalten, gnadenlosen Winternacht kurz zu schlagen aufgehört hatte.",
          TextMapId = "PartyReward_Description_150203"
        },
        PartyReward_Description_150204 = {
          ContentES = "In diesem Traum existieren weder die Qualen des Lebens noch die Leiden des Todes. Reue bleibt unausgesprochen, Fehler müssen sich erst noch entfalten – alles ist einfach da, geborgen in der Wärme des Sonnenlichts und dem sanften Rauschen des Baches.",
          TextMapId = "PartyReward_Description_150204"
        },
        PartyReward_Description_150301 = {
          ContentES = "Ein Schwert kann töten – doch es kann auch einem anderen Zweck dienen.",
          TextMapId = "PartyReward_Description_150301"
        },
        PartyReward_Description_150302 = {
          ContentES = "Zwischen Traum und Erinnerung hallt das Wandern freier Geister. Mitten in Freude und Leid ein wehmütiges Lächeln für eine vergangene Welt.",
          TextMapId = "PartyReward_Description_150302"
        },
        PartyReward_Description_150303 = {
          ContentES = "Die Seiten sind vom Alter gezeichnet, doch in dieser Sammlung finden sich Gerichte seltener Kunstfertigkeit, die in dieser gewöhnlichen Welt kaum je begegnet werden.",
          TextMapId = "PartyReward_Description_150303"
        },
        PartyReward_Description_150304 = {
          ContentES = "Ein Heft voller Halbwahrheiten, einst sehr beliebt. Wer kann heute noch die Kämpfe entschlüsseln, die in diesen Zeichen verborgen sind? Das Buch schweigt.",
          TextMapId = "PartyReward_Description_150304"
        },
        PartyReward_Description_180101 = {
          ContentES = "Ein Haufen leerer Patronenhülsen, die sich mit einem Hauch von Kreativität in Pistolen, Kanonen, Luftschiffe und gewaltige Roboter verwandeln lassen – Schlüssel, um eine Welt voller Träume zu entdecken.",
          TextMapId = "PartyReward_Description_180101"
        },
        PartyReward_Description_180102 = {
          ContentES = "Märchen haben nicht immer ein Happy End. Nachdem die Vogeldame sich in einen brennenden Stern verwandelt hat, weint sie immer noch am Nachthimmel?",
          TextMapId = "PartyReward_Description_180102"
        },
        PartyReward_Description_180103 = {
          ContentES = "Auch wenn die kalten Regenschauer der Vergangenheit immer noch herniederprasseln, spürt sie noch immer die Wärme einer Handfläche, die einem anderen gehörte.",
          TextMapId = "PartyReward_Description_180103"
        },
        PartyReward_Description_180104 = {
          ContentES = "Wie lange muss ihre Reise noch dauern, bevor sie ein wunderschönes Ende für diese Geschichte zu Papier bringen kann?",
          TextMapId = "PartyReward_Description_180104"
        },
        PartyReward_Description_210101 = {
          ContentES = "Trink es aus. Schlucke die Bitterkeit im Glas und genieße die Süße der Liebe.",
          TextMapId = "PartyReward_Description_210101"
        },
        PartyReward_Description_210102 = {
          ContentES = "Die Qualle windet sich im Glas unter dem Licht, lässt sich lautlos in die Tiefe sinken und findet keinen Partner, bevor sie sich auf dem Meeresgrund verflüchtigt.",
          TextMapId = "PartyReward_Description_210102"
        },
        PartyReward_Description_210103 = {
          ContentES = "Beziehungen ähneln oft diesem Getränk: Am Anfang fühlt man Wärme, dann schleicht sich langsam Bitterkeit ein und am Ende bleibt nur noch ein kalter Nachgeschmack. Wie Wasser und Feuer passen manche Sachen einfach nicht zusammen.",
          TextMapId = "PartyReward_Description_210103"
        },
        PartyReward_Description_210104 = {
          ContentES = "Dieses Getränk besticht durch seine Einfachheit und seinen unverfälschten Geschmack, denn die wahre Liebe bedarf keiner sinnloser Schnörkel – sie existiert in den Augen der Liebenden.",
          TextMapId = "PartyReward_Description_210104"
        },
        PartyReward_Description_230101 = {
          ContentES = "Runter damit! Die herbsüße Note knistert und knallt auf deiner Zunge wie das Lachen von Kindern auf der Veranda.",
          TextMapId = "PartyReward_Description_230101"
        },
        PartyReward_Description_230102 = {
          ContentES = "Süße und Salzigkeit sind keine Widersprüche, denn auch die Unschuld und die Boshaftigkeit können nebeneinander existieren.",
          TextMapId = "PartyReward_Description_230102"
        },
        PartyReward_Description_230103 = {
          ContentES = "Die anfängliche Säuerlichkeit treibt dir Falten auf die Stirn, aber sobald sich deine Geschmacksknospen daran gewöhnt haben, entfaltet sich eine angenehme Süße – ähnlich wie das Verständnis der Welt: Nach dem Sturm kehrt immer wieder die Hoffnung ein.",
          TextMapId = "PartyReward_Description_230103"
        },
        PartyReward_Description_230104 = {
          ContentES = "%*$^&!@#%*^^Y&!#(%^%???!!",
          TextMapId = "PartyReward_Description_230104"
        },
        PartyReward_Description_240101 = {
          ContentES = "Ein Kompendium, in dem 1.890 medizinische Substanzen aufgelistet sind – fast die Hälfte davon sind Kräuter. Der Name des Autors lautet: Fufeng.",
          TextMapId = "PartyReward_Description_240101"
        },
        PartyReward_Description_240102 = {
          ContentES = "Vom Erscheinungsbild fast identisch mit Oneirowort, aber als Auslöser von Halluzinationen bekannt. Wenn es sich bei Halluzinationen um Wachträume handelt, dann ergibt ihre Ähnlichkeit plötzlich Sinn.",
          TextMapId = "PartyReward_Description_240102"
        },
        PartyReward_Description_240103 = {
          ContentES = "Obgleich der bizarren Erscheinung ist er in Huaxu ein geschätztes Symbol für Langlebigkeit.",
          TextMapId = "PartyReward_Description_240103"
        },
        PartyReward_Description_240104 = {
          ContentES = "Die silberne Lampe ist zwar noch nicht erloschen, aber ich befürchte, dass unser Wiedersehen nur ein flüchtiger Traum war.",
          TextMapId = "PartyReward_Description_240104"
        },
        PartyReward_Description_310101 = {
          ContentES = "Ein feuriges, kräftiges Getränk für alle, die sich nach einem stärkeren Kick sehnen. Der erste Schluck regt deinen Appetit an, der zweite beflügelt deine Stimmung – ein perfekter Eisbrecher.",
          TextMapId = "PartyReward_Description_310101"
        },
        PartyReward_Description_310102 = {
          ContentES = "Was beim Trinken erzählt wird, verbleibt in der Kneipe – das ist eines der ungeschriebenen Gesetze jeder guten Trinkrunde.",
          TextMapId = "PartyReward_Description_310102"
        },
        PartyReward_Description_310103 = {
          ContentES = "Icelake mag klein sein – ein winziger Klecks auf der Karte des Imperiums –, doch es besitzt eine unergründliche Gewaltigkeit: Die Erinnerungen daran verweilen, egal wie weit man reist.",
          TextMapId = "PartyReward_Description_310103"
        },
        PartyReward_Description_310201 = {
          ContentES = "Unter den Blütenblättern lauern Dornen, und unter dem Rocksaum einer Magd? Kugeln.",
          TextMapId = "PartyReward_Description_310201"
        },
        PartyReward_Description_310202 = {
          ContentES = "Verkleidungen sind keine Magie, sondern eine Kunstform – sie können nicht nur dein Aussehen, sondern auch deinen Gemütszustand verändern.",
          TextMapId = "PartyReward_Description_310202"
        },
        PartyReward_Description_310203 = {
          ContentES = "Sei froh, dass die Schere in der Hand der Maid nur die verwelkten Blumen beschneidet.",
          TextMapId = "PartyReward_Description_310203"
        },
        PartyReward_Description_310204 = {
          ContentES = "Eine Tasse Blütentee, das feierliche Versprechen einer Magd.",
          TextMapId = "PartyReward_Description_310204"
        },
        PartyReward_Description_310301 = {
          ContentES = "Die Namen mögen sich unterscheiden, aber jedes Spielzeug auf dieser Liste verspricht eine spektakuläre Explosion.",
          TextMapId = "PartyReward_Description_310301"
        },
        PartyReward_Description_310302 = {
          ContentES = "Ein hochwirksamer Energydrink, der die Müdigkeit der erschöpften Reisenden hinwegfegt. Mit einem klaren Kopf erkennt das Herz vielleicht endlich, was es wirklich will.",
          TextMapId = "PartyReward_Description_310302"
        },
        PartyReward_Description_310303 = {
          ContentES = "Ein Getränk mit einer äußerst beruhigenden Wirkung, das sich hervorragend dazu eignet, die Nerven der Wartenden zu beruhigen. Nur durch geduldiges Warten erkennt das Herz, was es wirklich will.",
          TextMapId = "PartyReward_Description_310303"
        },
        PartyReward_Description_310304 = {
          ContentES = "Diese gigantische Spielzeugkiste ist randvoll mit Kabumm-Kreiseln, Schnurrknall-Feuerwerkskörpern und Sternensprengern und läutet ein neues Kapitel für „Snap 'n' Spark“ ein.",
          TextMapId = "PartyReward_Description_310304"
        },
        PartyReward_Description_320101 = {
          ContentES = "„Kümmere dich gut um diesen Gast.“",
          TextMapId = "PartyReward_Description_320101"
        },
        PartyReward_Description_320102 = {
          ContentES = "Du hättest nie gedacht, dass man dieses Gebräu tatsächlich trinken kann.",
          TextMapId = "PartyReward_Description_320102"
        },
        PartyReward_Description_320103 = {
          ContentES = "Ein dickflüssiger, köstlicher Sirup, dessen Süßlichkeit noch lange nach dem letzten Tropfen am Gaumen klebt.",
          TextMapId = "PartyReward_Description_320103"
        },
        PartyReward_Description_320104 = {
          ContentES = "Ein billiger Fusel – manche tranken ihn, um sich lebendig zu fühlen, andere, um den Schmerz zu betäuben. Doch wann immer sie ihre Gläser erhoben, erklangen dieselben Worte: „Die Unbeugsamkeit – für die, die sich niemals beugen.“",
          TextMapId = "PartyReward_Description_320104"
        },
        PartyReward_Description_330101 = {
          ContentES = "Nach einem langen Tag, an dem du und Margie die Villa von Kossak durchforstet habt, habt ihr einen Haufen Schätze zusammengetragen. Hoffentlich sind sie den Muskelkater wert.",
          TextMapId = "PartyReward_Description_330101"
        },
        PartyReward_Description_330102 = {
          ContentES = "Eine Komposition für die Gemeinschaft der Charon, die lange in der Versenkung verschwunden war. Erst als Margie die Melodie über Icelake verbreitete, fand sie wieder ihre wahre Bestimmung.",
          TextMapId = "PartyReward_Description_330102"
        },
        PartyReward_Description_330103 = {
          ContentES = "Ein durchdachtes Geburtstagsgeschenk von einem liebevollen Vater. In diesem multifunktionalen Helm steckt eine kleine Überraschung.",
          TextMapId = "PartyReward_Description_330103"
        },
        PartyReward_Description_330104 = {
          ContentES = "Dieses graue, von schwarzen Flecken übersäte Fellknäuel erinnert an den Anblick einer stolzen Katze mit buschigem Schweif, die über die Schneefelder stolziert.",
          TextMapId = "PartyReward_Description_330104"
        },
        PartyReward_Description_410101 = {
          ContentES = "In der Kolumne „Tägliche Pflichten“ finden sich immer jede Menge Bagatellen, die sich manchmal sogar über eine zweite Seite erstrecken. So verlief Rhythms Leben in der Eskorte.",
          TextMapId = "PartyReward_Description_410101"
        },
        PartyReward_Description_410102 = {
          ContentES = "Ein ordentliches Sammelalbum, gefüllt mit Zeitungsausschnitten – Reinigungskraft, Küchenhilfe, Schreibkraft, Fischer, Barkeeper, Maurer ... und sogar ein Dompteur?",
          TextMapId = "PartyReward_Description_410102"
        },
        PartyReward_Description_410103 = {
          ContentES = "Jede verzwickte Stelle ist sorgfältig markiert und an den Rändern mit Anmerkungen versehen. Sie gehört offensichtlich einem gewissenhaften – wenn auch noch wenig erfahrenen – Spieler. Bei genauer Betrachtung zeigt sich in der Ecke eine niedliche Kritzelei in Blitzform.",
          TextMapId = "PartyReward_Description_410103"
        },
        PartyReward_Description_420201 = {
          ContentES = "Vergiss den Alltagsstress und schüttle deine Müdigkeit ab – starte mit einem gekühlten, süßen Genuss in deine wohlverdiente Auszeit!",
          TextMapId = "PartyReward_Description_420201"
        },
        PartyReward_Description_420202 = {
          ContentES = "Das 20 Jahre lang gereifte Premium-Getränk „Triumph“ gilt bei der Elite von Hyperborea als Symbol für Raffinesse und Prestige. Doch unter der luxuriösen Aufmachung lässt sich die Bitterkeit nur schwer verbergen.",
          TextMapId = "PartyReward_Description_420202"
        },
        PartyReward_Description_420203 = {
          ContentES = "Die Pistole dient sowohl als Sinnbild für die Verantwortung, die schwer auf den Schultern eines Vaters lastet, als auch als Ehrenabzeichen, das von Generation zu Generation vererbt wird.",
          TextMapId = "PartyReward_Description_420203"
        },
        PartyReward_Description_420204 = {
          ContentES = "Die besten Ideen kommen einem manchmal beim Duschen, Schlafen oder wenn man eine Tasse Tee schlürft. Die Maßnahmen, die man auf der Suche nach solchen Inspirationen ergreift, mögen für Außenstehende ein bisschen ... verschroben wirken.",
          TextMapId = "PartyReward_Description_420204"
        },
        PartyReward_Description_430101 = {
          ContentES = "Die 13. Legion symbolisiert Autorität und ist das Werkzeug für den Willen und die Brutalität des Kaisers.",
          TextMapId = "PartyReward_Description_430101"
        },
        PartyReward_Description_430102 = {
          ContentES = "Gewohnheiten sind eine mächtige Waffe. Sie bringen uns dazu, das Ungewöhnliche zu akzeptieren und noch weiter von der Norm abzuschweifen.",
          TextMapId = "PartyReward_Description_430102"
        },
        PartyReward_Description_430103 = {
          ContentES = "Unter dem Glanz dieser Medaille liegt ein dornenreicher Weg.",
          TextMapId = "PartyReward_Description_430103"
        }
      }
    end
  },
  {
    MinKey = "PartyReward_Description_510101",
    MaxKey = "PartyTopic_Name_310201",
    Loader = function()
      return {
        PartyReward_Description_510101 = {
          ContentES = "Dieses klassische Getränk entstand durch ein Missgeschick, erfreut sich aber wegen seines facettenreichen Charakters großer Beliebtheit in ganz Atlasia. Nach vielen Generationen der Veredelung ist es über seinen ursprünglichen Bestimmungszweck, den Durst zu löschen und den Hunger zu stillen, hinausgewachsen und hat sich zu einem Sinnbild für unser Streben nach kulinarischen Gaumenfreuden entwickelt.",
          TextMapId = "PartyReward_Description_510101"
        },
        PartyReward_Description_510102 = {
          ContentES = "Von der Zeit gereift und in verschneites Weiß gehüllt, warten die Drehkapseln im Stillen auf ihre Ernte und bieten die Fülle der Natur.",
          TextMapId = "PartyReward_Description_510102"
        },
        PartyReward_Description_510103 = {
          ContentES = "Aus diesem frisch gepressten Borealbeeren-Saft wurde jegliche Säuerlichkeit herausgefiltert, sodass nur die volle Süße zurückbleibt. Die wahre Magie, die ihn noch leckerer macht, ist der gemeinsame Genuss mit deinem besten Freund!",
          TextMapId = "PartyReward_Description_510103"
        },
        PartyReward_Description_510104 = {
          ContentES = "Ein Filbert pro Frage – das hast du mit dem Mädchen vereinbart. Wenn du also unschlüssig bist, frag doch einfach den magischen Filbert!",
          TextMapId = "PartyReward_Description_510104"
        },
        PartyReward_Description_510201 = {
          ContentES = "Es bedarf keiner Worte – das Getränk spricht für sich.",
          TextMapId = "PartyReward_Description_510201"
        },
        PartyReward_Description_510202 = {
          ContentES = "Nach einem langen Tag macht nicht der Geschmack ein gutes Getränk aus – sondern der klare Abgang und jemand, mit dem man darüber sprechen kann.",
          TextMapId = "PartyReward_Description_510202"
        },
        PartyReward_Description_510203 = {
          ContentES = "Ertränke diese unerträglichen Erinnerungen in einem Trank. Dann kippst du das Ganze in einem Zug hinunter.",
          TextMapId = "PartyReward_Description_510203"
        },
        PartyReward_Description_510204 = {
          ContentES = "Für jedes Problem gibt es eine Lösung. Aber je mehr man darüber nachgrübelt, desto schwieriger wird es, den richtigen Weg zu finden.",
          TextMapId = "PartyReward_Description_510204"
        },
        PartyReward_Description_530101 = {
          ContentES = "Kinder kuscheln sich aneinander und träumen von einer Zukunft, die für sie zum Greifen nah und doch unerreichbar ist.",
          TextMapId = "PartyReward_Description_530101"
        },
        PartyReward_Description_530102 = {
          ContentES = "„Bitte sieh dir die Welt für mich mit deinen Augen an.“",
          TextMapId = "PartyReward_Description_530102"
        },
        PartyReward_Description_530103 = {
          ContentES = "Die Münze wurde geworfen. Niemand kann den Ausgang vorhersagen – Kopf oder Zahl, Tod oder Wiedergeburt.",
          TextMapId = "PartyReward_Description_530103"
        },
        PartyReward_Description_540101 = {
          ContentES = "Ein Strauß vom Tau geküsster Blüten, einem Patienten aus Wohlwollen dargeboten. Doch wahres Leid lässt sich nicht so leicht durch freundliche Gesten lindern.",
          TextMapId = "PartyReward_Description_540101"
        },
        PartyReward_Description_540102 = {
          ContentES = "Ein Skalpell, auf dem noch das Blut klebt, ist ein stummer Zeuge einer Tragödie, die man als „Unfall“ deklariert hat. Aber sie weiß, dass es kein Unfall war. Der wahre Schuldige war keine einzelne Person – oder vielleicht waren es alle.",
          TextMapId = "PartyReward_Description_540102"
        },
        PartyReward_Description_540103 = {
          ContentES = "Ein kleiner Stimmenrekorder, der ihre Entschlossenheit im Moment der Abreise aufzeichnet.",
