        },
        PartyReward_Name_510102 = {
          ContentES = "Drehkapsel",
          TextMapId = "PartyReward_Name_510102"
        },
        PartyReward_Name_510103 = {
          ContentES = "Saisonales Getränk: Borealbeeren-Saft",
          TextMapId = "PartyReward_Name_510103"
        },
        PartyReward_Name_510104 = {
          ContentES = "Magischer Filbert",
          TextMapId = "PartyReward_Name_510104"
        },
        PartyReward_Name_510201 = {
          ContentES = "Getränk: Auf die Freundschaft",
          TextMapId = "PartyReward_Name_510201"
        },
        PartyReward_Name_510202 = {
          ContentES = "Getränk: Auf die harte Arbeit",
          TextMapId = "PartyReward_Name_510202"
        },
        PartyReward_Name_510203 = {
          ContentES = "Getränk: Auf die Vergangenheit",
          TextMapId = "PartyReward_Name_510203"
        },
        PartyReward_Name_510204 = {
          ContentES = "Getränk: Auf die Zukunft",
          TextMapId = "PartyReward_Name_510204"
        },
        PartyReward_Name_530101 = {
          ContentES = "Sehnsüchte",
          TextMapId = "PartyReward_Name_530101"
        },
        PartyReward_Name_530102 = {
          ContentES = "Ein Geschenk",
          TextMapId = "PartyReward_Name_530102"
        },
        PartyReward_Name_530103 = {
          ContentES = "Münze der Götter",
          TextMapId = "PartyReward_Name_530103"
        },
        PartyReward_Name_540101 = {
          ContentES = "Ein Blumenstrauß",
          TextMapId = "PartyReward_Name_540101"
        },
        PartyReward_Name_540102 = {
          ContentES = "Blutbeflecktes Skalpell",
          TextMapId = "PartyReward_Name_540102"
        },
        PartyReward_Name_540103 = {
          ContentES = "Kompaktes Aufnahmegerät",
          TextMapId = "PartyReward_Name_540103"
        },
        PartyTopic_Description_110101 = {
          ContentES = "Sie goss seltsame Zutaten in den Topf und rührte dabei die in ihrem Inneren zögernde, unbeholfene Güte mit.",
          TextMapId = "PartyTopic_Description_110101"
        },
        PartyTopic_Description_110102 = {
          ContentES = "Du bist der Grund, warum ich stark sein muss.",
          TextMapId = "PartyTopic_Description_110102"
        },
        PartyTopic_Description_110103 = {
          ContentES = "Diese Küste ist meine ganze Welt, ein Käfig, der nur für mich geschmiedet wurde.",
          TextMapId = "PartyTopic_Description_110103"
        },
        PartyTopic_Description_110104 = {
          ContentES = "Alles ist zu Ende – und alles fängt von vorne an.",
          TextMapId = "PartyTopic_Description_110104"
        },
        PartyTopic_Description_110301 = {
          ContentES = "Ein Stückeschreiber hat mir einmal verraten, dass man einem Protagonisten zunächst jegliche Hoffnung nehmen muss, um ihn zum Handeln zu bewegen. Ich wünschte wirklich, dass es in der Wirklichkeit nicht so wäre.",
          TextMapId = "PartyTopic_Description_110301"
        },
        PartyTopic_Description_110302 = {
          ContentES = "Sobald die Hoffnung zerschlagen und jeder Rückzugsort versperrt ist, gibt es für den Protagonisten kein Zurück mehr in sein früheres Leben. Einst versuchte ich, diesen Moment so lange wie möglich hinauszuzögern.",
          TextMapId = "PartyTopic_Description_110302"
        },
        PartyTopic_Description_110303 = {
          ContentES = "Das Publikum liebt Wendungen und Überraschungen, deshalb sind die Geschichten aus der Feder von Dramatikern stets voller Höhen und Tiefen. Aber meine Geschichte ... scheint nur eine Richtung zu kennen – in den Abgrund, immer weiter nach unten, in einer endlosen Abwärtsspirale.",
          TextMapId = "PartyTopic_Description_110303"
        },
        PartyTopic_Description_110304 = {
          ContentES = "Vielleicht war es nie mein Schicksal, eine schöne Geschichte zu erleben – aber dennoch habe ich das Recht, über mein Ende zu entscheiden.",
          TextMapId = "PartyTopic_Description_110304"
        },
        PartyTopic_Description_150201 = {
          ContentES = "Eine falsche Hoffnung kann manchmal grausamer sein als die Hoffnungslosigkeit selbst, da sie das Leid der Vergangenheit in eine Zukunft hineinzieht, in der eigentlich schon ein Abschluss gefunden sein sollte.",
          TextMapId = "PartyTopic_Description_150201"
        },
        PartyTopic_Description_150202 = {
          ContentES = "Auch wenn die Winde der Zukunft irgendwann alle Spuren verwehen, die wir hinterlassen haben, werden die glorreichen Momente, die wir einst geteilt haben, für immer in den Erinnerungen der Zurückgebliebenen weiterleben.",
          TextMapId = "PartyTopic_Description_150202"
        },
        PartyTopic_Description_150203 = {
          ContentES = "Wir wählen den Pfad, der zum Rand der Klippe führt, denn am Wegesrand begrüßen uns wunderschöne Wildblumen.",
          TextMapId = "PartyTopic_Description_150203"
        },
        PartyTopic_Description_150204 = {
          ContentES = "Unzählige Geschichten verweben sich zu der endlosen Reise ihres Lebens.",
          TextMapId = "PartyTopic_Description_150204"
        },
        PartyTopic_Description_150301 = {
          ContentES = "Im Herzen des Tiefwalds sucht jede Seele, eine Geschichte zu hinterlassen – die meisten sind von Rache und Liebe durchwoben. Doch keine Geschichte zu haben ... ist selbst eine Geschichte.",
          TextMapId = "PartyTopic_Description_150301"
        },
        PartyTopic_Description_150302 = {
          ContentES = "Hinter jedem Gipfel liegt eine Hoffnung, und hinter jeder Hoffnung ein schwindendes Licht. Doch beim Zurückblicken bleibt die schönste Aussicht jene, die er zurückließ.",
          TextMapId = "PartyTopic_Description_150302"
        },
        PartyTopic_Description_150303 = {
          ContentES = "Düfte wecken tiefverwurzelte Erinnerungen der Seele. Vielleicht ist das der Grund, warum jedes Herz andere Genüsse schätzt, denn kein Weg gleicht dem anderen.",
          TextMapId = "PartyTopic_Description_150303"
        },
        PartyTopic_Description_150304 = {
          ContentES = "Die Jugend, die das Schwert verfolgt, steigt immer weiter zum Gipfel. Weiter und weiter, bis die Gefährten weniger werden. Am Gipfel bleibt keiner, nur endloser Schnee über gesenkten Häuptern.",
          TextMapId = "PartyTopic_Description_150304"
        },
        PartyTopic_Description_180101 = {
          ContentES = "Mit Flüsterstimme raunte sie ihren Freunden ihre magischen Wünsche zu.",
          TextMapId = "PartyTopic_Description_180101"
        },
        PartyTopic_Description_180102 = {
          ContentES = "Sie schickte ihre längst vergessenen Träume in den Himmel zu den Sternen.",
          TextMapId = "PartyTopic_Description_180102"
        },
        PartyTopic_Description_180103 = {
          ContentES = "Sie begrub ihre Erinnerungen in fernen Ländern.",
          TextMapId = "PartyTopic_Description_180103"
        },
        PartyTopic_Description_180104 = {
          ContentES = "Sie vertraut ihre Hoffnungen für die Zukunft den leeren Seiten an.",
          TextMapId = "PartyTopic_Description_180104"
        },
        PartyTopic_Description_210101 = {
          ContentES = "*Klopf, klopf, klopf* – hast du das gehört? So klingt die Liebe, wenn sie hindurchströmt.",
          TextMapId = "PartyTopic_Description_210101"
        },
        PartyTopic_Description_210102 = {
          ContentES = "Liebe ist dazu da, auf die Probe gestellt zu werden. Anstelle süßer Nichtigkeiten wird ein Tropfen Gift zu einer weitaus ehrlicheren Prüfung. Für immer getrennt oder glücklich bis ans Ende ihrer Tage – warum finden wir es nicht hier und jetzt heraus?",
          TextMapId = "PartyTopic_Description_210102"
        },
        PartyTopic_Description_210103 = {
          ContentES = "Selbst Monster haben ihre Schwächen. Sie sind keine herzlosen Dämonen – nur einsame Außenseiter, die sich in der Menge verloren haben.",
          TextMapId = "PartyTopic_Description_210103"
        },
        PartyTopic_Description_210104 = {
          ContentES = "Liebe ist wie eine Klinge, die durch alle Schranken schneidet, sei es über Berge, Meere oder einen einzigen Tropfen tödlichen Gifts.",
          TextMapId = "PartyTopic_Description_210104"
        },
        PartyTopic_Description_230101 = {
          ContentES = "Tarnung bietet Schutz – Mimikry bestraft die Bösen.",
          TextMapId = "PartyTopic_Description_230101"
        },
        PartyTopic_Description_230102 = {
          ContentES = "Auch wenn andere die Begriffe „gut“ und „schlecht“ definieren, liegt es an dir, zu entscheiden, was richtig und was falsch ist.",
          TextMapId = "PartyTopic_Description_230102"
        },
        PartyTopic_Description_230103 = {
          ContentES = "Sobald du deine Augen öffnest, entfaltet sich vor dir eine weitaus größere Welt.",
          TextMapId = "PartyTopic_Description_230103"
        },
        PartyTopic_Description_230104 = {
          ContentES = "Selbst im Chaos findet man Wärme.",
          TextMapId = "PartyTopic_Description_230104"
        },
        PartyTopic_Description_240101 = {
          ContentES = "Eine Heilerin, einst schlummerte sie ein Jahrhundert lang, bietet dir nun an, deine Schlaflosigkeit zu kurieren.",
          TextMapId = "PartyTopic_Description_240101"
        },
        PartyTopic_Description_240102 = {
          ContentES = "Ein einziger Grashalm kann die Augen verschleiern – und alles, was vor ihnen liegt, wird zu einem Wachtraum aus Vergangenem.",
          TextMapId = "PartyTopic_Description_240102"
        },
        PartyTopic_Description_240103 = {
          ContentES = "Du hast sie gesehen, so klar wie der helle Tag – eine Heilerin, eine Nonkonformistin und eine Schwester.",
          TextMapId = "PartyTopic_Description_240103"
        },
        PartyTopic_Description_240104 = {
          ContentES = "Die Halle der Vergänglichkeit steht leer – und dennoch bleibt sie, solange die Erinnerung währt, das Zuhause, das ihr am Herzen liegt.",
          TextMapId = "PartyTopic_Description_240104"
        },
        PartyTopic_Description_310101 = {
          ContentES = "Das Leben ist einfach – iss, um zu leben, nicht umgekehrt. Wenn du diese Weisheit beherzigst, wendet sich alles zum Guten.",
          TextMapId = "PartyTopic_Description_310101"
        },
        PartyTopic_Description_310102 = {
          ContentES = "Hochspannung besitzt eine fast magische Anziehungskraft – sie fordert dich heraus, mit der Gefahr zu kokettieren und ihre riskanten Geheimnisse zu ergründen.",
          TextMapId = "PartyTopic_Description_310102"
        },
        PartyTopic_Description_310103 = {
          ContentES = "Noch schmerzlicher als der Verlust des Zuhauses ist es, wenn man feststellt, dass es zwar noch unversehrt ist, aber für immer unerreichbar bleibt.",
          TextMapId = "PartyTopic_Description_310103"
        },
        PartyTopic_Description_310201 = {
          ContentES = "Die Aufgaben einer Magd erstrecken sich auf alle Bereiche des Lebens – zu denen auch ein paar gehören, die vielleicht ein bisschen ... Blutvergießen mit sich bringen.",
          TextMapId = "PartyTopic_Description_310201"
        },
        PartyTopic_Description_310202 = {
          ContentES = "Der erste Eindruck ist entscheidend, und nichts sagt direkter über dich aus als deine Kleidung. Mode ist schließlich eine zeitlose Kunst.",
          TextMapId = "PartyTopic_Description_310202"
        },
        PartyTopic_Description_310203 = {
          ContentES = "*Schnipp, schnapp* Beschneide die Pflanzen – und mit ihnen auch die Sorgen.",
          TextMapId = "PartyTopic_Description_310203"
        },
        PartyTopic_Description_310204 = {
          ContentES = "Ganz egal, wie geschickt du dich versteckst, das „Erwachsenwerden“ findet immer einen Weg, dich zu erwischen.",
          TextMapId = "PartyTopic_Description_310204"
        },
        PartyTopic_Description_310301 = {
          ContentES = "Alle seine Aussagen beziehen sich auf Explosionen – das ist eine explosive Art, einen ersten Eindruck zu hinterlassen.",
          TextMapId = "PartyTopic_Description_310301"
        },
        PartyTopic_Description_310302 = {
          ContentES = "Ein unerwarteter Besuch, ein konfliktreiches Gespräch.",
          TextMapId = "PartyTopic_Description_310302"
        },
        PartyTopic_Description_310303 = {
          ContentES = "Sie sind vielleicht Erzfeinde, aber auch untrennbare Hälften desselben Ganzen.",
          TextMapId = "PartyTopic_Description_310303"
        },
        PartyTopic_Description_310304 = {
          ContentES = "Gefangen in der Dunkelheit ist geteilte Wärme das einzige Licht, das die Schwermut vertreibt.",
          TextMapId = "PartyTopic_Description_310304"
        },
        PartyTopic_Description_320101 = {
          ContentES = "Ein verwunschenes Haus, ein Gast mit Geheimnissen und ein Barkeeper, der seinen Beruf noch nicht beherrscht.",
          TextMapId = "PartyTopic_Description_320101"
        },
        PartyTopic_Description_320102 = {
          ContentES = "Ein starker Tropfen, destilliert aus hochkonzentrierten Pflanzenextrakten. Trotz des Namens schmeckt er nicht nur bitter – in ihm stecken zahlreiche Facetten, die sich stetig verändern und eine überraschende Vielschichtigkeit aufweisen.",
          TextMapId = "PartyTopic_Description_320102"
        },
        PartyTopic_Description_320103 = {
          ContentES = "Das Verlangen nach Süßem ist ganz natürlich – die Menschen fühlen sich, oft unbewusst, zu Erinnerungen an Fröhlichkeit und Geborgenheit hingezogen, auch wenn übermäßiger Genuss dem Körper zusetzen kann.",
          TextMapId = "PartyTopic_Description_320103"
        },
        PartyTopic_Description_320104 = {
          ContentES = "Brennt in der Kehle wie ein glühendes Messer – und nur der Trinkende weiß, was es in ihm aufschlitzt.",
          TextMapId = "PartyTopic_Description_320104"
        },
        PartyTopic_Description_330101 = {
          ContentES = "Wenn man guter Stimmung ist, kann das die Leistungsfähigkeit enorm beflügeln, und der Schlüssel zu guter Stimmung liegt darin, zu erkennen, wann man auf sich selbst achten muss.",
          TextMapId = "PartyTopic_Description_330101"
        },
        PartyTopic_Description_330102 = {
          ContentES = "Auch ausrangierte oder in Vergessenheit geratene Gegenstände können eine neue Bestimmung finden.",
          TextMapId = "PartyTopic_Description_330102"
        },
        PartyTopic_Description_330103 = {
          ContentES = "Was Vater und Tochter verbindet, sind nicht nur Gewohnheiten, Beruf, Blut und ihr Blick auf die Welt, sondern auch der liebevolle Titel „Dummkopf“.",
          TextMapId = "PartyTopic_Description_330103"
        },
        PartyTopic_Description_330104 = {
          ContentES = "Die Wege eines Menschen und einer Katze verlaufen unterschiedlich. Vielleicht ist es am besten, Verabschiedungen mit einem Lächeln zu akzeptieren und sich auf ein Wiedersehen zu freuen.",
          TextMapId = "PartyTopic_Description_330104"
        },
        PartyTopic_Description_410101 = {
          ContentES = "Sie sagt sich immer wieder: Die Augen zu verschließen ist das Grausamste, was man nur tun kann – also muss sie handeln, auch wenn es nur kleine Dinge sind.",
          TextMapId = "PartyTopic_Description_410101"
        },
        PartyTopic_Description_410102 = {
          ContentES = "Um den Weg vor sich zu erkennen – und voranzukommen – muss man manchmal innehalten und durchatmen.",
          TextMapId = "PartyTopic_Description_410102"
        },
        PartyTopic_Description_410103 = {
          ContentES = "Keine Jagd mehr nach den Notizen anderer – wende dich einer leeren Seite zu und beginne deine eigene Bewegung.",
          TextMapId = "PartyTopic_Description_410103"
        },
        PartyTopic_Description_420201 = {
          ContentES = "Wenn kluge Leute reden, verbirgt sich hinter ihren Worten immer eine Absicht. Effizienz ist ihr Handwerk, und in gewisser Weise ist das eine eigene Form von Ehrlichkeit.",
          TextMapId = "PartyTopic_Description_420201"
        },
        PartyTopic_Description_420202 = {
          ContentES = "Ein Gentleman wird nicht geboren, sondern geschmiedet – geprägt durch Bildung, veredelt durch das Umfeld und perfektioniert durch ein bisschen „Anleitung“ von der Familie.",
          TextMapId = "PartyTopic_Description_420202"
        },
        PartyTopic_Description_420203 = {
          ContentES = "Ach, Vater!",
          TextMapId = "PartyTopic_Description_420203"
        },
        PartyTopic_Description_420204 = {
          ContentES = "Ein letzter Tanz, bevor die Uhr zwölf schlägt.",
          TextMapId = "PartyTopic_Description_420204"
        },
        PartyTopic_Description_430101 = {
          ContentES = "Der wahre Test der Treue liegt in dem allgegenwärtigen Schwert, das jederzeit fallen kann.",
          TextMapId = "PartyTopic_Description_430101"
        },
        PartyTopic_Description_430102 = {
          ContentES = "Der Krieg endet niemals wirklich – er ändert nur seine Form.",
          TextMapId = "PartyTopic_Description_430102"
        },
        PartyTopic_Description_430103 = {
          ContentES = "Seit die Menschheit zum ersten Mal durch Wälder und über Ebenen streifte, sichern Werkzeuge das Überleben. Unabhängig davon, ob es um die Erschaffung oder die Zerstörung geht, bleibt ihr Zweck unverändert.",
          TextMapId = "PartyTopic_Description_430103"
        },
        PartyTopic_Description_510101 = {
          ContentES = "Die Nahrungsaufnahme ist das grundlegendste Bedürfnis aller Lebewesen, aber die Kunst des Speisens ist alles andere als einfach.",
          TextMapId = "PartyTopic_Description_510101"
        },
        PartyTopic_Description_510102 = {
          ContentES = "„Spare in der Zeit, so hast du in der Not“ – diese einfache Regel ist im Laufe des Lebens immer schwerer einzuhalten.",
          TextMapId = "PartyTopic_Description_510102"
        },
        PartyTopic_Description_510103 = {
          ContentES = "Filbert mag für Außenstehende wie ein ganz normales Schwein aussehen, aber für Truffle bedeutet er die Welt.",
          TextMapId = "PartyTopic_Description_510103"
        },
        PartyTopic_Description_510104 = {
          ContentES = "Jeder hat seine eigene Vorstellung von Glück, aber ein voller Magen verleiht uns auf jeden Fall die Energie, ihm nachzujagen.",
          TextMapId = "PartyTopic_Description_510104"
        },
        PartyTopic_Description_510201 = {
          ContentES = "Wahre Freunde erwarten keine Gegenleistungen. Eine warme Mahlzeit und ein freundliches Wort – das ist mehr als genug.",
          TextMapId = "PartyTopic_Description_510201"
        },
        PartyTopic_Description_510202 = {
          ContentES = "Selbst die kniffligsten Regeln lassen sich umgehen. Aber Menschen? Die, die Ärger machen – die ändern sich nie. Gewöhnt man sich zu sehr an sie, findet man sein Leben in Knoten verheddert.",
          TextMapId = "PartyTopic_Description_510202"
        },
        PartyTopic_Description_510203 = {
          ContentES = "Manche Geheimnisse kann man ruhig teilen – bei einem gemeinsamen Umtrunk mit dem richtigen Freund. Es erleichtert die Seele und bringt die Menschen näher zusammen. Aber andere? Die lässt man lieber vergraben. In der Tiefe, in der Dunkelheit und in der Unberührtheit. Es ist am Besten, wenn sie niemals ans Tageslicht kommen.",
          TextMapId = "PartyTopic_Description_510203"
        },
        PartyTopic_Description_510204 = {
          ContentES = "Es ist nicht mein richtiger Name – aber mittlerweile bevorzuge ich „Outsider”.",
          TextMapId = "PartyTopic_Description_510204"
        },
        PartyTopic_Description_530101 = {
          ContentES = "Nicht die Länge des Lebens ist entscheidend, sondern wie wir es leben.",
          TextMapId = "PartyTopic_Description_530101"
        },
        PartyTopic_Description_530102 = {
          ContentES = "Der Tod ist nicht das Schlimmste, solange man nicht in Vergessenheit gerät.",
          TextMapId = "PartyTopic_Description_530102"
        },
        PartyTopic_Description_530103 = {
          ContentES = "Niemand kann die Zukunft vorhersagen, aber selbst angesichts der Ungewissheiten des Lebens stellen wir uns dem Unbekannten und hoffen auf eine bessere Zukunft.",
          TextMapId = "PartyTopic_Description_530103"
        },
        PartyTopic_Description_540101 = {
          ContentES = "Anhaltende Schmerzen oder der sofortige Tod – ich weiß nicht, was grausamer ist. Aber vielleicht ... haben wir noch eine Chance, das erstere zu überwinden.",
          TextMapId = "PartyTopic_Description_540101"
        },
        PartyTopic_Description_540102 = {
          ContentES = "Kehre um – jetzt! Dies ist nicht der Turm, der mir im Traum erschien. In meinen Träumen gab es kein Blutvergießen ... kein Wehklagen!",
          TextMapId = "PartyTopic_Description_540102"
        },
        PartyTopic_Description_540103 = {
          ContentES = "Wenn sich die lange Nacht dem Ende zuneigt, ziehe auch ich weiter. Ich glaube, mich erwartet kein sinnloser Tod – sondern etwas, das jenseits davon liegt. Etwas, das ich finden muss.",
          TextMapId = "PartyTopic_Description_540103"
        },
        PartyTopic_Name_110101 = {
          ContentES = "Geschmack",
          TextMapId = "PartyTopic_Name_110101"
        },
        PartyTopic_Name_110102 = {
          ContentES = "Wunden",
          TextMapId = "PartyTopic_Name_110102"
        },
        PartyTopic_Name_110103 = {
          ContentES = "Die Ferne",
          TextMapId = "PartyTopic_Name_110103"
        },
        PartyTopic_Name_110104 = {
          ContentES = "Morgen",
          TextMapId = "PartyTopic_Name_110104"
        },
        PartyTopic_Name_110301 = {
          ContentES = "Angriffspunkt",
          TextMapId = "PartyTopic_Name_110301"
        },
        PartyTopic_Name_110302 = {
          ContentES = "Einsperren",
          TextMapId = "PartyTopic_Name_110302"
        },
        PartyTopic_Name_110303 = {
          ContentES = "Wendung",
          TextMapId = "PartyTopic_Name_110303"
        },
        PartyTopic_Name_110304 = {
          ContentES = "Trügerisches Finale",
          TextMapId = "PartyTopic_Name_110304"
        },
        PartyTopic_Name_150201 = {
          ContentES = "Der Tod ist sanft",
          TextMapId = "PartyTopic_Name_150201"
        },
        PartyTopic_Name_150202 = {
          ContentES = "Ein Sonnenstrahl",
          TextMapId = "PartyTopic_Name_150202"
        },
        PartyTopic_Name_150203 = {
          ContentES = "Die Landschaft entlang des falschen Weges",
          TextMapId = "PartyTopic_Name_150203"
        },
        PartyTopic_Name_150204 = {
          ContentES = "Ihre Geschichte",
          TextMapId = "PartyTopic_Name_150204"
        },
        PartyTopic_Name_150301 = {
          ContentES = "Tiefwald-Duo – Klingen im Spiel",
          TextMapId = "PartyTopic_Name_150301"
        },
        PartyTopic_Name_150302 = {
          ContentES = "Der Vagabund bereut – Jenseits von Bergen und Flüssen",
          TextMapId = "PartyTopic_Name_150302"
        },
        PartyTopic_Name_150303 = {
          ContentES = "Von Jadeflöten und durchwachten Nächten",
          TextMapId = "PartyTopic_Name_150303"
        },
        PartyTopic_Name_150304 = {
          ContentES = "Jugendkraft vom Schnee der Zeit erstarrt",
          TextMapId = "PartyTopic_Name_150304"
        },
        PartyTopic_Name_180101 = {
          ContentES = "Der Wunsch nach Magie",
          TextMapId = "PartyTopic_Name_180101"
        },
        PartyTopic_Name_180102 = {
          ContentES = "Der Wunsch nach den Sternen",
          TextMapId = "PartyTopic_Name_180102"
        },
        PartyTopic_Name_180103 = {
          ContentES = "Der Wunsch nach Überblick",
          TextMapId = "PartyTopic_Name_180103"
        },
        PartyTopic_Name_180104 = {
          ContentES = "Unerfüllter Wunsch",
          TextMapId = "PartyTopic_Name_180104"
        },
        PartyTopic_Name_210101 = {
          ContentES = "Liebe nähren",
          TextMapId = "PartyTopic_Name_210101"
        },
        PartyTopic_Name_210102 = {
          ContentES = "Einzigartig",
          TextMapId = "PartyTopic_Name_210102"
        },
        PartyTopic_Name_210103 = {
          ContentES = "Das Herz eines Monsters",
          TextMapId = "PartyTopic_Name_210103"
        },
        PartyTopic_Name_210104 = {
          ContentES = "Am Rande der Liebe",
          TextMapId = "PartyTopic_Name_210104"
        },
        PartyTopic_Name_230101 = {
          ContentES = "Meisterin der Verwandlung",
          TextMapId = "PartyTopic_Name_230101"
        },
        PartyTopic_Name_230102 = {
          ContentES = "Flucht aus dem Waisenhaus",
          TextMapId = "PartyTopic_Name_230102"
        },
        PartyTopic_Name_230103 = {
          ContentES = "Die Grenze zwischen Gut und Böse",
