        PhantomTalk_1101_Chest = {
          ContentES = "Hier ist eine Truhe, wollen wir sie gemeinsam öffnen?",
          TextMapId = "PhantomTalk_1101_Chest"
        },
        PhantomTalk_1102_Chest = {
          ContentES = "Unerwartetes Glück ... Vielleicht war es immer für dich bestimmt. ",
          TextMapId = "PhantomTalk_1102_Chest"
        },
        PhantomTalk_1103_Chest = {
          ContentES = "Nicht alle Überraschungen verstecken sich hinter dem Vorhang. Manche treten direkt ins Licht.",
          TextMapId = "PhantomTalk_1103_Chest"
        },
        PhantomTalk_1104_Chest = {
          ContentES = "Hier könnte ein Schatz liegen, {性别:mein junger Freund|meine junge Freundin} – leg ihn in deinen Vorrat.",
          TextMapId = "PhantomTalk_1104_Chest"
        },
        PhantomTalk_1501_Chest = {
          ContentES = "Eine Truhe? Zerschmettere sie, Samael! Moment, nein ... heute nicht.",
          TextMapId = "PhantomTalk_1501_Chest"
        },
        PhantomTalk_1502_Chest = {
          ContentES = "Es scheint ein Andenken zu sein ... vielleicht hinterlassen von einer Seele, die ins Nebelmeer getrieben wurde.",
          TextMapId = "PhantomTalk_1502_Chest"
        },
        PhantomTalk_1503_Chest = {
          ContentES = "Einige Schätze hier wären zu schade, um sie in der Erde zu lassen, nimm sie mit.",
          TextMapId = "PhantomTalk_1503_Chest"
        },
        PhantomTalk_160101_Chest = {
          ContentES = "Nicht schlecht, eine unerwartete Freude entdeckt.",
          TextMapId = "PhantomTalk_160101_Chest"
        },
        PhantomTalk_1601_Chest = {
          ContentES = "Nicht schlecht, eine unerwartete Freude entdeckt.",
          TextMapId = "PhantomTalk_1601_Chest"
        },
        PhantomTalk_1801_Chest = {
          ContentES = "Finas Freunde sagen, sie riechen den Schatz des Königs.",
          TextMapId = "PhantomTalk_1801_Chest"
        },
        PhantomTalk_2101_Chest = {
          ContentES = "Romantik braucht gelegentliche Überraschungen. Schau, hier ist eine.",
          TextMapId = "PhantomTalk_2101_Chest"
        },
        PhantomTalk_2301_Chest = {
          ContentES = "Etwas Schönes gefunden. Hehe, willst du raten, was drin ist?",
          TextMapId = "PhantomTalk_2301_Chest"
        },
        PhantomTalk_2401_Chest = {
          ContentES = "Unerwartetes Glück auf dem Land. Genug, um ein paar Heiltränke zu kaufen.",
          TextMapId = "PhantomTalk_2401_Chest"
        },
        PhantomTalk_3101_Chest = {
          ContentES = "Unerwartete Beute? Sieht aus, als hätten wir Glück.",
          TextMapId = "PhantomTalk_3101_Chest"
        },
        PhantomTalk_3102_Chest = {
          ContentES = "Wie ich schon sagte – beim Aufräumen gibt es gelegentlich Überraschungen.",
          TextMapId = "PhantomTalk_3102_Chest"
        },
        PhantomTalk_3103_Chest = {
          ContentES = "Äh ... Oliver meint, hier liegt etwas Glänzendes in der Nähe.",
          TextMapId = "PhantomTalk_3103_Chest"
        },
        PhantomTalk_3201_Chest = {
          ContentES = "Ungerechtes Eigentum? Nimm es, das widerspricht der Gerechtigkeit nicht.",
          TextMapId = "PhantomTalk_3201_Chest"
        },
        PhantomTalk_3202_Chest = {
          ContentES = "Glück ist auch eine Möglichkeit, Reichtum anzuhäufen. Nimm diese Dinge an.",
          TextMapId = "PhantomTalk_3202_Chest"
        },
        PhantomTalk_3301_Chest = {
          ContentES = "Ich rieche Schätze! Heute ist wohl ein guter Fang!",
          TextMapId = "PhantomTalk_3301_Chest"
        },
        PhantomTalk_4101_Chest = {
          ContentES = "Umgebung abgesucht, einige zurückgelassene Vorräte gefunden.",
          TextMapId = "PhantomTalk_4101_Chest"
        },
        PhantomTalk_4102_Chest = {
          ContentES = "Erde unten, Feuer oben – Gold durch Arbeit geboren. Die Zeichen haben nicht getäuscht.",
          TextMapId = "PhantomTalk_4102_Chest"
        },
        PhantomTalk_4201_Chest = {
          ContentES = "Solche weltlichen Dinge sind für mich nutzlos, nimm sie dir.",
          TextMapId = "PhantomTalk_4201_Chest"
        },
        PhantomTalk_4202_Chest = {
          ContentES = "Schatz? Schön, wenn man ihn gegen einen freien Tag eintauschen könnte.",
          TextMapId = "PhantomTalk_4202_Chest"
        },
        PhantomTalk_4301_Chest = {
          ContentES = "Herumliegende Schätze? Hmph. An Beute, die sich nicht wehrt, habe ich kein Interesse.",
