        },
        RESOURCE_DESC_ATTRITEM_Wind = {
          ContentES = "Cristal impregnado de magia Anemo. Obtenido a través de la Expedición abisal. Puede usarse como material de fundición para Armas de calamidad.",
          TextMapId = "RESOURCE_DESC_ATTRITEM_Wind"
        },
        RESOURCE_DESC_BACKPACKUNLOCK = {
          ContentES = "Se usa para desbloquear el permiso de uso de la Bolsa del tesoro del tamaño correspondiente",
          TextMapId = "RESOURCE_DESC_BACKPACKUNLOCK"
        },
        RESOURCE_DESC_CANCELPHANTOM = {
          ContentES = "Un sello utilizado para anular una invocación.\nAunque el encuentro haya sido breve, el recuerdo no se extingue, tal vez el próximo reencuentro ocurra en un abrir y cerrar de ojos.",
          TextMapId = "RESOURCE_DESC_CANCELPHANTOM"
        },
        RESOURCE_DESC_GENERALSKIN_1 = {
          ContentES = "Nach der Verwendung kann ein Outfit aus folgenden Figuren ausgewählt werden: Berenica, Phantasio, Lisbell, Frau Nifle, Fina, Rebecca, Tabethe, Lynn, Yale und Oliver, Hellfire, Margie, Rhythm, Randy, Sibylle, Truffle und Filbert, Outsider, Psyche oder Daphne.",
          TextMapId = "RESOURCE_DESC_GENERALSKIN_1"
        },
        RESOURCE_DESC_GENERALSKIN_2 = {
          ContentES = "Nach der Verwendung kann ein Outfit aus folgenden Figuren ausgewählt werden: Berenica, Phantasio, Lisbell, Frau Nifle, Kezhou, Fina, Rebecca, Tabethe, Fushu, Lynn, Yale und Oliver, Hellfire, Margie, Rhythm, Randy, Sibylle, Truffle und Filbert, Outsider, Psyche oder Daphne.",
          TextMapId = "RESOURCE_DESC_GENERALSKIN_2"
        },
        RESOURCE_DESC_HYPERWEAPONPROTOTYPE = {
          ContentES = "Uno de los prototipos legendarios de Arma de calamidad.\nSu destino fue amargo como el ajenjo, afilado como una espada de dos filos.\nSe obtiene por medios especiales y puede usarse como material de fundición para Armas de calamidad.",
          TextMapId = "RESOURCE_DESC_HYPERWEAPONPROTOTYPE"
        },
        RESOURCE_DESC_MONSTERITEM_Diguo = {
          ContentES = "Insignia obtenida al derrotar enemigos del Imperio Hiperbóreo. El poder supremo que perseguían murió en la cuna de su derrota.\nPuede usarse para forjar Armas de calamidad.",
          TextMapId = "RESOURCE_DESC_MONSTERITEM_Diguo"
        },
        RESOURCE_DESC_MONSTERITEM_Dongguo = {
          ContentES = "Insignia obtenida al derrotar enemigos de Huaxu. La paz construida sobre la voluntad humana y la ley es un equilibrio que millones de personas han sostenido durante miles de años.\nPuede usarse para forjar Armas de calamidad.",
          TextMapId = "RESOURCE_DESC_MONSTERITEM_Dongguo"
        },
        RESOURCE_DESC_MONSTERITEM_Huishou = {
          ContentES = "Insignia obtenida al derrotar Filthoids. El recuerdo de la hoja rajando el inmundo caparazón del monstruo sigue grabado en tu mente; ni una gota de sangre brotó de las heridas.\nPuede usarse para forjar Armas de calamidad.",
          TextMapId = "RESOURCE_DESC_MONSTERITEM_Huishou"
        },
        RESOURCE_DESC_MONSTERITEM_Jiaohui = {
          ContentES = "Insignia obtenida al derrotar enemigos de la Iglesia Elysiana. La fe se quebró en la larga noche, y el asceta maldijo al sol que tardaba en salir.\nPuede usarse para forjar Armas de calamidad.",
          TextMapId = "RESOURCE_DESC_MONSTERITEM_Jiaohui"
        },
        RESOURCE_DESC_MONSTERITEM_Tongmeng = {
          ContentES = "Insignia obtenida al derrotar miembros de Los Abandonados. Abandonados por el mundo, y ellos respondieron con matanza. ¿Pero puede la sangre redimirlos?\nPuede usarse para forjar Armas de calamidad.",
          TextMapId = "RESOURCE_DESC_MONSTERITEM_Tongmeng"
        },
        RESOURCE_DESC_MUSIC = {
          ContentES = "Una partitura cuyas notas trazan una historia, como huellas dejadas en la arena.",
          TextMapId = "RESOURCE_DESC_MUSIC"
        },
        RESOURCE_DESC_OPTWEAPON_1 = {
          ContentES = "Nach der Nutzung kann eine Waffe aus der Liste frei ausgewählt werden.",
          TextMapId = "RESOURCE_DESC_OPTWEAPON_1"
        },
        RESOURCE_DESC_PHANTOM = {
          ContentES = "Un sello usado para invocar a un aliado, un símbolo de lucha codo a codo, un lazo de confianza para caminar juntos, una promesa silenciosa.\nCuando tus oraciones transmiten tus pensamientos, esa persona aparecerá a tu lado.",
          TextMapId = "RESOURCE_DESC_PHANTOM"
        },
        RESOURCE_DESC_ROOT = {
          ContentES = "Fragmentos de pensamiento extraídos de las arenas movedizas de la memoria, contienen recuerdos pasados o futuros sobre cierta persona.",
          TextMapId = "RESOURCE_DESC_ROOT"
        },
        RESOURCE_DESC_TICKET = {
          ContentES = "Sigue los pasos de la calamidad, busca el poder capaz de derribar el mundo y deja que la brújula marque tu camino.\nPuede usarse para entrar en la Expedición abisal.",
          TextMapId = "RESOURCE_DESC_TICKET"
        },
        RESOURCE_DESC_WEAPONPIECE = {
