        RLBlessingGroup_Active = {
          ContentES = "Kann aktiviert werden",
          TextMapId = "RLBlessingGroup_Active"
        },
        RLBlessingGroup_Desc_1 = {
          ContentES = "Verstärkungen der Nahkampfwaffen",
          TextMapId = "RLBlessingGroup_Desc_1"
        },
        RLBlessingGroup_Desc_101 = {
          ContentES = "Jeder Docht dieses Sets erhöht zusätzlich die KRIT-Rate um <Highlight>15 %</> und den KRIT-SCH um <Highlight>15 %</> bei Nahkampfwaffen.\n Das Verursachen von Schaden mit Nahkampfwaffen hat eine Chance von <Highlight>10 %</>, 1 Stapelung [Schmelz-Feuerglut] anzuwenden.",
          TextMapId = "RLBlessingGroup_Desc_101"
        },
        RLBlessingGroup_Desc_102 = {
          ContentES = "[Schmelz-Feuerglut] verursacht alle <Highlight>1</> s DoT in Höhe von <Highlight>35 %</> des ANG der Figur.",
          TextMapId = "RLBlessingGroup_Desc_102"
        },
        RLBlessingGroup_Desc_103 = {
          ContentES = "Verlängert die Dauer von [Schmelz-Feuerglut] auf <Highlight>10</> s, bis zu <Highlight>20</>-mal stapelbar.",
          TextMapId = "RLBlessingGroup_Desc_103"
        },
        RLBlessingGroup_Desc_104 = {
          ContentES = "Ziele, die von [Schmelz-Feuerglut] betroffen sind, erleiden alle <Highlight>5 </> s einen Treffer durch [Schmelz-Feuerglutsäbel]. Wenn du mit Nahkampfwaffen SCH verursachst, besteht eine Chance von <Highlight>10 %</>, zusätzlich [Schmelz-Feuerglutsäbel] auszulösen.",
          TextMapId = "RLBlessingGroup_Desc_104"
        },
        RLBlessingGroup_Desc_2 = {
          ContentES = "Verstärkungen der Fernkampfwaffen",
          TextMapId = "RLBlessingGroup_Desc_2"
        },
        RLBlessingGroup_Desc_201 = {
          ContentES = "Jeder Docht dieses Sets erhöht zusätzlich die KRIT-Rate um <Highlight>15 %</> und den KRIT-SCH um <Highlight>15 %</> bei Fernkampfwaffen.\n Erhöht den Sammelradius. Gewährt nach dem Aufsammeln von Beute für <Highlight>3</> s Immunität gegen Trefferstarre.",
          TextMapId = "RLBlessingGroup_Desc_201"
        },
        RLBlessingGroup_Desc_202 = {
          ContentES = "Wenn du mit einer Fernkampfwaffe SCH verursachst, wird [Meergebundener Mond] aktiviert und es werden <Highlight>3</> zusätzliche [Mini-Meergebundene Monde] gespawnt (kann einmal alle <Highlight>10</> s ausgelöst werden).",
          TextMapId = "RLBlessingGroup_Desc_202"
        },
        RLBlessingGroup_Desc_203 = {
          ContentES = "Das Einsammeln eines [Mini-Meergebundener Mond] gewährt 1 [Verschleierter Mond].",
          TextMapId = "RLBlessingGroup_Desc_203"
        },
        RLBlessingGroup_Desc_204 = {
          ContentES = "Beim Einsatz von [Verschleierter Mond] werden <Highlight>3</> [Stinger] in einem fächerförmigen Muster abgefeuert. Das Aufsammeln von Beute gewährt 1 Stapelung [Phantomdrift].",
          TextMapId = "RLBlessingGroup_Desc_204"
        },
        RLBlessingGroup_Desc_3 = {
          ContentES = "Verstärkungen der Fähigkeiten",
          TextMapId = "RLBlessingGroup_Desc_3"
        },
        RLBlessingGroup_Desc_301 = {
          ContentES = "Jeder Docht dieses Sets erhöht das max. Schild um <Highlight>10 %</>.\n Erhöht den Fähigkeits-SCH um <Highlight>25 %</>.",
          TextMapId = "RLBlessingGroup_Desc_301"
        },
        RLBlessingGroup_Desc_302 = {
          ContentES = "Erhält 1 Stapelung von <Highlight>[Glanz]</> pro Sekunde (max. 60). Bei 60 Stapelungen verbraucht das Einsetzen einer Fähigkeit alle <Highlight>[Glanz]</> und gewährt <Highlight>[Strahlung]</> für 10 s</>, wodurch der Fähigkeits-SCH um <Highlight>50 %</> erhöht wird.",
          TextMapId = "RLBlessingGroup_Desc_302"
        },
        RLBlessingGroup_Desc_303 = {
          ContentES = "Solange du unter [Strahlung] stehst, löst du alle 2 s 1 [Emission] aus, die Gegnern im Umkreis von <Highlight>6</> m einmal Fähigkeits-SCH in Höhe von <Highlight>810 %</> des ANG der Figur zufügt.",
          TextMapId = "RLBlessingGroup_Desc_303"
        },
        RLBlessingGroup_Desc_304 = {
          ContentES = "Verlängert die Dauer der [Strahlung] auf <Highlight>20</> s.",
          TextMapId = "RLBlessingGroup_Desc_304"
        },
        RLBlessingGroup_Desc_4 = {
          ContentES = "Spezialisiertes beschworenes Objekt",
          TextMapId = "RLBlessingGroup_Desc_4"
        },
        RLBlessingGroup_Desc_401 = {
          ContentES = "Jeder Docht dieses Sets erhöht den SCH des beschworenen Objekts um <Highlight>10 %</>.\n Bei jeder Beschwörung eines beschworenen Objekts außer dem Lumi-Zweigs wird 1 [Lumi-Saat] beschworen.\n [Lumi-Saat]: Detoniert, wenn ein Gegner innerhalb von <Highlight>3</> m auftaucht, und verursacht SCH in Höhe von <Highlight>600 %</> des ANG. Hält <Highlight>10</> s an; gleichzeitig können maximal <Highlight>10</> existieren.",
          TextMapId = "RLBlessingGroup_Desc_401"
        },
        RLBlessingGroup_Desc_402 = {
          ContentES = "Jede [Lumi-Saat] hat eine Chance von <Highlight>40 %</>, sich in [Lumi-Blatt] zu entwickeln, wenn es beschworen wird.\n [Lumi-Blatt]: Detoniert, wenn ein Gegner innerhalb von <Highlight>3</> m auftaucht, und verursacht SCH in Höhe von <Highlight>1000 %</> des ANG. Hält <Highlight>10</> s an; gleichzeitig können maximal <Highlight>10</> existieren.",
          TextMapId = "RLBlessingGroup_Desc_402"
        },
        RLBlessingGroup_Desc_403 = {
          ContentES = "[Lumi-Blatt] erzeugt bei der Detonation 1 [Lumi-Holz]. Erhält die Figur Heilung, erleiden Gegner im Umkreis von <Highlight>6</> SCH in Höhe von <Highlight>4000 </> der Heilungsmenge.\n [Lumi-Holz]: Heilt Verbündete im Umkreis von <Highlight>10</> um <Highlight>5 %</> der max. LP pro Sekunde. Hält <Highlight>10</> s an; gleichzeitig kann nur 1 existieren.",
          TextMapId = "RLBlessingGroup_Desc_403"
        },
        RLBlessingGroup_Desc_404 = {
          ContentES = "Verdoppelt die Chance für alle Effekte, die [Lumi-Saat] beschwören können. [Lumi-Holz] fügt Gegnern in Reichweite pro Sekunde einmal SCH in Höhe von <Highlight>650 %</> des ANG zu.",
          TextMapId = "RLBlessingGroup_Desc_404"
        },
        RLBlessingGroup_Desc_5 = {
          ContentES = "Verstärkungen der Mobilität",
          TextMapId = "RLBlessingGroup_Desc_5"
        },
        RLBlessingGroup_Desc_501 = {
          ContentES = "Jeder Docht dieses Sets erhöht den max. Geist um <Highlight>10 %</>.\n Jeder Stapelung von [Umbraler Verschlinger] erhöht ANG der Figur um <Highlight>1 %</>.",
          TextMapId = "RLBlessingGroup_Desc_501"
        },
        RLBlessingGroup_Desc_502 = {
          ContentES = "Das Verursachen von Schaden gewährt <Highlight>5</> Stapelungen von [Umbraler Verschlinger]. (maximal einmal alle <Highlight>5</> s ausgelöst).",
          TextMapId = "RLBlessingGroup_Desc_502"
        },
        RLBlessingGroup_Desc_503 = {
          ContentES = "Stellt <Highlight>2</> Punkte Geist pro Sekunde für jeweils 10 Stapelungen von [Umbraler Verschlinger] wieder her.",
          TextMapId = "RLBlessingGroup_Desc_503"
        },
        RLBlessingGroup_Desc_504 = {
          ContentES = "[Pulver], [Windflügel] und [Klingenflügel] verursachen beim Schaden zusätzlich einen Treffer, der SCH in Höhe von <Highlight>1 % × ANG der Figur × Max. Geist</> zufügt.",
          TextMapId = "RLBlessingGroup_Desc_504"
        },
        RLBlessingGroup_Desc_6 = {
          ContentES = "Suchrakete",
          TextMapId = "RLBlessingGroup_Desc_6"
        },
        RLBlessingGroup_Desc_601 = {
          ContentES = "Jeder Docht dieses Sets erhöht die Fähigkeitsreichweite zusätzlich um <Highlight>10 %</>.\n Die max. Anzahl der [Glühkäfer] wird um <Highlight>1</> erhöht. [Glühkäfer] verursachen nun Flächenschaden in einem Radius von <Highlight>2</> m.",
          TextMapId = "RLBlessingGroup_Desc_601"
        },
        RLBlessingGroup_Desc_602 = {
          ContentES = "Wenn du einen Glühkäfer erhältst, besteht eine Chance von <Highlight>30 %</>, eine größere Variante zu spawnen.",
          TextMapId = "RLBlessingGroup_Desc_602"
        },
        RLBlessingGroup_Desc_603 = {
          ContentES = "Die max. Anzahl der [Glühkäfer] wird um <Highlight>1</> erhöht. Größere Varianten teilen sich bei einem Treffer in <Highlight>3</> normale [Glühkäfer].",
          TextMapId = "RLBlessingGroup_Desc_603"
        },
        RLBlessingGroup_Desc_604 = {
          ContentES = "Wenn [Glühkäfer] SCH verursacht, erhöht den erlittenen SCH dauerhaft um <Highlight>12 %</>, bis zu <Highlight>5</>-mal stapelbar.",
          TextMapId = "RLBlessingGroup_Desc_604"
        },
        RLBlessingGroup_Desc_7 = {
          ContentES = "Verstärkt die Überlebensfähigkeit und gewährt den Status Zorn.",
          TextMapId = "RLBlessingGroup_Desc_7"
        },
        RLBlessingGroup_Desc_701 = {
          ContentES = "Jeder Docht dieses Sets erhöht die Fähigkeitsdauer zusätzlich um <Highlight>10 %</>.\n Beim Besiegen eines Gegners werden die max. LP um <Highlight>0,5 %</> erhöht, bis zu <Highlight>50 %</>.",
          TextMapId = "RLBlessingGroup_Desc_701"
        },
        RLBlessingGroup_Desc_702 = {
          ContentES = "Stellt <Highlight>1 %</> der max. LP pro Sekunde wieder her. Der Effekt wird um <Highlight>0,33 %</> für jeweils <Highlight>25 %</> verlorene LP erhöht.",
          TextMapId = "RLBlessingGroup_Desc_702"
        },
        RLBlessingGroup_Desc_703 = {
          ContentES = "Fügt Gegnern in Reichweite alle 3 Sekunden SCH in Höhe von <Highlight>50 %</> der max. LP der Figur zu. Für jeweils <Highlight>25 %</> verlorene LP wird der Effekt um <Highlight>16,7 %</> erhöht.",
          TextMapId = "RLBlessingGroup_Desc_703"
        },
        RLBlessingGroup_Desc_704 = {
          ContentES = "Bei mehr als <Highlight>40 %</> LP werden alle [Vamprose]-Effekte, die auf dem aktuellen LP-Prozentsatz basieren, für die Berechnung so behandelt, als lägen nur <Highlight>40 %</> LP vor. Auch bei Moral- und Entschlossenheitseffekten wird der LP-Prozentsatz für die Berechnung auf <Highlight>40 %</> begrenzt.",
          TextMapId = "RLBlessingGroup_Desc_704"
        },
        RLBlessingGroup_Desc_unknown = {
          ContentES = "Dieser Segen bleibt im Nebel verborgen",
          TextMapId = "RLBlessingGroup_Desc_unknown"
        },
        RLBlessingGroup_HavingNum = {
          ContentES = "Aktiviert",
          TextMapId = "RLBlessingGroup_HavingNum"
        },
        RLBlessingGroup_Name_1 = {
          ContentES = "Kernflamme",
          TextMapId = "RLBlessingGroup_Name_1"
        },
        RLBlessingGroup_Name_2 = {
          ContentES = "Meergebundener Mond",
          TextMapId = "RLBlessingGroup_Name_2"
        },
        RLBlessingGroup_Name_3 = {
