        },
        RLBlessing_ActivateGroup = {
          ContentES = "Aktiviere den Artefakt-Set-Effekt",
          TextMapId = "RLBlessing_ActivateGroup"
        },
        RLBlessing_Desc_101 = {
          ContentES = "Erhöht ANG der Nahkampfwaffen um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_101"
        },
        RLBlessing_Desc_102 = {
          ContentES = "Erhöht die Auslöserate der Nahkampfwaffen um <Highlight>#1</>",
          TextMapId = "RLBlessing_Desc_102"
        },
        RLBlessing_Desc_103 = {
          ContentES = "Erhöht den Standardangriff-SCH der Nahkampfwaffen um <Highlight>$1</>.",
          TextMapId = "RLBlessing_Desc_103"
        },
        RLBlessing_Desc_104 = {
          ContentES = "Wenn du Gegner innerhalb von <Highlight>$2</> m besiegst, stellst du <Highlight>$1</> LP wieder her.",
          TextMapId = "RLBlessing_Desc_104"
        },
        RLBlessing_Desc_105 = {
          ContentES = "Erlittener SCH durch Gegner im Umkreis von <Highlight>$2</> m oder durch Gegner mit [Schmelz-Feuerglut] wird um <Highlight>$1</> reduziert.",
          TextMapId = "RLBlessing_Desc_105"
        },
        RLBlessing_Desc_106 = {
          ContentES = "Wenn du SCH erleidest, wird <Highlight>1</> Stapelung von [Schmelz-Feuerglut] auf Gegner im Umkreis von <Highlight>8</> m angewendet. Kann einmal alle <Highlight>$1</> s ausgelöst werden.",
          TextMapId = "RLBlessing_Desc_106"
        },
        RLBlessing_Desc_107 = {
          ContentES = "Erhöht die <Highlight>KRIT-Rate</> der Nahkampfwaffen um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_107"
        },
        RLBlessing_Desc_108 = {
          ContentES = "Erhöht den <Highlight>KRIT-SCH</> der Nahkampfwaffe um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_108"
        },
        RLBlessing_Desc_109 = {
          ContentES = "Erhöht den SCH der Nahkampfwaffen beim <Highlight>Sturzangriff, geladenen Angriff und Gleitangriff </> um <Highlight>$1</>.",
          TextMapId = "RLBlessing_Desc_109"
        },
        RLBlessing_Desc_110 = {
          ContentES = "Wendet alle <Highlight>$1</> s <Highlight>1</> Stapelung von [Schmelz-Feuerglut] auf Gegner innerhalb von <Highlight>8</> m an.",
          TextMapId = "RLBlessing_Desc_110"
        },
        RLBlessing_Desc_111 = {
          ContentES = "Wenn du Gegnern mit mehr als <Highlight>$3</> Stapelungen von [Schmelz-Feuerglut] SCH zufügst, werden <Highlight>$1</> LP wiederhergestellt. Kann einmal alle <Highlight>$2</> s ausgelöst werden.",
          TextMapId = "RLBlessing_Desc_111"
        },
        RLBlessing_Desc_112 = {
          ContentES = "Erhöht die <Highlight>Angriffs-GES </> der Nahkampfwaffen um <Highlight>#1</> und die <Highlight>Angriffsreichweite</> um <Highlight>#2</>.",
          TextMapId = "RLBlessing_Desc_112"
        },
        RLBlessing_Desc_113 = {
          ContentES = "Wenn der SCH die LP des Ziels unter <Highlight>$3</> senkt, fügt er einmal SCH in Höhe von <Highlight>$1</> des ANG der Figur zu. Kann nur einmal alle <Highlight>$2</> s bei demselben Ziel ausgelöst werden.",
          TextMapId = "RLBlessing_Desc_113"
        },
        RLBlessing_Desc_114 = {
          ContentES = "Nahkampfwaffen fügen Zielen mit mehr als <Highlight>$2</> Stapelungen von [Schmelz-Feuerglut] einen Bonus-SCH in Höhe von <Highlight>$1</> des ANG der Figur zu.",
          TextMapId = "RLBlessing_Desc_114"
        },
        RLBlessing_Desc_115 = {
          ContentES = "Je weniger Gegner sich im Umkreis von <Highlight>8 Metern</> befinden, desto höher ist der verursachte SCH (bis zu <Highlight>$1</>).",
          TextMapId = "RLBlessing_Desc_115"
        },
        RLBlessing_Desc_201 = {
          ContentES = "Erhöht den <Highlight>ANG</> der Fernkampfwaffe um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_201"
        },
        RLBlessing_Desc_202 = {
          ContentES = "Erhöht <Highlight>Auslöserate</> der Fernkampfwaffen um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_202"
        },
        RLBlessing_Desc_203 = {
          ContentES = "Wenn du mit Fernkampfwaffen SCH verursachst, wird eine [Munitionskiste] gespawnt (kann einmal alle <Highlight>$1</> s ausgelöst werden). Während Phase II von [Meergebundener Mond] aktiv ist, spawnen <Highlight>1</> zusätzlicher [Mini-Meergebundener Mond].",
          TextMapId = "RLBlessing_Desc_203"
        },
        RLBlessing_Desc_204 = {
          ContentES = "Das Aufsammeln von Gegenständen bringt <Highlight>$1</> Ultra-Schilde. Dieser Effekt kann nur einmal alle <Highlight>5</> s ausgelöst werden.",
          TextMapId = "RLBlessing_Desc_204"
        },
        RLBlessing_Desc_205 = {
          ContentES = "Bringt [Aktiviertes Sal Volatil] oder [Beruhigungstautropfen] hervor, wenn du SCH verursachst. Dieser Effekt kann nur einmal alle <Highlight>$1</> s ausgelöst werden. Wenn Phase II von [Meergebundener Mond] aktiv ist, spawnen <Highlight>1</> zusätzlicher [Mini-Meergebundener Mond].",
          TextMapId = "RLBlessing_Desc_205"
        },
        RLBlessing_Desc_206 = {
          ContentES = "Wenn sich Gegner innerhalb von <Highlight>20</> m befinden und Phase III aktiv ist, erhöht sich der ANG der Figur um <Highlight>$1</>; andernfalls erhöht sich der ANG der Figur um <Highlight>$2</>.",
          TextMapId = "RLBlessing_Desc_206"
        },
        RLBlessing_Desc_207 = {
          ContentES = "Erhöht <Highlight>KRIT-Rate</> der Fernkampfwaffen um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_207"
        },
        RLBlessing_Desc_208 = {
          ContentES = "Erhöht <Highlight>KRIT-SCH</> der Fernkampfwaffen um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_208"
        },
        RLBlessing_Desc_209 = {
          ContentES = "Wenn die LP oder der Geist unter <Highlight>$2</> fallen, wird die Wahrscheinlichkeit erhöht, dass <Highlight>[Vorrat des Ozeans]</> passende Vorräte erzeugt, bis zu <Highlight>$1</>.\n Wenn LP, Geist oder Munition unter <Highlight>$2</> fallen, erhöht sich die Anzahl der gespawnten [Mini-Meergebundener Mond] um <Highlight>100 %</>.",
          TextMapId = "RLBlessing_Desc_209"
        },
        RLBlessing_Desc_210 = {
          ContentES = "Das Aufsammeln von Gegenständen stellt zusätzliche <Highlight>$1</> Punkte Geist wieder her.",
          TextMapId = "RLBlessing_Desc_210"
        },
        RLBlessing_Desc_211 = {
          ContentES = "Verringert die Abklingzeit der Geniemon-Unterstützung um <Highlight>$1</>.",
          TextMapId = "RLBlessing_Desc_211"
        },
        RLBlessing_Desc_212 = {
          ContentES = "Erhöht <Highlight>Mehrfachschussrate</> der Fernkampfwaffen um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_212"
        },
        RLBlessing_Desc_213 = {
          ContentES = "Erhöht <Highlight>Angriffs-GES </> der Fernkampfwaffen um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_213"
        },
        RLBlessing_Desc_214 = {
          ContentES = "Fernkampfwaffen-SCH an Zielen, die mehr als <Highlight>$2</> m entfernt sind, verursacht zusätzlich <Highlight>$1</> Fernkampfwaffen-SCH, bis maximal <Highlight>$3</>.",
          TextMapId = "RLBlessing_Desc_214"
        },
        RLBlessing_Desc_215 = {
          ContentES = "Wenn du dich für mehr als <Highlight>2</> s ununterbrochen bewegst, verringert sich erlittener SCH um <Highlight>$1</> (bis angehalten).\n Wenn du länger als <Highlight>2</> s stillstehst, erhöht sich verursachter SCH um <Highlight>$2</> (bis du dich bewegst).",
          TextMapId = "RLBlessing_Desc_215"
        },
        RLBlessing_Desc_301 = {
          ContentES = "Erhöht die Fähigkeitsreichweite um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_301"
        },
        RLBlessing_Desc_302 = {
          ContentES = "Erhöht die Fähigkeitsdauer um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_302"
        },
        RLBlessing_Desc_303 = {
          ContentES = "Erhöht die Fähigkeitseffizienz um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_303"
        },
        RLBlessing_Desc_304 = {
          ContentES = "Stellt <Highlight>$1</> Punkte Geist wieder her, wenn du Fähigkeiten einsetzt. Dieser Effekt kann nur einmal alle <Highlight>$2</> s ausgelöst werden.",
          TextMapId = "RLBlessing_Desc_304"
        },
        RLBlessing_Desc_305 = {
          ContentES = "Stellt beim Einsatz von Fähigkeiten den Schild um <Highlight>$1</> des Max. Schildes wieder her. Dieser Effekt kann nur einmal alle <Highlight>$2</> s ausgelöst werden.",
          TextMapId = "RLBlessing_Desc_305"
        },
        RLBlessing_Desc_306 = {
          ContentES = "Erhöht die Fähigkeits-GES um <Highlight>$1</>.",
          TextMapId = "RLBlessing_Desc_306"
        },
        RLBlessing_Desc_307 = {
          ContentES = "Erhöht max. Geist um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_307"
        },
        RLBlessing_Desc_308 = {
          ContentES = "Reduziert den erlittenen SCH um <Highlight>$1</>, wenn Geist unter <Highlight>$2</> fällt.",
          TextMapId = "RLBlessing_Desc_308"
        },
        RLBlessing_Desc_309 = {
          ContentES = "Wenn der Geist unter <Highlight>$3</> fällt, werden über <Highlight>$4</> s jede Sekunde <Highlight>$1</> Punkte Geist wiederhergestellt. Dieser Effekt kann nur einmal alle <Highlight>$2</> s ausgelöst werden.",
          TextMapId = "RLBlessing_Desc_309"
        },
        RLBlessing_Desc_310 = {
          ContentES = "Gewährt beim Einsatz von Fähigkeiten <Highlight>$1</> Stapelung [Glanz].",
          TextMapId = "RLBlessing_Desc_310"
        },
        RLBlessing_Desc_311 = {
          ContentES = "Im Zustand [Strahleung] erhältst du ‍<Highlight>$1</>‍ Punkte Geist pro Sekunde.",
          TextMapId = "RLBlessing_Desc_311"
        },
        RLBlessing_Desc_312 = {
          ContentES = "Erhöht den Fähigkeits-SCH um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_312"
        },
        RLBlessing_Desc_313 = {
          ContentES = "Fähigkeits-SCH ignoriert <Highlight>$1</> VTD des Ziels.",
          TextMapId = "RLBlessing_Desc_313"
        },
        RLBlessing_Desc_314 = {
          ContentES = "Die Erhöhung des Fähigkeits-SCH durch [Strahlung] wurde auf <Highlight>$1</> erhöht.",
          TextMapId = "RLBlessing_Desc_314"
        },
