        },
        RLBlessing_SimpleDesc_102 = {
          ContentES = "Erhöht Auslöserate der Nahkampfwaffen",
          TextMapId = "RLBlessing_SimpleDesc_102"
        },
        RLBlessing_SimpleDesc_103 = {
          ContentES = "Erhöht den Standardangriff-SCH der Nahkampfwaffen",
          TextMapId = "RLBlessing_SimpleDesc_103"
        },
        RLBlessing_SimpleDesc_104 = {
          ContentES = "Stellt LP wieder her, wenn du Gegner im <Highlight>Nahkampfreichweite</> besiegst.",
          TextMapId = "RLBlessing_SimpleDesc_104"
        },
        RLBlessing_SimpleDesc_105 = {
          ContentES = "Erlittener SCH durch Gegner <Highlight>in der Nähe</> oder durch Gegner mit [Schmelz-Feuerglut] wird reduziert.",
          TextMapId = "RLBlessing_SimpleDesc_105"
        },
        RLBlessing_SimpleDesc_106 = {
          ContentES = "Wenn du Schaden erleiderst, wird [Schmelz-Feuerglut] auf Gegner <Highlight>in der Nähe</> angewendet.",
          TextMapId = "RLBlessing_SimpleDesc_106"
        },
        RLBlessing_SimpleDesc_107 = {
          ContentES = "Erhöht die <Highlight>KRIT-Rate</> der Nahkampfwaffen.",
          TextMapId = "RLBlessing_SimpleDesc_107"
        },
        RLBlessing_SimpleDesc_108 = {
          ContentES = "Erhöht den <Highlight>KRIT-SCH</> der Nahkampfwaffen.",
          TextMapId = "RLBlessing_SimpleDesc_108"
        },
        RLBlessing_SimpleDesc_109 = {
          ContentES = "Erhöht den SCH der Nahkampfwaffen beim <Highlight>Sturzangriff, geladenen Angriff und Gleitangriff</>.",
          TextMapId = "RLBlessing_SimpleDesc_109"
        },
        RLBlessing_SimpleDesc_110 = {
          ContentES = "Wendet regelmäßig [Schmelz-Feuerglut] auf <Highlight>Gegner in der Nähe</> an.",
          TextMapId = "RLBlessing_SimpleDesc_110"
        },
        RLBlessing_SimpleDesc_111 = {
          ContentES = "Stellt LP wieder her, wenn du Gegnern mit [Schmelz-Feuerglut] SCH zufügst.",
          TextMapId = "RLBlessing_SimpleDesc_111"
        },
        RLBlessing_SimpleDesc_112 = {
          ContentES = "Erhöht die <Highlight>Angriffs-GES </> und die <Highlight>Angriffsreichweite</> der Nahkampfwaffen.",
          TextMapId = "RLBlessing_SimpleDesc_112"
        },
        RLBlessing_SimpleDesc_113 = {
          ContentES = "Verursacht <Highlight>zusätzlichen</> Schaden, wenn ein Schaden die LP des Ziels auf ein <Highlight>niedrigeres Niveau</> reduziert.",
          TextMapId = "RLBlessing_SimpleDesc_113"
        },
        RLBlessing_SimpleDesc_114 = {
          ContentES = "Nahkampfwaffen fügen Gegnern mit [Schmelz-Feuerglut] <Highlight>Bonus-SCH</> zu.",
          TextMapId = "RLBlessing_SimpleDesc_114"
        },
        RLBlessing_SimpleDesc_115 = {
          ContentES = "Je weniger Gegner sich <Highlight>in der Nähe</> befinden, desto höher ist der verursachte SCH.",
          TextMapId = "RLBlessing_SimpleDesc_115"
        },
        RLBlessing_SimpleDesc_201 = {
          ContentES = "Erhöht den <Highlight>ANG</> der Fernkampfwaffe.",
          TextMapId = "RLBlessing_SimpleDesc_201"
        },
        RLBlessing_SimpleDesc_202 = {
          ContentES = "Erhöht <Highlight>Auslöserate</> der Fernkampfwaffen.",
          TextMapId = "RLBlessing_SimpleDesc_202"
        },
        RLBlessing_SimpleDesc_203 = {
          ContentES = "Wenn du mit einer Fernkampfwaffe SCH verursachst, spawnen [Munitionskisten].",
          TextMapId = "RLBlessing_SimpleDesc_203"
        },
        RLBlessing_SimpleDesc_204 = {
          ContentES = "Das Aufsammeln von Gegenständen gewährt Ultra-Schilde.",
          TextMapId = "RLBlessing_SimpleDesc_204"
        },
        RLBlessing_SimpleDesc_205 = {
          ContentES = "Wenn du SCH verursachst, spawnen [Aktiviertes Sal Volatil] oder [Beruhigungstautropfen].",
          TextMapId = "RLBlessing_SimpleDesc_205"
        },
        RLBlessing_SimpleDesc_206 = {
          ContentES = "Der ANG der Figur erhöht sich, wenn Gegner in der Nähe sind.",
          TextMapId = "RLBlessing_SimpleDesc_206"
        },
        RLBlessing_SimpleDesc_207 = {
          ContentES = "Erhöht <Highlight>KRIT-Rate</> der Fernkampfwaffen.",
          TextMapId = "RLBlessing_SimpleDesc_207"
        },
        RLBlessing_SimpleDesc_208 = {
          ContentES = "Erhöht <Highlight>KRIT-SCH</> der Fernkampfwaffen.",
          TextMapId = "RLBlessing_SimpleDesc_208"
        },
        RLBlessing_SimpleDesc_209 = {
          ContentES = "Wenn die LP oder der Geist niedrig ist, wird die Wahrscheinlichkeit erhöht, dass <Highlight>[Vorrat des Ozeans]</> passende Vorräte erzeugt.",
          TextMapId = "RLBlessing_SimpleDesc_209"
        },
        RLBlessing_SimpleDesc_210 = {
          ContentES = "Das Aufsammeln von Gegenständen stellt zusätzlichen Geist wieder her.",
          TextMapId = "RLBlessing_SimpleDesc_210"
        },
        RLBlessing_SimpleDesc_211 = {
          ContentES = "Verringert die Abklingzeit der Geniemon-Unterstützung.",
          TextMapId = "RLBlessing_SimpleDesc_211"
        },
        RLBlessing_SimpleDesc_212 = {
          ContentES = "Erhöht <Highlight>Mehrfachschussrate</> der Fernkampfwaffen.",
          TextMapId = "RLBlessing_SimpleDesc_212"
        },
        RLBlessing_SimpleDesc_213 = {
          ContentES = "Erhöht <Highlight>Angriffs-GES </> der Fernkampfwaffen.",
          TextMapId = "RLBlessing_SimpleDesc_213"
        },
        RLBlessing_SimpleDesc_214 = {
          ContentES = "Fernkampfwaffen verursachen mehr Schaden, je weiter das Ziel entfernt ist.",
          TextMapId = "RLBlessing_SimpleDesc_214"
        },
        RLBlessing_SimpleDesc_215 = {
          ContentES = "Wenn du dich mehr als <Highlight>2</> s lang ununterbrochen bewegst, verringert sich erlittener SCH (bis zum Anhalten).\n Wenn du länger als <Highlight>2</> s stillstehst, erhöht sich verursachter SCH (bis du dich bewegst).",
          TextMapId = "RLBlessing_SimpleDesc_215"
        },
        RLBlessing_SimpleDesc_301 = {
          ContentES = "Erhöht die Fähigkeitsreichweite.",
          TextMapId = "RLBlessing_SimpleDesc_301"
        },
        RLBlessing_SimpleDesc_302 = {
          ContentES = "Erhöht die Fähigkeitsdauer.",
          TextMapId = "RLBlessing_SimpleDesc_302"
        },
        RLBlessing_SimpleDesc_303 = {
          ContentES = "Erhöht die Fähigkeitseffizienz beim Einsatz der Fähigkeiten.",
          TextMapId = "RLBlessing_SimpleDesc_303"
        },
        RLBlessing_SimpleDesc_304 = {
          ContentES = "Stellt Geist wieder her, wenn du Fähigkeiten einsetzt.",
          TextMapId = "RLBlessing_SimpleDesc_304"
        },
        RLBlessing_SimpleDesc_305 = {
          ContentES = "Stellt den Schild wieder her, wenn du Fähigkeiten einsetzt.",
          TextMapId = "RLBlessing_SimpleDesc_305"
        },
        RLBlessing_SimpleDesc_306 = {
          ContentES = "Erhöht die Fähigkeits-GES.",
          TextMapId = "RLBlessing_SimpleDesc_306"
        },
        RLBlessing_SimpleDesc_307 = {
          ContentES = "Erhöht max. Geist.",
          TextMapId = "RLBlessing_SimpleDesc_307"
        },
        RLBlessing_SimpleDesc_308 = {
          ContentES = "Reduziert den erlittenen SCH, wenn dein Geist niedrig ist.",
          TextMapId = "RLBlessing_SimpleDesc_308"
        },
        RLBlessing_SimpleDesc_309 = {
          ContentES = "Stellt Geist pro Sekunde wieder her, wenn Geist niedrig ist.",
          TextMapId = "RLBlessing_SimpleDesc_309"
        },
        RLBlessing_SimpleDesc_310 = {
          ContentES = "Gewährt beim Einsatz von Fähigkeiten eine bestimmte Anzahl der Stapelung <Highlight>[Glanz]</>.",
          TextMapId = "RLBlessing_SimpleDesc_310"
        },
        RLBlessing_SimpleDesc_311 = {
          ContentES = "Stellt jede Sekunde Geist wieder her, solange du im Zustand [Strahlung] bist.",
          TextMapId = "RLBlessing_SimpleDesc_311"
        },
        RLBlessing_SimpleDesc_312 = {
          ContentES = "Erhöht den Fähigkeits-SCH",
          TextMapId = "RLBlessing_SimpleDesc_312"
        },
        RLBlessing_SimpleDesc_313 = {
          ContentES = "Fähigkeits-SCH ignoriert einen bestimmten Prozentsatz der VTD des Ziels.",
          TextMapId = "RLBlessing_SimpleDesc_313"
        },
        RLBlessing_SimpleDesc_314 = {
          ContentES = "[Strahlung] gewährt jetzt eine höhere Steigerung des Fähigkeits-SCH.",
          TextMapId = "RLBlessing_SimpleDesc_314"
        },
        RLBlessing_SimpleDesc_315 = {
          ContentES = "[Emission] wird häufiger ausgelöst.",
          TextMapId = "RLBlessing_SimpleDesc_315"
        },
        RLBlessing_SimpleDesc_401 = {
          ContentES = "Beim Verursachen von SCH besteht eine Chance, 1 Lumi-Saat zu beschwören.",
          TextMapId = "RLBlessing_SimpleDesc_401"
        },
        RLBlessing_SimpleDesc_402 = {
          ContentES = "Erhöht den Fähigkeits-SCH beim Beschwören.",
          TextMapId = "RLBlessing_SimpleDesc_402"
        },
        RLBlessing_SimpleDesc_403 = {
          ContentES = "Erhöht den ANG beim Beschwören.",
          TextMapId = "RLBlessing_SimpleDesc_403"
        },
        RLBlessing_SimpleDesc_404 = {
          ContentES = "Erhöht erhaltene Heilung.",
          TextMapId = "RLBlessing_SimpleDesc_404"
        },
        RLBlessing_SimpleDesc_405 = {
          ContentES = "Stellt beim Beschwören LP wieder her.",
          TextMapId = "RLBlessing_SimpleDesc_405"
        },
        RLBlessing_SimpleDesc_406 = {
          ContentES = "Stellt beim Beschwören Geist wieder her.",
          TextMapId = "RLBlessing_SimpleDesc_406"
        },
        RLBlessing_SimpleDesc_407 = {
          ContentES = "Beschwört in regelmäßigen Abständen 1 [Lumi-Saat].",
          TextMapId = "RLBlessing_SimpleDesc_407"
        },
        RLBlessing_SimpleDesc_408 = {
          ContentES = "Wenn du Schaden erleidest, besteht die Chance, 1 [Lumi-Saat] zu beschwören.",
          TextMapId = "RLBlessing_SimpleDesc_408"
        },
        RLBlessing_SimpleDesc_409 = {
          ContentES = "Reduziert erlittenen SCH, wenn sich ein beschworenes Objekt in Reichweite befindet.",
          TextMapId = "RLBlessing_SimpleDesc_409"
        },
        RLBlessing_SimpleDesc_410 = {
          ContentES = "Bei erhaltener Heilung wird der verursachte SCH für eine kurze Zeit erhöht.",
          TextMapId = "RLBlessing_SimpleDesc_410"
        },
        RLBlessing_SimpleDesc_411 = {
          ContentES = "Beim Beschwören wird die Kampfhaltung der Gegner im Umkreis des Beschwörungsorts reduziert.",
          TextMapId = "RLBlessing_SimpleDesc_411"
        },
        RLBlessing_SimpleDesc_412 = {
          ContentES = "Je mehr beschworene Objekte sich um einen selbst befinden, desto höher ist der verursachte SCH.",
          TextMapId = "RLBlessing_SimpleDesc_412"
        },
        RLBlessing_SimpleDesc_413 = {
          ContentES = "Erhöht ANG des beschworenen Objekts.",
          TextMapId = "RLBlessing_SimpleDesc_413"
        },
        RLBlessing_SimpleDesc_414 = {
          ContentES = "Bei jeder Beschwörung eines beschworenen Objekts außer dem Lumi-Zweigs löst eine Explosion an ihrem Ort aus.",
          TextMapId = "RLBlessing_SimpleDesc_414"
        },
        RLBlessing_SimpleDesc_415 = {
          ContentES = "Erhöht die Chance, dass sich eine [Lumi-Saat] in ein [Lumi-Blatt] entwickelt, auf <Highlight>100 %</>.",
          TextMapId = "RLBlessing_SimpleDesc_415"
        },
        RLBlessing_SimpleDesc_501 = {
