        },
        RLBlessing_SimpleDesc_510 = {
          ContentES = "Beim Ausweichen wird ein [Pulver]-Feld erzeugt.",
          TextMapId = "RLBlessing_SimpleDesc_510"
        },
        RLBlessing_SimpleDesc_511 = {
          ContentES = "Gewährt in regelmäßigen Abständen [Umbraler Verschlinger]. Wenn die Anzahl der Stapelung von [Umbraler Verschlinger] einen Schwellenwert überschreitet, feuert er einen zusätzlichen [Klingenflügel] ab.",
          TextMapId = "RLBlessing_SimpleDesc_511"
