          TextMapId = "RLTreasureGroup_Desc_101"
        },
        RLTreasureGroup_Desc_102 = {
          ContentES = "Wenn du alle <Highlight>3</> Artefakte von [Bund des Gottes der Ernte] gesammelt hast, erhöht sich der verursachte SCH um <Highlight>10 %</> für je <Highlight>100</> Glut.\n Wenn du Glut weiniger als <Highlight>200</> besitzt, verringert sich der erlittene SCH um <Highlight>30 %</>.",
          TextMapId = "RLTreasureGroup_Desc_102"
        },
