        RLTreasure_SimpleDesc_10301 = {
          ContentES = "Gewährt zufällige [Dochte] von <Highlight>lila</> oder <Highlight>goldener</> Qualität.",
          TextMapId = "RLTreasure_SimpleDesc_10301"
        },
        RLTreasure_SimpleDesc_10302 = {
          ContentES = "Gewährt zufällige [Artefakte] von <Highlight>lila</> oder <Highlight>goldener</> Qualität.",
          TextMapId = "RLTreasure_SimpleDesc_10302"
        },
        RLTreasure_SimpleDesc_10303 = {
          ContentES = "Erhöht die auto. Wiederherstellung des Geists.",
          TextMapId = "RLTreasure_SimpleDesc_10303"
        },
        RLTreasure_SimpleDesc_10304 = {
          ContentES = "Ersetzt alle Dochte durch zufällige Dochte und gewährt Glut entsprechend der Anzahl der gehaltenen Dochte.",
          TextMapId = "RLTreasure_SimpleDesc_10304"
        },
        RLTreasure_SimpleDesc_10305 = {
          ContentES = "Ersetzt alle Artefakte durch zufällige Artefakte.",
          TextMapId = "RLTreasure_SimpleDesc_10305"
        },
        RLTreasure_SimpleDesc_10306 = {
          ContentES = "Je mehr Artefakte, desto höher der verursachte SCH.",
          TextMapId = "RLTreasure_SimpleDesc_10306"
        },
        RLTreasure_SimpleDesc_10307 = {
          ContentES = "Erhöht den Durchschlag gegen alle Elemente für jede Art von Docht, die du besitzt.",
          TextMapId = "RLTreasure_SimpleDesc_10307"
        },
        RLTreasure_SimpleDesc_10308 = {
          ContentES = "Reduziert die Anzahl der Dochte desselben Typs, die benötigt werden, um Effekte eines Sets zu aktivieren.",
          TextMapId = "RLTreasure_SimpleDesc_10308"
        },
        RLTreasure_SimpleDesc_10309 = {
          ContentES = "Wenn der Wiederbelebungsversuch aufgebraucht ist, gibst du Glut aus, um zusätzlichen Wiederbelebungsversuch zu erhalten.",
          TextMapId = "RLTreasure_SimpleDesc_10309"
        },
        RLTreasure_SimpleDesc_10310 = {
          ContentES = "Wenn Nahkampfangriffe SCH verursachen, werden Schwertwellen entfesselt, die jedem getroffenen Gegner Lumino-SCH zufügen.",
          TextMapId = "RLTreasure_SimpleDesc_10310"
        },
        RLTreasure_SimpleDesc_10311 = {
          ContentES = "Wenn eine Fähigkeit SCH verursacht, löst sie eine Explosion um den Anwender aus, die allen Gegnern in der Nähe Umbro-SCH zufügt.",
          TextMapId = "RLTreasure_SimpleDesc_10311"
        },
        RLTreasure_SimpleDesc_10312 = {
          ContentES = "Wenn ein Gegner SCH erleidet, werden 12 zielverfolgende Projektile abgefeuert, die bei einem Treffer Anemo-SCH verursachen.",
          TextMapId = "RLTreasure_SimpleDesc_10312"
        },
        RLTreasure_SimpleDesc_10313 = {
          ContentES = "Wenn ein beschworenes Objekt erscheint, löst es an seinem Erscheinungsort einen Angriff aus, der bei getroffenen Gegnern Hydro-SCH verursacht.",
          TextMapId = "RLTreasure_SimpleDesc_10313"
        },
        RLTreasure_SimpleDesc_10314 = {
          ContentES = "Wenn Fernkampfangriffe SCH verursachen, fügt sie Gegnern in einem kegelförmigen Bereich vor ihr zusätzlichen Pyro-SCH zu.",
          TextMapId = "RLTreasure_SimpleDesc_10314"
        },
        RLTreasure_SimpleDesc_10315 = {
          ContentES = "Beim Einsatz einer Fähigkeit werden 3 Bolzenwellen beschworen, die jeweils Elektro-SCH verursachen.",
          TextMapId = "RLTreasure_SimpleDesc_10315"
        },
        RLTreasure_SimpleDesc_10316 = {
          ContentES = "Geringer SCH löst einen zusätzlichen wahren SCH aus.",
          TextMapId = "RLTreasure_SimpleDesc_10316"
        },
        RLTreasure_SimpleDesc_11101 = {
          ContentES = "Solange du einen Schild hast, wird der erlittene SCH reduziert.",
          TextMapId = "RLTreasure_SimpleDesc_11101"
        },
        RLTreasure_SimpleDesc_11201 = {
          ContentES = "Solange du einen Schild hast, wird der verursachte SCH erhöht.",
          TextMapId = "RLTreasure_SimpleDesc_11201"
        },
        RLTreasure_SimpleDesc_12101 = {
          ContentES = "Die Aktualisierungskosten bei der Auswahl werden erhöht. Der Effekt endet nach einigen Etappen und gewährt Glut.",
          TextMapId = "RLTreasure_SimpleDesc_12101"
        },
        RLTreasure_SimpleDesc_12102 = {
          ContentES = "Preise bei der mysteriösen Händlerin werden erhöht. Der Effekt endet nach einigen Etappen und gewährt Glut.",
          TextMapId = "RLTreasure_SimpleDesc_12102"
        },
        RLTreasure_SimpleDesc_12201 = {
          ContentES = "Verursachter SCH wird reduziert. Der Effekt endet nach einigen Etappen und gewährt Glut.",
          TextMapId = "RLTreasure_SimpleDesc_12201"
        },
        RLTreasure_SimpleDesc_13101 = {
          ContentES = "Wenn du SCH verursachst, besteht eine Chance, zusätzlich Pyro-SCH zu verursachen.",
          TextMapId = "RLTreasure_SimpleDesc_13101"
        },
        RLTreasure_SimpleDesc_13102 = {
          ContentES = "Wenn du SCH verursachst, besteht eine Chance, zusätzlich Hydro-SCH zu verursachen.",
          TextMapId = "RLTreasure_SimpleDesc_13102"
        },
        RLTreasure_SimpleDesc_13103 = {
          ContentES = "Wenn du SCH verursachst, besteht eine Chance, zusätzlich Anemo-SCH zu verursachen.",
          TextMapId = "RLTreasure_SimpleDesc_13103"
        },
        RLTreasure_SimpleDesc_13104 = {
          ContentES = "Wenn du SCH verursachst, besteht eine Chance, zusätzlich Elektro-SCH zu verursachen.",
          TextMapId = "RLTreasure_SimpleDesc_13104"
        },
        RLTreasure_SimpleDesc_14101 = {
          ContentES = "Erhöht den verursachten SCH und verringert die Fähigkeitseffizienz.",
          TextMapId = "RLTreasure_SimpleDesc_14101"
        },
        RLTreasure_SimpleDesc_14201 = {
          ContentES = "Erhöht den verursachten SCH und verringert den Nahkampfwaffe-SCH.",
          TextMapId = "RLTreasure_SimpleDesc_14201"
        },
        RLTreasure_SimpleDesc_14202 = {
          ContentES = "Erhöht den verursachten SCH und verringert den Fernkampfwaffe-SCH.",
          TextMapId = "RLTreasure_SimpleDesc_14202"
        },
        RLTreasure_SimpleDesc_14301 = {
          ContentES = "Erhöht den verursachten SCH und den erlittenen SCH.",
          TextMapId = "RLTreasure_SimpleDesc_14301"
        },
        RLTreasure_SimpleDesc_15101 = {
          ContentES = "Deine Figur stellt ihren Geist wieder her, wenn sie Gegnern mit hoher [Kampfhaltung] SCH zufügt.",
