        Raid_Buff_11 = {
          ContentES = "Cuando el Daño de Habilidad de un personaje Anemo supere el 100%, por cada #1 que exceda el umbral, obtiene #2 de Penetración de todo atributo, hasta un máximo de #3.",
          TextMapId = "Raid_Buff_11"
        },
        Raid_Buff_12 = {
          ContentES = "Cuando el Daño de Habilidad de un personaje Electro supere el 100%, por cada #1 adicional, ignora #2 de DEF del objetivo al infligir Daño de Habilidad, hasta un máximo de #3.",
          TextMapId = "Raid_Buff_12"
        },
        Raid_Buff_13 = {
          ContentES = "Cuando el Rango de Habilidad de un personaje Lumino supera la Duración de Habilidad, por cada #1 de exceso, ignora #2 de DEF del objetivo al infligir Daño de Habilidad, hasta un máximo de #3. Cuando la Duración de Habilidad supera el Rango de Habilidad, por cada #4 de exceso, la Penetración de Atributo total aumenta en #5, hasta un máximo de #6.",
          TextMapId = "Raid_Buff_13"
        },
        Raid_Buff_14 = {
          ContentES = "Por cada #1 de Moral que posea un personaje Umbro, la Penetración de todo atributo aumenta en #2, hasta un máximo de #3.",
          TextMapId = "Raid_Buff_14"
        },
        Ranged = {ContentES = "Fernkampf", TextMapId = "Ranged"},
        Reading_Content_101223 = {
          ContentES = "(Ein Tagebuch, das in der Glevum-Grube gefunden wurde. Dem Schreibstil nach zu urteilen, scheint es sich um die Aufzeichnungen eines Gelehrten zu handeln.)\n ...\n 16. April\n Wir haben in dieser längst verlassenen Mine einen merkwürdigen <H>gelben Kristallklumpen</> entdeckt. Seiner Beschaffenheit nach handelt es sich weder um den sagenumwobenen Kristallo von Stella, der tief in den Höhlen des Berges verborgen liegen soll, noch um Phoxene aus einer verlassenen Mine. Vielmehr scheint es ein bislang unbekanntes Mineral zu sein.\n ...\n 18. April\n Zu unserer Überraschung stellte Bob fest, dass die schwach leuchtenden gelben Kristalle <H>gewachsen waren</>. Was einst nicht größer als eine Handspanne war, hatte sich zu gedrungenen, strauchartigen Klumpen entwickelt.\n ...\n 20. April\n Die Klumpen waren erneut gewachsen und hatten sich in spitzenartige Kristalle verwandelt, die die Türen in der Mine vollständig blockierten – fast so, als wären sie lebendig. Zum Glück sind die Kristalle extrem spröde. Es braucht nur eine kleine Menge <H>Schießpulver</>, um sie zu sprengen.\n Bob hat eine Hypothese aufgestellt: Diese Formationen sind vielleicht gar keine Mineralien, sondern eine Art von <H>Filthoid</>-Sekret – vielleicht sogar eine Art „Nachkommen”. Wie Schwämme, die im Wasser liegen, scheinen sie mit der Zeit zu quellen und sich auszudehnen. Das ist selbst für jemanden mit Bobs Fachwissen über Filthoid-Biologie eine gewagte Theorie.\n ...\n 21. April\n Um Bobs Theorie zu überprüfen, haben wir beschlossen, tiefer in die Mine vorzudringen. Wenn sich seine Vermutung als richtig erweist, dann gibt es irgendwo in dieser verlassenen Grube eine einzigartige Filthoid-Art, die sich von denen in freier Wildbahn unterscheidet – vielleicht einen <H>Vorfahren</> ...\n ...",
          TextMapId = "Reading_Content_101223"
        },
        Reading_Content_200208 = {
          ContentES = "Wenn du das hier liest, sind wir schon weg.\n Die Eskorte wurde durch das, was Psyche in dieser Nacht passiert ist, alarmiert – wir konnten nicht länger in Icelake bleiben.\n Bevor ihre Ermittlungen Hypnos’ Haus erreichten, habe ich alle versammelt und bin gegangen.\n Bitte trauere nicht um uns und fürchte dich nicht, dass wir jemandem Schaden zufügen könnten, sollte die Verderbnis uns zu schnell einfordern.\n Wir machen uns auf den Weg in die Wildnis und wandern in ferne, unbekannte Länder.\n Wir wissen nicht, was uns am Ende der Reise erwartet – vielleicht der Tod oder ein unvorhergesehenes Wunder.\n So oder so, wir werden bis zum Schluss an der Hoffnung festhalten.\n Das hat sie uns beigebracht.\n Und ... danke für alles, was du für uns getan hast.\n Pass auf dich auf,\n Elisa Taylor",
          TextMapId = "Reading_Content_200208"
        },
        Reading_Title_101223 = {
          ContentES = "Notizen des Alchemisten (Ⅰ)",
          TextMapId = "Reading_Title_101223"
        },
        Reading_Title_200208 = {
          ContentES = "Brief von Elisa Taylor",
          TextMapId = "Reading_Title_200208"
        },
