        SCEREAD_NAME_1000002 = {
          ContentES = "{空格}",
          TextMapId = "SCEREAD_NAME_1000002"
        },
        SCEREAD_TEXT_1000001 = {
          ContentES = "El Dragón Negro arrasa con todo desbordando las aguas turbias, mientras el día y la noche pierden su ritmo y la temperatura cambia de manera abrupta.\nLa vegetación se marchita y la vida se extingue. Los peñascos se fragmentan y el cielo y la tierra se tornan de un color extraño.\nMientras el pueblo que vive en circunstancias humildes teme por su hogar, los Tejestrellas se lanzan juntos a enfrentar la adversidad.\nSe funde el cobre y se forja el hierro, se alza la torre entre el humo, mientras la fragancia se esparce y el aire contaminado se purifica.\nLa torre debe cuidarse constantemente, sin dejar que la fragancia se pierda, y se deben realizar inspecciones periódicas para mantener la seguridad.\nSi el Zhuyin se alza, los desastres volverán. Tras un siglo de buena fortuna, la torre teme agotarse.\nHoy escribo estas palabras para advertir a las generaciones venideras, que si se enfrentan a esta calamidad, busquen un nuevo registro.\nTrabajen juntos y protejan los ríos, que Huaxu conserve la paz eternamente de generación en generación.",
          TextMapId = "SCEREAD_TEXT_1000001"
        },
        SCEREAD_TEXT_1000002 = {
          ContentES = "Por voto y decreto convocamos a los perdidos: Deja de vagar; apresúrate hacia el Reino de la Felicidad.\nQue quede como constancia que:\nGui — una campesina; cayó mientras huía del Bi’an sombrío.\nChuntao — una tejedora; su hogar fue invadido, y ella fue asesinada dentro.\nLi Erlang — un campesino; cayó trabajando en sus campos mientras los Bi’an sombríos arrasaban la región.\nXiao Xiaosan — un asistente; separado de su maestro durante la huida, se perdió en el Mar de Polvo y pereció.\n...",
          TextMapId = "SCEREAD_TEXT_1000002"
        },
        SKILL_100001_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Verbündete.",
          TextMapId = "SKILL_100001_DESC"
        },
        SKILL_100001_NAME = {
          ContentES = "Schlag",
          TextMapId = "SKILL_100001_NAME"
        },
        SKILL_100003_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den Fähigkeits-SCH für sich selbst und Verbündete.",
          TextMapId = "SKILL_100003_DESC"
        },
        SKILL_100003_NAME = {
          ContentES = "Neuheit",
          TextMapId = "SKILL_100003_NAME"
        },
        SKILL_100005_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den Waffen-SCH für sich selbst und Verbündete.",
          TextMapId = "SKILL_100005_DESC"
        },
        SKILL_100005_NAME = {
          ContentES = "Schneide",
          TextMapId = "SKILL_100005_NAME"
        },
        SKILL_100007_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht die VTD für sich selbst und Verbündete.",
          TextMapId = "SKILL_100007_DESC"
        },
        SKILL_100007_NAME = {
          ContentES = "Befestigung",
          TextMapId = "SKILL_100007_NAME"
        },
        SKILL_100009_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht die KRIT-Rate für sich selbst und Verbündete.",
          TextMapId = "SKILL_100009_DESC"
        },
        SKILL_100009_NAME = {
          ContentES = "Leidenschaftlicher Impuls",
          TextMapId = "SKILL_100009_NAME"
        },
        SKILL_10101_DESC = {
          ContentES = "Figur-ANG +<H>#1</>.",
          TextMapId = "SKILL_10101_DESC"
        },
        SKILL_10102_DESC = {
          ContentES = "Auslöserate +<H>#1</>. Wenn ein Hydro-Figur mit dieser Waffe einen Bonuseffekt auslöst, erhalten alle anderen Verbündeten +<H>#2</> ANG für <H>#3</> Sek.",
          TextMapId = "SKILL_10102_DESC"
        },
        SKILL_10103_DESC = {
          ContentES = "Angriffsreichweite +<H>#1</>. Wird mit dieser Waffe ein KRIT gelandet, besteht eine Chance von <H>#2</>, <H>#3</> Punkte Geist wiederherzustellen. Kann einmal alle <H>#4</> Sek. ausgelöst werden.",
          TextMapId = "SKILL_10103_DESC"
        },
        SKILL_10104_DESC = {
          ContentES = "VTD +<H>#1</>. Wird mit dieser Waffe ein SCH verursacht, wird ein Bonuseffekt ausgelöst, mit einer Chance von <H>#3</>, den Schild des Ziels um <H>#2</> der VTD des Anwenders zu reduzieren.",
          TextMapId = "SKILL_10104_DESC"
        },
        SKILL_10105_DESC = {
          ContentES = "Angriffs-GES +<H>#1</>. Wird mit dieser Waffe ein geladener Angriff ausgeführt, besteht eine Chance von <H>#2</>, die Abk. der Resonanz-Unterstützung um <H>#3</> Sek. zu verkürzen.",
          TextMapId = "SKILL_10105_DESC"
        },
        SKILL_10201_DESC = {
          ContentES = "Fähigkeitsreichweite +<H>#1</>. Beim Treffen eines Gegners mit dieser Waffe im Standardangriff wird die Angriffs-GES um <H>#2</> für <H>#3</> Sek. erhöht (bis zu <H>#4</>-mal stapelbar). Der Effekt wird beim Waffenwechsel deaktiviert.",
          TextMapId = "SKILL_10201_DESC"
        },
        SKILL_10202_DESC = {
          ContentES = "Angriffs-GES +<H>#1</>. Verursacht +<H>#2</> SCH bei Zielen, die mit Bonuseffekten belegt sind.",
          TextMapId = "SKILL_10202_DESC"
        },
        SKILL_10203_DESC = {
          ContentES = "Fähigkeits-SCH +<H>#1</>. Wenn ein Elektro-Figur mit dieser Waffe einen Sturzangriff ausführt, wird Fähigkeits-SCH um <H>#2</> für <H>#3</> Sek. erhöht (bis zu <H>3</>-mal stapelbar).",
          TextMapId = "SKILL_10203_DESC"
        },
        SKILL_10204_DESC = {
          ContentES = "Entschlossenheit +<H>#1</>. Nachdem eine Anemo-Figur ihren Ultimate eingesetzt hat, erhält sie den [Segen der Tausend Winde]: Erhöht die Entschlossenheit um <H>#2</> und die Angriffs-GES um <H>#3</> für <H>#4</> Sek. Jede Instanz von Fähigkeits-SCH oder Schaden durch Fernkampfwaffen verlängert die Dauer um <H>#5</> Sek.",
          TextMapId = "SKILL_10204_DESC"
        },
        SKILL_10206_DESC = {
          ContentES = "Fähigkeits-SCH +<H>#1</>.",
          TextMapId = "SKILL_10206_DESC"
        },
        SKILL_10208_DESC = {
          ContentES = "KRIT-Rate +<H>#1</>. Bei Schaden durch normale Angriffe mit dieser Waffe besteht eine Chance von <H>#2</>, das Magazin der Fernkampfwaffe nachzuladen.",
          TextMapId = "SKILL_10208_DESC"
        },
        SKILL_10301_DESC = {
          ContentES = "Max. LP +<H>#1</>. Wenn ein Pyro-Figur SCH erleidet, wird die Fähigkeitsdauer um <H>#2</> für <H>#3</> Sek. verlönert (bis zu <H>#4</>-mal stapelbar).",
          TextMapId = "SKILL_10301_DESC"
        },
        SKILL_10302_DESC = {
          ContentES = "KRIT-Rate +<H>#1</>. Wird mit dieser Waffe ein SCH verursacht, wird ein Bonuseffekt ausgelöst, mit eine Chance von <H>#2</>, die Kombostufe auf das Maximum zu erhöhen.",
          TextMapId = "SKILL_10302_DESC"
        },
        SKILL_10303_DESC = {
          ContentES = "Fähigkeitsdauer +<H>#1</>.",
          TextMapId = "SKILL_10303_DESC"
        },
        SKILL_10304_DESC = {
          ContentES = "Moral +<H>#1</>. Wenn ein Elektro-Figur den Ultimate einsetzt, wird der Fähigkeits-SCH um <H>#2</> für <H>#3</> Sek. erhöht (bis zu <H>#4</>-mal stapelbar).",
          TextMapId = "SKILL_10304_DESC"
        },
        SKILL_10401_DESC = {
          ContentES = "Angriffs-GES +<H>#1</>. Wird mit dieser Waffe ein SCH verursacht, wird ein Bonuseffekt ausgelöst – wenn die LP des Trägers unter 25 % liegen, besteht eine Chance von <H>#2</>, <H>#3</> der max. LP wiederherzustellen.",
          TextMapId = "SKILL_10401_DESC"
        },
        SKILL_10402_DESC = {
          ContentES = "KRIT-SCH +<H>#1</>. Gleitangriffe mit dieser Waffe erhalten +<H>#2</> KRIT-Rate.",
          TextMapId = "SKILL_10402_DESC"
        },
        SKILL_10403_DESC = {
          ContentES = "Fähigkeitsreichweite +<H>#1</>.",
          TextMapId = "SKILL_10403_DESC"
        },
        SKILL_10501_DESC = {
          ContentES = "Max. LP +<H>#1</>. Wenn diese Waffe bei einem Treffer einen Bonuseffekt auslöst, werden die max. LP um <H>#2</> für <H>#3</> Sek. erhöht (bis zu <H>#4</>-mal stapelbar).",
          TextMapId = "SKILL_10501_DESC"
        },
        SKILL_10502_DESC = {
          ContentES = "Fähigkeits-SCH +<H>#1</>. Wenn ein Hydro-Figur mit dieser Waffe einen KRIT-SCH verursacht, erhöht sich der Fähigkeits-SCH für Verbündete um <H>#2</> für <H>#3</> Sek.",
          TextMapId = "SKILL_10502_DESC"
        },
        SKILL_10503_DESC = {
          ContentES = "Fähigkeitsdauer +<H>#1</>.",
          TextMapId = "SKILL_10503_DESC"
        },
        SKILL_10504_DESC = {
          ContentES = "Auslöserate +<H>#1</>. Geladene Angriffe mit dieser Waffe gewähren +<H>#2</> Angriffs-GES für <H>#3</> Sek. Der Effekt wird beim Waffenwechsel deaktiviert.",
          TextMapId = "SKILL_10504_DESC"
        },
        SKILL_10601_DESC = {
          ContentES = "KRIT-SCH +<H>#1</>. Wenn mit dieser Waffe Schaden verursacht wird, erhöht sich der verursachte SCH um <H>#2</>, zusätzlich um <H>#2</> pro Kombostufe.",
          TextMapId = "SKILL_10601_DESC"
        },
        SKILL_10602_DESC = {
          ContentES = "Fähigkeitsreichweite +<H>#1</>.",
          TextMapId = "SKILL_10602_DESC"
        },
        SKILL_10603_DESC = {
          ContentES = "Figur-ANG +<H>#1</>. Geladene Angriffe mit dieser Waffe gewähren +<H>#2</> KRIT-SCH für <H>#3</> Sek. Der Effekt wird beim Waffenwechsel deaktiviert.",
          TextMapId = "SKILL_10603_DESC"
        },
        SKILL_110001_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Umbro-Verbündete.",
          TextMapId = "SKILL_110001_DESC"
        },
        SKILL_110001_NAME = {
          ContentES = "Herzverschlinger",
          TextMapId = "SKILL_110001_NAME"
        },
        SKILL_110003_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Umbro-Verbündete.",
          TextMapId = "SKILL_110003_DESC"
        },
        SKILL_110003_NAME = {
          ContentES = "Waage der Gerechtigkeit",
          TextMapId = "SKILL_110003_NAME"
        },
        SKILL_110101_DESC = {
          ContentES = "Stürmt vorwärts und verursacht auf dem Weg 4-mal UmbroFlächenschaden.",
          TextMapId = "SKILL_110101_DESC"
        },
        SKILL_110101_NAME = {
          ContentES = "Letzter Schein",
          TextMapId = "SKILL_110101_NAME"
        },
        SKILL_110102_DESC = {
          ContentES = "Wechselt zur Nahkampfwaffe [Ymir] und setzt 1 Schwertwelle ein.\n Die Ausführung eines Standardangriffs mit [Ymir] entfesselt Schwertwellen in die Angriffsrichtung und verbraucht ständig Geist – wenn Benerica währenddessen Schaden erleidet, ist sie immun gegen Trefferstarre. Sobald der Geist unter den Wert 0 fällt oder die Fähigkeit erneut eingesetzt wird, wird [Ymir] in die Scheide gesteckt.",
          TextMapId = "SKILL_110102_DESC"
        },
        SKILL_110102_NAME = {
          ContentES = "Unterweltflammen",
          TextMapId = "SKILL_110102_NAME"
        },
        SKILL_110103_DESC = {
          ContentES = "Wird mit [letzter Schein] oder dem Schwert ein Schaden verursacht, besteht eine Chance, Geist für Berenica wiederherzustellen.",
          TextMapId = "SKILL_110103_DESC"
        },
        SKILL_110103_NAME = {
          ContentES = "Kreisel",
          TextMapId = "SKILL_110103_NAME"
        },
        SKILL_110104_DESC = {
          ContentES = "Nach dem Einsatz von [Unterweltflammen] verbraucht der nächste Einsatz von [Letzter Schein] keinen Geist.",
          TextMapId = "SKILL_110104_DESC"
        },
        SKILL_110104_NAME = {
          ContentES = "Nachglut",
          TextMapId = "SKILL_110104_NAME"
        },
        SKILL_110301_DESC = {
          ContentES = "Verursacht Umbro-SCH an Gegnern vor sich und belegt sie mit 5 Stapelung [Adagio], bis zu 10 Stapelungen. Die Dauer des Effekts wird mit dem Erhalt einer jeden neuen Stapelung aktualisiert.\n Im Zustand [Bestialische Wut] wird diese Fähigkeit durch [Arie] ersetzt.",
          TextMapId = "SKILL_110301_DESC"
        },
        SKILL_110301_NAME = {
          ContentES = "Rezitativ",
          TextMapId = "SKILL_110301_NAME"
        },
        SKILL_110302_DESC = {
          ContentES = "Tritt in den Zustand [Bestialische Wut] ein und verbraucht ständig Geist – wenn der Geist auf den Wert 0 sinkt, endet der Zustand [Bestialische Wut].\n Im Zustand [Bestialische Wut] können keine Waffen benutzt werden.\n Der Nahkampfangriff wird durch [Wütende Klauen] ersetzt und es werden bis zu vier Angriffe in Folge ausgeführt, um Umbro-SCH zu verursachen. In der Luft eingesetzt führt Phantasio einen Sturzangriff aus und verursacht Umbro-SCH an Gegnern in Reichweite.\n Der Fernkampfangriff wird durch [Klagendes Heulen] ersetzt und es wird ein Energiestrahl abgefeuert, der Umbro-SCH verursacht.\n Wenn der 3-Angriff von [Wütende Klauen] und [Klagendes Heulen] SCH verursachen, wird [Duett] ausgelöst; wenn der 4-Angriff von [Wütende Klauen] und der Sturzangriff SCH verursachen, wird [Fermate] ausgelöst.",
          TextMapId = "SKILL_110302_DESC"
        },
        SKILL_110302_NAME = {
          ContentES = "Vorhang Auf",
          TextMapId = "SKILL_110302_NAME"
        },
        SKILL_110303_DESC = {
          ContentES = "Im Zustand [Bestialische Wut] erhöht sich der ANG basierend auf dem max. Geist von Phantasio.\n Phantasio erhält [Immersion] durch den Einsatz von Fähigkeiten, wobei die [Immersion]-Obergrenze dem max. Geist von Phantasio entspricht. Der Einsatz von [Rezitativ] oder [Arie] gewährt eine bestimmte Menge [Immersion] – im Zustand [Bestialische Wut] wird kontinuierlich [Immersion] pro Sekunde erhalten.\n Wenn [Immersion] im Zustand [Bestialische Wut] den Maximalwert erreicht, tritt Phantasio in den Zustand [Bestialische Wut: Hingabe] ein.",
          TextMapId = "SKILL_110303_DESC"
        },
        SKILL_110303_NAME = {
          ContentES = "Auf der Bühne",
          TextMapId = "SKILL_110303_NAME"
        },
        SKILL_110304_DESC = {
          ContentES = "Wenn die 3-Angriff von [Wütende Klauen] und [Klagendes Heulen] SCH verursachen, besteht eine Chance, das Ziel mit 1 Stapelung [Adagio] zu belegen.",
          TextMapId = "SKILL_110304_DESC"
        },
        SKILL_110304_NAME = {
          ContentES = "Konzert",
          TextMapId = "SKILL_110304_NAME"
        },
        SKILL_150001_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Lumino-Verbündete.",
          TextMapId = "SKILL_150001_DESC"
        },
        SKILL_150001_NAME = {
          ContentES = "Karmesinleuchten",
          TextMapId = "SKILL_150001_NAME"
        },
        SKILL_150003_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Lumino-Verbündete.",
          TextMapId = "SKILL_150003_DESC"
        },
        SKILL_150003_NAME = {
          ContentES = "Als der Himmel golden wurde",
          TextMapId = "SKILL_150003_NAME"
        },
        SKILL_150101_DESC = {
          ContentES = "Springt vorwärts und verursacht auf dem Weg 3-mal Lumino-Flächenschaden, hämmert dann nach unten, um weiteren Lumino-Flächenschaden zu verursachen.",
          TextMapId = "SKILL_150101_DESC"
        },
        SKILL_150101_NAME = {
          ContentES = "Im Namen der Geduld",
          TextMapId = "SKILL_150101_NAME"
        },
        SKILL_150102_DESC = {
          ContentES = "Wechselt die Nahkampfwaffe zu [Samael] und verursacht Lumino-SCH an Gegnern vor sich. Während [Samael] geführt wird, kann [Samael] durch den erneuten Einsatz der Fähigkeit zurückgezogen werden.\n Standardangriffe mit [Samael] können bis zu 4 Angriffe verketten.\n Beim Halten zum Aufladen von [Samael] wird fortlaufend Geist verbraucht. Während des Aufladens wird [Ungeduld] gewährt, und alle 0,5 Sek. werden Kombopunkte erzeugt.\n Wird das Halten beendet, die maximale Kombostufe erreicht oder der Geist erschöpft, wird ein geladener Angriff ausgelöst, der Gegnern im vorderen Wirkungsbereich Lumino-Flächenschaden zufügt.",
          TextMapId = "SKILL_150102_DESC"
        },
        SKILL_150102_NAME = {
          ContentES = "Das war's!",
          TextMapId = "SKILL_150102_NAME"
        },
        SKILL_150103_DESC = {
          ContentES = "Wenn die Kombostufe steigt, wird Lumino-SCH an Gegnern in der Nähe verursacht, und [Samael] wird verstärkt.\n Bei den Kombostufen C/B/A/S erhält [Samael] die entsprechenden Verstärkungsstufen 1/2/3/4. Wenn die Kombostufe sinkt, bleibt die aktuelle Verstärkungsstufe für kurze Zeit unverändert.\n Während [Samael] verstärkt wird, erhält die Resonanzwaffe die Angriffsreichweite und Auslöserate basierend auf der Verstärkungsstufe.",
          TextMapId = "SKILL_150103_DESC"
        },
        SKILL_150103_NAME = {
          ContentES = "Hmpf!",
          TextMapId = "SKILL_150103_NAME"
        },
        SKILL_150104_DESC = {
          ContentES = "Wird der geladene Angriff von [Samael] auf Kombostufe S ausgelöst, verlängert sich die Dauer von [Ungeduld] um eine gewisse Zeit.",
          TextMapId = "SKILL_150104_DESC"
        },
        SKILL_150104_NAME = {
          ContentES = "Ich kann mich nicht beruhigen!",
          TextMapId = "SKILL_150104_NAME"
        },
        SKILL_150202_DESC = {
          ContentES = "Tritt in den Zustand [Bestattungsritual] ein. Wenn die Fähigkeitsreichweite beim Eintritt 100 % übersteigt, wird der Überschuss zu einem festen Verhältnis in Fähigkeits-SCH umgewandelt und die Fähigkeitsreichweite verringert sich für die Dauer auf 100 %.\n Während [Bestattungsritual] erhalten Fernkampfwaffen eine Erhöhung der Auslöserate. [Mondjagd] und [Sonnenfinsternis] kosten keinen Geist. [Mondjagd] zieht Gegner in sein Zentrum. [Sonnenfinsternis] verursacht erhöhten Schaden.\n [Bestattungsritual] endet nach einer festgelegten Dauer oder nach dem Einsatz von insgesamt 6× [Mondjagd] und/oder [Sonnenfinsternis].",
          TextMapId = "SKILL_150202_DESC"
        },
        SKILL_150202_NAME = {
