        SKILL_150211_NAME = {
          ContentES = "Mondjagd",
          TextMapId = "SKILL_150211_NAME"
        },
        SKILL_150301_DESC = {
          ContentES = "Verursacht 3-mal Lumino-SCH an Gegnern innerhalb der Reichweite und erhöht Kezhous Angriffs-GES mit Fernkampfwaffen. Im Zustand [Aspektmanifestation] wird Kezhous Angriffs-GES mit Nahkampfwaffen erhöht – wenn Kezhou dabei Schaden erleidet, ist er immun gegen Trefferstarre.",
          TextMapId = "SKILL_150301_DESC"
