        SKILL_150301_NAME = {
          ContentES = "Drift der Jugend",
          TextMapId = "SKILL_150301_NAME"
        },
        SKILL_150302_DESC = {
          ContentES = "Tritt in den Zustand [Aspektmanifestation] ein und beschwört [Schneiden aller Zeiten], die vom Himmel regnen und Lumino-SCH an Gegnern innerhalb der Reichweite verursachen.\n Im Zustand [Aspektmanifestation] wird Kezhous Nahkampfwaffe in das [Phanoschwert] gewechselt. Beim Auslösen des Bonuseffekts mit dem [Phanoschwert] wird 1 [Phanofeder] erzeugt.\n Im Zustand [Aspektmanifestation] wird diese Fähigkeit durch [Staubjagende Feder] ersetzt.",
          TextMapId = "SKILL_150302_DESC"
