        SKILL_150302_NAME = {
          ContentES = "Sternenstreifendes Frostschwert",
          TextMapId = "SKILL_150302_NAME"
        },
        SKILL_150303_DESC = {
          ContentES = "Startet mit jeweils 50 Punkten [Schwertabsicht] und [Saitenabsicht] (max. 100).\n [Schwertabsicht] erhöht den verursachten SCH von Nahkampfwaffen sowie die Auslöserate von Nahkampfwaffen und reduziert die Geisteskosten von [Sternenstreifendes Frostschwert]. Bei max. [Schwertabsicht] werden die Geisteskosten um weitere 20 Punkte reduziert.\n [Saitenabsicht] erhöht den verursachen SCH von Fernkampfwaffen sowie die Auslöserate von Fernkampfwaffen und reduziert die Geisteskosten von [Staubjagende Feder]. Bei max. [Saitenabsicht] werden die Geisteskosten um weitere 20 Punkte reduziert.\n Jedes Mal, wenn Schaden durch eine Fernkampfwaffe verursacht wird, verwandelt sich 1 Punkt [Saitenabsicht] in [Schwertabsicht]. Jedes Mal, wenn Schaden durch eine Nahkampfwaffe verursacht wird, verwandelt sich 1 Punkt [Schwertabsicht] in [Saitenabsicht].",
          TextMapId = "SKILL_150303_DESC"
        },
        SKILL_150303_NAME = {
          ContentES = "Das Leben treibt, die Gezeiten wandeln",
          TextMapId = "SKILL_150303_NAME"
        },
        SKILL_150304_DESC = {
          ContentES = "Beim Eintritt in den Zustand [Aspektmanifestation] werden die aktuellen [Schwertabsicht]-Punkte gespeichert. Fällt ein [Schwertabsicht]-Punkt unter diesen Wert, nimmt der bei [Das Leben treibt, die Gezeiten wandeln] angewendete [Schwertabsicht]-Effekt für eine gewisse Zeit den gespeicherten Wert an. Beim Verlassen von [Aspektmanifestation] geht dieser Effekt verloren.\n Beim Verlassen in den Zustand [Aspektmanifestation] werden die aktuellen [Saitenabsicht]-Punkte gespeichert. Fällt ein [Saitenabsicht]-Punkt unter diesen Wert, nimmt der bei [Das Leben treibt, die Gezeiten wandeln] angewendete [Saitenabsicht]-Effekt für eine gewisse Zeit den gespeicherten Wert an. Beim Eintritt in den Zustand [Aspektmanifestation] geht dieser Effekt verloren.",
          TextMapId = "SKILL_150304_DESC"
        },
        SKILL_150304_NAME = {
          ContentES = "Doch der Wanderer kündigt die Veränderung an",
          TextMapId = "SKILL_150304_NAME"
        },
        SKILL_150401_DESC = {
          ContentES = "Tritt in den Zustand [Gleitflug] ein, erhält Hochgeschwindigkeitsflug und verursacht entlang der Flugbahn Lumino-SCH an Gegnern. Dieser Zustand verbraucht kontinuierlich [Kunstwerker-Energie] und endet, wenn die Energie 0 erreicht oder wenn die Fähigkeit erneut eingesetzt wird.",
          TextMapId = "SKILL_150401_DESC"
