        SKILL_210104_DESC = {
          ContentES = "Beim Verursachen von SCH mit Standardangriff mit Nahkampfwaffen besteht die Chance, den SCH von [Gift der Liebe] des Ziels einmal zusätzlich anzuwenden.\n Beim Verursachen von SCH mit [Ladas Liebestau] wird dieser Effekt ausgelöst.",
          TextMapId = "SKILL_210104_DESC"
        },
        SKILL_210104_NAME = {
          ContentES = "Liebeskummer-Synergie",
          TextMapId = "SKILL_210104_NAME"
        },
        SKILL_230101_DESC = {
          ContentES = "Befiehlt allen [Beschworenes Objekt: Tentakel], gleichzeitig anzugreifen, und erhöht deren verursachten SCH. Erhöht den Fähigkeits-SCH für sich selbst und Verbündete.",
          TextMapId = "SKILL_230101_DESC"
        },
        SKILL_230101_NAME = {
          ContentES = "Tabethes Spezialität!",
          TextMapId = "SKILL_230101_NAME"
        },
        SKILL_230102_DESC = {
          ContentES = "Beschwört 9 [Tentakel] um Tabethe.",
          TextMapId = "SKILL_230102_DESC"
        },
        SKILL_230102_NAME = {
          ContentES = "Gerechtigkeitskeilerei!",
          TextMapId = "SKILL_230102_NAME"
        },
        SKILL_230103_DESC = {
          ContentES = "Beim Verursachen von KRIT-SCH mit einer Fernkampfwaffe besteht eine Chance, 1 [Tentakel] in der Nähe des Ziels zu beschwören, was nur einmal pro Sekunde ausgelöst werden kann. Es können maximal 18 [Tentakel] gleichzeitig existieren.",
          TextMapId = "SKILL_230103_DESC"
        },
        SKILL_230103_NAME = {
          ContentES = "Die Farce beginnt!",
          TextMapId = "SKILL_230103_NAME"
        },
        SKILL_230104_DESC = {
          ContentES = "Beim Beschwören von [Tentakeln] wird die KRIT-Rate von Tabethe erhöht, bis zu 10-mal stapelbar.",
          TextMapId = "SKILL_230104_DESC"
        },
        SKILL_230104_NAME = {
          ContentES = "Tentakel überall!",
          TextMapId = "SKILL_230104_NAME"
        },
        SKILL_240101_DESC = {
          ContentES = "Beschwört 1 [Yunchi]. Es können maximal 2 [Yunchi] gleichzeitig existieren.",
          TextMapId = "SKILL_240101_DESC"
        },
        SKILL_240101_NAME = {
          ContentES = "Unterhimmelstrost",
          TextMapId = "SKILL_240101_NAME"
        },
        SKILL_240102_DESC = {
          ContentES = "Verursacht Hydro-SCH an Gegnern in der Nähe. Gewährt einen Ultra-Schild und eine Erhöhung der Angriffs-GES. Verbündete in der Nähe erhalten einen Ultra-Schild und die [Neun-Nadel-Therapie].",
          TextMapId = "SKILL_240102_DESC"
        },
        SKILL_240102_NAME = {
          ContentES = "Ganzheitliche Harmonie",
          TextMapId = "SKILL_240102_NAME"
        },
        SKILL_240103_DESC = {
          ContentES = "Der Einsatz einer Fertigkeit oder eines Ultimates durch sich selbst oder Verbündete wird die Fähigkeits-GES erhöht, bis zu 2-mal stapelbar. Die Dauer wird beim Stapeln aktualisiert.",
          TextMapId = "SKILL_240103_DESC"
        },
        SKILL_240103_NAME = {
          ContentES = "Archäus-Wiederbelebung",
          TextMapId = "SKILL_240103_NAME"
        },
        SKILL_240104_DESC = {
          ContentES = "Erhöht den Fähigkeits-SCH basierend auf der Anzahl der [Yunchi] auf dem Kampffeld.",
          TextMapId = "SKILL_240104_DESC"
        },
        SKILL_240104_NAME = {
          ContentES = "Blühende Vitalität",
          TextMapId = "SKILL_240104_NAME"
        },
        SKILL_240191_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den Fähigkeits-SCH für sich selbst und Verbündete, wenn 2 oder mehr Figuren im Team das gleiche Element teilen.",
          TextMapId = "SKILL_240191_DESC"
        },
        SKILL_240191_NAME = {
          ContentES = "Meridian-Synergie",
          TextMapId = "SKILL_240191_NAME"
        },
        SKILL_310001_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Pyro-Verbündete.",
          TextMapId = "SKILL_310001_DESC"
        },
        SKILL_310001_NAME = {
          ContentES = "Ätherflamme",
          TextMapId = "SKILL_310001_NAME"
        },
        SKILL_310003_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Pyro-Verbündete.",
          TextMapId = "SKILL_310003_DESC"
        },
        SKILL_310003_NAME = {
          ContentES = "Höllenschmiede ",
          TextMapId = "SKILL_310003_NAME"
        },
        SKILL_310101_DESC = {
          ContentES = "Verursacht Pyro-SCH an Gegnern vor sich und fügt [Risswunde] zu.",
          TextMapId = "SKILL_310101_DESC"
        },
        SKILL_310101_NAME = {
          ContentES = "Tödliche Blüte",
          TextMapId = "SKILL_310101_NAME"
        },
        SKILL_310102_DESC = {
          ContentES = "Wechselt die Fernkampfwaffe zu [Hansel und Gretel]. In diesem Zustand kann Lynn nur schießen und Fähigkeiten einsetzen, sich jedoch nur mithilfe von [Tödliche Blüte] bewegen.\n Schießen verursacht SCH an allen Gegnern voraus, und dabei wird Lynns Angriffs-GES alle 0,2 Sek. erhöht, bis zu 35-mal stapelbar.\n Beim Einsatz von [Hänsel und Gretel] wird kontinuierlich Geist verbraucht. Währenddessen ist Lynn beim Erleiden von SCH immun gegen Trefferstarre. Fällt der Geist unter 0 oder wird die Fähigkeit erneut eingesetzt, wird [Hänsel und Gretel] wieder in die Scheide zurückgeführt.",
          TextMapId = "SKILL_310102_DESC"
        },
        SKILL_310102_NAME = {
          ContentES = "Pulverrausch",
          TextMapId = "SKILL_310102_NAME"
        },
        SKILL_310103_DESC = {
          ContentES = "Wenn Lynn nicht schießt, erhält sie 1 Stapelung [Vorladen] pro Sekunde, bis zu 6 Stapelungen. Wenn sie schießt, verbraucht sie alle Stapelungen [Vorladen], um für eine bestimmte Zeit [Unterdrückungsfeuer] zu erhalten. [Unterdrückungsfeuer]: Erhöht den Schaden basierend auf der Anzahl der verbrauchten [Vorladen]-Stapelungen.\n [Vorladen]-Stapelung kann während [Unterdrückungsfeuer] nicht erhalten werden.",
          TextMapId = "SKILL_310103_DESC"
        },
        SKILL_310103_NAME = {
          ContentES = "Taktisches Schnellfeuer",
          TextMapId = "SKILL_310103_NAME"
        },
        SKILL_310104_DESC = {
          ContentES = "Entfernt sofort [Risswunde] und verursacht Schaden, sobald die [Aufgerissene Wunde]-Anzahl das Maximum erreicht.",
          TextMapId = "SKILL_310104_DESC"
        },
        SKILL_310104_NAME = {
          ContentES = "Unverzeihlichkeit",
          TextMapId = "SKILL_310104_NAME"
        },
        SKILL_310201_DESC = {
          ContentES = "Befiehlt allen [Schmutzvertilgern], sich kontinuierlich um Hilda zu drehen und [Hyperthermische Reinigungsstrahlen] abzufeuern. Währenddessen wird die Dauer aller [Leichten Schmutzvertilger] angehalten. [Hyperthermische Reinigungsstrahlen] fügen getroffenen Gegnern Pyro-SCH zu. Während der Dauer von [Hyperthermischer Reinigungsstrahl] besteht beim Besiegen eines Gegners die Chance, Hilda Geist wiederherzustellen.",
          TextMapId = "SKILL_310201_DESC"
        },
        SKILL_310201_NAME = {
          ContentES = "Pyrolytische Reinigung",
          TextMapId = "SKILL_310201_NAME"
        },
        SKILL_310202_DESC = {
          ContentES = "Verursacht Pyro-SCH an Gegnern in der Umgebung und belegt sie mit [Entwaffnung]. Für jedes getroffene Ziel wird 1 [Leichter Schmutzvertilger] in der Nähe von Hilda beschworen und die Dauer aller [Leichten Schmutzvertilger] wird aktualisiert.\n Trägt 2 [Schwere Schmutzvertilger] herum. [Schwere Schmutzvertilger] und [Leichte Schmutzvertilger] zielen automatisch auf Gegner in der Nähe und schießen alle 3 Sek. auf sie, wobei sie Pyro-SCH verursachen.\n Es können maximal 6 [Leichte Schmutzvertilger] gleichzeitig existieren.",
          TextMapId = "SKILL_310202_DESC"
        },
        SKILL_310202_NAME = {
          ContentES = "Hingebungsvoller Service",
          TextMapId = "SKILL_310202_NAME"
        },
        SKILL_310203_DESC = {
          ContentES = "Beim Ausweichen wird Hildas Fernkampfwaffen-Magazin vollständig nachgeladen, und sie erhält für kurze Zeit [Elegante Wut].",
          TextMapId = "SKILL_310203_DESC"
        },
        SKILL_310203_NAME = {
          ContentES = "Automatische Reinigung",
          TextMapId = "SKILL_310203_NAME"
        },
        SKILL_310204_DESC = {
          ContentES = "[Schmutzvertilger] hat eine Chance, beim Angriff 1 zusätzliches Geschoss abzufeuern, mit einer Wahrscheinlichkeit in Höhe von [30 % + 20 % × Hildas Mehrfachschussrate der Fernkampfwaffen]. Erhöht den SCH von [Hyperthermischer Reinigungsstrahl] um [30 % + 20 % × Hildas Mehrfachschussrate der Fernkampfwaffen].",
          TextMapId = "SKILL_310204_DESC"
        },
        SKILL_310204_NAME = {
          ContentES = "Multitasking",
          TextMapId = "SKILL_310204_NAME"
        },
        SKILL_310301_DESC = {
          ContentES = "Wirft eine Bombe namens [Kleiner Knaller], die entweder die Form von [Kleiner Knaller: Yales Werk] oder [Kleiner Knaller: Olivers Werk] annimmt. Nach der Landung detoniert die Bombe nach 2 Sek. und verursacht Pyro-SCH in einem kreuzförmigen Bereich, wodurch alle weiteren [Kleinen Knaller] im Umkreis ausgelöst werden. Es können maximal 10 [Kleine Knaller] gleichzeitig existieren.",
          TextMapId = "SKILL_310301_DESC"
        },
        SKILL_310301_NAME = {
          ContentES = "Kleiner Knaller",
          TextMapId = "SKILL_310301_NAME"
        },
        SKILL_310302_DESC = {
          ContentES = "Generiert [Alptraumlabor] um Yale und Oliver herum. Der erneute Einsatz dieser Fähigkeit kann das [Alptraumlabor] vorzeitig schließen.",
          TextMapId = "SKILL_310302_DESC"
        },
        SKILL_310302_NAME = {
          ContentES = "Alptraumerinnerung",
          TextMapId = "SKILL_310302_NAME"
        },
        SKILL_310303_DESC = {
          ContentES = "Wenn ein [Kleiner Knaller] eingesetzt wird und sich beim Abwurf mindestens 2 m über dem Boden befindet, verursacht er bei der Landung Pyro-SCH an nahe stehenden Gegnern.",
          TextMapId = "SKILL_310303_DESC"
        },
        SKILL_310303_NAME = {
          ContentES = "Bomben-Spielregeln",
          TextMapId = "SKILL_310303_NAME"
        },
        SKILL_310304_DESC = {
          ContentES = "Bei jedem Einsatz eines [Kleinen Knallers] erhalten Yale und Oliver 1 Stapelung [Bombenfieber], bis zu 3 Stapelungen.",
          TextMapId = "SKILL_310304_DESC"
        },
        SKILL_310304_NAME = {
          ContentES = "Bomben-Erinnerungen",
          TextMapId = "SKILL_310304_NAME"
        },
        SKILL_320101_DESC = {
          ContentES = "Tritt in den Zustand [Vergeltung] ein.",
          TextMapId = "SKILL_320101_DESC"
        },
        SKILL_320101_NAME = {
          ContentES = "Glühendes Inferno",
          TextMapId = "SKILL_320101_NAME"
        },
        SKILL_320102_DESC = {
          ContentES = "Verursacht Pyro-SCH an Gegnern in der Umgebung und verspottet sie.",
          TextMapId = "SKILL_320102_DESC"
        },
        SKILL_320102_NAME = {
          ContentES = "Käfig der Verzweiflung",
          TextMapId = "SKILL_320102_NAME"
        },
        SKILL_320103_DESC = {
          ContentES = "Erhöht die max. LP und stellt dauerhaft LP wieder her.",
          TextMapId = "SKILL_320103_DESC"
        },
        SKILL_320103_NAME = {
          ContentES = "Strafentschlossenheit",
          TextMapId = "SKILL_320103_NAME"
        },
        SKILL_320104_DESC = {
          ContentES = "Erhöht den Schaden an Gegnern, die durch Hellfire verspottet werden.",
          TextMapId = "SKILL_320104_DESC"
        },
        SKILL_320104_NAME = {
          ContentES = "Schuldspruch",
          TextMapId = "SKILL_320104_NAME"
        },
        SKILL_320201_DESC = {
          ContentES = "Entfesselt alle [Drehklingen], verursacht Pyro-SCH an Gegnern vor sich und erhält 1 Stapelung [Rausch]. Drücke wiederholt oder halte die Angriffstaste gedrückt, um ein Gestöber von Angriffen auszuführen.",
          TextMapId = "SKILL_320201_DESC"
        },
        SKILL_320201_NAME = {
          ContentES = "Burgunder-Gestöber",
          TextMapId = "SKILL_320201_NAME"
        },
        SKILL_320202_DESC = {
          ContentES = "Verursacht Pyro-SCH an Gegnern vor sich und beschwört 8 [Drehklingen] um sich, die auf ihrem Weg Schaden an Gegnern verursachen.",
          TextMapId = "SKILL_320202_DESC"
        },
        SKILL_320202_NAME = {
          ContentES = "Weinroter Walzer",
          TextMapId = "SKILL_320202_NAME"
        },
        SKILL_320203_DESC = {
          ContentES = "Der von [Drehklingen] verursachte Schaden fügt dem Gegner 1 Stapelung [Risswunde] hinzu, bis zu 20 Stapelungen.",
          TextMapId = "SKILL_320203_DESC"
        },
        SKILL_320203_NAME = {
          ContentES = "Blut auf Wein",
          TextMapId = "SKILL_320203_NAME"
        },
        SKILL_320204_DESC = {
          ContentES = "Das Auslösen von [Risswunde] gewährt 1 Stapelung [Beschwipstes Zeichen]. Stellt Geist wieder her, sobald 20 Stapelungen erreicht sind.",
          TextMapId = "SKILL_320204_DESC"
        },
        SKILL_320204_NAME = {
          ContentES = "Blut unter Wein",
          TextMapId = "SKILL_320204_NAME"
        },
        SKILL_330101_DESC = {
          ContentES = "Greift mehrere Gegner im Umkreis an, verursacht Pyro-SCH und betäubt sie. Beim Einsatz dieser Fähigkeit durch Halten führt Margie einen dauerhaften Angriff aus.",
          TextMapId = "SKILL_330101_DESC"
        },
        SKILL_330101_NAME = {
          ContentES = "Margies Schatzschaufel",
          TextMapId = "SKILL_330101_NAME"
        },
        SKILL_330102_DESC = {
          ContentES = "Wirft 3 [Margies Brandmülltonnen] nach vorne. Beim Auftreffen auf ein Ziel oder Hindernis explodieren sie sofort, verursachen Pyro-Flächenschaden und verbrauchen eine bestimmte Anzahl der Stapelungen von [Jackpot!] zur Verstärkung:\n Beim Verbrauch von 3 Stapelungen [Jackpot!]: Erhöht Explosionsbereich und -schaden.\n Beim Verbrauch von 6 Stapelungen [Jackpot!]: Erschafft eine Eiferzone nach der Explosion, die Gegnern innerhalb der Zone alle 2 Sek. einen Pyro-SCH zufügt.\n Beim Verbrauch von 9 Stapelungen [Jackpot!]: Verursacht nach der Explosion zusätzlich 2-mal Pyro-Flächenschaden.",
          TextMapId = "SKILL_330102_DESC"
        },
        SKILL_330102_NAME = {
          ContentES = "Margies Brandmülltonne",
          TextMapId = "SKILL_330102_NAME"
        },
        SKILL_330103_DESC = {
          ContentES = "Wenn die Figur oder Verbündete Beute aufnehmen, erhält 1 Stapelung [Jackpot!], die für den Rest des Kampfes anhält. Jede Stapelung erhöht den Fähigkeits-SCH, bis zu 20-mal stapelbar.",
          TextMapId = "SKILL_330103_DESC"
        },
        SKILL_330103_NAME = {
          ContentES = "Margies Sammelbeutel",
          TextMapId = "SKILL_330103_NAME"
        },
        SKILL_330104_DESC = {
          ContentES = "Erhöht den ANG anderer Verbündeten.",
          TextMapId = "SKILL_330104_DESC"
        },
        SKILL_330104_NAME = {
          ContentES = "Margies Aufmunterungslied",
          TextMapId = "SKILL_330104_NAME"
        },
        SKILL_410001_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Elektro-Verbündete.",
          TextMapId = "SKILL_410001_DESC"
        },
        SKILL_410001_NAME = {
          ContentES = "Donnernder Nachtbrecher",
          TextMapId = "SKILL_410001_NAME"
        },
        SKILL_410003_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Elektro-Verbündete.",
          TextMapId = "SKILL_410003_DESC"
        },
        SKILL_410003_NAME = {
          ContentES = "Göttliche Vergeltung",
          TextMapId = "SKILL_410003_NAME"
        },
        SKILL_410101_DESC = {
          ContentES = "Rhythm springt vorwärts und verursacht Elektro-SCH an Gegnern auf dem Weg.\n Wenn die [Elektroenergie]-Punkte mindestens 30 betragen, werden 30 Punkte verbraucht, um die Sprungs-GES und den SCH von [Voltsturm] zu erhöhen und einen Effekt zu gewähren, der den von Rhythm verursachten SCH steigert.",
          TextMapId = "SKILL_410101_DESC"
        },
        SKILL_410101_NAME = {
          ContentES = "Voltsturm",
          TextMapId = "SKILL_410101_NAME"
        },
        SKILL_410102_DESC = {
          ContentES = "Verursacht Elektro-SCH an Gegnern in Reichweite und tritt in den Zustand [Elektro-Ausbruch] ein, währenddessen kontinuierlich Geist verbraucht wird. Der Zustand [Elektro-Ausbruch] endet, wenn der Geist auf 0 sinkt oder wenn die Fähigkeit erneut eingesetzt wird.",
          TextMapId = "SKILL_410102_DESC"
        },
        SKILL_410102_NAME = {
          ContentES = "Elektro-Wirbel",
          TextMapId = "SKILL_410102_NAME"
        },
        SKILL_410103_DESC = {
          ContentES = "Wenn Geist verbraucht wird, wird ein Prozentsatz des verbrauchten Geists in [Elektroenergie] umgewandelt. Die Obergrenze der [Elektroenergie] entspricht dem max. Geist.",
          TextMapId = "SKILL_410103_DESC"
        },
        SKILL_410103_NAME = {
          ContentES = "Taktische Stromsparung",
          TextMapId = "SKILL_410103_NAME"
        },
        SKILL_410104_DESC = {
          ContentES = "Beim Verbrauch von [Elektroenergie] werden 50 % der verbrauchten [Elektroenergie] in Geist umgewandelt.",
          TextMapId = "SKILL_410104_DESC"
        },
        SKILL_410104_NAME = {
          ContentES = "Akkusorgen",
          TextMapId = "SKILL_410104_NAME"
        },
        SKILL_410201_DESC = {
          ContentES = "Drücken:\n Zhiliu setzt [Himmlische Offenbarung: Zhen] ein, verursacht Elektro-SCH an Gegnern in Reichweite vor sich und erhält 1 [Talisman: Zhen].\n Gedrückt halten:\n Zhiliu setzt [Himmlische Offenbarung: Xun] ein, verursacht Elektro-SCH an Gegnern in Reichweite vor sich und erhält Ultra-Schild sowie 1 [Talisman: Xun].",
          TextMapId = "SKILL_410201_DESC"
        },
        SKILL_410201_NAME = {
          ContentES = "Himmlische Offenbarung",
          TextMapId = "SKILL_410201_NAME"
        },
        SKILL_410202_DESC = {
          ContentES = "Wenn die Figur weniger als 2 [Talismane] hält, wird Elektro-SCH an Gegnern in der Nähe verursacht.\n Wenn die Figur 2 oder mehr [Talismane] hält, wird diese Fähigkeit entsprechend der Kombination. durch eine andere Fähigkeit ersetzt.",
          TextMapId = "SKILL_410202_DESC"
        },
        SKILL_410202_NAME = {
          ContentES = "Himmel-Erde-Divination",
          TextMapId = "SKILL_410202_NAME"
        },
        SKILL_410203_DESC = {
          ContentES = "Erhält [Talismane] durch [Himmlische Offenbarung], bis zu 2 [Talismane]. Wenn die Anzahl der [Talismane] das Limit überschreitet, wird der am frühesten erhaltene [Talisman] entfernt.\n Wird ein [Talisman] nach dem Einsatz von [Donnerndes Orakel], [Alles Gedeiht] oder [Klarheit des Schicksals] verbraucht, besteht für jeden [Talisman] eine auf der Auslöserate von Zhilius Nahkampfwaffen basierende Chance, erhalten zu bleiben.",
          TextMapId = "SKILL_410203_DESC"
        },
        SKILL_410203_NAME = {
          ContentES = "Talisman-Paartanz",
          TextMapId = "SKILL_410203_NAME"
        },
        SKILL_410204_DESC = {
          ContentES = "Erhält 1 Stapelung Moral, wenn die Figur oder Verbündete Elektro-Fähigkeits-SCH verursachen, bis zu 20 Stapelungen.",
          TextMapId = "SKILL_410204_DESC"
        },
        SKILL_410204_NAME = {
          ContentES = "Symbiose",
          TextMapId = "SKILL_410204_NAME"
        },
        SKILL_420101_DESC = {
          ContentES = "Yuming springt in die Luft und der nächste Sturzangriff wird durch [Sternenlichtabstieg] ersetzt.\n Der Einsatz dieser Fähigkeit im Zustand [Xuanjiao-Besessenheit] gewährt Yuming 1 [Widerschuppe].\n Wenn die [Widerschuppen]-Anzahl ihren Höchstwert erreicht, wird [Sternenlichtabstieg] zu [Milchstraßensturz] verstärkt.",
          TextMapId = "SKILL_420101_DESC"
        },
        SKILL_420101_NAME = {
          ContentES = "Stürzender Gewitterfall",
          TextMapId = "SKILL_420101_NAME"
        },
        SKILL_420102_DESC = {
          ContentES = "Verursacht Elektro-SCH an Gegnern vor sich und tritt in den Zustand [Xuanjiao-Besessenheit] ein.\n Wenn aktiv, erhalten die Figur und Elektro-Verbündete [Fisch-Drachen-Tanz].",
          TextMapId = "SKILL_420102_DESC"
        },
        SKILL_420102_NAME = {
          ContentES = "Düsterschuppen",
          TextMapId = "SKILL_420102_NAME"
        },
        SKILL_420103_DESC = {
          ContentES = "Wenn Schaden mit einer Nahkampfwaffe verursacht wird, werden Gegner mit [Donnernder Ansturm] belegt, der ihre Elektro-Resistenz reduziert.\n Während [Xuanjiao-Besessenheit] wird [Donnernder Ansturm] automatisch auf alle Gegner angewendet.",
          TextMapId = "SKILL_420103_DESC"
        },
        SKILL_420103_NAME = {
          ContentES = "Himmelsgebrüll",
          TextMapId = "SKILL_420103_NAME"
        },
        SKILL_420104_DESC = {
          ContentES = "Yuming erhält 6 [Widerschuppen], wenn [Düsterschuppen] eingesetzt wird.",
          TextMapId = "SKILL_420104_DESC"
        },
        SKILL_420104_NAME = {
          ContentES = "Donnergrollen",
          TextMapId = "SKILL_420104_NAME"
        },
        SKILL_420191_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht die Moral für sich selbst und Elektro-Verbündete.",
          TextMapId = "SKILL_420191_DESC"
        },
        SKILL_420191_NAME = {
          ContentES = "Galopp nach Nordwesten",
          TextMapId = "SKILL_420191_NAME"
        },
        SKILL_420201_DESC = {
          ContentES = "Errichtet eine [Barriere] vor sich und fügt Gegnern in der Nähe Elektro-SCH zu.\n [Barriere] verbraucht im Laufe der Zeit Geist. Währenddessen kann sich Randy weder bewegen noch eine Waffe benutzen und ist immun gegen Trefferstarre. Gegner in der Nähe werden durch [Barriere] mit [Überlastungsgroll] belegt.\n Wenn diese Fähigkeit erneut eingesetzt wird, wird die [Barriere] aufgehoben.",
          TextMapId = "SKILL_420201_DESC"
        },
        SKILL_420201_NAME = {
          ContentES = "Legitimes Faulenzen",
          TextMapId = "SKILL_420201_NAME"
        },
        SKILL_420202_DESC = {
          ContentES = "Wirft 1 [Schild nach Maß] nach vorne. Wenn er zum Stillstand kommt, wird einmal [Aufprall] ausgelöst. Solange [Schild nach Maß] auf dem Schlachtfeld aktiv ist, wird alle 3 Sekunden [Aufprall] erneut ausgelöst.\n „[Aufprall] verursacht nur bei Schilden Schaden, basierend auf Randys VTD, und gewährt Randy und seinen Verbündeten einen Ultra-Schild, der ebenfalls auf Randys VTD basiert. Ziele mit einem Schildwert von 0 werden beim [Aufprall] gelähmt.",
          TextMapId = "SKILL_420202_DESC"
        },
        SKILL_420202_NAME = {
          ContentES = "Spezialgeschenk",
          TextMapId = "SKILL_420202_NAME"
        },
        SKILL_420203_DESC = {
          ContentES = "Wenn Randy einem Teammitglied erfolgreich einen Ultra-Schild gewährt, wird seine VTD basierend auf Randys VTD erhöht, bis zu 10-mal stapelbar.",
          TextMapId = "SKILL_420203_DESC"
        },
        SKILL_420203_NAME = {
          ContentES = "Gemeinsamer Schild",
          TextMapId = "SKILL_420203_NAME"
        },
        SKILL_420204_DESC = {
          ContentES = "Sobald [Barriere] Schaden in Höhe von 70 % von Randys maximalen LP absorbiert hat, wird Geist verbraucht, um die [Barriere] zu erneuern, und es wird einmal der Barriere-Schaden von [Legitimes Faulenzen] ausgelöst.",
          TextMapId = "SKILL_420204_DESC"
        },
        SKILL_420204_NAME = {
          ContentES = "Wohlverdiente Pause",
          TextMapId = "SKILL_420204_NAME"
        },
        SKILL_430101_DESC = {
          ContentES = "Verursacht Elektro-SCH an Gegnern in Reichweite vor sich und erschafft ein Feld [Bestrafung der Legion] an den Zielorten.",
          TextMapId = "SKILL_430101_DESC"
        },
        SKILL_430101_NAME = {
          ContentES = "Göttliche Herrschaft",
          TextMapId = "SKILL_430101_NAME"
        },
        SKILL_430102_DESC = {
          ContentES = "Beschwört [Chaotische Donnerkugel].\n Es kann maximal 1 gleichzeitig existieren. Verbraucht [Kraft des Donners], um eine verstärkte [Chaotische Donnerkugel] zu beschwören. Das Intervall, in dem die verstärkte [Chaotische Donnerkugel] [Vernichtender Sturm] auslöst, wird auf 2 Sek. verkürzt, und ihr Verbund-SCH wird erhöht.",
          TextMapId = "SKILL_430102_DESC"
        },
        SKILL_430102_NAME = {
          ContentES = "Sturmrufer",
          TextMapId = "SKILL_430102_NAME"
        },
        SKILL_430103_DESC = {
          ContentES = "Wenn der verursachte SCH einen Bonuseffekt auslöst, erhält Sibylle eine bestimmte Anzahl der Punkte von [Kraft des Donners], bis zu 300 Punkte. [Göttliche Herrschaft] und [Sturmrufer] können durch das Verbrauchen von [Kraft des Donners] verstärkt werden.",
          TextMapId = "SKILL_430103_DESC"
        },
        SKILL_430103_NAME = {
          ContentES = "Kraft des Donners",
          TextMapId = "SKILL_430103_NAME"
        },
        SKILL_430104_DESC = {
          ContentES = "Der durch [Göttliche Herrschaft] und [Bestrafung der Legion] verursachte SCH löst mit einer gewissen Chance einen Bonuseffekt aus, der auf Sibylles Auslöserate der Nahkampfwaffen basiert.",
          TextMapId = "SKILL_430104_DESC"
        },
        SKILL_430104_NAME = {
          ContentES = "Meisterin der Sturmwolken",
          TextMapId = "SKILL_430104_NAME"
        },
        SKILL_510001_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Anemo-Verbündete.",
          TextMapId = "SKILL_510001_DESC"
        },
        SKILL_510001_NAME = {
          ContentES = "Luftdominanz",
          TextMapId = "SKILL_510001_NAME"
        },
        SKILL_510003_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Anemo-Verbündete.",
          TextMapId = "SKILL_510003_DESC"
        },
        SKILL_510003_NAME = {
          ContentES = "Freudenflug",
          TextMapId = "SKILL_510003_NAME"
        },
        SKILL_510101_DESC = {
          ContentES = "Befiehlt [Filbert], vorwärts zu stürmen, wodurch Anemo-SCH an Gegnern auf dem Weg verursacht wird. Bei Kollision mit einem Hindernis wird am Endpunkt Anemo-SCH ausgelöst. Während diese Fähigkeit aktiv ist, werden Truffle und Verbündete geheilt und ihr SCH wird erhöht.\n Wenn Truffle auf Filbert reitet, wird diese Fähigkeit durch [Huf-Stampede] ersetzt.",
          TextMapId = "SKILL_510101_DESC"
        },
        SKILL_510101_NAME = {
          ContentES = "Huf-Getrappel",
          TextMapId = "SKILL_510101_NAME"
        },
        SKILL_510102_DESC = {
          ContentES = "Reitet auf [Filbert] und erhält 100 Punkte [Arbeitsleidenschaft] erhöht die Bewegungs-GES und verursacht bei der Bewegung Anemo-SCH an Gegnern auf dem Weg.\n Wenn Truffle auf Filbert reitet, kann Truffle keine andere Waffe benutzen, kann aber Filbert befehlen anzugreifen. Wenn diese Fähigkeit erneut eingesetzt wird, steigt Truffle ab und setzt einmal [Huf-Getrappel] ein.",
          TextMapId = "SKILL_510102_DESC"
        },
        SKILL_510102_NAME = {
          ContentES = "Voller Bauch, volle Hände",
          TextMapId = "SKILL_510102_NAME"
        },
        SKILL_510103_DESC = {
          ContentES = "Für jede Sekunde, in der Truffle sich bewegt, erhält sie 1 Stapelung [Schwergewicht], bis zu 10 Stapelungen.\n [Schwergewicht]: Erhöht verursachten SCH und verringert erlittenen SCH.",
          TextMapId = "SKILL_510103_DESC"
        },
        SKILL_510103_NAME = {
          ContentES = "Hopp Hopp, Kommissarin!",
          TextMapId = "SKILL_510103_NAME"
        },
        SKILL_510104_DESC = {
          ContentES = "Wenn Fähigkeits-SCH verursacht wird, besteht eine Chance, dass 1 [Munitionskiste] erscheint.",
          TextMapId = "SKILL_510104_DESC"
        },
        SKILL_510104_NAME = {
          ContentES = "Kampfnachschub",
          TextMapId = "SKILL_510104_NAME"
        },
        SKILL_510191_DESC = {
          ContentES = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht die Entschlossenheit für sich selbst und Verbündete, wenn 2 oder mehr Figuren im Team das gleiche Element teilen.",
          TextMapId = "SKILL_510191_DESC"
        },
        SKILL_510191_NAME = {
          ContentES = "Spähen und picken",
          TextMapId = "SKILL_510191_NAME"
        },
        SKILL_510201_DESC = {
          ContentES = "Tritt in den Zustand [Tarnung] ein und verlässt den Zustand [Jagd].\n Erzeugt 2 [Reißzahnstachel], die zufällige Gegner in der Nähe angreifen, wenn der Zustand [Tarnung] aktiv beendet wird oder [Heimliche Pirsch] im Zustand [Tarnung] erneut eingesetzt wird.",
          TextMapId = "SKILL_510201_DESC"
        },
        SKILL_510201_NAME = {
          ContentES = "Heimliche Pirsch",
          TextMapId = "SKILL_510201_NAME"
        },
        SKILL_510202_DESC = {
          ContentES = "Zieht alle [Reißzahnstachel] ein und tritt in den Zustand [Jagd] ein.\n Für jeden eingezogenen [Reißzahnstachel] verliert Outsider eine gewisse LP-Anzahl, die in eine entsprechende Menge an Ultra-Schild umgewandelt wird, und zusätzlich wird die Dauer des Zustands [Jagd] verlängert. Werden LP aufgrund dieses Effekts verloren, sinken die LP nicht unter 1.",
          TextMapId = "SKILL_510202_DESC"
        },
        SKILL_510202_NAME = {
          ContentES = "Jägers Sprungangriff",
          TextMapId = "SKILL_510202_NAME"
        },
        SKILL_510203_DESC = {
          ContentES = "Bei erlittenem Schaden generiert Outsider 1 [Reißzahnstachel], der den Schadensverursacher angreift. Dieser Effekt kann nur einmal pro Sekunde ausgelöst werden.",
          TextMapId = "SKILL_510203_DESC"
        },
        SKILL_510203_NAME = {
          ContentES = "Zahn um Zahn",
          TextMapId = "SKILL_510203_NAME"
        },
        SKILL_510204_DESC = {
          ContentES = "Außerhalb des Zustands [Jagd] besteht beim Verursachen von Schaden mit einer Nahkampfwaffe eine Chance, 1 [Reißzahnstachel] zu generieren, der das Ziel angreift. Dieser Effekt kann nur einmal pro Sekunde ausgelöst werden.",
          TextMapId = "SKILL_510204_DESC"
        },
        SKILL_510204_NAME = {
          ContentES = "Unstillbarer Biss",
          TextMapId = "SKILL_510204_NAME"
        },
        SKILL_530101_DESC = {
          ContentES = "Erschafft 1 [Trugbild] und flitzt dann nach vorne. Diese Fähigkeit kann jederzeit eingesetzt werden, ohne dass Psyche ihre aktuelle Aktion unterbrechen muss. Im Zustand [Schlüpfen] wird diese Fähigkeit durch [Phototaxis] ersetzt.",
          TextMapId = "SKILL_530101_DESC"
        },
        SKILL_530101_NAME = {
          ContentES = "Chrysalis-Traumgewebe",
          TextMapId = "SKILL_530101_NAME"
        },
        SKILL_530102_DESC = {
          ContentES = "Tritt in den zustand [Schlüpfen] ein und erhält die Fähigkeit zu fliegen. Im Zustand [Schlüpfen] kann Psyche nur Fähigkeiten einsetzen und schießen. Der Zustand [Schlüpfen] verbraucht kontinuierlich Geist, und wenn Geist auf 0 sinkt oder diese Fähigkeit erneut eingesetzt wird, endet der Zustand [Schlüpfen].\n Wenn der LP-Prozentsatz von Psyche über 15 % liegt, verbraucht der Zustand [Schlüpfen] LP statt Geist. Die verbrauchten LP werden zu einem gewissen Prozentsatz in Ultra-Schild umgewandelt.",
          TextMapId = "SKILL_530102_DESC"
        },
        SKILL_530102_NAME = {
          ContentES = "Fluoreszierende Eklosion",
          TextMapId = "SKILL_530102_NAME"
        },
        SKILL_530103_DESC = {
          ContentES = "Wird KRIT-SCH verursacht, erhält Psyche zufällig einen der folgenden Buffs: Erhlöhung des ANG, Erhlöhung des Fähigkeits-SCH oder Erhlöhung der Entschlossenheit.\n Erhöht Psyches SCH für jeden Buff, den sie erhält, bis zu 12 Buffs.",
          TextMapId = "SKILL_530103_DESC"
        },
        SKILL_530103_NAME = {
          ContentES = "Bernsteinlicht",
          TextMapId = "SKILL_530103_NAME"
        },
        SKILL_530104_DESC = {
          ContentES = "Wenn Psyches LP-Prozentsatz beim Einsatz von [Fluoreszierende Eklosion] nicht unter 75 % liegt, wird [Vergänglich wie Tau] erhalten. [Vergänglich wie Tau]: Wenn der Effekt von Moral oder Entschlossenheit ausgelöst wird, wird der LP-Prozentsatz von Psyche als 1 % angesehen. Dieser Effekt kann nur einmal alle 120 Sek. ausgelöst werden.",
          TextMapId = "SKILL_530104_DESC"
        },
        SKILL_530104_NAME = {
          ContentES = "Vergänglich wie Tau",
          TextMapId = "SKILL_530104_NAME"
        },
        SKILL_540101_DESC = {
          ContentES = "Gewährt [Smaragd-Verstreuung]. Während der Wirkungsdauer füllt alchemistischer Rauch den Bereich um die Figur, heilt kontinuierlich sich selbst und Verbündete und reduziert die Bewegungs-GES der Gegner im Bereich.\n Wenn [Smaragd-Verstreuung] aktiv ist, werden 2 [Azoth-Projektile] pro Sekunde generiert.",
          TextMapId = "SKILL_540101_DESC"
        },
        SKILL_540101_NAME = {
          ContentES = "Smaragd-Verstreuung",
          TextMapId = "SKILL_540101_NAME"
        }
      }
    end
  },
