        TERMEXP_1504_Passive_01 = {
          ContentES = "Jeder verbrauchte Überhitzung-Stapelung stellt Geist wieder her und erhöht den SCH der anschließenden Arsenal-Explosion.",
          TextMapId = "TERMEXP_1504_Passive_01"
        },
        TERMEXP_1504_Skill02_01 = {
          ContentES = "Stellt dem [Kunstwerker-Arsenal] zusätzliche Munition bereit und erhöht die Angriffs-GES. Wird beim Zurückziehen des Arsenals entfernt.",
          TextMapId = "TERMEXP_1504_Skill02_01"
        },
        TERMEXP_1504_Skill02_02 = {
          ContentES = "Standardangriffe mit dem [Kunstwerker-Großschwert] verbrauchen 5 Patronen des [Kunstwerker-Arsenals] und verursachen entlang des Wegs Lumino-SCH.",
          TextMapId = "TERMEXP_1504_Skill02_02"
        },
        TERMEXP_1504_Skill02_03 = {
          ContentES = "Feuert mit dem [Kunstwerker-Geschütz] eine Kunstwerker-Granate nach vorn, die beim Aufprall explodiert und Lumino-Flächenschaden verursacht.\n Ist der Dämonenkeil [Kunstwerker-Umkonfiguration] ausgerüstet, wird stattdessen eine Zündgranate abgefeuert, die sich auf zufällige Gegner zubewegt und entlang ihres Wegs alle 0,5 Sek. Lumino-Flächenschaden verursacht.",
          TextMapId = "TERMEXP_1504_Skill02_03"
        },
        TERMEXP_1601_Skill02 = {
          ContentES = "Erhöht den Waffen-SCH.",
          TextMapId = "TERMEXP_1601_Skill02"
        },
        TERMEXP_1801_Passive = {
          ContentES = "Verursacht zusätzlichen Lumino-SCH.",
          TextMapId = "TERMEXP_1801_Passive"
        },
        TERMEXP_1801_Skill02 = {
          ContentES = "Erzeugt ein Elementarfeld basierend auf dem Typ der [Teeparty-Gäste] — [Nachtigall] für Hydro, [Hund] für Pyro, [Einhorn] für Elektro und [Schmetterling] für Anemo.\n Wenn das Feld auftaucht oder sich sein Element verschiebt, erhalten Fina und Verbündete einen zusätzlichen Elementarschaden, der dem Typ des Felds entspricht. Während [Ausgelassene Teeparty] aktiv ist, verursacht das Feld außerdem alle 2 Sek. Elementarschaden an Gegnern innerhalb der Reichweite.",
          TextMapId = "TERMEXP_1801_Skill02"
        },
        TERMEXP_2101_Dot = {
          ContentES = "Verursacht Hydro-SCH einmal alle 2 Sek. Wenn ein Gegner, der mit [Gift der Liebe] belegt ist, besiegt wird, überträgt er sein eigenes [Gift der Liebe] entsprechend der aktuellen Stapelzahl und der verbleibenden Dauer auf nahe Gegner.",
          TextMapId = "TERMEXP_2101_Dot"
        },
        TERMEXP_2101_Summon = {
          ContentES = "Erbt 100 % von Rebeccas Attributen und fügt nahe Gegnern fortlaufend Hydro-SCH zu.",
          TextMapId = "TERMEXP_2101_Summon"
        },
        TERMEXP_2301_Summon = {
          ContentES = "Erbt 100 % von Tabethes Attributen, verursacht kontinuierlich Hydro-SCH an Gegnern in der Nähe und erfasst bis zu 2 Gegner, um sie bewegungsunfähig zu machen.",
          TextMapId = "TERMEXP_2301_Summon"
        },
        TERMEXP_2401_Skill02Buff = {
          ContentES = "Erhöht den Fähigkeits-SCH um einen Prozentsatz von [Fushu]s Fähigkeits-SCH.",
          TextMapId = "TERMEXP_2401_Skill02Buff"
        },
        TERMEXP_2401_Summon = {
          ContentES = "Erbt 100 % von Fushus Attributen und verursacht pro Sekunde Hydro-SCH an den fünf nächststehenden Gegnern.\n [Yunchi] stellt einmal alle 3 Sek. LP und Geist für Teammitglieder in der Nähe wieder her.",
          TextMapId = "TERMEXP_2401_Summon"
        },
        TERMEXP_3101_Debuff = {
          ContentES = "Wenn der Gegner unter dem Einfluss von [Risswunde] einen Fernkampf-SCH durch [Lynn] erleidet, wird die [Aufgerissene Wunde]-Anzahl um 1 erhöht. Wenn die Dauer von [Risswunde] endet, wird beim Gegner einmal Pyro-SCH in Höhe der [Aufgerissene Wunde]-Anzahl × [Risswunde]-SCH verursacht.",
          TextMapId = "TERMEXP_3101_Debuff"
        },
        TERMEXP_3102_Buff = {
          ContentES = "Erhöht die Angriffs-GES von [Schmutzvertilger], die Rotations-GES von [Pyrolytische Reinigung] und die Angriffs-GES von Fernkampfwaffen.",
          TextMapId = "TERMEXP_3102_Buff"
        },
        TERMEXP_3102_Debuff = {
          ContentES = "Deaktiviert dauerhaft Fernkampfwaffen.",
          TextMapId = "TERMEXP_3102_Debuff"
        },
        TERMEXP_3103_Skill02 = {
          ContentES = "Im Bereich des [Alptraumlabors]:\n Die Bewegungs-GES von Gegnern im Bereich wird reduziert. Die Detonationstimer von [Kleinen Knallern] auf dem Boden werden pausiert und sie detonieren nicht durch andere [Kleine Knaller].\n Wenn das [Alptraumlabor] schließt:\n Detonieren alle [Kleinen Knaller] im Bereich, und das Labor löst eine Explosion aus, die Pyro-SCH an den Gegnern verursacht. Für jeden detonierten [Kleinen Knaller] steigt der Explosions-SCH des [Alptraumlabors] und es wird Geist für Yale und Oliver wiederhergestellt.",
          TextMapId = "TERMEXP_3103_Skill02"
        },
        TERMEXP_3103_Summon01 = {
          ContentES = "Wird Schaden verursacht, erleidet das Ziel eine stärkere Reduzierung der Kampfhaltung. Je größer der Unterschied zwischen der Fähigkeitsreichweite und dem Fähigkeits-SCH von Yale und Oliver ist, desto höher ist die Chance, [Kleiner Knaller: Yales Werk] einzusetzen. Wenn der Unterschied nicht geringer als 50 % ist, ist es garantiert ein [Kleiner Knaller: Yales Werk].",
          TextMapId = "TERMEXP_3103_Summon01"
        },
        TERMEXP_3103_Summon02 = {
          ContentES = "Verursacht höheren SCH. Je größer der Unterschied zwischen dem Fähigkeits-SCH und der Fähigkeitsreichweite von Yale und Oliver ist, die durch ausgerüstete Dämonenkeile bereitgestellt werden, desto höher ist die Chance, [Kleiner Knaller: Olivers Werk] einzusetzen. Wenn der Unterschied nicht geringer als 50 % ist, ist es garantiert ein [Kleiner Knaller: Olivers Werk].",
          TextMapId = "TERMEXP_3103_Summon02"
        },
        TERMEXP_3201_Skill01 = {
          ContentES = "Verursacht alle 2 Sek. Pyro-SCH an Gegnern in der Nähe. Wenn Hellfire während [Vergeltung] SCH erleidet, verlängert sich die Dauer des Zustands, und [Durchdringende Vergeltung] verursacht alle 2 Sekunden Pyro-SCH an Gegnern in der Nähe.",
          TextMapId = "TERMEXP_3201_Skill01"
        },
        TERMEXP_3202_Passive01 = {
          ContentES = "Jeder Waffen- und Fähigkeits-SCH, außer [Drehklingen] und [Risswunde], detoniert 2 Stapelungen [Risswunde], was zusätzlichen Elementar-SCH verursacht. Max. 20 Detonationen pro Sekunde.",
          TextMapId = "TERMEXP_3202_Passive01"
        },
        TERMEXP_3202_Skill01 = {
          ContentES = "Erhöt Fähigkeits-GES. [Drehklingen] erhöhen ihre Geschwindigkeit und ihre Dauer wird pausiert. Erhält Immunität gegen Trefferstarre. Alle [Rausch]-Stapelungen werden entfernt, wenn [Burgunder-Gestöber] endet.",
          TextMapId = "TERMEXP_3202_Skill01"
        },
        TERMEXP_3202_Skill02 = {
          ContentES = "Jede [Drehklinge] rotiert alle 2 Sekunden einmal um die Figur. Nach dem Abheben fliegt sie 30 m weit, bevor sie zurückkehrt. Wird sie auf dem Rückweg von Angriffen von [Burgunder-Gestöber] getroffen, wird sie auf einen zufälligen Gegner innerhalb von 20 m erneut abgefeuert. Bei jedem Abfeuern wird ihre Geschwindigkeit basierend auf den [Rausch]-Stapelungen aktualisiert. Es können maximal 8 [Drehklingen] gleichzeitig existieren.",
          TextMapId = "TERMEXP_3202_Skill02"
        },
        TERMEXP_4101_Skill02_01 = {
          ContentES = "Erhöht die Bewegungs-GES für sich selbst und Verbündete. Verursacht jede Sekunde Elektro-SCH an 1 zufälligem Gegner in Reichweite und wechselt dabei zwischen [Positive Ladung] und [Negative Ladung]. Gegner ohne [Elektrische Ladung] werden priorisiert.",
          TextMapId = "TERMEXP_4101_Skill02_01"
        },
        TERMEXP_4101_Skill02_02 = {
          ContentES = "Das Ziel mit [Positive Ladung] wählt alle 3 Sek. 1 zufälliges Ziel mit [Negative Ladung] in Reichweite aus, dann werden beide zum Mittelpunkt zwischen ihren Positionen gezogen und erleiden Elektro-SCH. Wenn keine Ziele mit [Negative Ladung] in der Umgebung sind, wird 1 zufälliges Ziel ausgewählt, um zusammen Elektro-SCH zu erleiden.\n Wenn ein mit [Elektrische Ladung] belegtes Ziel erneut mit derselben Ladung belegt wird, wird die Dauer der bestehenden [Elektrischen Ladung] aktualisiert. Es kann nicht mit der entgegengesetzten [Elektrischen Ladung] belegt werden.",
          TextMapId = "TERMEXP_4101_Skill02_02"
        },
        TERMEXP_4102_Skill02_01 = {
          ContentES = [[
Wenn Zhiliu 2 [Talismane: Zhen] hat, wird [Himmel-Erde-Divination] mit [Donnerndes Orakel] ersetzt.
 [Donnerndes Orakel]: Verbraucht alle [Talismane], verursacht Elektro-SCH an Gegnern in einer geraden Linie vor sich.]],
          TextMapId = "TERMEXP_4102_Skill02_01"
        },
        TERMEXP_4102_Skill02_02 = {
          ContentES = "Wird [Himmel-und-Erde-Evolution] durch diese Fähigkeit ersetzt, wenn Zhiliu 1 [Talisman: Zhen] und 1 [Talisman: Xun] besitzt.\n [Donnerndes Orakel]: Verbraucht alle [Talismane], Verursacht DoT an Gegnern in einem Bereich nach vorne und erschafft anschließend ein Feld [Vier-Reiche-Harmonisierung] an ihrem Standort. Zielt alle 3 Sek. auf bis zu 5 Gegner innerhalb des Feldes und erschafft eine [Zhen-Xun-Konvergenz] an ihrem Standort, wodurch Elektro-Flächenschaden verursacht wird.",
          TextMapId = "TERMEXP_4102_Skill02_02"
        },
        TERMEXP_4102_Skill02_03 = {
          ContentES = "Wenn Zhiliu 2 [Talismane: Xun] hat, wird [Himmel-Erde-Divination] durch [Klarheit des Schicksals] ersetzt.\n [Klarheit des Schicksals]: Verbraucht alle [Talismane], um Elektro-SCH an Gegnern im Umkreis zu verursachen und Zhilius Fähigkeits-SCH zu erhöhen.",
          TextMapId = "TERMEXP_4102_Skill02_03"
        },
        TERMEXP_4201_BonusAttack = {
          ContentES = "Erzeugt [Tobende Donner] bei Zielen, die durch [Sternenlichtabstieg] oder [Milchstraßensturz] Schaden erlitten haben, und verursacht Elektro-Flächenschaden. Es werden maximal 5 Ziele ausgewählt.",
          TextMapId = "TERMEXP_4201_BonusAttack"
        },
        TERMEXP_4201_FallAttack = {
          ContentES = "Stürzt mit hoher Geschwindigkeit herab und verursacht Elektro-Flächenschaden beim Aufprall. Dieser Angriff wird als Sturzangriff mit Nahkampfwaffen angesehen. Der Einsatz dieser Fähigkeit im Zustand [Xuanjiao-Besessenheit] löst [Drachenrufwolken] aus.",
          TextMapId = "TERMEXP_4201_FallAttack"
        },
        TERMEXP_4201_Marks = {
          ContentES = "Die Widerschuppe bleibt bestehen, wobei maximal 6 Schuppen gleichzeitig existieren. Die Schuppen werden entfernt, wenn der Zustand [Xuanjiao-Besessenheit] endet.",
          TextMapId = "TERMEXP_4201_Marks"
        },
        TERMEXP_4201_Skill2Buff = {
          ContentES = "Wenn Fähigkeits-SCH bei einem Ziel verursacht wird, das mit [Donnernder Ansturm] belegt ist, wird zusätzlicher Elektro-SCH verursacht. Kann alle 3 Sek. beim gleichen Ziel ausgelöst werden.",
          TextMapId = "TERMEXP_4201_Skill2Buff"
        },
        TERMEXP_4201_Summon = {
          ContentES = [[
Immun gegen Trefferstarre. Xuanjiao schwebt um [Yuming] herum und verursacht beim Kontakt mit Gegnern alle 2 Sekunden einmal Elektro-SCH pro Gegner.
 Xuanjiao kann den SCH, den [Yuming] erleidet, absorbieren. Wenn die absorbierte Menge einen festgelegten Prozentsatz von [Yuming]s max. LP erreicht, endet [Xuanjiao-Besessenheit].]],
          TextMapId = "TERMEXP_4201_Summon"
        },
        TERMEXP_4201_SuperFallAttack = {
          ContentES = "Verbraucht alle [Widerschuppen], um den verursachten SCH für sich selbst und Verbündete zu erhöhen.\n Stürzt anschließend mit hoher Geschwindigkeit herab und verursacht Elektro-Flächenschaden beim Aufprall. Dieser Angriff wird als Sturzangriff mit Nahkampfwaffen angesehen. Der Einsatz dieser Fähigkeit im Zustand [Xuanjiao-Besessenheit] löst [Drachenrufwolken] aus.",
          TextMapId = "TERMEXP_4201_SuperFallAttack"
        },
        TERMEXP_4202_Skill01 = {
          ContentES = "[Barriere] blockt Frontalangriffe ab und absorbiert deren Schaden. Sie verschwindet, sobald sie Schaden in Höhe von 100 % der Randys max. LP absorbiert hat.",
          TextMapId = "TERMEXP_4202_Skill01"
        },
        TERMEXP_4202_Skill01Buff = {
          ContentES = "Reduziert den ANG und verursacht Elektro-SCH einmal alle 2 Sek.",
          TextMapId = "TERMEXP_4202_Skill01Buff"
        },
        TERMEXP_4301_Skill01 = {
          ContentES = "Nach einer Verzögerung von 1,5 Sek. wird alle 0,4 Sek. eine bestimmte Menge [Kraft des Donners] verbraucht, um einem zufälligen Gegner im Bereich Elektro-SCH zuzufügen. Das hält bis zu 10 Sek. an. Wenn [Kraft des Donners] auf 0 sinkt, verschwindet das [Bestrafung der Legion]-Feld. Es können maximal 3 solcher Felder gleichzeitig existieren.",
          TextMapId = "TERMEXP_4301_Skill01"
        },
        TERMEXP_4301_Skill02 = {
          ContentES = "Erbt einen Prozentsatz von Sibylles max. LP, hat 0 VTD und wird als gegnerische Einheit behandelt.\n [Beschworenes Objekt: Chaotische Donnerkugel] ruft alle 3 Sek. einen [Vernichtenden Sturm] herbei.\n Nach der Beschwörung verbindet sich die [Beschworenes Objekt: Chaotische Donnerkugel] zunächst mit den 5 am weitesten entfernten Gegnern im Wirkungsbereich und anschließend jede Sekunde mit einem weiteren Gegner, bis zu insgesamt 10. Die [Beschworenes Objekt: Chaotische Donnerkugel] verursacht einmal pro Sekunde Elektro-SCH bei allen verbundenen Zielen.\n Wenn [Beschworenes Objekt: Chaotische Donnerkugel] SCH erleidet, wird ein gewisser Prozentsatz auf die verbundenen Gegner übertragen.",
          TextMapId = "TERMEXP_4301_Skill02"
        },
        TERMEXP_4301_Skill02Damage = {
          ContentES = "Verursacht Elektro-SCH an Gegnern in der Nähe.",
          TextMapId = "TERMEXP_4301_Skill02Damage"
        },
        TERMEXP_5101_Skill01 = {
          ContentES = "Beim Gedrückthalten der Fähigkeit verbraucht Truffle kontinuierlich Geist und stürmt im Reiten auf [Filbert] weiter, wobei sie Anemo-SCH an Gegnern auf ihrem Weg verursacht. Beim Zusammenstoß mit einem Hindernis endet der Sturm und verursacht Anemo-Flächenschaden am Endpunkt.",
          TextMapId = "TERMEXP_5101_Skill01"
        },
        TERMEXP_5101_Skill02_Value = {
          ContentES = "[Arbeitsleidenschaft] verliert 5 Punkte pro Sekunde und stellt 1 Punkt wieder her, wenn beim Bewegungsschub Schaden verursacht wird. Während [Huf-Stampede] verliert [Arbeitsleidenschaft] keine Punkte. Wenn [Arbeitsleidenschaft] auf 0 sinkt, steigt Truffle ab und setzt einmal [Huf-Getrappel] ein.",
          TextMapId = "TERMEXP_5101_Skill02_Value"
        },
        TERMEXP_5102_Skill01 = {
          ContentES = "Im Zustand [Tarnung] kann Outsider von Gegnern nicht entdeckt werden, und er verlässt diesen Zustand auch nicht, wenn er Schaden erleidet. Beim Starten eines Angriffs oder beim Einsatz von [Jägers Sprungangriff] verlässt er den Zustand [Tarnung].",
          TextMapId = "TERMEXP_5102_Skill01"
        },
        TERMEXP_5102_Skill02 = {
          ContentES = "Im Zustand [Jagd] ist Outsider immun gegen Trefferstarre und erhält eine Erhöhung der Waffen-Angriffs-GES sowie der Entschlossenheit. Outsider kann in diesem Zustand keine Heilung erhalten und jede erhaltene Heilung wird in eine entsprechende Menge Ultra-Schild umgewandelt.",
          TextMapId = "TERMEXP_5102_Skill02"
        },
        TERMEXP_5102_Skill03 = {
          ContentES = "Beim Generieren fliegt [Reißzahnstachel] auf sein Ziel zu, verursacht Anemo-SCH an Gegnern auf seinem Weg und belegt sie mit [Kehlenschneider]. Nachdem er eine Weile geflogen ist, fällt der [Reißzahnstachel] zu Boden und bleibt liegen. Es können maximal 10 [Reißzahnstachel] gleichzeitig existieren.",
          TextMapId = "TERMEXP_5102_Skill03"
        },
        TERMEXP_5301_Skill01 = {
          ContentES = "Stürmt vorwärts in die Luft und entfesselt 16 [Ätherische Pulver]. Die [Ätherischen Pulver] richten sich automatisch auf 1 Gegner aus, verursachen Anemo-SCH und belegen ihn mit 1 Stapelung [Pulverstigma], bis zu 12 Stapelungen.",
          TextMapId = "TERMEXP_5301_Skill01"
        },
        TERMEXP_5301_Skill01Mark = {
          ContentES = "Wenn ein mit [Pulverstigma] belegtes Ziel einen Fernkampfwaffen-SCH durch [Psyche] erleidet, wird 1 Stapelung [Pulverstigma] verbraucht, um Anemo-SCH zu verursachen.",
          TextMapId = "TERMEXP_5301_Skill01Mark"
        },
        TERMEXP_5301_Summon = {
          ContentES = "Nach dem Erzeugen verlangsamt das Trugbild kontinuierlich die Gegner in der Nähe. Nach 5 Sekunden verursacht es Anemo-SCH an Gegnern in der Nähe und verschwindet. Wenn ein neues [Trugbild] erzeugt wird, verursacht das bereits vorhandene [Trugbild] sofort Anemo-SCH und verschwindet.",
          TextMapId = "TERMEXP_5301_Summon"
        },
        TERMEXP_5401_Buff = {
          ContentES = "Gewährt Erhöhung des Anemo-SCH.",
          TextMapId = "TERMEXP_5401_Buff"
        },
        TERMEXP_5401_Debuff = {
          ContentES = "Reduziert den ANG und verursacht alle 2 Sek. Anemo-DoT an betroffenen Zielen.",
          TextMapId = "TERMEXP_5401_Debuff"
        },
        TERMEXP_Common_AdditionalDmg = {
          ContentES = "Beim Verursachen von Schaden wird zusätzlich 1-mal Schaden basierend auf dem ursprünglichen Schaden zugefügt.",
          TextMapId = "TERMEXP_Common_AdditionalDmg"
        },
        TERMEXP_Common_OverES = {
          ContentES = "Ein zusätzlicher Schild, der sich unabhängig stapelt. Das Ultra-Schild hat eine Obergrenze von 425+75×Figurstufe.",
          TextMapId = "TERMEXP_Common_OverES"
        },
        TERMEXP_Common_SkillSpeed = {
          ContentES = "Bestimmt, wie schnell Fähigkeiten ausgeführt werden.",
          TextMapId = "TERMEXP_Common_SkillSpeed"
        },
        TERMEXP_Common_Taunt = {
          ContentES = "Zwingt das Ziel, seine Aggression auf dich zu richten.",
          TextMapId = "TERMEXP_Common_Taunt"
        },
        TERMEXP_Rou_10101_MoltenBlaze = {
          ContentES = "Erhöht den erlittenen SCH des Ziels für <Highlight>5</> s um <Highlight>2,5 %</>, bis zu <Highlight>10</>-mal stapelbar.",
          TextMapId = "TERMEXP_Rou_10101_MoltenBlaze"
        },
        TERMEXP_Rou_10101_MoltenBlazeSabre = {
          ContentES = "Verursacht SCH in Höhe von <Highlight>563 %</> des ANG der Figur.",
          TextMapId = "TERMEXP_Rou_10101_MoltenBlazeSabre"
        },
        TERMEXP_Rou_10102_MiniSeaborneMoons = {
          ContentES = "[Mini-Meergebundener Monde] gelten als Beute. Wenn du einen aufhebst, werden die LP, der Geist und die Munition wiederhergestellt.",
          TextMapId = "TERMEXP_Rou_10102_MiniSeaborneMoons"
        },
        TERMEXP_Rou_10102_PhantomDrift = {
          ContentES = "Erhöht den Fernkampfwaffen-SCH um <Highlight>6 %</> für <Highlight>15</> s, bis zu <Highlight>10</>-mal stapelbar.",
          TextMapId = "TERMEXP_Rou_10102_PhantomDrift"
        },
        TERMEXP_Rou_10102_SeaborneMoon = {
          ContentES = "Verursacht Flächenschaden in Höhe von <Highlight>1350 %</> des ANG der Figur und beschwört <Highlight>3</> [Mini-Meergebundener Mond].",
          TextMapId = "TERMEXP_Rou_10102_SeaborneMoon"
        },
        TERMEXP_Rou_10102_Stinger = {
          ContentES = "Verursacht bei dem Treffer Flächenschaden in Höhe von <Highlight>270 %</> des ANG der Figur.",
          TextMapId = "TERMEXP_Rou_10102_Stinger"
        },
        TERMEXP_Rou_10102_VeiledMoon = {
          ContentES = "Eine besondere Ressource. Du kannst bis zu <Highlight>6</> behalten. Wenn du Fernkampfwaffen-SCH verursachst, wird 1 [Verschleierter Mond] verbraucht, um einen [Stinger] abzufeuern, der bei dem Treffer Flächenschaden in Höhe von <Highlight>270 %</> des ANG der Figur verursacht.",
          TextMapId = "TERMEXP_Rou_10102_VeiledMoon"
        },
        TERMEXP_Rou_10103_Emission = {
          ContentES = "Verursacht an Gegnern im Umkreis von <Highlight>6 </> m Fähigkeits-SCH in Höhe von <Highlight>810 %</> des ANG der Figur.",
          TextMapId = "TERMEXP_Rou_10103_Emission"
        },
        TERMEXP_Rou_10103_Radiance = {
          ContentES = "Erhöht im aktiven Zustand Fähigkeits-SCH um <Highlight>50 %</>.",
          TextMapId = "TERMEXP_Rou_10103_Radiance"
        },
        TERMEXP_Rou_10104_GlowingTree = {
          ContentES = "Heilt Verbündete im Umkreis von <Highlight>10</> m um <Highlight>5 %</> ihrer max. LP pro Sekunde. Hält <Highlight>10</> s an, kann maximal 1 gleichzeitig existieren.",
          TextMapId = "TERMEXP_Rou_10104_GlowingTree"
        },
        TERMEXP_Rou_10104_Lumileaf = {
          ContentES = "Detoniert, sobald ein Gegner im Umkreis von <Highlight>3</> m auftaucht, und verursacht SCH in Höhe von <Highlight>1000 %</> des ANG. Hält <Highlight>10</> s an, kann maximal 10 gleichzeitig existieren.",
          TextMapId = "TERMEXP_Rou_10104_Lumileaf"
        },
        TERMEXP_Rou_10104_Lumiseed = {
          ContentES = "Detoniert, sobald ein Gegner im Umkreis von <Highlight>3</> m auftaucht, und verursacht SCH in Höhe von <Highlight>600 %</> des ANG. Hält <Highlight>10</> s an, kann maximal 10 gleichzeitig existieren.",
          TextMapId = "TERMEXP_Rou_10104_Lumiseed"
