        TERMEXP_Rou_10105_BladeWings = {
          ContentES = "Große zielsuchende Geschosse, die die Kampfhaltung noch effektiver reduzieren.",
          TextMapId = "TERMEXP_Rou_10105_BladeWings"
        },
        TERMEXP_Rou_10105_Nocturne = {
          ContentES = "Jede Stapelung erhöht die Bewegungs-GES um <Highlight>1 %</> für <Highlight>20</> s, bis zu <Highlight>60</>-mal stapelbar.",
          TextMapId = "TERMEXP_Rou_10105_Nocturne"
