        Toast_DonglishiJiaoxue = {
          ContentES = "Greife die aktiven Phoxynamo-Räder an, um sie auszuschalten",
          TextMapId = "Toast_DonglishiJiaoxue"
        },
        Toast_MiYao = {
          ContentES = "Schlüssel erfolgreich gefunden",
