        Two = {ContentES = "2", TextMapId = "Two"},
        UIGUIDE_AMMO = {
          ContentES = "Es besteht die Chance, Munitionsvorräte zu erhalten, indem du Gegner besiegst, Truhen öffnest oder zerbrechliche Objekte zerstörst. Mit diesen Vorräten kannst du die Geschosse für Fernkampfwaffen auffüllen.",
          TextMapId = "UIGUIDE_AMMO"
        },
        UIGUIDE_ATTACK = {
          ContentES = "Drücke &Attack&, um Nahkampfangriff auszuführen.",
          TextMapId = "UIGUIDE_ATTACK"
        },
        UIGUIDE_CHARGEATTACK = {
          ContentES = "Halte &Attack& gedrückt, um einen geladenen Angriff auszuführen.",
          TextMapId = "UIGUIDE_CHARGEATTACK"
        },
        UIGUIDE_EXECUTION_01 = {
          ContentES = "Starke Gegner behalten ihre Kampfhaltung bei, die durch Angriffe <Highlight>geschwächt</> werden kann. Die Gegner <Highlight>verlieren das Gleichgewicht</>, wenn ihre Haltung bis zu einem bestimmten Grad geschwächt ist, und sobald sie vollständig geschwächt ist, werden sie für kurze Zeit <Highlight>betäubt</>.",
          TextMapId = "UIGUIDE_EXECUTION_01"
        },
        UIGUIDE_EXECUTION_02 = {
          ContentES = "Betäubte Gegner werden verwundbar und zeigen ihre Schwäche. In diesem Moment <H>kann man sich ihnen nähern, um einen mächtigen Schlag auszuführen</>. Einige Daimons bezeichnen dies als <H>Asks Vergeltung</>, was sowohl Zerstörung als auch Gelegenheit bringt.</>",
          TextMapId = "UIGUIDE_EXECUTION_02"
        },
        UIGUIDE_FALLATTACK = {
          ContentES = "Drücke &Attack& in der Luft, um einen Sturzangriff auszuführen.",
          TextMapId = "UIGUIDE_FALLATTACK"
        },
        UIGUIDE_GUN = {
          ContentES = "Fernkampfwaffen eignen sich ideal, um Gegner in der Ferne oder auf erhöhter Position zu besiegen. Beachte die Begrenzungen von Magazin und Munition.",
          TextMapId = "UIGUIDE_GUN"
        },
        UIGUIDE_HPSHIELD = {
          ContentES = [[
Wenn eine Figur angegriffen wird, wird zuerst das <Highlight>Schild</> verbraucht.
 Sobald das <Highlight>Schild</> aufgebraucht ist, verringern weitere Angriffe die <Highlight>LP</>.]],
          TextMapId = "UIGUIDE_HPSHIELD"
        },
        UIGUIDE_PARTIALDAMAGE_01 = {
          ContentES = "Einige Gegner haben leuchtende Teile, die zerstörbar sind, und jedes Teil hat seine <Highlight>eigene LP</>.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_01"
        },
        UIGUIDE_PARTIALDAMAGE_02 = {
          ContentES = "Wenn die LP eines zerstörbaren Teils auf 0 reduziert werden, gerät der Gegner in den <Highlight>Gebrochenen Zustand</>, der die <Highlight>Kampfhaltung des Gegners deutlich schwächt</>.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_02"
        },
        UIGUIDE_PARTIALDAMAGE_03 = {
          ContentES = "Wenn ihre Kampfhaltung bis zu einem bestimmten Grad geschwächt ist, wird der Gegner <Highlight>das Gleichgewicht verlieren</>.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_03"
        },
        UIGUIDE_PARTIALDAMAGE_04 = {
          ContentES = "Sobald die Kampfhaltung eines Gegners vollständig geschwächt ist, wird er für kurze Zeit <Highlight>betäubt</>. <Highlight>Während der Haltungserholung</> <Highlight>wird die Schwachstelle des Gegners aufgedeckt</> und er erleidet deutlich mehr Schaden.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_04"
        },
        UIGUIDE_PARTIALDAMAGE_05 = {
          ContentES = "Die Rüstung von Kristallophage ist zerstörbar, und jedes Teil hat seine <Highlight>eigene LP</>.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_05"
        },
        UIGUIDE_PARTIALDAMAGE_06 = {
          ContentES = "Solange <Highlight>irgendeine</> Rüstung vorhanden ist, bleibt Kristallophage <Highlight>unbesiegbar</>. Wenn die LP eines zerstörbaren Teils auf 0 reduziert werden, gerät Kristallophage in den <Highlight>Gebrochenen Zustand</> und verliert das Gleichgewicht.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_06"
        },
        UIGUIDE_PARTIALDAMAGE_07 = {
          ContentES = "Wenn Kristallophage <Highlight>das Gleichgewicht verliert</>, wird es für kurze Zeit <Highlight>betäubt</> und <Highlight>verliert seine Unverwundbarkeit</>.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_07"
        },
        UIGUIDE_PARTIALDAMAGE_08 = {
          ContentES = "Wenn die gesamte Rüstung zerstört ist, wird Kristallophage <Highlight>vollständig betäubt</> und seine <Highlight>Schwachstelle aufgedeckt</>. Wenn du <Highlight>Asks Vergeltung</> in diesem Moment auf seinen <Highlight>Kopf</> einsetzt, <Highlight>wird es sofort besiegt</>.",
          TextMapId = "UIGUIDE_PARTIALDAMAGE_08"
        },
        UIGUIDE_SKILL2_01 = {
          ContentES = "Inspiriert von der Kraft der Resonanz wurde Berenicas <Highlight>Ultimate</> erweckt.\n Drücke &Skill2&, um Berenicas Ultimate [Unterweltflammen] einzusetzen. [Unterweltflammen] <Highlight>verbraucht während der Aktivierung fortlaufend Geist</> und entfesselt Schwertwellen in die Angriffsrichtung. Drücke &Skill2& <Highlight>erneut</>, um <Highlight>den Ultimate zu beenden</>.",
          TextMapId = "UIGUIDE_SKILL2_01"
        },
        UIGUIDE_SKILL2_01_phone = {
          ContentES = "Inspiriert von der Kraft der Resonanz wurde Berenicas <Highlight>Ultimate</> erweckt.\n Tippe auf die Taste, um Berenicas Ultimate [Unterweltflammen] einzusetzen. [Unterweltflammen] <Highlight>verbraucht während der Aktivierung fortlaufend Geist</> und entfesselt Schwertwellen in die Angriffsrichtung. Tippe <Highlight>erneut</> auf die Taste, um <Highlight>den Ultimate zu beenden</>.",
          TextMapId = "UIGUIDE_SKILL2_01_phone"
        },
        UIGUIDE_SLIDEATTACK = {
          ContentES = "Drücke &attack& beim Gleiten, um einen Gleitangriff auszuführen.",
          TextMapId = "UIGUIDE_SLIDEATTACK"
        },
        UIGUIDE_TITLE_AMMO = {
          ContentES = "Munition",
          TextMapId = "UIGUIDE_TITLE_AMMO"
        },
        UIGUIDE_TITLE_ATTACK = {
          ContentES = "Nahkampfangriff",
          TextMapId = "UIGUIDE_TITLE_ATTACK"
        },
        UIGUIDE_TITLE_CHARGEATTACK = {
          ContentES = "Geladener Angriff",
          TextMapId = "UIGUIDE_TITLE_CHARGEATTACK"
        },
        UIGUIDE_TITLE_EXECUTION_01 = {
          ContentES = "Kampfmechanik: Kampfhaltung",
          TextMapId = "UIGUIDE_TITLE_EXECUTION_01"
        },
        UIGUIDE_TITLE_EXECUTION_02 = {
          ContentES = "Figurenmechanik: „Asks Vergeltung“",
          TextMapId = "UIGUIDE_TITLE_EXECUTION_02"
        },
        UIGUIDE_TITLE_FALLATTACK = {
          ContentES = "Sturzangriff",
          TextMapId = "UIGUIDE_TITLE_FALLATTACK"
        },
        UIGUIDE_TITLE_GUN = {
          ContentES = "Fernkampfwaffe",
          TextMapId = "UIGUIDE_TITLE_GUN"
        },
        UIGUIDE_TITLE_HPSHIELD = {
          ContentES = "Schild/LP",
          TextMapId = "UIGUIDE_TITLE_HPSHIELD"
        },
        UIGUIDE_TITLE_PARTIALDAMAGE = {
          ContentES = "Kampfmechanik: Teilen und Zerstören",
          TextMapId = "UIGUIDE_TITLE_PARTIALDAMAGE"
        },
        UIGUIDE_TITLE_SIDEWAYSJUMP = {
          ContentES = "Seitwärts klettern",
          TextMapId = "UIGUIDE_TITLE_SIDEWAYSJUMP"
        },
        UIGUIDE_TITLE_SKILL2_01 = {
          ContentES = "Ultimate: Unterweltflammen",
          TextMapId = "UIGUIDE_TITLE_SKILL2_01"
        },
        UIGUIDE_TITLE_SLIDEATTACK = {
          ContentES = "Gleitangriff",
          TextMapId = "UIGUIDE_TITLE_SLIDEATTACK"
        },
        UIGUIDE_TITLE_SpecialSideStoryUI = {
          ContentES = "Besondere Nebenaufträge",
          TextMapId = "UIGUIDE_TITLE_SpecialSideStoryUI"
        },
        UIGUIDE_TITLE_WIKI = {
          ContentES = "Atlasipedia",
          TextMapId = "UIGUIDE_TITLE_WIKI"
        },
        UIGuide_Abyss_1 = {
          ContentES = "Bediene das Gerät, um die Herausforderung „Immersives Theater“ zu starten.",
          TextMapId = "UIGuide_Abyss_1"
        },
        UIGuide_Abyss_2 = {
          ContentES = "Wenn sich der Vorhang hebt, treten als Gegner verkleidete Darsteller auf die Bühne. Besiege die erforderliche Anzahl an Gegnern innerhalb der vorgegebenen Zeit, um fortzufahren.",
          TextMapId = "UIGuide_Abyss_2"
        },
        UIGuide_Abyss_3_1 = {
          ContentES = "Erfolg: Eliminiere die vorgegebene Anzahl an Gegnern innerhalb des Zeitlimits, um die nächste Phase freizuschalten.",
          TextMapId = "UIGuide_Abyss_3_1"
        },
        UIGuide_Abyss_3_2 = {
          ContentES = "Niederlage: Wenn du das Ziel nicht erfüllst, wird die Herausforderung sofort beendet.",
          TextMapId = "UIGuide_Abyss_3_2"
        },
        UIGuide_Abyss_4 = {
          ContentES = "Sobald der Weg frei ist, mach mit der nächsten Phase weiter, bevor der Countdown abläuft – sonst scheitert die Herausforderung.",
          TextMapId = "UIGuide_Abyss_4"
        },
        UIGuide_Abyss_5 = {
          ContentES = "Im fünften und letzten Akt triffst du auf besonders starke Gegner. Besiege sie innerhalb des Zeitlimits, um das „Immersive Theater“ abzuschließen.",
          TextMapId = "UIGuide_Abyss_5"
        },
        UIGuide_AssistanceSkill = {
          ContentES = "<H>Geniemon</> bieten im Kampf verschiedene Unterstützung.",
          TextMapId = "UIGuide_AssistanceSkill"
        },
        UIGuide_BattleWheel_1 = {
          ContentES = "Der <H>taktische Rucksack</> ist für den Kampf unverzichtbar. Damit kannst du <H>Verbündete beschwören</> und <H>Gegenstände benutzen</>, um dir einen taktischen Vorteil zu verschaffen.\n Du kannst auch <H>Haltungen</> aus dem <H>Bewaffnung</>-Schnittstelle zum taktischen Rucksack hinzufügen.",
          TextMapId = "UIGuide_BattleWheel_1"
        },
        UIGuide_BattleWheel_2_PC = {
          ContentES = "Halte &OpenBattleWheel& gedrückt, um einen Kampfbegleiter zu beschwören, der an der Seite deiner aktuellen Figur kämpft.",
          TextMapId = "UIGuide_BattleWheel_2_PC"
        },
        UIGuide_BattleWheel_2_Phone = {
          ContentES = "Tippe auf die Taste, um einen Kampfbegleiter zu beschwören, der an der Seite deiner aktuellen Figur kämpft.",
          TextMapId = "UIGuide_BattleWheel_2_Phone"
        },
        UIGuide_Biography = {
          ContentES = "Volkserzählungen liefern detaillierte Hintergrundgeschichten über Personen aus aller Welt. Wenn du sie näher kennenlernst, kannst du ihre Kurzgeschichten freischalten.",
          TextMapId = "UIGuide_Biography"
        },
        UIGuide_BonusDamage = {
          ContentES = "Wenn du mit einer Waffe Schaden verursachst, fügt du basierend auf dem ursprünglichen Schaden und seinem Element <H>1 Mal</> zusätzlichen Schaden zu. Der zusätzliche Schaden kann den entsprechenden Bonuseffekt basierend auf der <H>Auslöserate der Waffen</> auslösen.",
          TextMapId = "UIGuide_BonusDamage"
        },
        UIGuide_BulletJump_1_PC = {
          ContentES = "Drücke &Slide& und anschließend &Jump&, um einen Spiralsprung über Klippen auszuführen oder weite Entfernungen zu überwinden.",
          TextMapId = "UIGuide_BulletJump_1_PC"
        },
        UIGuide_BulletJump_1_Phone = {
          ContentES = "Halte die Springen-Taste gedrückt und <H>wische nach oben</>, um einen Spiralsprung über Klippen auszuführen oder weite Entfernungen zu überwinden",
          TextMapId = "UIGuide_BulletJump_1_Phone"
        },
        UIGuide_BulletJump_2 = {
          ContentES = "Neige die Kamera nach oben und setze den Spiralsprung ein, um <H>höhere</> Bereiche zu erreichen.",
          TextMapId = "UIGuide_BulletJump_2"
        },
        UIGuide_ChenMo_1 = {
