        },
        UI_Achievement_Des_70111 = {
          ContentES = "Presencia el destino de un Charon… o quizá de todos los Charons.",
          TextMapId = "UI_Achievement_Des_70111"
        },
        UI_Achievement_Des_70112 = {
          ContentES = "A medida que gira el carrusel del tiempo, los recuerdos desfilan como sombras en una linterna.",
          TextMapId = "UI_Achievement_Des_70112"
        },
        UI_Achievement_Des_70113 = {
          ContentES = "Enciende una linterna en la Mina de Glevum para quienes vengan después.",
          TextMapId = "UI_Achievement_Des_70113"
        },
        UI_Achievement_Des_70114 = {
          ContentES = "Establecerse en el Santuario.",
          TextMapId = "UI_Achievement_Des_70114"
        },
        UI_Achievement_Des_70115 = {
          ContentES = "Si no puedo vivir como un ser humano, entonces déjenme morir como tal.",
          TextMapId = "UI_Achievement_Des_70115"
        },
        UI_Achievement_Des_70116 = {
          ContentES = "Esta fotografía recuerda tu nombre, como el eco de mi voz.",
          TextMapId = "UI_Achievement_Des_70116"
        },
        UI_Achievement_Des_70117 = {
          ContentES = "Sobrevive al entrenamiento infernal de Outsider.",
          TextMapId = "UI_Achievement_Des_70117"
        },
        UI_Achievement_Des_70118 = {
          ContentES = "Rema contra la corriente, arrastrado una y otra vez hacia los días de antaño.",
          TextMapId = "UI_Achievement_Des_70118"
        },
        UI_Achievement_Des_70119 = {
          ContentES = "Un mundo nuevo, un nuevo comienzo.",
          TextMapId = "UI_Achievement_Des_70119"
        },
        UI_Achievement_Des_70120 = {
          ContentES = "He venido a llevarte a casa.",
          TextMapId = "UI_Achievement_Des_70120"
        },
        UI_Achievement_Des_70121 = {
          ContentES = "Sobrecarga el depósito Phoxichor para destruir la sala de máquinas.",
          TextMapId = "UI_Achievement_Des_70121"
        },
        UI_Achievement_Des_70122 = {
          ContentES = "Usar la torreta para abrir el camino hacia la Sala de control central.",
          TextMapId = "UI_Achievement_Des_70122"
        },
        UI_Achievement_Des_70123 = {
          ContentES = "Tic, tac…",
          TextMapId = "UI_Achievement_Des_70123"
        },
        UI_Achievement_Des_70124 = {
          ContentES = "Nunca tientes al destino diciendo: “Lo haré cuando la guerra termine”.",
          TextMapId = "UI_Achievement_Des_70124"
        },
        UI_Achievement_Des_70125 = {
          ContentES = "Si solo hay espacio para uno bajo el paraguas, entonces caminemos juntos bajo la lluvia.",
          TextMapId = "UI_Achievement_Des_70125"
        },
        UI_Achievement_Des_70126 = {
          ContentES = "Renace de la prisión de llamas.",
          TextMapId = "UI_Achievement_Des_70126"
        },
        UI_Achievement_Des_70127 = {
          ContentES = "Completar la Misión secundaria: Donde floreció el osmanto",
          TextMapId = "UI_Achievement_Des_70127"
        },
        UI_Achievement_Des_70128 = {
          ContentES = "Completar la Misión secundaria: Foco de atención",
          TextMapId = "UI_Achievement_Des_70128"
        },
        UI_Achievement_Des_70131 = {
          ContentES = "Schließe den Auftrag „Zeit der Unschuld“ ab",
          TextMapId = "UI_Achievement_Des_70131"
        },
        UI_Achievement_Des_70132 = {
          ContentES = "Schließe den Auftrag „Das Scharlachrote Land“ ab",
          TextMapId = "UI_Achievement_Des_70132"
        },
        UI_Achievement_Des_70133 = {
          ContentES = "Schließe den Auftrag „Requiem für die Namenlosen“ ab",
          TextMapId = "UI_Achievement_Des_70133"
        },
        UI_Achievement_Des_70134 = {
          ContentES = "Leite das wahrscheinliche Versteck des Täters im Fall „Jagd auf Charon“ ab.",
          TextMapId = "UI_Achievement_Des_70134"
        },
        UI_Achievement_Des_70135 = {
          ContentES = "Stelle dich den Monstern, die dich einst verwundet haben.",
          TextMapId = "UI_Achievement_Des_70135"
        },
        UI_Achievement_Des_70136 = {
          ContentES = "„Ich werde nie wieder zulassen, dass jemand durch Filthoiden stirbt.“",
          TextMapId = "UI_Achievement_Des_70136"
        },
        UI_Achievement_Des_70137 = {
          ContentES = "Fange einen großen Fisch für die Bewohner von Mist Aken.",
          TextMapId = "UI_Achievement_Des_70137"
        },
        UI_Achievement_Des_70138 = {
          ContentES = "Wir liegen alle in der Gosse, aber einige von uns blicken zu den Sternen.",
          TextMapId = "UI_Achievement_Des_70138"
        },
        UI_Achievement_Des_70139 = {
          ContentES = "Ich habe mir unser Wiedersehen unzählige Male vorgestellt – aber niemals so.",
          TextMapId = "UI_Achievement_Des_70139"
        },
        UI_Achievement_Des_70140 = {
          ContentES = "Zerreiße den Käfig – auch wenn deine Hände dabei zerfetzt werden.",
          TextMapId = "UI_Achievement_Des_70140"
        },
        UI_Achievement_Des_70141 = {
          ContentES = "„Auf die einzige gelungene Vorstellung meines Lebens.“",
          TextMapId = "UI_Achievement_Des_70141"
        },
        UI_Achievement_Des_80101 = {
