        UI_Skin_CharHasnotGottenReminder = {
          ContentES = "<H>%s</> noch nicht erhalten. Willst du <H>%s</> ×1 wirklich beanspruchen?",
          TextMapId = "UI_Skin_CharHasnotGottenReminder"
        },
        UI_Skin_Des_0010 = {
          ContentES = "La campana suena en el día más corto del año y los deseos se confían a la noche, para que los transmita la luz de las estrellas hacia el mañana.",
          TextMapId = "UI_Skin_Des_0010"
        },
        UI_Skin_Des_0011 = {
          ContentES = "Una presencia plena, donde la elegancia se despliega por sí misma.",
          TextMapId = "UI_Skin_Des_0011"
        },
        UI_Skin_Des_0121 = {
          ContentES = "Entre todos los muñecos de nieve, ¿por qué hay uno que parece mucho más grande?",
          TextMapId = "UI_Skin_Des_0121"
        },
        UI_Skin_Des_0122 = {
          ContentES = "Entre campanas y páginas, el tiempo pasa veloz.",
          TextMapId = "UI_Skin_Des_0122"
        },
        UI_Skin_Des_0141 = {
          ContentES = "El pecado no necesita condiciones especiales para florecer; germina en silencio dentro del corazón humano.",
          TextMapId = "UI_Skin_Des_0141"
        },
        UI_Skin_Des_1101 = {
          ContentES = "El negro es el color de la noche: un velo sereno y vigilante que cubre el mundo. El negro es el color de la sombra: un manto que permite permanecer siempre cerca de los seres queridos. A Berenica le gusta.",
          TextMapId = "UI_Skin_Des_1101"
        },
        UI_Skin_Des_110201 = {
          ContentES = "El noble ángel empuña la espada del juicio: al culpable lo condena, al inocente lo absuelve.",
          TextMapId = "UI_Skin_Des_110201"
        },
        UI_Skin_Des_1103 = {
          ContentES = "Una sombra en movimiento. Un actor torpe en el escenario. Un cuento urdido por un tonto.",
          TextMapId = "UI_Skin_Des_1103"
        },
        UI_Skin_Des_1104 = {
          ContentES = "Alta costura dorada, hecha a medida, ostentosa: más que un simple atuendo, es una proclamación de estatus.",
          TextMapId = "UI_Skin_Des_1104"
        },
        UI_Skin_Des_1501 = {
          ContentES = "La doctrina de la Iglesia Elysiana no está simplemente cosida en la tela: está grabada en el alma, dando testimonio de una muchacha que una y otra vez se deshace de su ira y se levanta paciente y resuelta.",
          TextMapId = "UI_Skin_Des_1501"
        },
        UI_Skin_Des_1502 = {
          ContentES = "Velos vaporosos, tejidos de crepúsculo y aurora, guían a cada alma a través del río lleno de lágrimas, hacia el Mar Nebuloso, donde todos renacen.",
          TextMapId = "UI_Skin_Des_1502"
        },
        UI_Skin_Des_150201 = {
          ContentES = "Aunque los milagros hayan desaparecido del mundo, aún hay quienes, en su fragilidad mortal, marchan adelante cargando el peso de la fe.",
          TextMapId = "UI_Skin_Des_150201"
        },
        UI_Skin_Des_1503 = {
          ContentES = "La lluvia se desliza desde las túnicas ondeantes, se acumula en la punta de la espada y luego desaparece en el mundo de las espadas a la deriva.",
          TextMapId = "UI_Skin_Des_1503"
        },
        UI_Skin_Des_1601 = {
          ContentES = "Un ser, una espada, un vestido inmaculado. Atravesar el océano y la noche helada, para finalmente encontrarse al borde del alba.",
          TextMapId = "UI_Skin_Des_1601"
        },
        UI_Skin_Des_1801 = {
          ContentES = "El ruiseñor cuelga plumas nevadas sobre su cola, dejando que sus delicadas alas lleven sus sueños a las nubes.",
          TextMapId = "UI_Skin_Des_1801"
        },
        UI_Skin_Des_2101 = {
          ContentES = "Las tentáculos de las medusas se deslizan hacia las profundidades como un dobladillo suelto, haciendo temblar el corazón de un amante en la oscuridad.",
          TextMapId = "UI_Skin_Des_2101"
        },
        UI_Skin_Des_210101 = {
          ContentES = "Las olas mojan el dobladillo del vestido blanco y traen consigo su murmullo: “Solo la muerte puede separarnos. ”",
          TextMapId = "UI_Skin_Des_210101"
        },
        UI_Skin_Des_210102 = {
          ContentES = "Un susurro de amor a través de las sedas, una eternidad sellada en un beso fatal.",
          TextMapId = "UI_Skin_Des_210102"
        },
        UI_Skin_Des_2301 = {
          ContentES = "¿Qué se retuerce en la oscuridad? ¿Conspiración, caos, crimen? Nada de eso. Solo tentáculos.",
          TextMapId = "UI_Skin_Des_2301"
        },
        UI_Skin_Des_2401 = {
          ContentES = "Jirones de fragancia de hierbas flotan a través de las mangas blancas, susurrando el regreso de la vida a los marchitos.",
          TextMapId = "UI_Skin_Des_2401"
        },
        UI_Skin_Des_240101 = {
          ContentES = "Las mareas para lavar el polvo, las olas para calmar el corazón.",
          TextMapId = "UI_Skin_Des_240101"
        },
        UI_Skin_Des_3101 = {
          ContentES = "El calor de la pólvora se adhiere al uniforme mate, impulsado por el pulso de la sangre ferviente.",
          TextMapId = "UI_Skin_Des_3101"
        },
        UI_Skin_Des_310101 = {
          ContentES = "Aunque los milagros hayan desaparecido del mundo, aún hay quienes, en su fragilidad mortal, marchan adelante cargando el peso de la fe.",
          TextMapId = "UI_Skin_Des_310101"
        },
        UI_Skin_Des_3103 = {
          ContentES = "Hilos ardientes de color rojo y blanco unen los sueños de un loco y cosen el sueño inocente de un niño.",
          TextMapId = "UI_Skin_Des_3103"
        },
        UI_Skin_Des_3201 = {
          ContentES = "Las cadenas y las espinas marcan el castigo por el pecado y atan el fuego justo que arde en nuestro interior.",
          TextMapId = "UI_Skin_Des_3201"
        },
        UI_Skin_Des_3301 = {
          ContentES = "Un casco multiusos forjado a partir de una olla: una armadura resistente para una chica recicladora.",
          TextMapId = "UI_Skin_Des_3301"
        },
        UI_Skin_Des_4101 = {
          ContentES = "Un azul salpicado de estrellas brilla en su uniforme: una voluntad de proteger y una mirada hacia el futuro.",
          TextMapId = "UI_Skin_Des_4101"
        },
        UI_Skin_Des_4102 = {
          ContentES = "La luz del sol se derrama sobre el suntuoso brocado como oro fundido: el amanecer de la revolución se refleja en sus ojos dorados.",
          TextMapId = "UI_Skin_Des_4102"
        },
        UI_Skin_Des_410201 = {
          ContentES = "Entre el entrelazarse de las copas y las voces, fluyen enfrentamientos silenciosos.",
          TextMapId = "UI_Skin_Des_410201"
        },
        UI_Skin_Des_4201 = {
          ContentES = "El trueno del cielo recorre su cuerpo. Cumpliendo el mandato de Dafeng, el pecado no encuentra refugio, ni él tampoco.",
          TextMapId = "UI_Skin_Des_4201"
        },
        UI_Skin_Des_4202 = {
          ContentES = "Una medalla brilla con una mente genial arriba. Un uniforme late con el corazón de un hombre común abajo.",
          TextMapId = "UI_Skin_Des_4202"
        },
        UI_Skin_Des_4301 = {
          ContentES = "No lleva ni armadura ni corona, pero su presencia resuena con un terror imponente.",
          TextMapId = "UI_Skin_Des_4301"
        },
        UI_Skin_Des_5101 = {
          ContentES = "Plumas blancas revolotean por las calles, dejando un rastro de aroma a malta y fuego de hogar, llevado por el viento a cada estómago vacío.",
          TextMapId = "UI_Skin_Des_5101"
        },
        UI_Skin_Des_510101 = {
          ContentES = "¡Sol reunido, sol disperso!",
          TextMapId = "UI_Skin_Des_510101"
        },
        UI_Skin_Des_5102 = {
          ContentES = "Una vestimenta sencilla no silenciará los lamentos carmesí de los callejones oscuros, pero protege un rayo de luz estelar de la brutalidad del mundo.",
          TextMapId = "UI_Skin_Des_5102"
        },
        UI_Skin_Des_5301 = {
          ContentES = "Una mariposa descansa en el hueco de su brazo, portando sueños que cruzaron la escarcha del invierno.",
          TextMapId = "UI_Skin_Des_5301"
        },
        UI_Skin_Des_530101 = {
          ContentES = "En una noche de verano, bajo un cielo estrellado, un bosque donde las violetas y las alas de mariposa danzaban en pasos delicados. Una visión que nunca había visto.",
          TextMapId = "UI_Skin_Des_530101"
        },
        UI_Skin_Des_5401 = {
          ContentES = "Verde verdoso, elevándose a través del humo y la pólvora, liviano como la hierba silvestre, e igual de inflexible.",
          TextMapId = "UI_Skin_Des_5401"
        },
