        },
        voice_ch_char_Suyi_vo_die_r02 = {
          ContentES = "El destino del Pájaro Yi... es el cielo.",
          TextMapId = "voice_ch_char_Suyi_vo_die_r02"
        },
        voice_ch_char_Suyi_vo_fail = {
          ContentES = "Potencia… módulos… motor… ¿Dónde estuvo exactamente el problema?",
          TextMapId = "voice_ch_char_Suyi_vo_fail"
        },
        voice_ch_char_Suyi_vo_gain = {
          ContentES = "Los discípulos de la Secta Jishu siempre hemos permanecido unidos. Si alguna vez tienes problemas en Huaxu, no dudes en pedirme ayuda, ¡yo me encargaré de todo!",
          TextMapId = "voice_ch_char_Suyi_vo_gain"
        },
        voice_ch_char_Suyi_vo_idle = {
          ContentES = "¿Estarás bien ahí fuera… sin mí?",
          TextMapId = "voice_ch_char_Suyi_vo_idle"
        },
        voice_ch_char_Suyi_vo_lvup = {
